    let html = await new Response(stream).text(); try { const i = html.indexOf('{"id": "en6"'); if (i >= 0) { const j = html.indexOf(String.fromCharCode(10), i); let s = html.slice(i, j); s = s.replace('["my task", "i had to", "i needed", "responsible"]', '["my task", "i had to", "i needed", "responsible", "my job", "my goal", "needed to", "task was"]'); s = s.replace('["i checked", "i tested", "i found", "i investigated", "i fixed", "i reproduced"]', '["i checked", "i tested", "i found", "i investigated", "i fixed", "i reproduced", "contact", "called", "explain", "meet", "email", "phone", "checked", "tested", "investigat", "reproduc"]'); s = s.replace('["result", "solved", "fixed", "since then", "reduced", "now"]', '["result", "solved", "fixed", "since then", "reduced", "now", "solution", "resolved", "storno", "corrected", "in the end", "as a result"]'); const k = s.indexOf('"model": "'); const m = s.indexOf('", "e": ', k); if (k >= 0 && m > k) { s = s.slice(0, k) + '"model": ' + JSON.stringify("A customer didn't understand his subscription, and it turned out to be bigger than the one he was supposed to have. My task was to clarify the situation and correct the billing. I contacted him by email and phone, then we held a Google Meet to explain everything step by step. The solution was a proforma storno, so he was no longer charged for the bigger plan.") + s.slice(m + 1); } html = html.slice(0, i) + s + html.slice(j); } html = html.replace("['gravit','priorit','sever','critic']", "['gravit','priorit','sever','critic','grav']"); } catch (e) {}
    try { const s0 = html.indexOf('const IV_BANK'); const e0 = s0 >= 0 ? html.indexOf('\n];', s0) : -1; if (e0 > s0) { html = html.slice(0, e0) + "\n/* ---------- Lot nou: QA, API/Playwright, Engleza (60) ---------- */\n{\"id\":\"qa21\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Care e diferența dintre un plan de testare (test plan) și o strategie de testare (test strategy)?\",\"o\":[\"Strategia descrie abordarea generală, pe termen lung; planul spune ce, când, cine și cu ce testezi într-un proiect concret\",\"Sunt același document cu nume diferite\",\"Planul se scrie doar după ce apar bugurile, strategia înainte\"],\"a\":0,\"h\":\"Strategia = cum gândim în general; planul = detaliile unui proiect.\",\"e\":\"Strategia e relativ stabilă (niveluri de testare, instrumente, riscuri), iar planul de testare se scrie pentru o versiune sau un proiect: perimetru, calendar, responsabili, medii, criterii de intrare și de ieșire.\"},\n{\"id\":\"qa22\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"La ce folosește o matrice de trasabilitate (traceability matrix)?\",\"o\":[\"Leagă cerințele de cazurile de test, ca să vezi ce cerință nu e acoperită\",\"Listează doar bugurile deschise\",\"Măsoară viteza de execuție a testelor\"],\"a\":0,\"h\":\"Poți urmări de unde vine fiecare test.\",\"e\":\"Fiecare cerință are cel puțin un caz de test asociat. Dacă o cerință se schimbă, știi ce teste actualizezi, iar golurile de acoperire se văd imediat.\"},\n{\"id\":\"qa23\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce automatizezi primul într-o suită de regresie?\",\"o\":[\"Scenariile critice, stabile și rulate des (ex. login, abonare, comandă)\",\"Funcțiile care se schimbă zilnic\",\"Orice scenariu nou, indiferent cât e de instabil\"],\"a\":0,\"h\":\"Câștigi cel mai mult din ce rulezi des și nu se schimbă.\",\"e\":\"Automatizarea aduce valoare pe fluxuri repetitive și stabile. Funcțiile încă în schimbare se testează manual până se așază, altfel pierzi timp cu mentenanța testelor.\"},\n{\"id\":\"qa24\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Dezvoltatorul răspunde pe un bug: „Cannot reproduce”. Ce faci?\",\"o\":[\"Verifici versiunea, mediul și datele din raport, completezi pașii exacți și atașezi capturi sau loguri\",\"Închizi bugul, probabil nu există\",\"Îl marchezi automat ca blocant\"],\"a\":0,\"h\":\"Pe mediul lui nu merge, deci lipsesc detalii.\",\"e\":\"Cel mai des diferă mediul, versiunea, datele de test sau pașii. Ajută: pași numerotați, rezultat așteptat vs obținut, browser și versiune, utilizatorul folosit, captură sau log.\"},\n{\"id\":\"qa25\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"De ce folosești conturi și date de test dedicate, nu conturile unor clienți reali?\",\"o\":[\"Ca să nu modifici date reale și să poți repeta testul cu aceleași date\",\"Pentru că datele reale nu pot fi citite niciodată\",\"E doar o regulă estetică, fără efect\"],\"a\":0,\"h\":\"Testul nu are voie să strice nimic real.\",\"e\":\"Date de test controlate fac testele repetabile și evită trimiteri către clienți reali sau modificări pe date reale. Datele personale reale nu se folosesc în teste fără motiv.\"},\n{\"id\":\"qa26\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Când e utilă o tabelă de decizie (decision table)?\",\"o\":[\"Când rezultatul depinde de combinații de condiții (ex. tip de abonat, cupon, livrare)\",\"Când testezi doar aspectul unui buton\",\"Când vrei să măsori timpul de încărcare\"],\"a\":0,\"h\":\"Combinații de reguli de business.\",\"e\":\"Enumeri combinațiile de condiții și rezultatul așteptat pentru fiecare. Te ajută să acoperi regulile complexe fără să uiți cazuri.\"},\n{\"id\":\"qa27\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"O comandă trece prin stările Nouă, Plătită, Expediată, Livrată. Ce urmărești cu testarea tranzițiilor de stare?\",\"o\":[\"Că tranzițiile permise merg, iar cele interzise (ex. Livrată înapoi la Nouă) sunt blocate\",\"Doar că textul fiecărei stări e scris corect\",\"Doar viteza cu care se schimbă starea\"],\"a\":0,\"h\":\"Ce treceri sunt permise și care nu.\",\"e\":\"Verifici atât drumurile valide, cât și încercările invalide. Multe bugurile apar la tranziții neprevăzute.\"},\n{\"id\":\"qa28\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce e testarea negativă (negative testing)?\",\"o\":[\"Verifici că aplicația reacționează corect la date sau acțiuni invalide (ex. email fără @)\",\"Testezi doar funcțiile care au deja bug\",\"Rulezi teste care trebuie să pice mereu\"],\"a\":0,\"h\":\"Încerci intenționat ce n-ar trebui să meargă.\",\"e\":\"Aplicația trebuie să respingă intrările greșite cu un mesaj clar, fără eroare tehnică și fără date corupte.\"},\n{\"id\":\"qa29\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Cum alegi pe ce browsere testezi când timpul e limitat?\",\"o\":[\"Pe cele mai folosite de utilizatori, după statisticile site-ului (analytics)\",\"Doar pe cel instalat pe calculatorul tău\",\"Pe toate versiunile vechi, în ordine alfabetică\"],\"a\":0,\"h\":\"Prioritizezi după utilizatori reali.\",\"e\":\"Analytics arată distribuția reală (Chrome, Safari pe mobil etc.). Începi cu cele mai folosite și acoperi restul în funcție de risc.\"},\n{\"id\":\"qa30\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Care e diferența dintre verificare și validare?\",\"o\":[\"Verificare: construim produsul corect (conform specificațiilor); validare: construim produsul potrivit (nevoii utilizatorului)\",\"Sunt sinonime\",\"Verificarea o fac doar clienții, validarea doar testerii\"],\"a\":0,\"h\":\"„Am făcut bine?” vs „am făcut ce trebuia?”\",\"e\":\"Poți respecta perfect specificația (verificare) și totuși să nu rezolvi problema utilizatorului (validare).\"},\n{\"id\":\"qa31\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Plata cu cardul eșuează pentru toți clienții unui magazin online. Cum clasifici bugul?\",\"o\":[\"Severitate critică, prioritate maximă\",\"Severitate mică, prioritate mică\",\"Severitate critică, dar prioritate mică, poate aștepta luna viitoare\"],\"a\":0,\"h\":\"Blochează încasările.\",\"e\":\"Funcția principală e blocată pentru toți: impact maxim și urgență maximă. Combinația severitate mare, prioritate mică apare la un bug grav pe un flux foarte rar folosit.\"},\n{\"id\":\"qa32\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Un test trece pe staging, dar pică în producție. Care e o cauză frecventă?\",\"o\":[\"Diferențe între medii: configurări, versiuni, date, chei de API\",\"Staging nu se poate folosi niciodată pentru teste\",\"Producția rulează întotdeauna mai rapid\"],\"a\":0,\"h\":\"Mediile nu sunt identice.\",\"e\":\"Compară configurarea, versiunea codului sau a pluginului, datele, certificatele și cheile externe înainte să cauți un bug în cod.\"},\n{\"id\":\"qa33\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce e UAT (User Acceptance Testing)?\",\"o\":[\"Testarea de acceptanță făcută de utilizatori sau reprezentanți ai clientului, înainte de lansare\",\"Un tip de test unitar scris de dezvoltatori\",\"Testarea performanței sub sarcină\"],\"a\":0,\"h\":\"U vine de la User.\",\"e\":\"Confirmă că produsul rezolvă nevoia de business în scenarii reale și se face de obicei după testarea de sistem.\"},\n{\"id\":\"qa34\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Echipa are 100% code coverage. Înseamnă asta că nu mai există bugurile?\",\"o\":[\"Nu: coverage arată ce cod a fost rulat, nu dacă testele verifică corect comportamentul\",\"Da, 100% garantează lipsa bugurilor\",\"Da, dar doar la aplicațiile web\"],\"a\":0,\"h\":\"Rulat nu înseamnă verificat.\",\"e\":\"Un test poate executa o linie fără nicio verificare utilă. Coverage e un indicator, nu o garanție; contează și calitatea aserțiunilor.\"},\n{\"id\":\"qa35\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"La ce ajută testarea pairwise (combinatorială)?\",\"o\":[\"Reduci numărul de teste, acoperind toate perechile de valori între parametri\",\"Verifici doar perechi de utilizatori care lucrează împreună\",\"Compari două versiuni ale aceluiași raport\"],\"a\":0,\"h\":\"Perechi de valori, nu toate combinațiile.\",\"e\":\"Majoritatea defectelor apar din interacțiunea a două setări, nu a zece. Pairwise dă acoperire bună cu mult mai puține teste decât toate combinațiile.\"},\n{\"id\":\"qa36\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Testezi abonarea cu double opt-in. Ce verifici la final?\",\"o\":[\"Că abonatul rămâne neconfirmat până dă click pe linkul din emailul de confirmare, apoi devine activ\",\"Doar că formularul afișează „Mulțumim”\",\"Că abonatul e activ imediat după completarea formularului\"],\"a\":0,\"h\":\"Dublă confirmare înseamnă doi pași.\",\"e\":\"Verifici emailul de confirmare (ajunge, linkul funcționează), statusul înainte și după click și că nu se trimit campanii către cei neconfirmați.\"},\n{\"id\":\"qa37\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Observi că un bug pe care voiai să-l raportezi există deja în tracker. Ce faci?\",\"o\":[\"Îl marchezi ca duplicat, legi tichetele și adaugi informațiile noi în cel existent\",\"Îl ștergi fără urmă\",\"Creezi un al treilea, ca să fie sigur\"],\"a\":0,\"h\":\"Un singur loc pentru fiecare problemă.\",\"e\":\"Legătura între duplicate păstrează istoricul, iar detaliile suplimentare (alt browser, alt mediu) ajută la reparare.\"},\n{\"id\":\"qa38\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce sunt criteriile de ieșire (exit criteria) ale unei etape de testare?\",\"o\":[\"Condițiile care spun când poți considera testarea încheiată (ex. testele critice rulate, niciun bug critic deschis)\",\"Lista persoanelor care pleacă din echipă\",\"Orele în care se oprește serverul de test\"],\"a\":0,\"h\":\"Când e gata testarea?\",\"e\":\"Se definesc dinainte: procent de teste rulate și trecute, bugurile deschise permise pe severități, acoperirea cerințelor.\"},\n{\"id\":\"qa39\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"Introduci \\u003cscript>alert(1)\\u003c/script> într-un câmp de nume din aplicația ta. Ce rezultat e corect?\",\"o\":[\"Textul e afișat ca text sau respins; scriptul nu se execută\",\"Apare o fereastră alert, e normal\",\"Aplicația se oprește și e acceptabil\"],\"a\":0,\"h\":\"Datele de la utilizator nu sunt cod.\",\"e\":\"Dacă scriptul se execută, există o vulnerabilitate XSS: ieșirea trebuie codificată (escaped). Se testează doar pe aplicații proprii sau cu acord.\"},\n{\"id\":\"qa40\",\"d\":\"qa\",\"nou\":1,\"t\":\"mc\",\"q\":\"O campanie e programată la 23:30 UTC. De ce poate apărea în altă zi pentru un utilizator din România?\",\"o\":[\"Din cauza fusului orar: România e la UTC+2 sau +3, deci e deja ziua următoare\",\"E sigur un bug de bază de date\",\"Pentru că România nu folosește UTC\"],\"a\":0,\"h\":\"Compară ora UTC cu ora locală.\",\"e\":\"Testezi cu ore apropiate de miezul nopții și la schimbarea orei de vară/iarnă. Afișarea trebuie să țină cont de fusul orar al utilizatorului.\"},\n{\"id\":\"ap11\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce diferență e între PUT și POST în privința idempotenței?\",\"o\":[\"PUT e idempotent: repetat dă același rezultat; POST de obicei creează o resursă nouă la fiecare apel\",\"POST e idempotent, PUT nu\",\"Niciuna dintre ele nu e idempotentă\"],\"a\":0,\"h\":\"Idempotent = același efect, oricâte repetări.\",\"e\":\"Un PUT /abonati/5 cu aceleași date lasă resursa în aceeași stare. Două POST /abonati pot crea doi abonați.\"},\n{\"id\":\"ap12\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce diferență e între 401 și 403?\",\"o\":[\"401: nu ești autentificat (credențiale lipsă sau greșite); 403: ești autentificat, dar nu ai voie\",\"401: resursa nu există; 403: serverul e căzut\",\"Sunt identice\"],\"a\":0,\"h\":\"Cine ești vs ce ai voie.\",\"e\":\"401 Unauthorized = autentificare lipsă sau invalidă. 403 Forbidden = identificat, dar fără permisiune. 404 = nu există.\"},\n{\"id\":\"ap13\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Un API întoarce 429. Ce înseamnă?\",\"o\":[\"Ai trimis prea multe cereri într-un interval (rate limit); aștepți și reîncerci, de obicei după Retry-After\",\"Resursa a fost ștearsă definitiv\",\"Corpul cererii e prea mare\"],\"a\":0,\"h\":\"Prea multe cereri.\",\"e\":\"429 Too Many Requests. Respecți header-ul Retry-After dacă există. În teste nu bombardezi API-ul de producție.\"},\n{\"id\":\"ap14\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Testezi GET /api/abonati cu parametrii page=2 și limit=10. Ce verifici la paginare?\",\"o\":[\"Că întoarce maxim 10 elemente, diferite de pagina 1, și că ultima pagină și o pagină inexistentă se comportă corect\",\"Doar că răspunsul e 200\",\"Doar că pagina 2 e identică cu pagina 1\"],\"a\":0,\"h\":\"Margini: prima, ultima, inexistentă.\",\"e\":\"Verifici dimensiunea paginii, lipsa duplicatelor între pagini, totalul, ordinea stabilă și cazurile limită (page=0, pagină peste ultima).\"},\n{\"id\":\"ap15\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce cod de răspuns e potrivit pentru un POST care a creat cu succes o resursă?\",\"o\":[\"201 Created, de obicei cu header-ul Location sau cu resursa în corp\",\"204 No Content întotdeauna\",\"301 Moved Permanently\"],\"a\":0,\"h\":\"Created înseamnă creat.\",\"e\":\"200 e acceptat în unele API-uri, dar 201 e convenția REST; Location indică adresa noii resurse.\"},\n{\"id\":\"ap16\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce face în Postman codul pm.test('Status 200', () => { pm.response.to.have.status(200); });\",\"o\":[\"Definește un test care pică dacă răspunsul nu are statusul 200\",\"Trimite încă o cerere automat\",\"Salvează răspunsul într-o variabilă de mediu\"],\"a\":0,\"h\":\"pm este obiectul Postman.\",\"e\":\"Testele din tab-ul Tests rulează după răspuns; rezultatele apar în Test Results și în Collection Runner.\"},\n{\"id\":\"ap17\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce înseamnă auto-waiting în Playwright?\",\"o\":[\"Înainte de o acțiune (click, fill), Playwright așteaptă singur ca elementul să fie vizibil, activ și stabil\",\"Playwright așteaptă mereu 30 de secunde între teste\",\"Trebuie să pui un sleep înainte de fiecare click\"],\"a\":0,\"h\":\"Mai puține sleep-uri.\",\"e\":\"Verifică actionability: atașat, vizibil, stabil, primește evenimente, activ. Reduce testele flaky.\"},\n{\"id\":\"ap18\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Care e mai bun într-un test Playwright: await expect(locator).toBeVisible() sau if (await locator.isVisible())?\",\"o\":[\"expect(locator).toBeVisible(): reîncearcă până la timeout, deci e mai stabil\",\"isVisible(), pentru că așteaptă mai mult\",\"Sunt identice în toate cazurile\"],\"a\":0,\"h\":\"Aserțiuni web-first.\",\"e\":\"isVisible() răspunde imediat, fără așteptare. expect cu locator reîncearcă până trece sau expiră timpul.\"},\n{\"id\":\"ap19\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Cum deschizi trace-ul unui test Playwright picat, ca să vezi pașii, rețeaua și capturile?\",\"o\":[\"npx playwright show-trace trace.zip\",\"npx playwright install\",\"npx playwright codegen\"],\"a\":0,\"h\":\"Show trace.\",\"e\":\"Setezi trace: 'on-first-retry' în config. Trace Viewer arată pașii, DOM-ul, cererile de rețea și consola.\"},\n{\"id\":\"ap20\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"La ce folosește storageState în Playwright?\",\"o\":[\"Salvezi starea sesiunii (cookie-uri, localStorage) după login și o refolosești, fără login la fiecare test\",\"Salvezi capturi de ecran\",\"Stochezi rezultatele testelor într-o bază de date\"],\"a\":0,\"h\":\"Te loghezi o singură dată.\",\"e\":\"Faci login într-un setup, salvezi fișierul și îl pui în use.storageState. Nu îl pui în Git: conține sesiuni.\"},\n{\"id\":\"ap21\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Cum izolezi un test de un API extern instabil în Playwright?\",\"o\":[\"Cu page.route(): interceptezi cererea și întorci un răspuns simulat (mock)\",\"Cu page.reload() de 10 ori\",\"Dezactivezi toate aserțiunile\"],\"a\":0,\"h\":\"Interceptezi cererea.\",\"e\":\"page.route cu route.fulfill simulează răspunsuri, inclusiv erori (500), greu de provocat altfel.\"},\n{\"id\":\"ap22\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Cum testezi direct un endpoint REST din Playwright, fără browser?\",\"o\":[\"Cu fixture-ul request, de exemplu await request.get('/api/abonati')\",\"Doar cu Postman, Playwright nu poate\",\"Cu page.goto() către endpoint și citind captura\"],\"a\":0,\"h\":\"APIRequestContext.\",\"e\":\"request merge fără interfață. Poți combina: creezi datele prin API, apoi verifici rezultatul în UI.\"},\n{\"id\":\"ap23\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce face opțiunea retries din playwright.config?\",\"o\":[\"Reia automat un test picat de câteva ori; un test care trece doar la reluare e marcat flaky\",\"Șterge testele care pică\",\"Rulează testele mai rapid\"],\"a\":0,\"h\":\"Nu ascunde problema.\",\"e\":\"Utile în CI, dar nu repară cauza: un test flaky trebuie investigat (așteptări, date, mediu).\"},\n{\"id\":\"ap24\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce avantaj are baseURL în playwright.config?\",\"o\":[\"Poți scrie page.goto('/login') și schimbi mediul (dev, staging) dintr-un singur loc\",\"Face testele mai rapide\",\"Blochează accesul către alte domenii\"],\"a\":0,\"h\":\"Un singur loc pentru adresa mediului.\",\"e\":\"În use setezi baseURL (ex. din variabila BASE_URL): aceleași teste rulează pe medii diferite.\"},\n{\"id\":\"ap25\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Când folosești getByTestId în Playwright?\",\"o\":[\"Când elementul nu are rol sau text stabil, iar echipa adaugă un atribut data-testid dedicat testelor\",\"Întotdeauna, în locul lui getByRole\",\"Doar pentru elemente invizibile\"],\"a\":0,\"h\":\"Locatori stabili.\",\"e\":\"Ordinea recomandată: getByRole, getByLabel, getByText; data-testid ca variantă stabilă când celelalte nu merg.\"},\n{\"id\":\"ap26\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Ce face expect.soft() în Playwright?\",\"o\":[\"Nu oprește testul la prima aserțiune picată; testul continuă și e marcat picat la final\",\"Face aserțiunea mai rapidă\",\"Ignoră complet rezultatul aserțiunii\"],\"a\":0,\"h\":\"Soft înseamnă mai moale.\",\"e\":\"Util când verifici mai multe câmpuri dintr-o pagină și vrei lista completă a diferențelor.\"},\n{\"id\":\"ap27\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"De ce testele Playwright rulate în paralel trebuie să fie independente?\",\"o\":[\"Pentru că rulează simultan în workeri diferiți și nu trebuie să depindă de ordinea sau de datele altui test\",\"Pentru că Playwright nu permite mai mult de un test pe fișier\",\"Pentru a consuma mai multă memorie\"],\"a\":0,\"h\":\"Fiecare test trebuie să meargă singur.\",\"e\":\"Un test care presupune că altul a creat datele pică aleatoriu în paralel. Fiecare test își creează și își curăță datele.\"},\n{\"id\":\"ap28\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"De ce e o practică proastă page.waitForTimeout(5000) în teste?\",\"o\":[\"E o pauză fixă: încetinește testele și tot poate pica dacă pagina e mai lentă\",\"Pentru că nu există în Playwright\",\"Pentru că oprește definitiv browserul\"],\"a\":0,\"h\":\"Aștepți o condiție, nu timp.\",\"e\":\"Folosește așteptări pe condiții: expect(...).toBeVisible(), waitForResponse, waitForURL.\"},\n{\"id\":\"ap29\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Cum verifici că un răspuns JSON respectă contractul API-ului?\",\"o\":[\"Verifici câmpurile obligatorii, tipurile (ex. id număr, email șir) și valorile, eventual cu validare pe schemă JSON\",\"Verifici doar că răspunsul nu e gol\",\"Verifici doar timpul de răspuns\"],\"a\":0,\"h\":\"Contează structura, nu doar statusul.\",\"e\":\"O schimbare de tip (id din număr în șir) strică clienții API chiar dacă statusul rămâne 200.\"},\n{\"id\":\"ap30\",\"d\":\"api\",\"nou\":1,\"t\":\"mc\",\"q\":\"Un apel merge în Postman, dar browserul îl blochează cu o eroare CORS. Ce înseamnă?\",\"o\":[\"Serverul nu trimite header-ele CORS care permit originea paginii; politica e aplicată de browser, nu de Postman\",\"API-ul e căzut\",\"Cheia de API a expirat\"],\"a\":0,\"h\":\"Politica o aplică browserul.\",\"e\":\"Soluția e pe server: Access-Control-Allow-Origin (și răspuns la preflight OPTIONS). Postman nu aplică CORS.\"},\n{\"id\":\"en8\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Your colleague says: “We need to roll back the release.” What do they want to do?\",\"o\":[\"Return to the previous version\",\"Publish the release earlier\",\"Make the release bigger\"],\"a\":0,\"h\":\"Roll back = înapoi la versiunea veche.\",\"e\":\"Roll back = revenire la versiunea anterioară după o problemă. Opusul: roll out (lansare treptată).\"},\n{\"id\":\"en9\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“Eventually, we fixed the bug.” What does “eventually” mean?\",\"o\":[\"În cele din urmă, după un timp\",\"Eventual, posibil\",\"Imediat\"],\"a\":0,\"h\":\"False friend.\",\"e\":\"Eventually = în final. „Eventual” în română se spune possibly sau if necessary.\"},\n{\"id\":\"en10\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"The interviewer says: “Can you walk me through your last project?” What do they want?\",\"o\":[\"A step-by-step explanation of your last project\",\"To walk together in the office\",\"A written report of ten pages\"],\"a\":0,\"h\":\"Walk me through = explică-mi pas cu pas.\",\"e\":\"Expresie foarte folosită în interviuri: începi cu contextul, apoi ce ai făcut tu, apoi rezultatul.\"},\n{\"id\":\"en11\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which sentence sounds correct on a CV or in an interview?\",\"o\":[\"I was responsible for testing new releases.\",\"I was responsable of testing new releases.\",\"I was responsible about test new releases.\"],\"a\":0,\"h\":\"responsible for + substantiv sau -ing.\",\"e\":\"Structura corectă: responsible for + substantiv sau verb cu -ing. „Responsable” e scris greșit în engleză.\"},\n{\"id\":\"en12\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“I escalated the issue to the senior engineer.” What did you do?\",\"o\":[\"I passed the problem to someone with more authority or expertise\",\"I solved the problem alone\",\"I ignored the problem\"],\"a\":0,\"h\":\"Escalate = urci problema la cineva mai sus.\",\"e\":\"În suport și testare, escalarea înseamnă să predai cazul unui nivel superior, cu toate detaliile adunate.\"},\n{\"id\":\"en13\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which is a good way to start a polite follow-up email after an interview?\",\"o\":[\"I’d like to follow up on our conversation from Tuesday.\",\"Why haven’t you answered me yet?\",\"Answer me today.\"],\"a\":0,\"h\":\"Ton politicos, concret.\",\"e\":\"Follow up = revii asupra unei discuții anterioare. Menționezi ziua sau subiectul și ceri politicos un răspuns.\"},\n{\"id\":\"en14\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“What are your salary expectations?” Which answer is the best?\",\"o\":[\"Based on my experience and the market, I’m looking at a range of X to Y, and I’m open to discussing it.\",\"I don’t care about money.\",\"Whatever you want, I’ll accept anything.\"],\"a\":0,\"h\":\"Un interval documentat.\",\"e\":\"Dai un interval argumentat, nu o cifră fixă și nu „orice”. X și Y sunt cifrele tale.\"},\n{\"id\":\"en15\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“What is your biggest weakness?” What is the best type of answer?\",\"o\":[\"A real, minor weakness and what you do to improve it\",\"“I have no weaknesses.”\",\"A weakness that is essential for the job\"],\"a\":0,\"h\":\"Sinceritate plus plan de îmbunătățire.\",\"e\":\"Intervievatorul vrea autocunoaștere. Alegi o slăbiciune reală, dar nu esențială pentru rol, și spui ce faci ca s-o corectezi.\"},\n{\"id\":\"en16\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“Let’s make sure we’re on the same page.” What does it mean?\",\"o\":[\"Let’s make sure we understand and agree on the same things\",\"Let’s read the same document aloud\",\"Let’s sit next to each other\"],\"a\":0,\"h\":\"Idiom.\",\"e\":\"On the same page = avem aceeași înțelegere. Se folosește des după o ședință sau la începutul unui proiect.\"},\n{\"id\":\"en17\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"What does “by EOD” mean in a message from your manager?\",\"o\":[\"By the end of the day\",\"By the end of the month\",\"By every other day\"],\"a\":0,\"h\":\"EOD = end of day.\",\"e\":\"Alte prescurtări utile: ASAP (as soon as possible), ETA (estimated time of arrival), FYI (for your information).\"},\n{\"id\":\"en18\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which sentence is correct?\",\"o\":[\"The customer’s issue has been resolved.\",\"The customer’s issue has resolved by me.\",\"The customer’s issue have been resolved.\"],\"a\":0,\"h\":\"has/have been + participiu.\",\"e\":\"Pasivul la present perfect: has/have been + participiul verbului. „Issue” e singular, deci has been.\"},\n{\"id\":\"en19\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which preposition is correct: “I’m good ___ testing APIs.”\",\"o\":[\"at\",\"in\",\"on\"],\"a\":0,\"h\":\"good at.\",\"e\":\"Good at + substantiv sau -ing. „Good in” nu se folosește în acest sens.\"},\n{\"id\":\"en20\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"What is a “stand-up” in a software team?\",\"o\":[\"A short daily meeting where everyone shares progress and blockers\",\"A comedy show at the office\",\"A meeting where nobody can talk\"],\"a\":0,\"h\":\"Ședință scurtă, în picioare.\",\"e\":\"Daily stand-up: ce am făcut ieri, ce fac azi, ce mă blochează. Ține 10-15 minute.\"},\n{\"id\":\"en21\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“It’s a sensible decision.” What does “sensible” mean?\",\"o\":[\"Rezonabil, înțelept\",\"Sensibil, emotiv\",\"Senzual\"],\"a\":0,\"h\":\"False friend.\",\"e\":\"Sensible = rezonabil. „Sensibil” în sensul de emotiv se spune sensitive.\"},\n{\"id\":\"en22\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"“How would you handle an angry customer?” Which answer is best?\",\"o\":[\"I’d listen carefully, apologize for the problem, and explain the next steps clearly.\",\"I’d tell them to calm down.\",\"I’d end the conversation as soon as possible.\"],\"a\":0,\"h\":\"Ascultă, recunoaște, propune pași.\",\"e\":\"Structură bună de răspuns: ascult, empatizez, spun clar ce fac mai departe și când revin.\"},\n{\"id\":\"en23\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"A teammate writes: “Just a heads-up: the server will restart at 6 PM.” What is it?\",\"o\":[\"A short warning in advance\",\"A request for a day off\",\"An error message\"],\"a\":0,\"h\":\"Heads-up = avertizare.\",\"e\":\"Heads-up = informare din timp, ca să nu fii luat prin surprindere.\"},\n{\"id\":\"en24\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"You didn’t hear the question well. What can you say politely?\",\"o\":[\"Sorry, could you repeat that, please?\",\"What?\",\"Say it again.\"],\"a\":0,\"h\":\"Politicos.\",\"e\":\"Alte variante: “Could you say that again?”, “Sorry, I didn’t catch that.”\"},\n{\"id\":\"en25\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"You don’t fully understand a requirement. What is a good question?\",\"o\":[\"Could you clarify what you mean by “urgent”?\",\"Your requirement is wrong.\",\"I don’t care what you mean.\"],\"a\":0,\"h\":\"Cere clarificări, fără ton acuzator.\",\"e\":\"Could you clarify... / Could you give me an example? sunt formule politicoase pentru cerințe neclare.\"},\n{\"id\":\"en26\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which verb goes with “deadline”?\",\"o\":[\"meet a deadline\",\"do a deadline\",\"win a deadline\"],\"a\":0,\"h\":\"Collocation.\",\"e\":\"Se spune meet a deadline (respecți termenul), miss a deadline (îl ratezi), extend a deadline (îl prelungești).\"},\n{\"id\":\"en27\",\"d\":\"en\",\"nou\":1,\"lng\":\"en\",\"t\":\"mc\",\"q\":\"Which sentence is correct at the end of an email?\",\"o\":[\"I look forward to hearing from you.\",\"I look forward to hear from you.\",\"I look forward hearing you.\"],\"a\":0,\"h\":\"look forward to + -ing.\",\"e\":\"În expresia look forward to, to e prepoziție, deci urmează forma cu -ing.\"}," + html.slice(e0); } } catch (e) {}
    try { const NEWQ = [{"id": "css1", "d": "web", "nou": 1, "t": "mc", "q": "Care selector are cea mai mare specificitate?", "o": ["#meniu", "div.meniu", "[type=text]"], "a": 0, "h": "ID bate clasa, clasa bate eticheta.", "e": "Ordinea specificității: inline, ID, clasă/atribut/pseudo-clasă, element. #meniu câștigă.", "px": ["Specificitatea e „greutatea” unui selector: id-ul cântărește mai mult decât clasa, clasa mai mult decât eticheta. La egalitate câștigă regula scrisă mai târziu.", "Încearcă: rulează (textul e roșu). Șterge `id=\"meniu\"` din HTML și vezi cum se schimbă culoarea."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  #meniu { color: red; }\n  div.meniu { color: green; }\n  [type=text] { color: blue; }\n</style>\n</head>\n<body>\n<div id=\"meniu\" class=\"meniu\">Ce culoare am? (id bate clasa)</div>\n<input type=\"text\" value=\"input cu atribut\" class=\"meniu\">\n</body>\n</html>\n"}}, {"id": "css2", "d": "web", "nou": 1, "t": "mc", "q": "Ce face box-sizing: border-box?", "o": ["Lățimea include padding-ul și bordura", "Lățimea include și marginile", "Elimină padding-ul"], "a": 0, "h": "Se schimbă ce înseamnă width.", "e": "Cu border-box, width și height includ conținutul, padding-ul și bordura; marginile rămân în afară.", "px": ["Cu `content-box`, `width` e doar lățimea conținutului, iar padding și bordura se adaugă. Cu `border-box`, `width` include și padding și bordura.", "Încearcă: rulează și compară cele două cutii (a doua e mai îngustă). Apasă F12 pe pagină, dacă vrei să le măsori."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  div { width: 200px; padding: 20px; border: 5px solid #333; margin: 10px; background: #e3f2fd; }\n  .bb { box-sizing: border-box; }\n</style>\n</head>\n<body>\n<div>content-box: lățime totală = 200 + 40 + 10 = 250px</div>\n<div class=\"bb\">border-box: lățime totală = 200px</div>\n</body>\n</html>\n"}}, {"id": "css3", "d": "web", "nou": 1, "t": "mc", "q": "Ce înseamnă margin collapse?", "o": ["Marginile verticale ale blocurilor vecine se contopesc în cea mai mare", "Marginile dispar dacă adaugi padding", "Marginile se adună întotdeauna"], "a": 0, "h": "Se întâmplă doar pe verticală.", "e": "Două margini verticale adiacente nu se adună, ci rămâne valoarea mai mare. Nu se aplică în flex sau grid.", "px": ["Două margini verticale care se ating se contopesc: rămâne cea mai mare (40px), nu suma (60px). În flex și grid nu se întâmplă.", "Încearcă: măsoară vizual spațiul dintre A și B în cele două cazuri."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .a { margin-bottom: 40px; background: #ffe0b2; }\n  .b { margin-top: 20px; background: #c8e6c9; }\n  .flex { display: flex; flex-direction: column; }\n</style>\n</head>\n<body>\n<h4>Bloc normal: spațiu = 40px (nu 60)</h4>\n<div class=\"a\">A</div><div class=\"b\">B</div>\n<h4>Flex: marginile se adună = 60px</h4>\n<div class=\"flex\"><div class=\"a\">A</div><div class=\"b\">B</div></div>\n</body>\n</html>\n"}}, {"id": "css4", "d": "web", "nou": 1, "t": "mc", "q": "Față de ce se poziționează un element cu position: absolute?", "o": ["Cel mai apropiat strămoș poziționat (non-static)", "Întotdeauna față de fereastra browserului", "Față de elementul anterior din pagină"], "a": 0, "h": "Caută un strămoș cu position setat.", "e": "Dacă niciun strămoș nu e poziționat, se raportează la blocul inițial. De aceea părintelui i se pune position: relative.", "px": ["Elementul absolut se măsoară față de cel mai apropiat strămoș care NU e `static`. De aceea pui `position: relative` pe părinte.", "Încearcă: șterge `position: relative` și vezi cum „zboară” spre colțul paginii."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .parinte { position: relative; width: 250px; height: 120px; background: #e3f2fd; margin: 30px; }\n  .copil { position: absolute; top: 10px; right: 10px; background: #ef9a9a; padding: 6px; }\n</style>\n</head>\n<body>\n<div class=\"parinte\">părinte (relative)<div class=\"copil\">absolut</div></div>\n</body>\n</html>\n"}}, {"id": "css5", "d": "web", "nou": 1, "t": "mc", "q": "Diferența dintre display: none și visibility: hidden?", "o": ["none scoate elementul din layout; hidden îl ascunde, dar păstrează locul", "Sunt identice", "hidden scoate elementul din layout, none păstrează locul"], "a": 0, "h": "Locul rămâne sau nu.", "e": "display:none nu ocupă spațiu și nu e citit de cititoarele de ecran. visibility:hidden păstrează spațiul.", "px": ["`display:none` scoate elementul complet din pagină (nu mai ocupă loc). `visibility:hidden` îl face invizibil, dar spațiul rămâne.", "Încearcă: observă golul lăsat de rândul 3."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .x { background: #ffcdd2; padding: 6px; margin: 6px 0; }\n</style>\n</head>\n<body>\n<div class=\"x\">Rând 1</div>\n<div class=\"x\" style=\"display:none\">Rând 2 (display:none)</div>\n<div class=\"x\" style=\"visibility:hidden\">Rând 3 (visibility:hidden)</div>\n<div class=\"x\">Rând 4</div>\n</body>\n</html>\n"}}, {"id": "css6", "d": "web", "nou": 1, "t": "mc", "q": "În flexbox, justify-content aliniază elementele pe care axă?", "o": ["Axa principală (main axis)", "Axa transversală (cross axis)", "Pe axa Z"], "a": 0, "h": "align-items e pe cealaltă axă.", "e": "justify-content = axa principală (implicit orizontală), align-items = axa transversală.", "px": ["`justify-content` lucrează pe axa principală, care e orizontală la `row` și verticală la `column`. `align-items` lucrează pe cealaltă.", "Încearcă: compară cele două cutii: în a doua, `justify-content` distribuie pe verticală."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .c { display: flex; justify-content: space-between; align-items: center; height: 120px; background: #e3f2fd; padding: 8px; }\n  .c div { background: #90caf9; padding: 10px; }\n  .col { flex-direction: column; }\n</style>\n</head>\n<body>\n<div class=\"c\"><div>1</div><div>2</div><div>3</div></div>\n<br>\n<div class=\"c col\"><div>1</div><div>2</div><div>3</div></div>\n</body>\n</html>\n"}}, {"id": "css7", "d": "web", "nou": 1, "t": "mc", "q": "Ce face grid-template-columns: repeat(3, 1fr)?", "o": ["Trei coloane egale", "Trei rânduri egale", "O coloană lată de 3 pixeli"], "a": 0, "h": "fr = fracțiune din spațiul liber.", "e": "1fr înseamnă o parte din spațiul disponibil; repeat(3, 1fr) creează trei coloane egale.", "px": ["`1fr` înseamnă „o parte din spațiul rămas”. `repeat(3, 1fr)` = trei coloane egale; `2fr 1fr 1fr` face prima coloană de două ori mai lată.", "Încearcă: schimbă `repeat(3, 1fr)` în `repeat(4, 1fr)`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .g { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }\n  .g div { background: #c5cae9; padding: 14px; text-align: center; }\n  .m { grid-template-columns: 2fr 1fr 1fr; margin-top: 16px; }\n</style>\n</head>\n<body>\n<div class=\"g\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div></div>\n<div class=\"g m\"><div>2fr</div><div>1fr</div><div>1fr</div></div>\n</body>\n</html>\n"}}, {"id": "css8", "d": "web", "nou": 1, "t": "mc", "q": "La ce se raportează unitatea rem?", "o": ["La font-size-ul elementului rădăcină (html)", "La font-size-ul părintelui", "La lățimea ecranului"], "a": 0, "h": "em e relativ la părinte.", "e": "rem e relativ la html, deci scalarea e previzibilă; em se compune în cascadă.", "px": ["`rem` se raportează la `font-size` de pe `html`. `em` se raportează la fontul părintelui, deci se poate „compune” în interiorul altor elemente.", "Încearcă: schimbă `html { font-size }` și vezi cum se scalează totul în rem."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  html { font-size: 20px; }\n  .rem { font-size: 1.5rem; }       /* 1.5 x 20 = 30px */\n  .em { font-size: 1.5em; }         /* 1.5 x fontul parintelui */\n  .p { font-size: 10px; }\n</style>\n</head>\n<body>\n<p class=\"rem\">rem: 30px</p>\n<div class=\"p\"><p class=\"em\">em: 1.5 × 10px = 15px</p><p class=\"rem\">rem: tot 30px</p></div>\n</body>\n</html>\n"}}, {"id": "css9", "d": "web", "nou": 1, "t": "mc", "q": "Când are efect z-index?", "o": ["Pe elemente poziționate (și pe copii de flex/grid)", "Pe orice element, oricând", "Doar pe imagini"], "a": 0, "h": "Pe un element static nu face nimic.", "e": "Fără position (sau fără a fi item flex/grid), z-index e ignorat. Contează și contextele de stivuire.", "px": ["`z-index` funcționează doar pe elemente poziționate (și pe copii de flex/grid). Pe `.a` (static) nu are efect, deci `.b` poziționat apare deasupra.", "Încearcă: adaugă `position: relative` la `.a` și vezi cum trece peste `.b`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .a, .b { width: 140px; height: 90px; padding: 8px; }\n  .a { background: #ef9a9a; z-index: 10; }\n  .b { background: #90caf9; margin-top: -40px; margin-left: 40px; }\n  .poz { position: relative; }\n</style>\n</head>\n<body>\n<div class=\"a\">z-index:10 pe element nepoziționat: nu are efect</div>\n<div class=\"b poz\">b (relative)</div>\n</body>\n</html>\n"}}, {"id": "css10", "d": "web", "nou": 1, "t": "mc", "q": "Ce selectează li:nth-child(2n)?", "o": ["Elementele li de pe poziții pare", "Elementele li de pe poziții impare", "Doar al doilea li"], "a": 0, "h": "2n = 2, 4, 6...", "e": "2n înseamnă pare; 2n+1 sau odd înseamnă impare.", "px": ["`2n` înseamnă „fiecare al doilea” (2, 4, 6...). Ai și `odd`, `even`, `3n+1`.", "Încearcă: schimbă în `li:nth-child(3n+1)`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  li:nth-child(2n) { background: #c8e6c9; }\n  li:nth-child(3) { font-weight: bold; }\n</style>\n</head>\n<body>\n<ul><li>1</li><li>2</li><li>3</li><li>4</li><li>5</li><li>6</li></ul>\n</body>\n</html>\n"}}, {"id": "css11", "d": "web", "nou": 1, "t": "mc", "q": "Care e un pseudo-element?", "o": ["::before", "::hover", "::checked"], "a": 0, "h": "Se scrie cu două puncte.", "e": "::before și ::after creează conținut generat. :hover și :checked sunt pseudo-clase.", "px": ["Pseudo-elementul (`::before`) creează o „piesă” nouă, care nu există în HTML. Pseudo-clasa (`:hover`) descrie o STARE a unui element existent.", "Încearcă: schimbă textul din `content`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .eticheta::before { content: \"★ \"; color: orange; }\n  .eticheta::after { content: \" (nou)\"; color: gray; }\n  a:hover { color: red; }  /* pseudo-clasa, cu un singur : */\n</style>\n</head>\n<body>\n<p class=\"eticheta\">Produs</p>\n<a href=\"#\">pune mouse-ul peste mine</a>\n</body>\n</html>\n"}}, {"id": "css12", "d": "web", "nou": 1, "t": "mc", "q": "Când se aplică @media (max-width: 600px)?", "o": ["Când fereastra are cel mult 600px lățime", "Când fereastra are cel puțin 600px", "Doar la imprimare"], "a": 0, "h": "max = limită superioară.", "e": "max-width se potrivește la ecrane mai înguste sau egale cu valoarea (abordare desktop-first).", "px": ["Regulile din `@media (max-width: 600px)` se aplică doar când fereastra e de cel mult 600px lățime.", "Încearcă: trage de marginea ferestrei sau folosește F12 → mod mobil."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  body { background: #e3f2fd; }\n  @media (max-width: 600px) { body { background: #ffcdd2; } }\n</style>\n</head>\n<body>\n<p>Micșorează fereastra sub 600px: fundalul devine roșu.</p>\n</body>\n</html>\n"}}, {"id": "css13", "d": "web", "nou": 1, "t": "mc", "q": "Ce face object-fit: cover pe o imagine?", "o": ["Umple containerul, păstrând proporțiile, și taie excesul", "Întinde imaginea fără să țină cont de proporții", "Micșorează imaginea ca să încapă întreagă"], "a": 0, "h": "Ca background-size: cover.", "e": "contain păstrează imaginea întreagă; cover umple cutia și taie ce depășește.", "px": ["`cover` umple cutia păstrând proporțiile și taie ce depășește. `contain` o încape întreagă (pot rămâne margini). `fill` o întinde, deformând-o.", "Încearcă: schimbă `placehold.co/400x200` în `200x400`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .c { width: 200px; height: 100px; background: #eee; border: 1px solid #999; display: inline-block; margin: 8px; }\n  .c img { width: 100%; height: 100%; }\n  .cover { object-fit: cover; } .contain { object-fit: contain; } .fill { object-fit: fill; }\n</style>\n</head>\n<body>\n<div class=\"c\"><img class=\"cover\" src=\"https://placehold.co/400x200/png\" alt=\"\">cover</div>\n<div class=\"c\"><img class=\"contain\" src=\"https://placehold.co/400x200/png\" alt=\"\">contain</div>\n<div class=\"c\"><img class=\"fill\" src=\"https://placehold.co/400x200/png\" alt=\"\">fill</div>\n</body>\n</html>\n"}}, {"id": "css14", "d": "web", "nou": 1, "t": "mc", "q": "De ce se evită !important?", "o": ["Rupe cascada și face stilurile greu de suprascris", "Nu funcționează în Chrome", "Încetinește randarea"], "a": 0, "h": "E ultimul argument, nu prima soluție.", "e": "!important ocolește specificitatea; singura cale de suprascriere devine un alt !important mai specific.", "px": ["`!important` ocolește regulile normale de cascadă, deci apoi poți suprascrie doar cu alt `!important` și mai specific. Duce repede la „războaie de specificitate”.", "Încearcă: șterge `!important` și vezi că devine albastru."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .buton { color: green; }\n  #meniu .buton { color: blue; }       /* specificitate mai mare */\n  .buton { color: red !important; }    /* bate tot, dar e greu de suprascris */\n</style>\n</head>\n<body>\n<div id=\"meniu\"><span class=\"buton\">Ce culoare am?</span></div>\n</body>\n</html>\n"}}, {"id": "ht1", "d": "web", "nou": 1, "t": "mc", "q": "De ce se adaugă rel=\"noopener\" la un link cu target=\"_blank\"?", "o": ["Pagina deschisă nu primește acces la window.opener", "Link-ul se încarcă mai repede", "Se blochează cookie-urile"], "a": 0, "h": "Securitate.", "e": "Fără el, pagina nouă poate manipula pagina de origine prin window.opener. Browserele moderne îl aplică implicit.", "px": ["Cu `target=\"_blank\"`, pagina nouă poate primi `window.opener`, adică o legătură înapoi către pagina ta, și o poate redirecționa. `rel=\"noopener\"` taie legătura. Browserele moderne o aplică implicit, dar e bine să o scrii."]}, {"id": "ht2", "d": "web", "nou": 1, "t": "mc", "q": "La ce folosește atributul alt la <img>?", "o": ["Text alternativ pentru accesibilitate și când imaginea nu se încarcă", "Titlul care apare la hover", "Dimensiunea imaginii"], "a": 0, "h": "Cititoarele de ecran îl citesc.", "e": "alt descrie imaginea; pentru imagini decorative se folosește alt=\"\".", "px": ["`alt` e „descrierea în cuvinte” a imaginii: pentru oameni care nu o văd, pentru motoarele de căutare și când fișierul lipsește.", "Încearcă: rulează (imaginea e greșită intenționat) și citește textul care apare în loc."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>img{border:1px solid #999}</style>\n</head>\n<body>\n<img src=\"imagine-care-nu-exista.png\" alt=\"Logo-ul companiei, text alternativ\" width=\"300\">\n<p>Textul din <code>alt</code> apare când imaginea nu se încarcă și îl citesc cititoarele de ecran.</p>\n</body>\n</html>\n"}}, {"id": "ht3", "d": "web", "nou": 1, "t": "mc", "q": "Care e elementul semantic pentru meniul principal de navigare?", "o": ["<nav>", "<menu-div>", "<header-list>"], "a": 0, "h": "Semantic înseamnă cu sens.", "e": "<nav> marchează blocurile de navigare; alături: header, main, footer, article, section.", "px": ["Elementele semantice spun ce e conținutul, nu doar cum arată. `<nav>` marchează blocul cu linkurile principale; cititoarele de ecran și motoarele de căutare îl recunosc."]}, {"id": "ht4", "d": "web", "nou": 1, "t": "mc", "q": "Diferența dintre defer și async la <script>?", "o": ["defer: rulează după parsarea paginii, în ordine; async: rulează imediat ce se descarcă, fără ordine garantată", "Sunt identice", "async păstrează ordinea, defer nu"], "a": 0, "h": "Ordinea de execuție.", "e": "defer e potrivit pentru scripturi dependente între ele; async pentru scripturi independente (ex. analytics).", "px": ["Fără atribute, scriptul oprește pagina până se descarcă și rulează. `defer` așteaptă să se termine HTML-ul, `async` rulează imediat ce e gata.", "Încearcă: deschide consola și vezi ordinea mesajelor."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script>console.log(\"scriptul inline rulează imediat\");</script>\n</head>\n<body>\n<p>Pagina se parsează; scripturile cu <code>defer</code> rulează DUPĂ parsare, în ordine, iar cele cu <code>async</code> rulează imediat ce se descarcă (ordine neprevizibilă).</p>\n<script defer>console.log(\"defer: după ce pagina e gata\");</script>\n<script async>console.log(\"async: când apuc\");</script>\n</body>\n</html>\n"}}, {"id": "ht5", "d": "web", "nou": 1, "t": "mc", "q": "Ce face for=\"email\" la un <label>?", "o": ["Leagă eticheta de elementul cu id=\"email\"", "Validează adresa de email", "Trimite formularul"], "a": 0, "h": "Click pe etichetă focusează câmpul.", "e": "Asocierea label-input îmbunătățește accesibilitatea și mărește zona de click.", "px": ["`for` leagă eticheta de câmpul cu același `id`. Când apeși pe text, cursorul intră în câmp, iar cititoarele de ecran citesc eticheta.", "Încearcă: apasă pe textul „Email”."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n</head>\n<body>\n<label for=\"email\">Email (apasă pe text)</label><br>\n<input id=\"email\" type=\"email\" placeholder=\"ana@exemplu.ro\">\n</body>\n</html>\n"}}, {"id": "ht6", "d": "web", "nou": 1, "t": "mc", "q": "Ce sunt atributele data-*?", "o": ["Atribute personalizate pentru date, citibile din JS prin dataset", "Atribute pentru baze de date", "Atribute obligatorii la formulare"], "a": 0, "h": "Ex. data-id=\"5\".", "e": "element.dataset.id citește valoarea. Utile și pentru selectori de test (data-testid).", "px": ["Atributele `data-*` sunt „etichete” proprii pe care le citești din JavaScript prin `dataset`. `data-produs-id` devine `dataset.produsId`.", "Încearcă: apasă butonul."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n</head>\n<body>\n<button id=\"b\" data-produs-id=\"42\" data-culoare=\"roșu\">Citește data-*</button>\n<p id=\"r\">...</p>\n<script>\n  document.getElementById(\"b\").addEventListener(\"click\", e => {\n    const d = e.target.dataset;           // data-produs-id -> produsId\n    document.getElementById(\"r\").textContent = d.produsId + \" / \" + d.culoare;\n  });\n</script>\n</body>\n</html>\n"}}, {"id": "ht7", "d": "web", "nou": 1, "t": "mc", "q": "La ce folosește meta name=\"viewport\"?", "o": ["Controlează lățimea și scalarea paginii pe mobil", "Setează limba paginii", "Adaugă cuvinte-cheie SEO"], "a": 0, "h": "Fără el, pagina apare micșorată pe telefon.", "e": "Valoarea uzuală: width=device-width, initial-scale=1.", "px": ["Meta viewport spune telefonului „folosește lățimea reală a ecranului”. Fără el, browserul mobil presupune ~980px și micșorează pagina.", "Încearcă: F12 → mod mobil, apoi scoate și pune meta."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n</head>\n<body>\n<p style=\"font-size:2rem\">Deschide pagina pe telefon cu și fără <code>&lt;meta name=\"viewport\"&gt;</code>. Fără ea, mobilul o desenează ca pe desktop și o micșorează.</p>\n</body>\n</html>\n"}}, {"id": "ht8", "d": "web", "nou": 1, "t": "mc", "q": "Ce face <!DOCTYPE html>?", "o": ["Pornește browserul în modul standard, nu în quirks mode", "Încarcă un framework", "Setează tipul de codificare"], "a": 0, "h": "Prima linie din document.", "e": "Fără doctype, browserul poate interpreta CSS-ul după reguli vechi (quirks mode).", "px": ["`<!DOCTYPE html>` pune browserul în modul standard. Fără el intră în „quirks mode”, cu comportamente vechi la dimensiuni și layout.", "Încearcă: rulează (apare `CSS1Compat`). În exemplul fără DOCTYPE ar fi `BackCompat`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n</head>\n<body>\n<p>Fără <code>&lt;!DOCTYPE html&gt;</code> pagina intră în „quirks mode” (reguli vechi).</p>\n<script>document.write(\"Mod curent: \" + document.compatMode);</script>\n</body>\n</html>\n"}}, {"id": "js1", "d": "web", "nou": 1, "t": "mc", "q": "Diferența dintre == și ===?", "o": ["=== compară valoarea și tipul; == face conversii de tip", "Sunt identice", "== compară și tipul, === nu"], "a": 0, "h": "Strict vs lax.", "e": "'5' == 5 e true, '5' === 5 e false. Se preferă ===.", "px": ["`==` încearcă să convertească tipurile înainte să compare, ceea ce dă rezultate surprinzătoare. `===` compară și valoarea, și tipul.", "Regula simplă: folosește `===`.", "Încearcă: prezice fiecare rezultat înainte să rulezi."], "tr": {"l": "javascript", "c": "console.log(0 == \"0\", 0 === \"0\");        // true false\nconsole.log(null == undefined, null === undefined); // true false\nconsole.log(\"\" == 0, [] == false);       // true true\nconsole.log(NaN == NaN, Object.is(NaN, NaN));\n"}}, {"id": "js2", "d": "web", "nou": 1, "t": "mc", "q": "Ce întoarce typeof null?", "o": ["\"object\"", "\"null\"", "\"undefined\""], "a": 0, "h": "O ciudățenie istorică.", "e": "E o eroare veche rămasă din limbaj; null se verifică cu === null.", "px": ["`typeof null` dă `\"object\"` dintr-o greșeală din primele versiuni de JavaScript, păstrată pentru compatibilitate.", "Pentru `null` verifici `x === null`, iar pentru array `Array.isArray`.", "Încearcă: rulează și compară."], "tr": {"l": "javascript", "c": "console.log(typeof null);        // \"object\" (bug istoric)\nconsole.log(typeof undefined);   // \"undefined\"\nconsole.log(typeof []);          // \"object\"\nconsole.log(Array.isArray([]));  // true\nconsole.log(typeof (() => 1));   // \"function\"\n"}}, {"id": "js3", "d": "web", "nou": 1, "t": "mc", "q": "Diferența de scope dintre var și let?", "o": ["var: la nivel de funcție; let: la nivel de bloc", "Sunt identice", "let: la nivel de funcție; var: la nivel de bloc"], "a": 0, "h": "Acolade.", "e": "let și const sunt limitate la blocul {...}; var iese din blocuri (hoisting).", "px": ["`var` are scope de funcție, `let` are scope de bloc (`{ }`). De aceea în bucla cu `var` toate cele trei `setTimeout` văd același `i`, deja 3.", "Încearcă: rulează și compară ce afișează cele două bucle."], "tr": {"l": "javascript", "c": "if (true) { var v = 1; let l = 2; }\nconsole.log(v);                       // 1: var iese din bloc\ntry { console.log(l); } catch (e) { console.log(\"let:\", e.name); }\n\nfor (var i = 0; i < 3; i++) setTimeout(() => console.log(\"var\", i));   // 3 3 3\nfor (let k = 0; k < 3; k++) setTimeout(() => console.log(\"let\", k));   // 0 1 2\n"}}, {"id": "js4", "d": "web", "nou": 1, "t": "mc", "q": "Ce e un closure?", "o": ["O funcție care își păstrează accesul la variabilele din scope-ul în care a fost creată", "O funcție fără parametri", "Un fel de buclă"], "a": 0, "h": "Funcția își amintește mediul.", "e": "Contoarele și funcțiile fabrică se bazează pe closure.", "px": ["Un closure e o funcție care „ține minte” variabilele din locul unde a fost creată, chiar după ce funcția exterioară s-a terminat.", "Fiecare apel al lui `contor()` creează propriul `n`.", "Încearcă: rulează și vezi că `a` și `b` numără separat."], "tr": {"l": "javascript", "c": "function contor() {\n  let n = 0;\n  return function () { n++; return n; };\n}\nconst a = contor(), b = contor();\nconsole.log(a(), a(), a());   // 1 2 3\nconsole.log(b());            // 1: alt contor, alta variabila n\n"}}, {"id": "js5", "d": "web", "nou": 1, "t": "mc", "q": "Ce face Promise.all dacă una dintre promisiuni e respinsă?", "o": ["Se respinge imediat cu acea eroare", "Așteaptă toate și întoarce doar succesele", "Ignoră eroarea"], "a": 0, "h": "Pentru rezultate parțiale există allSettled.", "e": "Promise.allSettled întoarce starea fiecărei promisiuni, fără a se opri la prima eroare.", "px": ["`Promise.all` e „totul sau nimic”: dacă una e respinsă, tot rezultatul e respins, imediat. `allSettled` așteaptă toate și îți spune cum s-a terminat fiecare.", "Încearcă: rulează și compară cele două mesaje."], "tr": {"l": "javascript", "c": "const ok = new Promise(r => setTimeout(() => r(\"ok\"), 100));\nconst rau = new Promise((_, rej) => setTimeout(() => rej(new Error(\"a picat\")), 50));\n\nPromise.all([ok, rau])\n  .then(v => console.log(\"toate:\", v))\n  .catch(e => console.log(\"all respins imediat:\", e.message));\n\nPromise.allSettled([ok, rau]).then(r => console.log(r.map(x => x.status)));\n"}}, {"id": "js6", "d": "web", "nou": 1, "t": "mc", "q": "Ce e event delegation?", "o": ["Un singur listener pe părinte, care prinde evenimentele copiilor (bubbling)", "Atașarea câte unui listener fiecărui copil", "Ștergerea evenimentelor"], "a": 0, "h": "Se bazează pe bubbling.", "e": "Verifici event.target. Funcționează și pentru elemente adăugate ulterior.", "px": ["Delegation: pui UN singur listener pe părinte. Evenimentele copiilor „urcă” (bubbling), iar tu verifici `e.target`. Merge și pentru elemente adăugate mai târziu.", "Încearcă: apasă pe elementele din listă dacă apar în pagină."], "tr": {"l": "javascript", "c": "// simulare: parintele prinde evenimentul copiilor (bubbling)\nconst lista = document.createElement(\"ul\");\nlista.innerHTML = \"<li>A</li><li>B</li>\";\nlista.addEventListener(\"click\", e => {\n  if (e.target.matches(\"li\")) console.log(\"click pe\", e.target.textContent);\n});\ndocument.body.appendChild(lista);\n\nconst nou = document.createElement(\"li\");   // adaugat ULTERIOR, tot merge\nnou.textContent = \"C (nou)\";\nlista.appendChild(nou);\nnou.click();\nlista.children[0].click();\n"}}, {"id": "js7", "d": "web", "nou": 1, "t": "mc", "q": "Diferența dintre map și forEach?", "o": ["map întoarce un array nou; forEach nu întoarce nimic", "map modifică array-ul original", "forEach întoarce array nou"], "a": 0, "h": "Care întoarce ceva?", "e": "Folosești map pentru transformări și forEach pentru efecte laterale.", "px": ["`map` produce un array nou cu rezultatele. `forEach` doar parcurge și nu întoarce nimic.", "Încearcă: rulează."], "tr": {"l": "javascript", "c": "const nr = [1, 2, 3];\nconst dublat = nr.map(x => x * 2);\nconst r = nr.forEach(x => x * 2);\nconsole.log(dublat);   // [2, 4, 6]\nconsole.log(r);        // undefined\n"}}, {"id": "js8", "d": "web", "nou": 1, "t": "mc", "q": "De ce 0.1 + 0.2 === 0.3 este false?", "o": ["Numerele zecimale sunt în virgulă mobilă binară și apar mici erori de rotunjire", "E un bug de browser", "JavaScript nu știe să adune zecimale"], "a": 0, "h": "IEEE 754.", "e": "Se compară cu o toleranță sau se lucrează în unități întregi (bani în bani, nu în lei cu zecimale).", "px": ["Calculatorul reprezintă numerele în binar, iar `0.1` nu are scriere exactă (ca `1/3` în zecimal). Rămâne o eroare mică.", "Compari cu o toleranță sau lucrezi în „bani întregi” (bani).", "Încearcă: rulează și vezi toate cifrele."], "tr": {"l": "javascript", "c": "console.log(0.1 + 0.2);                 // 0.30000000000000004\nconsole.log(0.1 + 0.2 === 0.3);          // false\nconsole.log(Math.abs(0.1 + 0.2 - 0.3) < Number.EPSILON);  // true\nconsole.log((0.1 + 0.2).toFixed(2));     // \"0.30\"\nconsole.log(0.1 * 3, 1.1 + 2.2);\n"}}, {"id": "js9", "d": "web", "nou": 1, "t": "mc", "q": "Cum tratează o arrow function pe this?", "o": ["Preia this din scope-ul înconjurător, nu are this propriu", "Are mereu this = window", "Are this = funcția însăși"], "a": 0, "h": "Lexical.", "e": "De aceea arrow functions sunt comode în callback-uri, dar nepotrivite ca metode de obiect.", "px": ["O arrow function nu are `this` propriu; îl ia din locul unde e scrisă. De aceea nu o folosești ca metodă de obiect, dar e perfectă în callback-uri.", "Încearcă: schimbă `sageata` să returneze `this.nume`."], "tr": {"l": "javascript", "c": "const obj = {\n  nume: \"Ana\",\n  clasica: function () { return this.nume; },\n  sageata: () => typeof this,        // this din exterior, nu obj\n  intr_o_metoda() { return [1].map(() => this.nume)[0]; }   // sageata preia this-ul metodei\n};\nconsole.log(obj.clasica());           // \"Ana\"\nconsole.log(obj.sageata());           // nu e obj\nconsole.log(obj.intr_o_metoda());     // \"Ana\"\n"}}, {"id": "js10", "d": "web", "nou": 1, "t": "mc", "q": "Ce întoarce [\"1\",\"2\",\"3\"].map(parseInt)?", "o": ["[1, NaN, NaN]", "[1, 2, 3]", "[NaN, NaN, NaN]"], "a": 0, "h": "map trimite și indexul.", "e": "parseInt primește (valoare, index): al doilea argument devine baza numerică.", "px": ["`map` dă funcției trei argumente: valoarea, indexul, array-ul. `parseInt` folosește al doilea argument ca bază de numerație: `parseInt('2', 1)` și `parseInt('3', 2)` dau `NaN`.", "Soluții: `x => parseInt(x)` sau `Number`.", "Încearcă: rulează toate trei."], "tr": {"l": "javascript", "c": "console.log([\"1\", \"2\", \"3\"].map(parseInt));       // [1, NaN, NaN]\nconsole.log([\"1\", \"2\", \"3\"].map(x => parseInt(x)));  // [1, 2, 3]\nconsole.log([\"1\", \"2\", \"3\"].map(Number));            // [1, 2, 3]\n"}}, {"id": "js11", "d": "web", "nou": 1, "t": "mc", "q": "Diferența dintre localStorage și sessionStorage?", "o": ["localStorage persistă între sesiuni; sessionStorage dispare la închiderea tab-ului", "Sunt identice", "sessionStorage persistă mai mult"], "a": 0, "h": "Durata de viață.", "e": "Ambele sunt per origine și stochează doar șiruri de caractere.", "px": ["`localStorage` păstrează datele între sesiuni, `sessionStorage` doar cât ține tab-ul deschis. Ambele stochează doar text.", "Încearcă: rulează, apoi redeschide pagina."], "tr": {"l": "javascript", "c": "localStorage.setItem(\"persistent\", \"ramane la inchiderea tab-ului\");\nsessionStorage.setItem(\"sesiune\", \"dispare cand inchizi tab-ul\");\nconsole.log(localStorage.getItem(\"persistent\"));\nconsole.log(sessionStorage.getItem(\"sesiune\"));\nconsole.log(localStorage.length, sessionStorage.length);\n"}}, {"id": "js12", "d": "web", "nou": 1, "t": "mc", "q": "Ce face user?.profile?.name?", "o": ["Întoarce undefined dacă user sau profile sunt null/undefined, fără eroare", "Aruncă mereu o eroare", "Creează obiectul user"], "a": 0, "h": "Optional chaining.", "e": "Se oprește la primul null/undefined. Se combină cu ?? pentru valoare implicită.", "px": ["`?.` oprește lanțul și dă `undefined` dacă o parte e `null`/`undefined`, în loc de eroare. `??` oferă o valoare implicită doar pentru `null`/`undefined`.", "Încearcă: rulează și compară `??` cu `||`."], "tr": {"l": "javascript", "c": "const user = { profile: null };\nconsole.log(user?.profile?.name);       // undefined, fara eroare\nconsole.log(user.profile?.name ?? \"anonim\");\ntry { console.log(user.profile.name); } catch (e) { console.log(\"eroare:\", e.message); }\nconsole.log(0 ?? \"implicit\", 0 || \"implicit\");   // ?? doar pentru null/undefined\n"}}, {"id": "js13", "d": "web", "nou": 1, "t": "mc", "q": "Cum prinzi o eroare dintr-un await?", "o": ["Cu try/catch în jurul await-ului", "Nu se poate", "Cu if după await"], "a": 0, "h": "Ca la cod sincron.", "e": "Alternativ: promise.catch(...).", "px": ["`await` face o promisiune respinsă să arunce o eroare normală în acel loc, deci o prinzi cu `try/catch`.", "Încearcă: scoate `try/catch` și vezi eroarea neprinsă."], "tr": {"l": "javascript", "c": "async function ia() {\n  await new Promise(r => setTimeout(r, 50));\n  throw new Error(\"a picat serverul\");\n}\nasync function main() {\n  try {\n    await ia();\n  } catch (e) {\n    console.log(\"prins:\", e.message);\n  } finally {\n    console.log(\"finally\");\n  }\n}\nmain();\n"}}, {"id": "js14", "d": "web", "nou": 1, "t": "mc", "q": "Ce copie face spread-ul {...obj}?", "o": ["Superficială (shallow): obiectele imbricate rămân partajate", "Profundă (deep)", "Nu face nicio copie"], "a": 0, "h": "Obiectele interioare sunt aceleași.", "e": "Pentru copie profundă: structuredClone(obj).", "px": ["Spread-ul copiază doar nivelul de sus. Obiectele din el rămân aceleași, partajate.", "Pentru copie completă: `structuredClone(obj)`.", "Încearcă: rulează și urmărește `a.adresa.oras`."], "tr": {"l": "javascript", "c": "const a = { nume: \"Ana\", adresa: { oras: \"Cluj\" } };\nconst b = { ...a };\nb.nume = \"Bob\";\nb.adresa.oras = \"Iasi\";\nconsole.log(a.nume, a.adresa.oras);         // Ana Iasi  (adresa e partajata)\nconst c = structuredClone(a);\nc.adresa.oras = \"Brasov\";\nconsole.log(a.adresa.oras);                  // Iasi\n"}}, {"id": "gi1", "d": "tools", "nou": 1, "t": "mc", "q": "Diferența dintre git fetch și git pull?", "o": ["fetch doar descarcă; pull = fetch + merge", "Sunt identice", "pull doar descarcă"], "a": 0, "h": "Unul schimbă și branch-ul local.", "e": "fetch îți lasă controlul; pull integrează imediat modificările.", "px": ["`git fetch` e ca și cum ai verifica poșta: vezi ce a apărut nou pe server, dar nu schimbă nimic în fișierele tale.", "`git pull` face două lucruri la rând: `fetch` și apoi `merge` în branch-ul curent. De aceea poate produce conflicte, iar `fetch` nu."]}, {"id": "gi2", "d": "tools", "nou": 1, "t": "mc", "q": "Ce păstrează git revert față de git reset --hard?", "o": ["revert creează un commit nou care anulează; istoricul rămâne", "revert șterge istoricul", "Sunt identice"], "a": 0, "h": "Sigur pe branch-uri partajate.", "e": "reset rescrie istoricul, deci e riscant după push.", "px": ["`git revert` nu șterge nimic din istoric: adaugă un commit nou care face exact opusul unui commit vechi. E varianta sigură pentru ce e deja publicat.", "`git reset --hard` mută branch-ul înapoi și aruncă modificările. Pe un branch partajat strică istoricul celorlalți."]}, {"id": "gi3", "d": "tools", "nou": 1, "t": "mc", "q": "Ce face git stash?", "o": ["Pune temporar modificările necomise deoparte", "Șterge definitiv modificările", "Trimite modificările pe server"], "a": 0, "h": "Dulap temporar.", "e": "Recuperezi cu git stash pop sau git stash apply.", "px": ["`git stash` pune modificările necomise într-un sertar, iar directorul de lucru revine curat. Util când trebuie să schimbi urgent branch-ul.", "Le readuci cu `git stash pop`."]}, {"id": "gi4", "d": "tools", "nou": 1, "t": "mc", "q": "Un fișier e deja urmărit de Git. Îl adaugi în .gitignore. Ce se întâmplă?", "o": ["Rămâne urmărit până îl scoți din index (git rm --cached)", "Dispare automat din repo", "Git dă eroare"], "a": 0, "h": ".gitignore afectează doar fișierele neurmărite.", "e": "Folosești git rm --cached fișier, apoi commit.", "px": [".gitignore se aplică doar fișierelor care NU sunt încă urmărite. Dacă Git le urmărește deja, le urmărește în continuare.", "Ca să le scoți din urmărire fără să le ștergi de pe disc: `git rm --cached fisier`, apoi commit."]}, {"id": "gi5", "d": "tools", "nou": 1, "t": "mc", "q": "La ce folosește git cherry-pick?", "o": ["Aplică pe branch-ul curent un singur commit ales din alt branch", "Șterge un branch", "Combină toate commit-urile într-unul"], "a": 0, "h": "Un commit ales.", "e": "Util pentru a aduce rapid o reparație în alt branch.", "px": ["`git cherry-pick <commit>` copiază un singur commit din alt branch peste branch-ul curent, ca un „copy-paste” de modificare.", "Se creează un commit nou, cu alt hash, dar cu aceeași modificare."]}, {"id": "gi6", "d": "tools", "nou": 1, "t": "mc", "q": "Ce diferență principală e între merge și rebase?", "o": ["merge păstrează istoricul și creează un commit de îmbinare; rebase mută commit-urile peste altă bază, rezultând istoric liniar", "Sunt identice", "rebase șterge commit-urile"], "a": 0, "h": "Nu rescrie istoricul public.", "e": "Regula: nu face rebase pe commit-uri deja publicate și folosite de alții.", "px": ["`merge` leagă două istorii și lasă un commit de îmbinare: istoricul reflectă ce s-a întâmplat de fapt.", "`rebase` ia commit-urile tale și le rescrie ca și cum ai fi pornit de la vârful celuilalt branch: istoric liniar, dar cu hash-uri noi. Nu da rebase pe commit-uri deja publicate și folosite de alții."]}, {"id": "sq1", "d": "sql", "nou": 1, "t": "mc", "q": "Diferența dintre INNER JOIN și LEFT JOIN?", "o": ["INNER: doar rândurile cu corespondent în ambele tabele; LEFT: toate rândurile din stânga, chiar fără corespondent", "Sunt identice", "LEFT JOIN întoarce doar rândurile fără corespondent"], "a": 0, "h": "Ce se întâmplă cu rândurile fără pereche.", "e": "La LEFT JOIN, coloanele din dreapta sunt NULL când nu există potrivire.", "px": ["`INNER JOIN` păstrează doar perechile care se potrivesc. `LEFT JOIN` păstrează toate rândurile din tabelul din stânga și completează cu NULL unde nu găsește pereche.", "Exemplu: clienți și comenzi. Cu `LEFT JOIN` vezi și clienții fără nicio comandă."]}, {"id": "sq2", "d": "sql", "nou": 1, "t": "mc", "q": "Diferența dintre WHERE și HAVING?", "o": ["WHERE filtrează rânduri înainte de grupare; HAVING filtrează grupuri după GROUP BY", "Sunt identice", "HAVING filtrează înainte de grupare"], "a": 0, "h": "Înainte sau după agregare.", "e": "HAVING COUNT(*) > 1 e un exemplu clasic, de exemplu pentru găsirea duplicatelor.", "px": ["Ordinea contează: întâi `WHERE` taie rândurile, apoi `GROUP BY` le grupează, apoi `HAVING` taie grupurile.", "De aceea `HAVING COUNT(*) > 5` merge, iar `WHERE COUNT(*) > 5` dă eroare: la momentul `WHERE` grupurile nu există încă."]}, {"id": "sq3", "d": "sql", "nou": 1, "t": "mc", "q": "Diferența dintre COUNT(*) și COUNT(coloana)?", "o": ["COUNT(coloana) ignoră valorile NULL", "COUNT(*) ignoră NULL", "Sunt mereu egale"], "a": 0, "h": "NULL nu se numără.", "e": "COUNT(*) numără rândurile; COUNT(col) numără doar valorile nenule.", "px": ["`COUNT(*)` numără rândurile. `COUNT(coloana)` numără doar rândurile în care coloana NU e NULL.", "Dacă 10 rânduri au 3 NULL-uri în `email`, `COUNT(*)` dă 10 și `COUNT(email)` dă 7."]}, {"id": "sq4", "d": "sql", "nou": 1, "t": "mc", "q": "Ce întoarce WHERE col = NULL?", "o": ["Niciun rând: pentru NULL se folosește IS NULL", "Rândurile unde col e NULL", "O eroare de sintaxă"], "a": 0, "h": "NULL nu e egal cu nimic, nici cu el însuși.", "e": "Corect: WHERE col IS NULL sau IS NOT NULL.", "px": ["NULL înseamnă „necunoscut”, iar `NULL = NULL` nu e adevărat, ci tot necunoscut. WHERE păstrează doar rândurile cu rezultat adevărat, deci nu iese nimic.", "Corect: `WHERE col IS NULL`."]}, {"id": "sq5", "d": "sql", "nou": 1, "t": "mc", "q": "La ce folosește un index?", "o": ["Accelerează căutările, dar încetinește ușor scrierile și ocupă spațiu", "Face baza de date mai mică", "Criptează datele"], "a": 0, "h": "Costuri și beneficii.", "e": "Indexezi coloanele folosite des în WHERE, JOIN și ORDER BY.", "px": ["Indexul e cuprinsul unei cărți: găsești repede pagina, fără să răsfoiești tot. Dar cuprinsul trebuie actualizat la fiecare modificare, deci INSERT/UPDATE devin puțin mai lente și ocupă spațiu."]}, {"id": "sq6", "d": "sql", "nou": 1, "t": "mc", "q": "Diferența dintre DELETE și TRUNCATE?", "o": ["DELETE poate avea WHERE și e logat rând cu rând; TRUNCATE golește tot tabelul rapid", "Sunt identice", "TRUNCATE are WHERE"], "a": 0, "h": "Cu filtru sau fără.", "e": "TRUNCATE de obicei resetează și contorul de auto-increment.", "px": ["`DELETE` poate avea `WHERE` și șterge rând cu rând (poate fi anulat într-o tranzacție). `TRUNCATE` golește tot tabelul rapid, fără WHERE.", "Detaliile (rollback, resetarea contorului) diferă de la o bază de date la alta."]}, {"id": "wx1", "d": "wpadm", "nou": 1, "t": "mc", "q": "Diferența dintre add_action și add_filter?", "o": ["Action execută cod la un moment dat; filter primește o valoare, o modifică și o returnează", "Sunt identice", "Filter nu poate fi folosit în teme"], "a": 0, "h": "Filter returnează ceva.", "e": "Funcția unui filtru trebuie să returneze valoarea, altfel o pierzi.", "px": ["`add_action` înseamnă „când se întâmplă X, rulează funcția mea”. Nu returnează nimic.", "`add_filter` înseamnă „ia o valoare, schimb-o și dă-mi-o înapoi”, de exemplu titlul unui articol. Funcția de filtru trebuie să returneze valoarea."]}, {"id": "wx2", "d": "wpadm", "nou": 1, "t": "mc", "q": "Cum încarci corect un script JS într-o temă sau plugin?", "o": ["Cu wp_enqueue_script, într-un hook wp_enqueue_scripts", "Cu <script> scris direct în header.php", "Cu include în wp-config.php"], "a": 0, "h": "WordPress gestionează dependențe și versiuni.", "e": "Enqueue evită dublurile și respectă ordinea dependențelor.", "px": ["Nu pui `<script>` direct în șablon. Înregistrezi scriptul cu `wp_enqueue_script` din funcția legată la hook-ul `wp_enqueue_scripts`.", "Așa WordPress gestionează dependențele (ex. jQuery), ordinea și evită încărcarea de două ori."]}, {"id": "wx3", "d": "wpadm", "nou": 1, "t": "mc", "q": "La ce folosește un nonce în WordPress?", "o": ["Protejează formularele și acțiunile împotriva CSRF", "Criptează parola", "Setează limba"], "a": 0, "h": "Token cu durată limitată.", "e": "Se creează cu wp_create_nonce și se verifică cu wp_verify_nonce sau check_ajax_referer.", "px": ["Un nonce e un cod de unică folosință, legat de utilizator și acțiune. Îl pui în formular și îl verifici la primire.", "Dacă un alt site încearcă să trimită cererea în numele tău (CSRF), nu are codul și cererea e respinsă."]}, {"id": "wx4", "d": "wpadm", "nou": 1, "t": "mc", "q": "De ce nu modifici direct fișierele unei teme părinte?", "o": ["Actualizarea temei îți șterge modificările; folosești o child theme", "Pentru că tema nu poate fi editată", "Pentru că e ilegal"], "a": 0, "h": "Actualizări.", "e": "Child theme moștenește tema părinte și păstrează personalizările.", "px": ["Când tema părinte se actualizează, fișierele ei se înlocuiesc și modificările tale dispar.", "Child theme e o temă mică peste cea părinte: pui acolo doar ce vrei să schimbi, iar actualizările nu o ating."]}, {"id": "dn1", "d": "tools", "nou": 1, "t": "mc", "q": "Ce face un record MX?", "o": ["Indică serverele care primesc emailul pentru domeniu", "Indică IP-ul site-ului", "Alias către alt domeniu"], "a": 0, "h": "Mail eXchange.", "e": "Prioritatea (valoarea mai mică) decide ordinea serverelor.", "px": ["MX = „Mail eXchanger”. Spune cărui server să-i livreze emailurile pentru domeniu. Fără MX corect, nu primești email."]}, {"id": "dn2", "d": "tools", "nou": 1, "t": "mc", "q": "Diferența dintre record A și CNAME?", "o": ["A leagă un nume de o adresă IP; CNAME leagă un nume de alt nume", "Sunt identice", "CNAME indică un IP"], "a": 0, "h": "IP vs alias.", "e": "CNAME nu se poate pune pe domeniul rădăcină (apex) alături de alte recorduri.", "px": ["`A` leagă un nume de o adresă IP. `CNAME` e o poreclă: leagă un nume de alt nume, iar IP-ul îl ia de la acela.", "Pe domeniul rădăcină (ex. `exemplu.ro`) de obicei nu poți pune CNAME."]}, {"id": "dn3", "d": "tools", "nou": 1, "t": "mc", "q": "La ce folosește recordul SPF?", "o": ["Listează serverele autorizate să trimită email pentru domeniu", "Criptează emailurile", "Stabilește viteza site-ului"], "a": 0, "h": "Anti-spoofing.", "e": "Se completează cu DKIM (semnătură) și DMARC (politică).", "px": ["SPF e o listă publică, în DNS, cu serverele care au voie să trimită email în numele domeniului. Serverul care primește verifică dacă expeditorul e pe listă."]}, {"id": "dn4", "d": "tools", "nou": 1, "t": "mc", "q": "Ce e TTL la un record DNS?", "o": ["Cât timp poate fi păstrat în cache răspunsul", "Dimensiunea recordului", "Prioritatea recordului"], "a": 0, "h": "Timp de viață în cache.", "e": "Înainte de o mutare de server, TTL-ul se scade pentru propagare mai rapidă.", "px": ["TTL (time to live) e în secunde și spune cât timp poate fi ținut răspunsul în cache. TTL mare = mai puține interogări, dar schimbările se văd mai greu. Înainte de o mutare, îl scazi."]}, {"id": "dn5", "d": "tools", "nou": 1, "t": "mc", "q": "Ce arată DKIM?", "o": ["Că mesajul are o semnătură digitală validată cu o cheie publică din DNS", "Că emailul a fost citit", "Câte emailuri s-au trimis"], "a": 0, "h": "Semnătură.", "e": "Receptorul verifică semnătura din header cu cheia publică din recordul TXT.", "px": ["DKIM e semnătura digitală pe email. Serverul tău semnează cu o cheie privată, iar cheia publică e în DNS. Destinatarul verifică semnătura și află că mesajul n-a fost modificat și vine de la domeniu."]}, {"id": "qa41", "d": "qa", "nou": 1, "t": "mc", "q": "Ce înseamnă un test flaky?", "o": ["Un test care uneori trece și uneori pică, fără modificări în cod", "Un test foarte lent", "Un test scris greșit"], "a": 0, "h": "Instabil.", "e": "Cauze: așteptări greșite, date partajate, ordine de rulare, mediu.", "px": ["Test flaky = test „capricios”: rulat de mai multe ori pe același cod, uneori trece, alteori pică. Cauze frecvente: așteptări prea scurte, ordinea testelor, date comune.", "E periculos pentru că echipa începe să ignore testele roșii."]}, {"id": "qa42", "d": "qa", "nou": 1, "t": "mc", "q": "Ce e smoke testing?", "o": ["Verificare rapidă a funcțiilor esențiale, după un build, ca să decizi dacă merită testarea detaliată", "Testarea detaliată a fiecărui câmp", "Testarea la foc"], "a": 0, "h": "Primul filtru.", "e": "Dacă smoke test pică, build-ul se returnează.", "px": ["Smoke testing = „ies fum?”. După un build nou verifici rapid funcțiile esențiale (pornește, te loghezi, pagina principală). Dacă pică, nu are rost testarea detaliată."]}, {"id": "qa43", "d": "qa", "nou": 1, "t": "mc", "q": "Ce e testarea exploratorie?", "o": ["Învățare, proiectare și execuție de teste în același timp, ghidate de experiență", "Rularea unui script automat", "Testarea doar după documentație"], "a": 0, "h": "Fără scripturi fixe.", "e": "Se lucrează pe sesiuni cu un scop (charter) și note.", "px": ["Nu urmezi un script fix. Explorezi aplicația, înveți din ce vezi și decizi pe loc următorul test, notând ce găsești. Se potrivește pentru a descoperi probleme pe care cazurile scrise nu le acoperă."]}, {"id": "ap31", "d": "api", "nou": 1, "t": "mc", "q": "Ce înseamnă un endpoint idempotent și de ce contează la reîncercări?", "o": ["Repetarea apelului nu schimbă rezultatul final, deci reîncercarea e sigură", "Endpoint-ul e foarte rapid", "Endpoint-ul nu cere autentificare"], "a": 0, "h": "Retry sigur.", "e": "GET, PUT și DELETE sunt idempotente; POST de obicei nu.", "px": ["Idempotent = repetarea cererii nu schimbă rezultatul final. `PUT` și `DELETE` sunt așa; `POST` de obicei nu.", "Contează la reîncercări: dacă cererea expiră și o trimiți din nou, nu vrei două comenzi sau două plăți."]}, {"id": "ap32", "d": "api", "nou": 1, "t": "mc", "q": "Ce cod HTTP indică o cerere validă ca sintaxă, dar cu date greșite semantic (ex. email invalid)?", "o": ["422 Unprocessable Entity (sau 400, după convenția API-ului)", "200 OK", "503 Service Unavailable"], "a": 0, "h": "Eroare de client.", "e": "Seria 4xx = vina clientului; 5xx = vina serverului.", "px": ["Sintaxa e corectă (JSON valid), dar valorile nu au sens, de exemplu un email fără @. 422 spune exact asta. Multe API-uri folosesc și 400 pentru același caz."]}, {"id": "ap33", "d": "api", "nou": 1, "t": "mc", "q": "Ce înseamnă un token Bearer în header-ul Authorization?", "o": ["Trimiți tokenul de acces: Authorization: Bearer <token>", "Trimiți parola în clar", "Trimiți cookie-ul de sesiune"], "a": 0, "h": "Cine deține tokenul are acces.", "e": "Tokenurile nu se pun în URL și nu se afișează în loguri.", "px": ["„Bearer” înseamnă „purtătorul” tokenului: oricine îl are, e primit. Îl trimiți în antet: `Authorization: Bearer <token>`. De aceea îl ții secret și îl trimiți doar prin HTTPS."]}, {"id": "en28", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“Could you please elaborate on that?” What is being asked?", "o": ["Give more details", "Make it shorter", "Repeat it louder"], "a": 0, "h": "Elaborate = a detalia.", "e": "Util în ședințe și interviuri când vrei mai multe informații.", "px": ["„Elaborate” înseamnă a explica mai în detaliu. „Could you please elaborate on that?” = „Poți să dai mai multe detalii?”. E o formulare politicoasă pentru întâlniri."]}, {"id": "en29", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“I’m in charge of customer support.” What does it mean?", "o": ["I’m responsible for customer support", "I charge customers money", "I’m angry at customers"], "a": 0, "h": "In charge of = responsabil de.", "e": "Variante: I’m responsible for / I lead / I’m the owner of.", "px": ["„To be in charge of” = a fi responsabil de ceva, a conduce. „I’m in charge of customer support” = „Răspund de suportul pentru clienți”. Nu înseamnă „încărcat cu”."]}, {"id": "en30", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“Actually” in English is most similar to which Romanian word?", "o": ["De fapt", "În prezent", "Actual"], "a": 0, "h": "False friend.", "e": "Actually = de fapt. Currently = în prezent. Actual (RO) = current sau real.", "px": ["„Actually” = „de fapt”, nu „actual” (care e „current” sau „present”). Îl folosești când corectezi sau aduci o informație neașteptată: „Actually, the meeting is on Friday.”"]}, {"id": "en31", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "Which sentence is correct?", "o": ["I have been working here for three years.", "I am working here since three years.", "I work here from three years."], "a": 0, "h": "Present perfect cu for/since.", "e": "For + durată, since + moment de început.", "px": ["Acțiune începută în trecut și care continuă acum, cu durată: present perfect continuous + `for` (durata): „I have been working here for three years.”", "În română spui „lucrez aici de trei ani”, dar în engleză nu folosești prezentul simplu."]}, {"id": "zp1", "d": "php", "nou": 1, "t": "mc", "q": "Ce face constructorul din: class User { public function __construct(private string $name) {} } ?", "o": ["Declară proprietatea privată $name și o inițializează automat (constructor promotion, PHP 8)", "Doar verifică tipul parametrului, fără să creeze proprietatea", "Dă eroare, pentru că proprietatea nu e declarată separat"], "a": 0, "h": "Din PHP 8.0 modificatorul de acces din parametru are un efect special.", "e": "Constructor promotion: modificatorul de vizibilitate din parametru declară proprietatea și îi atribuie valoarea, fără cod repetitiv.", "px": ["Constructor promotion: scrii modificatorul direct în parametrul constructorului și PHP creează singur proprietatea și îi dă valoarea.", "E scurtătura pentru: declari proprietatea, apoi scrii `$this->nume = $nume;`.", "Încearcă: scoate comentariul de la ultima linie și vezi eroarea (proprietatea e privată)."], "tr": {"l": "php", "c": "<?php\nclass User {\n    public function __construct(private string $name, public int $age = 18) {}\n    public function name(): string { return $this->name; }\n}\n$u = new User('Ana');\necho $u->name(), ' ', $u->age, \"\\n\";\n// echo $u->name;   // Error: private\n"}}, {"id": "zp2", "d": "php", "nou": 1, "t": "mc", "q": "Când este apelat destructorul __destruct()?", "o": ["Când nu mai există nicio referință la obiect sau când se termină scriptul", "Imediat după ce se termină constructorul", "Doar când apelezi explicit $obj->__destruct()"], "a": 0, "h": "Gândește-te la referințe, nu la un apel manual.", "e": "PHP apelează __destruct când ultima referință dispare (unset, reasignare) sau la finalul scriptului.", "px": ["Destructorul rulează când nimeni nu mai ține obiectul (`unset` sau reasignare) sau când se termină scriptul.", "Util pentru închiderea fișierelor sau conexiunilor.", "Încearcă: rulează și urmărește ordinea mesajelor."], "tr": {"l": "php", "c": "<?php\nclass Resursa {\n    public function __construct(public string $n) { echo \"creez {$this->n}\\n\"; }\n    public function __destruct() { echo \"distrug {$this->n}\\n\"; }\n}\n$a = new Resursa('A');\n$b = new Resursa('B');\n$a = null;                // nu mai exista referinte la A\necho \"sfarsit script\\n\"; // B se distruge dupa asta\n"}}, {"id": "zp3", "d": "php", "nou": 1, "t": "mc", "q": "class A { public static function make() { return new static; } } class B extends A {} Ce întoarce B::make()?", "o": ["Un obiect de tip B (late static binding)", "Un obiect de tip A", "Eroare, new static nu e permis"], "a": 0, "h": "static:: se rezolvă la clasa apelată, nu la cea în care e scris codul.", "e": "new static folosește late static binding: clasa efectivă apelată (B). new self ar fi creat A.", "px": ["`static` înseamnă „clasa prin care ai apelat”. `self` înseamnă „clasa în care e scris codul”.", "De aceea `new static` dă copilul, iar `new self` dă mereu părintele.", "Încearcă: rulează și compară cele două rânduri."], "tr": {"l": "php", "c": "<?php\nclass A { public static function make() { return new static; } }\nclass B extends A {}\necho get_class(B::make()), \"\\n\";   // B\n\nclass C { public static function make() { return new self; } }\nclass D extends C {}\necho get_class(D::make()), \"\\n\";   // C\n"}}, {"id": "zp4", "d": "php", "nou": 1, "t": "mc", "q": "Clasa Copil extends Parinte. Parinte are o proprietate private $x. Ce se întâmplă cu $this->x în Copil?", "o": ["Nu e accesibilă direct în Copil; private e vizibilă doar în clasa care a declarat-o", "Este accesibilă, pentru că Copil moștenește tot", "Este accesibilă doar în citire"], "a": 0, "h": "Diferența dintre private și protected.", "e": "private rămâne vizibil doar în clasa declarantă. Pentru acces din copii folosești protected.", "px": ["`private` = vizibil doar în clasa în care e scris. `protected` = vizibil și în clasele copil.", "Dacă vrei ca un copil să vadă ceva, folosește `protected`.", "Încearcă: rulează și vezi că `y` se vede, iar `x` nu."], "tr": {"l": "php", "c": "<?php\nclass P { private $x = 'secret'; protected $y = 'familie'; }\nclass C extends P {\n    public function arata() {\n        echo $this->y, \"\\n\";           // merge\n        echo @$this->x ?? 'x nu e vizibil', \"\\n\";\n    }\n}\n(new C)->arata();\n"}}, {"id": "zp5", "d": "php", "nou": 1, "t": "mc", "q": "Ce se întâmplă la new dintr-o clasă abstract?", "o": ["Eroare: o clasă abstractă nu poate fi instanțiată", "Se creează obiectul, dar metodele abstracte returnează null", "Se creează obiectul normal"], "a": 0, "h": "Abstract înseamnă „șablon incomplet”.", "e": "O clasă abstractă se poate doar extinde. Clasa copil trebuie să implementeze metodele abstracte, apoi poate fi instanțiată.", "px": ["O clasă abstractă e un șablon incomplet: nu poți face obiecte din ea, doar din copiii care completează metodele abstracte.", "Încearcă: rulează și citește mesajul de eroare."], "tr": {"l": "php", "c": "<?php\nabstract class Forma { abstract public function arie(): float; }\nclass Patrat extends Forma {\n    public function __construct(private float $l) {}\n    public function arie(): float { return $this->l ** 2; }\n}\necho (new Patrat(3))->arie(), \"\\n\";\ntry { new Forma(); } catch (Error $e) { echo \"Eroare: \", $e->getMessage(), \"\\n\"; }\n"}}, {"id": "zp6", "d": "php", "nou": 1, "t": "mc", "q": "Care e o diferență reală între o clasă abstractă și o interfață?", "o": ["O clasă poate implementa mai multe interfețe, dar extinde o singură clasă", "Interfața poate avea proprietăți, clasa abstractă nu", "Clasa abstractă nu poate avea metode cu corp"], "a": 0, "h": "Moștenirea multiplă e permisă doar într-o formă.", "e": "PHP are moștenire simplă pentru clase, dar o clasă poate implementa oricâte interfețe. Clasa abstractă poate avea și metode cu corp și proprietăți.", "px": ["O clasă poate extinde O SINGURĂ clasă, dar poate implementa oricâte interfețe. Interfața e un contract: „trebuie să ai aceste metode”.", "Încearcă: rulează și vezi că obiectul e și `Zboara`, și `Inoata`."], "tr": {"l": "php", "c": "<?php\ninterface Zboara { public function zboara(): string; }\ninterface Inoata { public function inoata(): string; }\nclass Rata implements Zboara, Inoata {\n    public function zboara(): string { return 'zbor'; }\n    public function inoata(): string { return 'inot'; }\n}\n$r = new Rata;\nvar_dump($r instanceof Zboara, $r instanceof Inoata);\n"}}, {"id": "zp7", "d": "php", "nou": 1, "t": "mc", "q": "O clasă folosește două trait-uri care definesc aceeași metodă hello(). Ce se întâmplă?", "o": ["Fatal error, dacă nu rezolvi conflictul cu insteadof", "Se folosește automat ultimul trait", "Se apelează ambele metode pe rând"], "a": 0, "h": "Există un operator dedicat conflictelor.", "e": "Conflictul se rezolvă cu insteadof (alegi metoda) și opțional cu as (redenumești/alias).", "px": ["Trait-urile sunt bucăți de cod pe care le „lipești” în clase. Dacă două au aceeași metodă, trebuie să alegi: `insteadof` alege, `as` redenumește.", "Încearcă: șterge liniile cu `insteadof` și `as` și vezi eroarea fatală."], "tr": {"l": "php", "c": "<?php\ntrait Salut { public function hello() { return 'salut'; } }\ntrait Hello { public function hello() { return 'hello'; } }\nclass T {\n    use Salut, Hello {\n        Salut::hello insteadof Hello;   // aleg una\n        Hello::hello as helloEn;        // o pastrez cu alt nume\n    }\n}\n$t = new T;\necho $t->hello(), ' ', $t->helloEn(), \"\\n\";\n"}}, {"id": "zp8", "d": "php", "nou": 1, "t": "mc", "q": "Ce înseamnă o proprietate readonly (PHP 8.1)?", "o": ["Poate fi inițializată o singură dată, din interiorul clasei, apoi nu mai poate fi modificată", "Nu poate fi citită din afara clasei", "Este constantă la nivel de clasă, ca const"], "a": 0, "h": "Imutabilitate după prima atribuire.", "e": "readonly permite o singură atribuire, din scope-ul clasei. A doua încercare aruncă Error.", "px": ["`readonly` = se poate seta o singură dată (în constructor), apoi nu se mai schimbă.", "Bun pentru obiecte-valoare (coordonate, bani, date).", "Încearcă: rulează și citește mesajul."], "tr": {"l": "php", "c": "<?php\nclass Punct {\n    public function __construct(public readonly int $x) {}\n}\n$p = new Punct(1);\necho $p->x, \"\\n\";\ntry { $p->x = 2; } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }\n"}}, {"id": "zp9", "d": "php", "nou": 1, "t": "mc", "q": "enum Status: string { case Activ = 'a'; } Ce întoarce Status::tryFrom('x')?", "o": ["null, pentru că nu există un case cu valoarea 'x'", "Aruncă ValueError", "Întoarce Status::Activ"], "a": 0, "h": "from() și tryFrom() diferă la valoare invalidă.", "e": "from() aruncă ValueError pentru valoare inexistentă, tryFrom() întoarce null.", "px": ["`from()` e „strict”: dă eroare dacă valoarea nu există. `tryFrom()` e „blând”: dă `null`.", "Încearcă: schimbă 'x' cu 'i' și vezi."], "tr": {"l": "php", "c": "<?php\nenum Status: string {\n    case Activ = 'a';\n    case Inactiv = 'i';\n}\nvar_dump(Status::tryFrom('x'));          // NULL\necho Status::from('a')->name, \"\\n\";     // Activ\ntry { Status::from('x'); } catch (ValueError $e) { echo \"ValueError\\n\"; }\n"}}, {"id": "zp10", "d": "php", "nou": 1, "t": "mc", "q": "Când este apelată metoda magică __get($name)?", "o": ["La citirea unei proprietăți inexistente sau inaccesibile", "La fiecare citire a oricărei proprietăți", "La apelul unei metode inexistente"], "a": 0, "h": "Se declanșează doar când accesul „normal” nu merge.", "e": "__get se apelează pentru proprietăți inaccesibile (private/protected din exterior) sau inexistente. Pentru metode inexistente există __call.", "px": ["`__get` se apelează când citești o proprietate care nu există sau nu e accesibilă. `__call` se apelează la o metodă care nu există.", "Încearcă: rulează și urmărește care metodă magică se declanșează."], "tr": {"l": "php", "c": "<?php\nclass Magic {\n    private $date = ['a' => 1];\n    public function __get($n) { echo \"citesc $n\\n\"; return $this->date[$n] ?? null; }\n    public function __call($n, $args) { return \"metoda $n nu exista\"; }\n}\n$m = new Magic;\nvar_dump($m->a);\nvar_dump($m->lipsa);\necho $m->oMetoda(), \"\\n\";\n"}}, {"id": "zp11", "d": "php", "nou": 1, "t": "mc", "q": "$a = new Obiect(); $b = $a; $b->x = 5; Ce valoare are $a->x?", "o": ["5, pentru că $a și $b indică același obiect", "Valoarea veche, pentru că $b e o copie", "Eroare de atribuire"], "a": 0, "h": "Atribuirea obiectelor nu clonează.", "e": "În PHP variabila ține un identificator al obiectului. $b = $a copiază identificatorul, nu obiectul. Pentru copie folosești clone.", "px": ["Variabila ține o „adresă” spre obiect, nu obiectul. `$b = $a` copiază adresa, deci amândouă arată spre același obiect.", "Pentru o copie reală folosești `clone`.", "Încearcă: rulează și compară."], "tr": {"l": "php", "c": "<?php\nclass O { public $x = 1; }\n$a = new O;\n$b = $a;\n$b->x = 5;\necho $a->x, \"\\n\";     // 5\n\n$c = clone $a;\n$c->x = 9;\necho $a->x, \" \", $c->x, \"\\n\";\n"}}, {"id": "zp12", "d": "php", "nou": 1, "t": "mc", "q": "Ce face clone dacă obiectul conține în proprietăți alte obiecte?", "o": ["Copie superficială: obiectele interne rămân partajate, dacă nu definești __clone()", "Copie profundă automată a tuturor obiectelor interne", "Eroare, obiectele compuse nu se pot clona"], "a": 0, "h": "Metoda magică __clone ajută.", "e": "clone e shallow. Pentru copie profundă clonezi manual obiectele interne în __clone().", "px": ["`clone` copiază doar obiectul de sus. Obiectele din el rămân partajate, dacă nu scrii `__clone()`.", "Încearcă: șterge `__clone` și vezi că `$a->in->v` devine 99."], "tr": {"l": "php", "c": "<?php\nclass Interior { public $v = 1; }\nclass Exterior {\n    public $in;\n    public function __construct() { $this->in = new Interior; }\n    public function __clone() { $this->in = clone $this->in; }   // copie profunda\n}\n$a = new Exterior;\n$b = clone $a;\n$b->in->v = 99;\necho $a->in->v, \"\\n\";   // 1 (cu __clone); fara __clone ar fi 99\n"}}, {"id": "zp13", "d": "php", "nou": 1, "t": "mc", "q": "Într-un fișier cu namespace App; scrii new DateTime(). Ce se întâmplă?", "o": ["Eroare: caută clasa App\\DateTime; trebuie new \\DateTime sau use DateTime;", "Merge, clasele globale se rezolvă automat", "Merge doar în PHP 8"], "a": 0, "h": "Funcțiile au fallback global, clasele nu.", "e": "Clasele (spre deosebire de funcțiile și constantele) nu au fallback în spațiul global. Folosești \\DateTime sau use DateTime;.", "px": ["Într-un fișier cu `namespace App;`, numele necalificate se caută în `App`. `new DateTime()` caută `App\\DateTime` și dă eroare. Ai două soluții: `new \\DateTime()` (slash în față = spațiul global) sau `use DateTime;` sus."]}, {"id": "zp14", "d": "php", "nou": 1, "t": "mc", "q": "Ce întoarce Utilizator::class?", "o": ["Numele complet al clasei ca string, inclusiv namespace-ul", "Un obiect ReflectionClass", "Numărul de instanțe ale clasei"], "a": 0, "h": "Util la autoload și în container DI.", "e": "::class dă string-ul fully qualified, rezolvat la compilare.", "px": ["`Clasa::class` dă numele complet al clasei, cu namespace, ca string.", "Încearcă: rulează și vezi `App\\Model\\Utilizator`."], "tr": {"l": "php", "c": "<?php\nnamespace App\\Model;\nclass Utilizator {}\necho Utilizator::class, \"\\n\";\necho \\strlen('abc'), \"\\n\";\n"}}, {"id": "zp15", "d": "php", "nou": 1, "t": "mc", "q": "Ce metode cere interfața Iterator pentru a folosi obiectul într-un foreach?", "o": ["current, key, next, rewind, valid", "getIterator și count", "next și prev"], "a": 0, "h": "Cinci metode.", "e": "Iterator cere current(), key(), next(), rewind(), valid(). Alternativ, IteratorAggregate cere doar getIterator().", "px": ["`foreach` cheamă pe rând: `rewind`, apoi `valid`, `current`, `key`, apoi `next` și repetă.", "Încearcă: adaugă un `echo` în fiecare metodă și urmărește ordinea."], "tr": {"l": "php", "c": "<?php\nclass Lista implements Iterator {\n    private $i = 0;\n    public function __construct(private array $d) {}\n    public function current(): mixed { return $this->d[$this->i]; }\n    public function key(): mixed { return $this->i; }\n    public function next(): void { $this->i++; }\n    public function rewind(): void { $this->i = 0; }\n    public function valid(): bool { return isset($this->d[$this->i]); }\n}\nforeach (new Lista(['a', 'b', 'c']) as $k => $v) echo \"$k=$v \";\necho \"\\n\";\n"}}, {"id": "zp16", "d": "php", "nou": 1, "t": "mc", "q": "Ce avantaj principal are un generator (yield) față de un array întors de o funcție?", "o": ["Produce valorile pe rând, consumă puțină memorie la seturi mari", "E mai rapid la sortare", "Permite chei duplicate în array"], "a": 0, "h": "Gândește-te la citirea unui fișier de 2 GB.", "e": "Generatorul calculează valorile la cerere (lazy). Nu ține toată lista în memorie.", "px": ["Generatorul dă valorile pe rând. Array-ul le ține pe toate în memorie deodată.", "Încearcă: rulează și compară cei doi consumuri."], "tr": {"l": "php", "c": "<?php\nfunction mare() {\n    for ($i = 0; $i < 1000000; $i++) yield $i;\n}\n$m1 = memory_get_usage();\nforeach (mare() as $x) { if ($x > 3) break; }\necho \"generator: \", memory_get_usage() - $m1, \" octeti\\n\";\n\n$m2 = memory_get_usage();\n$lista = range(0, 999999);\necho \"array: \", memory_get_usage() - $m2, \" octeti\\n\";\n"}}, {"id": "zp17", "d": "php", "nou": 1, "t": "mc", "q": "Ce tip acceptă parametrul declarat iterable?", "o": ["Un array sau orice obiect Traversable", "Doar array", "Doar obiecte care implementează Countable"], "a": 0, "h": "Include și generatoarele.", "e": "iterable = array | Traversable. Generator, Iterator și IteratorAggregate sunt Traversable.", "px": ["`iterable` primește un array sau orice obiect care se poate parcurge (generator, Iterator).", "Încearcă: dă-i un string și vezi eroarea de tip."], "tr": {"l": "php", "c": "<?php\nfunction suma(iterable $x) { $s = 0; foreach ($x as $v) $s += $v; return $s; }\nfunction gen() { yield 1; yield 2; }\necho suma([1, 2, 3]), \" \", suma(gen()), \" \", suma(new ArrayIterator([4, 5])), \"\\n\";\n"}}, {"id": "zp18", "d": "php", "nou": 1, "t": "mc", "q": "Cum se comportă o proprietate statică declarată în clasa părinte, într-o clasă copil care nu o redeclară?", "o": ["Este aceeași valoare partajată între părinte și copil", "Fiecare copil primește propria copie", "E interzis să o accesezi din copil"], "a": 0, "h": "Static aparține clasei, nu instanței.", "e": "Proprietatea statică e partajată în ierarhie, dacă copilul nu o redeclară. Dacă o redeclară, are valoare separată.", "px": ["Proprietatea statică aparține clasei, nu obiectului. Dacă copilul n-o redeclară, e aceeași valoare pentru toți.", "Încearcă: rulează și vezi cele două rânduri."], "tr": {"l": "php", "c": "<?php\nclass A { public static $n = 0; public static function inc() { return ++static::$n; } }\nclass B extends A {}\nA::inc(); B::inc();\necho A::$n, \" \", B::$n, \"\\n\";   // 2 2 : aceeasi proprietate\n\nclass C { public static $n = 0; }\nclass D extends C { public static $n = 100; }   // redeclarata\necho C::$n, \" \", D::$n, \"\\n\";\n"}}, {"id": "zp19", "d": "php", "nou": 1, "t": "mc", "q": "Ce cere metoda magică __toString()?", "o": ["Să returneze un string; e apelată la conversia obiectului în șir (echo, concatenare)", "Să afișeze direct cu echo", "Să returneze un array"], "a": 0, "h": "Se declanșează la echo $obiect.", "e": "__toString trebuie să returneze string. De PHP 8 clasa devine automat Stringable.", "px": ["`__toString` spune cum arată obiectul când îl tratezi ca text (`echo`, concatenare).", "Încearcă: scoate metoda și vezi eroarea."], "tr": {"l": "php", "c": "<?php\nclass Om {\n    public function __construct(private string $nume) {}\n    public function __toString(): string { return \"Om({$this->nume})\"; }\n}\n$o = new Om('Ana');\necho $o, \"\\n\";\necho 'Salut ' . $o . \"\\n\";\nvar_dump($o instanceof Stringable);\n"}}, {"id": "zp20", "d": "php", "nou": 1, "t": "mc", "q": "Ce permite metoda magică __invoke()?", "o": ["Să apelezi obiectul ca pe o funcție: $obj()", "Să apelezi metode statice", "Să interceptezi accesul la proprietăți"], "a": 0, "h": "Obiect callable.", "e": "Un obiect cu __invoke este callable și poate fi dat ca argument funcțiilor care așteaptă callback.", "px": ["Cu `__invoke` obiectul poate fi apelat ca o funcție: `$f(21)`.", "Încearcă: dă-l ca argument la `array_map`."], "tr": {"l": "php", "c": "<?php\nclass Dubleaza { public function __invoke($x) { return $x * 2; } }\n$f = new Dubleaza;\necho $f(21), \"\\n\";\nprint_r(array_map(new Dubleaza, [1, 2, 3]));\nvar_dump(is_callable($f));\n"}}, {"id": "zp21", "d": "php", "nou": 1, "t": "mc", "q": "Care e diferența dintre const și define() pentru constante globale?", "o": ["const se evaluează la compilare și nu merge în if/funcții; define() rulează la execuție", "Sunt identice în toate cazurile", "define() nu permite valori string"], "a": 0, "h": "Moment de evaluare.", "e": "const trebuie la nivel superior (nu condiționat). define() e apel de funcție și poate fi condiționat sau cu nume dinamic.", "px": ["`const` se rezolvă la compilare și nu merge în `if`; `define()` e o funcție, rulează la execuție.", "Încearcă: scoate comentariul de la ultima linie și vezi eroarea."], "tr": {"l": "php", "c": "<?php\nconst A = 1;\ndefine('B', 2);\necho A + B, \"\\n\";\nclass K { const X = 10; final public const Y = 20; }\necho K::X, ' ', K::Y, \"\\n\";\nif (true) { define('DINAMIC', 5); }\necho DINAMIC, \"\\n\";\n// if (true) { const Z = 1; }   // eroare de sintaxa\n"}}, {"id": "zp22", "d": "php", "nou": 1, "t": "mc", "q": "Clasa Copil are propriul constructor. Se apelează automat constructorul părintelui?", "o": ["Nu, trebuie apelat explicit cu parent::__construct()", "Da, întotdeauna înainte", "Da, dar doar dacă părintele e abstract"], "a": 0, "h": "Regula tăcută care produce bug-uri.", "e": "Dacă Copil definește __construct, cel al părintelui nu rulează singur. Îl apelezi cu parent::__construct(...).", "px": ["Dacă și copilul are constructor, cel al părintelui NU rulează singur. Îl chemi tu cu `parent::__construct()`.", "Încearcă: rulează și numără mesajele."], "tr": {"l": "php", "c": "<?php\nclass P { public function __construct() { echo \"constructor P\\n\"; } }\nclass Copil extends P {\n    public function __construct() { echo \"constructor Copil\\n\"; }\n}\nclass Copil2 extends P {\n    public function __construct() { parent::__construct(); echo \"constructor Copil2\\n\"; }\n}\nnew Copil;\nnew Copil2;\n"}}, {"id": "zp23", "d": "php", "nou": 1, "t": "mc", "q": "Ce rol are PSR-4 împreună cu Composer?", "o": ["Mapează namespace-ul clasei la un director, ca fișierul să fie încărcat automat", "Formatează codul la standarde", "Validează tipurile la runtime"], "a": 0, "h": "Autoload fără require.", "e": "Cu PSR-4, App\\Service\\Mailer e căutat în src/Service/Mailer.php, după maparea din composer.json.", "px": ["PSR-4 e o regulă: namespace-ul clasei se mapează pe un folder. `App\\Models\\User` ajunge în `src/Models/User.php`. Composer generează autoload-ul și nu mai scrii `require` pentru fiecare clasă."]}, {"id": "zp24", "d": "php", "nou": 1, "t": "mc", "q": "Ce înseamnă dependency injection în PHP?", "o": ["Clasa primește dependențele (ex. conexiunea DB) din exterior, de obicei prin constructor, nu le creează singură", "Clasa își creează dependențele cu new în interior", "Dependențele se declară globale"], "a": 0, "h": "Testabilitate.", "e": "DI face codul testabil: poți injecta un mock în loc de conexiunea reală.", "px": ["În loc ca o clasă să-și creeze singură dependențele (`new Database()`), le primește de-a gata, de obicei în constructor. Codul devine mai ușor de testat (poți da o conexiune falsă) și de schimbat."]}, {"id": "zp25", "d": "php", "nou": 1, "t": "mc", "q": "Ce face cuvântul final în fața unei clase?", "o": ["Împiedică extinderea clasei", "Împiedică instanțierea", "O face abstractă"], "a": 0, "h": "Opusul lui abstract, într-un fel.", "e": "final class nu poate fi extinsă. final pe metodă interzice suprascrierea.", "px": ["`final` pe clasă: nu mai poți moșteni din ea. Pe metodă: nu o mai poți suprascrie.", "Încearcă: scoate comentariul și citește eroarea."], "tr": {"l": "php", "c": "<?php\nfinal class Sigilat {}\necho \"ok\\n\";\n// class Copil extends Sigilat {}   // Fatal error\n"}}, {"id": "zp26", "d": "php", "nou": 1, "t": "mc", "q": "În PHP 8, ce întoarce 0 == 'a'?", "o": ["false (PHP 8 compară numărul cu string-ul non-numeric ca string)", "true, ca în PHP 7", "Eroare TypeError"], "a": 0, "h": "Regula de comparare s-a schimbat în PHP 8.", "e": "În PHP 8, la compararea int cu string non-numeric, intul e convertit la string: '0' == 'a' e false.", "px": ["În PHP 8, `0 == 'a'` e false: numărul se compară ca text cu șirul care nu e număr. În PHP 7 era true.", "Pentru siguranță folosește `===`.", "Încearcă: rulează și compară rezultatele."], "tr": {"l": "php", "c": "<?php\nvar_dump(0 == 'a');        // false in PHP 8\nvar_dump('1' == '01');     // true\nvar_dump(100 == '1e2');    // true\nvar_dump('abc' == 0);      // false in PHP 8\nvar_dump(null == false);   // true\nvar_dump(0 === '0');       // false (strict)\n"}}, {"id": "zp27", "d": "php", "nou": 1, "t": "mc", "q": "$a = [1,2,3]; foreach ($a as &$v) {} foreach ($a as $v) {} Ce conține $a la final?", "o": ["[1, 2, 2]", "[1, 2, 3]", "[3, 3, 3]"], "a": 0, "h": "Referința rămâne după primul foreach.", "e": "$v rămâne referință la ultimul element. Al doilea foreach îl suprascrie pe rând. Soluție: unset($v) după primul foreach.", "px": ["După primul `foreach`, `$v` rămâne legat de ULTIMUL element. Al doilea `foreach` scrie în `$v` pe rând, deci scrie în ultimul element.", "Soluția: `unset($v)` după primul `foreach`.", "Încearcă: rulează și apoi adaugă `unset($v);` între bucle."], "tr": {"l": "php", "c": "<?php\n$a = [1, 2, 3];\nforeach ($a as &$v) {}\nforeach ($a as $v) {}\nprint_r($a);          // [1, 2, 2]\nunset($v);\n"}}, {"id": "zp28", "d": "php", "nou": 1, "t": "mc", "q": "$a = ['k' => null]; Ce întorc isset($a['k']) și array_key_exists('k', $a)?", "o": ["false și true", "true și true", "false și false"], "a": 0, "h": "isset tratează null ca „nesetat”.", "e": "isset() e false pentru valoare null. array_key_exists() verifică doar existența cheii.", "px": ["`isset` zice false și pentru valoarea `null`. `array_key_exists` verifică doar dacă cheia există.", "Încearcă: rulează și compară."], "tr": {"l": "php", "c": "<?php\n$a = ['k' => null];\nvar_dump(isset($a['k']));\nvar_dump(array_key_exists('k', $a));\nvar_dump(empty($a['k']));\nvar_dump(isset($a['lipsa']));\n"}}, {"id": "zp29", "d": "php", "nou": 1, "t": "mc", "q": "Ce se întâmplă cu cheile după array_filter([1,2,3,4], fn($x) => $x > 2)?", "o": ["Se păstrează: rezultatul are cheile 2 și 3; folosești array_values pentru reindexare", "Se reindexează automat de la 0", "Rezultatul e string"], "a": 0, "h": "json_encode ar da obiect, nu listă.", "e": "array_filter păstrează cheile originale. Pentru listă fără goluri aplici array_values().", "px": ["`array_filter` păstrează cheile originale. Cu „găuri” în chei, `json_encode` face un obiect, nu o listă.", "Încearcă: rulează și compară cele două `json_encode`."], "tr": {"l": "php", "c": "<?php\n$r = array_filter([1, 2, 3, 4], fn($x) => $x > 2);\nprint_r($r);                 // cheile 2 si 3\necho json_encode($r), \"\\n\";  // obiect!\necho json_encode(array_values($r)), \"\\n\";\n"}}, {"id": "zp30", "d": "php", "nou": 1, "t": "mc", "q": "Ce diferență are array_merge față de operatorul + pe două array-uri?", "o": ["array_merge renumerotează cheile numerice și suprascrie cele string; + păstrează valoarea din stânga la chei identice", "Sunt identice", "+ suprascrie cu valoarea din dreapta"], "a": 0, "h": "Chei numerice și conflicte.", "e": "Operatorul + adaugă doar cheile care lipsesc din stânga. array_merge lipește valorile numerice și suprascrie cheile string.", "px": ["`array_merge` renumerotează cheile numerice și suprascrie cheile text. Operatorul `+` păstrează valoarea din stânga la chei identice.", "Încearcă: rulează și compară."], "tr": {"l": "php", "c": "<?php\n$a = ['x' => 1, 5 => 'a'];\n$b = ['x' => 2, 5 => 'b'];\nprint_r(array_merge($a, $b));   // x=2, cheile numerice renumerotate\nprint_r($a + $b);               // pastreaza stanga: x=1, 5=a\n"}}, {"id": "zp31", "d": "php", "nou": 1, "t": "mc", "q": "Cum verifici corect o parolă stocată cu password_hash()?", "o": ["password_verify($parola, $hash)", "md5($parola) === $hash", "hash('sha1', $parola) == $hash"], "a": 0, "h": "Funcția care vine în pereche.", "e": "password_hash folosește algoritm lent cu salt integrat. Verifici cu password_verify, nu cu comparare directă.", "px": ["`password_hash` pune singură un „salt” aleator și folosește un algoritm lent, ca să fie greu de spart. Verifici cu `password_verify`, nu cu `==`.", "Încearcă: rulează și vezi că două hash-uri ale aceleiași parole sunt diferite."], "tr": {"l": "php", "c": "<?php\n$h = password_hash('parola', PASSWORD_DEFAULT);\nvar_dump(password_verify('parola', $h));\nvar_dump(password_verify('alta', $h));\necho strlen($h) > 50 ? \"hash lung, cu salt inclus\\n\" : \"scurt\\n\";\necho $h === password_hash('parola', PASSWORD_DEFAULT) ? \"egale\" : \"diferite la fiecare apel (salt)\", \"\\n\";\n"}}, {"id": "zp32", "d": "php", "nou": 1, "t": "mc", "q": "Ce face expresia match față de switch?", "o": ["Compară strict (===), întoarce o valoare și aruncă UnhandledMatchError dacă nu există potrivire", "Compară slab, ca switch", "Nu permite mai multe valori pe un braț"], "a": 0, "h": "PHP 8.", "e": "match e expresie, cu comparare strictă, fără break și fără fall-through.", "px": ["`match` e ca `switch`, dar întoarce o valoare, compară strict (`===`) și aruncă eroare dacă nu găsește potrivire.", "Încearcă: rulează și urmărește."], "tr": {"l": "php", "c": "<?php\n$v = 3;\necho match(true) { $v < 2 => 'mic', $v < 5 => 'mediu', default => 'mare' }, \"\\n\";\ntry { echo match(99) { 1 => 'a', 2 => 'b' }; } catch (\\UnhandledMatchError $e) { echo \"UnhandledMatchError\\n\"; }\nvar_dump(match('1') { 1 => 'int', '1' => 'string' });   // comparare stricta\n"}}, {"id": "zp33", "d": "php", "nou": 1, "t": "mc", "q": "Ce schimbă declare(strict_types=1); pe prima linie a unui fișier?", "o": ["Apelurile de funcții din acel fișier nu mai convertesc automat tipurile scalare (TypeError)", "Activează afișarea tuturor erorilor", "Interzice variabilele nedeclarate"], "a": 0, "h": "Se aplică pe apelurile făcute din fișier.", "e": "Cu strict_types, trimiți '5' la un parametru int și primești TypeError în loc de conversie.", "px": ["Fără `strict_types`, `'5'` ar fi convertit în `5`. Cu el, PHP cere exact tipul declarat.", "Încearcă: comentează `declare` și vezi că `dublu('5')` merge."], "tr": {"l": "php", "c": "<?php\ndeclare(strict_types=1);\nfunction dublu(int $x) { return $x * 2; }\necho dublu(5), \"\\n\";\ntry { echo dublu('5'); } catch (TypeError $e) { echo \"TypeError: \", $e->getMessage(), \"\\n\"; }\n"}}, {"id": "zp34", "d": "php", "nou": 1, "t": "mc", "q": "Ce face json_decode($json, true) cu un JSON invalid?", "o": ["Întoarce null; verifici cu json_last_error() sau folosești JSON_THROW_ON_ERROR", "Aruncă mereu excepție", "Întoarce un array gol"], "a": 0, "h": "null poate însemna și JSON valid cu null.", "e": "Fără flag de excepții, eșecul dă null. Pentru diferențiere folosești json_last_error() sau JSON_THROW_ON_ERROR.", "px": ["La JSON invalid, `json_decode` întoarce `null`. Dar `null` poate fi și un JSON valid, deci verifici cu `json_last_error()` sau folosești `JSON_THROW_ON_ERROR`.", "Încearcă: rulează și urmărește."], "tr": {"l": "php", "c": "<?php\nvar_dump(json_decode('{\"a\":1}', true));\nvar_dump(json_decode('{gresit}'));\necho json_last_error_msg(), \"\\n\";\ntry { json_decode('{gresit}', false, 512, JSON_THROW_ON_ERROR); }\ncatch (JsonException $e) { echo \"Exceptie: \", $e->getMessage(), \"\\n\"; }\n"}}, {"id": "zp35", "d": "php", "nou": 1, "t": "mc", "q": "Care e diferența dintre include și require?", "o": ["La fișier lipsă include dă warning și continuă, require dă fatal error", "Sunt identice", "include dă fatal error, require doar warning"], "a": 0, "h": "Cât de critic e fișierul?", "e": "require oprește scriptul. include doar avertizează. Variantele _once evită încărcarea dublă.", "px": ["Ambele includ un fișier. Dacă lipsește: `include` dă warning și scriptul continuă, `require` dă eroare fatală și se oprește. Folosești `require` pentru ce e obligatoriu (configurare, clase)."]}, {"id": "zp36", "d": "php", "nou": 1, "t": "mc", "q": "Cum previi corect XSS când afișezi text introdus de utilizator într-o pagină HTML?", "o": ["Escapezi la ieșire cu htmlspecialchars($t, ENT_QUOTES, 'UTF-8')", "Folosești addslashes", "Folosești strip_tags la salvare și gata"], "a": 0, "h": "Escapezi în contextul în care afișezi.", "e": "XSS se previne prin escape la output, adaptat contextului (HTML, atribut, JS). addslashes nu e pentru HTML.", "px": ["XSS apare când textul utilizatorului ajunge în pagină ca HTML. Escapezi la afișare: `htmlspecialchars($t, ENT_QUOTES, 'UTF-8')` transformă `<` în `&lt;` etc., deci e doar text. Escapezi la ieșire, în contextul unde afișezi."]}, {"id": "zp37", "d": "php", "nou": 1, "t": "mc", "q": "Ce diferență e între bindParam și bindValue la PDO?", "o": ["bindParam leagă variabila prin referință și citește valoarea la execute(); bindValue ia valoarea în momentul apelului", "Sunt identice", "bindValue funcționează doar cu string-uri"], "a": 0, "h": "Moment de citire a valorii.", "e": "Dacă schimbi variabila după bindParam și înainte de execute, se folosește noua valoare.", "px": ["`bindValue` ia valoarea acum. `bindParam` leagă variabila prin referință și citește valoarea abia la `execute()`. Dacă schimbi variabila între timp, contează ultima valoare."]}, {"id": "zp38", "d": "php", "nou": 1, "t": "mc", "q": "Ce setezi la PDO pentru ca erorile SQL să arunce excepții?", "o": ["PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION", "PDO::ATTR_PERSISTENT => true", "error_reporting(0)"], "a": 0, "h": "Atributul pentru modul de eroare.", "e": "Cu ERRMODE_EXCEPTION, erorile devin PDOException și le prinzi cu try/catch.", "px": ["Cu `ERRMODE_EXCEPTION`, erorile SQL devin excepții pe care le prinzi cu `try/catch`. Fără el, apare doar un warning sau nimic.", "Încearcă: scoate linia cu `setAttribute` și vezi ce se schimbă."], "tr": {"l": "php", "c": "<?php\n$pdo = new PDO('sqlite::memory:');\n$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);\ntry { $pdo->query('SELECT * FROM tabela_inexistenta'); }\ncatch (PDOException $e) { echo \"Prins: \", $e->getMessage(), \"\\n\"; }\n"}}, {"id": "zp39", "d": "php", "nou": 1, "t": "mc", "q": "Ce prinde catch (InvalidArgumentException | TypeError $e) ?", "o": ["Oricare dintre cele două tipuri (multi-catch, PHP 7.1+)", "Doar prima", "Nimic, sintaxa e invalidă"], "a": 0, "h": "Bara verticală.", "e": "Multi-catch permite un singur bloc pentru mai multe tipuri.", "px": ["Bara `|` în `catch` prinde oricare dintre tipuri într-un singur bloc.", "Încearcă: rulează și vezi cele trei rezultate."], "tr": {"l": "php", "c": "<?php\nfunction t($x) {\n    try {\n        if ($x == 1) throw new InvalidArgumentException('arg');\n        if ($x == 2) throw new TypeError('tip');\n        return 'ok';\n    } catch (InvalidArgumentException | TypeError $e) {\n        return get_class($e);\n    }\n}\necho t(1), ' ', t(2), ' ', t(3), \"\\n\";\n"}}, {"id": "zp40", "d": "php", "nou": 1, "t": "mc", "q": "Un bloc finally dintr-un try/catch...", "o": ["Rulează întotdeauna, chiar dacă try face return sau apare o excepție", "Rulează doar dacă nu apare excepție", "Rulează doar dacă apare excepție"], "a": 0, "h": "Curățenie garantată.", "e": "finally se execută în orice caz, de obicei pentru închis resurse.", "px": ["`finally` rulează chiar dacă în `try` ai deja `return`.", "Încearcă: rulează și urmărește ordinea."], "tr": {"l": "php", "c": "<?php\nfunction f() {\n    try { return 'try'; }\n    finally { echo \"finally ruleaza mereu\\n\"; }\n}\necho f(), \"\\n\";\n"}}, {"id": "zp41", "d": "php", "nou": 1, "t": "mc", "q": "function f() { static $n = 0; return ++$n; } f(); f(); Ce întoarce al treilea apel f()?", "o": ["3", "1", "0"], "a": 0, "h": "static într-o funcție.", "e": "Variabila statică își păstrează valoarea între apeluri.", "px": ["O variabilă `static` într-o funcție își păstrează valoarea între apeluri.", "Încearcă: apelează funcția de mai multe ori."], "tr": {"l": "php", "c": "<?php\nfunction f() { static $n = 0; return ++$n; }\nf(); f();\necho f(), \"\\n\";   // 3\n"}}, {"id": "zp42", "d": "php", "nou": 1, "t": "mc", "q": "Ce face operatorul ??= ?", "o": ["Atribuie doar dacă variabila e nedefinită sau null", "Atribuie mereu", "Compară strict"], "a": 0, "h": "null coalescing assignment.", "e": "$a ??= 5 e echivalent cu $a = $a ?? 5.", "px": ["`??=` atribuie doar dacă variabila e nedefinită sau `null`.", "Încearcă: rulează și vezi că a doua atribuire nu mai schimbă nimic."], "tr": {"l": "php", "c": "<?php\n$a = null;\n$a ??= 5;\necho $a, \"\\n\";\n$a ??= 9;\necho $a, \"\\n\";   // ramane 5\n"}}, {"id": "zp43", "d": "php", "nou": 1, "t": "mc", "q": "Ce afișează: function f(int $a, int $b) { return $a - $b; } echo f(b: 1, a: 5); ?", "o": ["4 (argumente numite, PHP 8)", "-4", "Eroare, ordinea contează"], "a": 0, "h": "Argumente numite.", "e": "Cu named arguments ordinea nu contează: a=5, b=1 → 4.", "px": ["Cu argumente numite, ordinea nu mai contează; spui `nume: valoare`.", "Încearcă: schimbă ordinea."], "tr": {"l": "php", "c": "<?php\nfunction f(int $a, int $b) { return $a - $b; }\necho f(b: 1, a: 5), \"\\n\";   // 4\necho f(5, b: 1), \"\\n\";       // 4\n"}}, {"id": "zp44", "d": "php", "nou": 1, "t": "mc", "q": "Ce diferență e între closure cu use ($x) și arrow function fn() => $x?", "o": ["Ambele captează $x prin valoare; arrow function o face automat, dar nu poate modifica variabila din exterior", "use captează prin referință implicit", "Arrow function nu poate citi variabile din exterior"], "a": 0, "h": "Captare automată.", "e": "Arrow function captează by-value automat. Pentru referință folosești closure cu use (&$x).", "px": ["Un closure își ia o copie a variabilei în momentul creării (`use ($x)`). Cu `&` păstrează legătura cu variabila reală.", "Arrow function `fn` captează automat prin valoare.", "Încearcă: rulează și urmărește valorile."], "tr": {"l": "php", "c": "<?php\n$x = 1;\n$a = function () use ($x) { return $x; };\n$b = fn() => $x;\n$x = 2;\necho $a(), ' ', $b(), \"\\n\";     // 1 1 : captura la creare\n$c = function () use (&$x) { return $x; };\n$x = 3;\necho $c(), \"\\n\";                // 3 : prin referinta\n"}}, {"id": "zp45", "d": "php", "nou": 1, "t": "mc", "q": "Ce funcție sortează un array cu o comparație definită de tine?", "o": ["usort($arr, fn($a, $b) => $a <=> $b)", "sort($arr, 'custom')", "array_sort($arr)"], "a": 0, "h": "Operatorul navetă.", "e": "usort primește callback ce întoarce <0, 0 sau >0. <=> face exact asta.", "px": ["Callback-ul din `usort` întoarce un număr negativ, zero sau pozitiv. Operatorul `<=>` face exact asta: -1, 0, 1.", "Încearcă: inversează `$a` și `$b`."], "tr": {"l": "php", "c": "<?php\n$arr = [3, 1, 2];\nusort($arr, fn($a, $b) => $b <=> $a);   // descrescator\nprint_r($arr);\necho 1 <=> 2, ' ', 2 <=> 2, ' ', 3 <=> 2, \"\\n\";\n"}}, {"id": "zz1", "d": "php", "nou": 1, "t": "mc", "q": "Ce s-a întâmplat cu Zend Framework?", "o": ["A devenit Laminas Project, găzduit de Linux Foundation, cu pachetele  (namespace Zend\\ → Laminas\\)", "A fost oprit complet", "A devenit parte din Symfony"], "a": 0, "h": "Căutând documentație nouă, caută Laminas.", "e": "Zend Framework 3 a devenit Laminas Project. Pachetele noi sunt laminas/laminas-*.", "px": ["Zend Framework a fost predat Linux Foundation și redenumit Laminas. Pachetele au trecut de la `Zend\\` la `Laminas\\`. Proiectele vechi încă folosesc `Zend`, de aceea apare la interviuri."]}, {"id": "zz2", "d": "php", "nou": 1, "t": "mc", "q": "La ce folosește ServiceManager în Zend/Laminas MVC?", "o": ["Container de servicii: creează și păstrează obiecte prin fabrici definite în configurare", "Gestionează sesiunile utilizatorului", "Rulează interogări SQL"], "a": 0, "h": "Zona de dependency injection.", "e": "ServiceManager instanțiază servicii prin factories (config 'service_manager') și le injectează în controllere.", "px": ["ServiceManager e containerul de servicii: spui o dată cum se construiește un obiect (fabrică, în configurare), iar el îl creează și îl reține. Controllerele își cer serviciile de acolo."]}, {"id": "zz3", "d": "php", "nou": 1, "t": "mc", "q": "Unde definești de obicei rutele unui modul Zend/Laminas MVC?", "o": ["În module.config.php, cheia 'router' => 'routes'", "În index.php", "În fișierul .htaccess"], "a": 0, "h": "Config de modul.", "e": "Fiecare modul întoarce un array de configurare cu rute, controllere și view_manager.", "px": ["Fiecare modul își declară rutele în `config/module.config.php`, la `router` > `routes`: ce URL ajunge la ce controller și acțiune."]}, {"id": "zz4", "d": "php", "nou": 1, "t": "mc", "q": "Ce rol are clasa Module într-un modul Zend/Laminas?", "o": ["Furnizează configurarea modulului (getConfig) și poate înregistra evenimente la bootstrap", "Este controllerul principal", "Conține doar view-urile"], "a": 0, "h": "Punctul de intrare al modulului.", "e": "Module::getConfig() întoarce config-ul, care e unit în configurarea aplicației.", "px": ["Clasa `Module` e „cartea de identitate” a modulului. `getConfig()` întoarce configurarea (rute, servicii, view-uri). Poate reacționa și la evenimente de bootstrap."]}, {"id": "zz5", "d": "php", "nou": 1, "t": "mc", "q": "Ce este un TableGateway în Zend\\Db / Laminas\\Db?", "o": ["Obiect care încapsulează accesul la un tabel (select, insert, update, delete)", "O tabelă HTML generată automat", "Un middleware de rutare"], "a": 0, "h": "Pattern: Table Data Gateway.", "e": "TableGateway abstractizează operațiile pe un singur tabel, fără SQL scris de mână.", "px": ["TableGateway reprezintă un tabel: `select()`, `insert()`, `update()`, `delete()` fără să scrii SQL de mână. Te adresezi tabelului, nu conexiunii."]}, {"id": "zz6", "d": "php", "nou": 1, "t": "mc", "q": "La ce folosește un InputFilter în Zend/Laminas?", "o": ["Definește reguli de filtrare și validare pentru datele unui formular", "Filtrează rutele", "Filtrează răspunsurile HTTP"], "a": 0, "h": "Validare + filtrare la un loc.", "e": "InputFilter leagă filtre (trim, strip tags) și validatori (obligatoriu, lungime, email) de câmpuri.", "px": ["InputFilter descrie, pentru fiecare câmp, ce se curăță (filtre, ex. trim) și ce se verifică (validatori, ex. email, lungime). Îl atașezi formularului."]}, {"id": "zz7", "d": "php", "nou": 1, "t": "mc", "q": "Cum trimite o acțiune de controller date către view în Zend/Laminas MVC?", "o": ["Returnează un ViewModel cu variabilele", "Folosește echo în controller", "Setează variabile $_GLOBALS"], "a": 0, "h": "Obiectul de view model.", "e": "return new ViewModel(['items' => $items]); iar view-ul le citește ca $this->items.", "px": ["Acțiunea controllerului nu afișează nimic direct. Returnează `new ViewModel(['titlu' => ...])`, iar șablonul `.phtml` primește variabilele."]}, {"id": "zz8", "d": "php", "nou": 1, "t": "mc", "q": "La ce folosește un Hydrator?", "o": ["Convertește între array și obiect (extract/hydrate), de exemplu pentru entități și formulare", "Criptează parolele", "Generează rute"], "a": 0, "h": "Din array în obiect și invers.", "e": "hydrate() populează obiectul dintr-un array, extract() face invers.", "px": ["Hydrator face legătura între un array (ex. datele din formular sau din DB) și un obiect: `hydrate()` umple obiectul, `extract()` scoate array-ul înapoi."]}, {"id": "zz9", "d": "php", "nou": 1, "t": "mc", "q": "Ce este Mezzio (fost Zend Expressive)?", "o": ["Microframework bazat pe middleware PSR-7/PSR-15", "Un ORM", "O extensie PHP"], "a": 0, "h": "Alternativă mai ușoară la MVC.", "e": "Mezzio construiește aplicația ca pipeline de middleware PSR-15, cu routere și containere interschimbabile.", "px": ["Mezzio (fost Expressive) e un microframework: cererea trece printr-un lanț de middleware PSR-15, pe obiecte HTTP PSR-7. Ai doar ce adaugi tu, spre deosebire de MVC complet."]}, {"id": "zz10", "d": "php", "nou": 1, "t": "mc", "q": "Cum instalezi componenta MVC Laminas într-un proiect?", "o": ["composer require laminas/laminas-mvc", "pear install zend", "npm install laminas"], "a": 0, "h": "Pachetele PHP moderne se instalează cu Composer.", "e": "Laminas e distribuit ca pachete Composer separate pe componente.", "px": ["Componentele se instalează cu Composer: `composer require laminas/laminas-mvc`. Numele pachetului e `laminas/laminas-mvc`, nu `zendframework/...`."]}, {"id": "zj1", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre $(document).ready() și $(window).on('load')?", "o": ["ready se declanșează când DOM-ul e gata, load abia după ce s-au încărcat și imaginile/resursele", "Sunt identice", "load se declanșează înainte de ready"], "a": 0, "h": "DOM versus toate resursele.", "e": "ready nu așteaptă imaginile. load așteaptă toate resursele paginii.", "px": ["`$(document).ready()` rulează când HTML-ul e gata de manevrat (DOM construit). `load` pe `window` așteaptă și imaginile, stilurile și restul resurselor. Pentru atașat evenimente, `ready` e de obicei suficient și mai rapid."]}, {"id": "zj2", "d": "web", "nou": 1, "t": "mc", "q": "Cum atașezi un click pe elementele <li> adăugate dinamic mai târziu în #lista?", "o": ["$('#lista').on('click', 'li', fn) — event delegation", "$('li').click(fn) înainte să existe elementele", "$('#lista').click(fn) pe fiecare li nou"], "a": 0, "h": "Handlerul stă pe un părinte existent.", "e": "Cu delegation, handlerul e pe un părinte stabil, iar evenimentul care bubbles e filtrat după selector.", "px": ["Pasul 1: handlerul se leagă o singură dată, pe `#lista`. Al doilea argument, `'li'`, spune jQuery pe ce copii să reacționeze.", "Pasul 2: când apeși pe un `li`, evenimentul urcă la `#lista` (bubbling), iar jQuery verifică dacă ținta e un `li`. Dacă da, rulează funcția, iar `this` e `li`-ul apăsat.", "Încearcă: apasă „Adaugă un li nou”, apoi pe elementul nou. Merge, deși nu exista când ai legat handlerul.", "Contrast: schimbă linia în `$('#lista li').on('click', ...)`. Elementele noi nu mai reacționează, pentru că handlerul s-a legat doar de `li`-urile care existau atunci."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<h3>Event delegation cu jQuery</h3>\n<ul id=\"lista\">\n  <li>A</li>\n  <li>B</li>\n</ul>\n<button id=\"adauga\">Adaugă un li nou</button>\n<p id=\"rezultat\">Apasă pe un element din listă.</p>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<h3>Event delegation cu jQuery</h3>\n<ul id=\"lista\">\n  <li>A</li>\n  <li>B</li>\n</ul>\n<button id=\"adauga\">Adaugă un li nou</button>\n<p id=\"rezultat\">Apasă pe un element din listă.</p>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\nli { cursor: pointer; padding: 4px 8px; }\nli:hover { background: #eef2ff; }\n.ales { background: #fff2a8; }\n", "js": "// Pasul 1: UN singur handler, pe părinte (#lista). 'li' = pe ce copii reacționează.\n$('#lista').on('click', 'li', function () {\n  $('#lista li').removeClass('ales');\n  $(this).addClass('ales');\n  $('#rezultat').text('Click pe: ' + $(this).text());\n});\n\n// Pasul 2: adăugăm un li DUPĂ ce handlerul a fost legat.\n$('#adauga').on('click', function () {\n  $('#lista').append('<li>Nou ' + ($('#lista li').length + 1) + '</li>');\n});\n\n// Încearcă: apasă „Adaugă”, apoi pe noul element. Merge fără alt handler.\n// Contrast: înlocuiește primul rând cu  $('#lista li').on('click', function () {...})\n// și noul li nu mai reacționează.\n"}}}, {"id": "zj3", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre .attr('checked') și .prop('checked') pe un checkbox?", "o": ["prop reflectă starea curentă (true/false), attr reflectă atributul din HTML inițial", "Sunt identice", "attr e mai nou"], "a": 0, "h": "Atribute versus proprietăți DOM.", "e": "Pentru checked, selected, disabled folosești .prop(), care urmărește starea actuală.", "px": ["`prop('checked')` dă starea de acum (`true`/`false`). `attr('checked')` citește atributul scris în HTML, care nu se schimbă când bifezi.", "Încearcă: apasă „Arată valorile” fără bifă, apoi bifează și apasă iar. `prop` se schimbă, `attr` rămâne `undefined`."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<label><input type=\"checkbox\" id=\"cb\"> Bifează-mă</label>\n<p id=\"out\"></p>\n<button id=\"arata\">Arată valorile</button>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<label><input type=\"checkbox\" id=\"cb\"> Bifează-mă</label>\n<p id=\"out\"></p>\n<button id=\"arata\">Arată valorile</button>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\n", "js": "// atributul din HTML nu are checked; proprietatea reflectă starea curentă\n$('#arata').on('click', function () {\n  $('#out').html(\n    \"prop('checked') = <b>\" + $('#cb').prop('checked') + \"</b><br>\" +\n    \"attr('checked') = <b>\" + $('#cb').attr('checked') + \"</b>\"\n  );\n});\n// Încearcă: apasă „Arată” înainte de bifare, apoi bifează și apasă din nou.\n"}}}, {"id": "zj4", "d": "web", "nou": 1, "t": "mc", "q": "De ce e riscant $(el).html(textDeLaUtilizator)?", "o": ["Interpretează textul ca HTML și poate executa cod (XSS); .text() îl tratează ca text", "E prea lent", "Șterge elementul părinte"], "a": 0, "h": ".text() versus .html().", "e": "Pentru conținut necontrolat folosești .text(), care escapează caracterele speciale.", "px": ["`.html(text)` interpretează textul ca HTML. Dacă utilizatorul scrie `<img src=x onerror=...>`, codul rulează (XSS). `.text()` îl afișează ca simplu text."]}, {"id": "zj5", "d": "web", "nou": 1, "t": "mc", "q": "Cum ieși dintr-un $.each() înainte de final?", "o": ["Returnezi false din callback", "Folosești break", "Apelezi $.stop()"], "a": 0, "h": "Return, nu break.", "e": "Într-un $.each, return false oprește bucla; return true sare la următorul element (ca continue).", "px": ["În `$.each` nu merge `break`. Returnezi `false` din callback ca să te oprești; `return true` sare doar la elementul următor (ca `continue`)."]}, {"id": "zj6", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre .find('p') și .children('p')?", "o": ["find caută în toți descendenții, children doar în copiii direcți", "Sunt identice", "children caută și în părinți"], "a": 0, "h": "Adâncimea căutării.", "e": "find parcurge întreg subarborele, children doar primul nivel.", "px": ["`find('p')` caută în toți descendenții (copii, nepoți...). `children('p')` caută doar în copiii direcți.", "Încearcă: apasă pe fiecare buton. Primul marchează 2 paragrafe, al doilea doar unul."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<div id=\"radacina\">\n  <p>copil direct</p>\n  <section><p>nepot (în section)</p></section>\n</div>\n<button id=\"f\">find('p')</button> <button id=\"c\">children('p')</button>\n<p id=\"out\">Apasă un buton.</p>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<div id=\"radacina\">\n  <p>copil direct</p>\n  <section><p>nepot (în section)</p></section>\n</div>\n<button id=\"f\">find('p')</button> <button id=\"c\">children('p')</button>\n<p id=\"out\">Apasă un buton.</p>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\n.marcat { background: #fff2a8; }\n", "js": "$('#f').on('click', function () {\n  $('p').removeClass('marcat');\n  var n = $('#radacina').find('p').addClass('marcat').length;\n  $('#out').text(\"find('p') a găsit \" + n + \" elemente\");\n});\n$('#c').on('click', function () {\n  $('p').removeClass('marcat');\n  var n = $('#radacina').children('p').addClass('marcat').length;\n  $('#out').text(\"children('p') a găsit \" + n + \" element\");\n});\n"}}}, {"id": "zj7", "d": "web", "nou": 1, "t": "mc", "q": "Un $.ajax cu dataType: 'json' primește un răspuns care nu e JSON valid. Ce se întâmplă?", "o": ["Se apelează error (cu textStatus 'parsererror'), chiar dacă HTTP e 200", "Se apelează success cu string", "Nu se apelează nimic"], "a": 0, "h": "Statusul HTTP nu e tot.", "e": "jQuery încearcă să parseze răspunsul; dacă eșuează, apelul e tratat ca eroare.", "px": ["jQuery încearcă să parseze răspunsul ca JSON. Dacă nu e valid, apelează `error` cu `textStatus` = `parsererror`, deși serverul a răspuns 200. Succesul HTTP nu garantează conținut valid."]}, {"id": "zj8", "d": "web", "nou": 1, "t": "mc", "q": "Într-un handler $('.btn').on('click', () => { $(this)... }) ce nu merge?", "o": ["this nu mai e elementul apăsat, pentru că arrow function nu are this propriu", "Nimic, merge normal", "$(this) e mereu document"], "a": 0, "h": "Funcție clasică versus arrow.", "e": "Într-un handler jQuery obișnuit, this e elementul DOM. Cu arrow function, this vine din scope-ul exterior; folosește event.currentTarget.", "px": ["O funcție clasică are `this` = elementul apăsat. O arrow function nu are `this` propriu, îl moștenește din exterior, deci `$(this)` nu mai e butonul. Folosește `function () { ... }` sau `event.currentTarget`."]}, {"id": "zj9", "d": "web", "nou": 1, "t": "mc", "q": "Ce face return false într-un handler jQuery?", "o": ["Apelează preventDefault() și stopPropagation()", "Doar preventDefault()", "Doar oprește handlerele de pe același element"], "a": 0, "h": "Două efecte într-unul.", "e": "În jQuery return false face ambele. În JS nativ (addEventListener) nu.", "px": ["În handler jQuery, `return false` face două lucruri: `preventDefault()` (linkul nu mai navighează) și `stopPropagation()` (evenimentul nu urcă la părinte).", "Încearcă: apasă linkul, apoi șterge `return false;` și apasă iar. Apare și mesajul de la cutie."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<div id=\"cutie\" style=\"padding:12px;border:1px solid #999\">\n  <a id=\"link\" href=\"#sus\">Link (ar sări la #sus)</a>\n</div>\n<p id=\"log\"></p>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<div id=\"cutie\" style=\"padding:12px;border:1px solid #999\">\n  <a id=\"link\" href=\"#sus\">Link (ar sări la #sus)</a>\n</div>\n<p id=\"log\"></p>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\n", "js": "$('#cutie').on('click', function () { $('#log').append('cutia a primit click<br>'); });\n$('#link').on('click', function () {\n  $('#log').append('link apăsat<br>');\n  return false;   // în jQuery = preventDefault() + stopPropagation()\n});\n// Încearcă: apasă linkul. Apare „link apăsat”, dar NU „cutia a primit click”.\n// Șterge „return false;” și apasă din nou: apar ambele.\n"}}}, {"id": "zj10", "d": "web", "nou": 1, "t": "mc", "q": "$('div').data('id') față de $('div').attr('data-id'): care e diferența?", "o": ["data() convertește tipul (ex. număr/obiect) și ține valoarea în cache; attr dă mereu string-ul din atribut", "Sunt identice", "attr convertește în număr"], "a": 0, "h": "Cache intern.", "e": "După ce citești cu .data(), schimbarea atributului în HTML nu mai e reflectată automat.", "px": ["`attr('data-id')` dă mereu text. `data('id')` convertește tipul (număr, boolean, JSON) și ține valoarea în cache; dacă schimbi atributul după aceea, `data()` poate rămâne cu valoarea veche."]}, {"id": "zj11", "d": "web", "nou": 1, "t": "mc", "q": "Ce face .closest('tr') apelat pe un <td>?", "o": ["Urcă prin strămoși (începând cu elementul însuși) până la primul <tr>", "Caută <tr> în copiii lui td", "Întoarce toate <tr> din pagină"], "a": 0, "h": "Parcurgere în sus.", "e": "closest merge de la element în sus. parents() întoarce toți strămoșii.", "px": ["`closest('tr')` pornește de la elementul apăsat și urcă prin strămoși până găsește primul `tr`.", "Încearcă: apasă „Alege” pe un rând. Tot rândul se colorează, nu doar celula."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<table id=\"t\">\n  <tr><td>Ana</td><td><button class=\"b\">Alege</button></td></tr>\n  <tr><td>Bob</td><td><button class=\"b\">Alege</button></td></tr>\n</table>\n<p id=\"out\">Apasă un buton.</p>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"></script>\n</head>\n<body>\n<table id=\"t\">\n  <tr><td>Ana</td><td><button class=\"b\">Alege</button></td></tr>\n  <tr><td>Bob</td><td><button class=\"b\">Alege</button></td></tr>\n</table>\n<p id=\"out\">Apasă un buton.</p>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\ntable { border-collapse: collapse; } td { border: 1px solid #ccc; padding: 6px 10px; }\n.sel { background: #fff2a8; }\n", "js": "$('#t').on('click', '.b', function () {\n  $('tr').removeClass('sel');\n  var rand = $(this).closest('tr');      // urcă din buton până la <tr>\n  rand.addClass('sel');\n  $('#out').text('Rând ales: ' + rand.find('td').first().text());\n});\n"}}}, {"id": "zj12", "d": "web", "nou": 1, "t": "mc", "q": "Ce trebuie să întoarcă un plugin jQuery ca să permită chaining?", "o": ["this (de obicei return this.each(...))", "un boolean", "un string"], "a": 0, "h": "$.fn.numePlugin.", "e": "Plugin-urile se adaugă în $.fn și întorc setul de elemente primit.", "px": ["jQuery e construit pe lanțuri: `$('x').a().b()`. Pluginul tău trebuie să returneze `this`, de obicei `return this.each(...)`, altfel lanțul se rupe."]}, {"id": "zq1", "d": "sql", "nou": 1, "t": "mc", "q": "Care e diferența dintre WHERE și HAVING?", "o": ["WHERE filtrează rândurile înainte de grupare, HAVING filtrează grupurile după agregare", "Sunt identice", "HAVING se aplică înainte de GROUP BY"], "a": 0, "h": "Ordinea de execuție.", "e": "WHERE nu poate folosi agregate (COUNT, SUM). HAVING da, pentru că rulează după GROUP BY.", "px": ["`WHERE` taie rânduri înainte să se facă grupurile. `HAVING` taie grupuri după ce s-au calculat agregările.", "Încearcă: pune `COUNT(*) > 1` în `WHERE` și citește eroarea."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT dept, COUNT(*) AS nr, AVG(salary) AS medie\nFROM emp\nWHERE salary > 4000            -- filtreaza RANDURI, inainte de grupare\nGROUP BY dept\nHAVING COUNT(*) > 1            -- filtreaza GRUPURI, dupa agregare\nORDER BY dept;\n"}}, {"id": "zq2", "d": "sql", "nou": 1, "t": "mc", "q": "Care e ordinea logică de execuție a unei interogări?", "o": ["FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY, LIMIT", "SELECT, FROM, WHERE, GROUP BY", "WHERE, FROM, SELECT, HAVING"], "a": 0, "h": "SELECT nu rulează primul.", "e": "De aceea un alias definit în SELECT nu poate fi folosit în WHERE.", "px": ["Scrii `SELECT` primul, dar baza de date îl evaluează aproape ultimul. Ordinea logică: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY, LIMIT.", "De aici: un alias definit în SELECT nu poate fi folosit în WHERE (încă nu există), dar poate în ORDER BY. (Unele sisteme, ca MySQL, permit alias în GROUP BY/HAVING.)"]}, {"id": "zq3", "d": "sql", "nou": 1, "t": "mc", "q": "Care e diferența dintre COUNT(*) și COUNT(coloana)?", "o": ["COUNT(*) numără toate rândurile, COUNT(coloana) ignoră valorile NULL", "Sunt identice", "COUNT(coloana) numără și NULL"], "a": 0, "h": "Tratamentul NULL.", "e": "Funcțiile de agregare (în afară de COUNT(*)) ignoră NULL.", "px": ["`COUNT(coloană)` ignoră NULL. Ana nu are șef, deci iese 6 față de 7.", "Încearcă: adaugă `COUNT(DISTINCT dept)`."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT COUNT(*) AS toate, COUNT(boss_id) AS cu_sef FROM emp;\n"}}, {"id": "zq4", "d": "sql", "nou": 1, "t": "mc", "q": "De ce WHERE coloana = NULL nu întoarce rânduri?", "o": ["NULL înseamnă necunoscut; comparația dă UNKNOWN. Folosești IS NULL", "NULL e egal cu 0", "Sintaxa e interzisă"], "a": 0, "h": "Logică cu trei valori.", "e": "Orice comparație cu NULL (inclusiv NULL = NULL) nu e adevărată. Folosești IS NULL / IS NOT NULL.", "px": ["`= NULL` nu e niciodată adevărat (nici `NULL = NULL`). Pentru NULL folosești `IS NULL`.", "Încearcă: rulează ambele."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT name FROM emp WHERE boss_id = NULL;     -- nimic\nSELECT name FROM emp WHERE boss_id IS NULL;    -- Ana\n"}}, {"id": "zq5", "d": "sql", "nou": 1, "t": "mc", "q": "WHERE id NOT IN (SELECT x FROM t) întoarce zero rânduri deși există id-uri care nu sunt în t. Ce cauză probabilă?", "o": ["Subinterogarea conține cel puțin un NULL", "Lipsește un index", "NOT IN e depreciat"], "a": 0, "h": "NULL în lista NOT IN.", "e": "Dacă lista conține NULL, NOT IN nu poate fi adevărat. Folosește NOT EXISTS sau filtrează x IS NOT NULL.", "px": ["`x NOT IN (1, 2, NULL)` înseamnă „x diferit de 1 ȘI de 2 ȘI de NULL”. Comparația cu NULL nu e niciodată adevărată, deci tot rezultatul devine necunoscut și nu iese niciun rând.", "Soluții: filtrezi NULL în subinterogare sau folosești `NOT EXISTS`."]}, {"id": "zq6", "d": "sql", "nou": 1, "t": "mc", "q": "SELECT ... FROM a LEFT JOIN b ON a.id = b.a_id WHERE b.status = 'ok'. Ce efect are condiția din WHERE?", "o": ["Elimină rândurile fără pereche și transformă practic LEFT JOIN în INNER JOIN", "Nu are niciun efect", "Păstrează toate rândurile din a"], "a": 0, "h": "Rândurile fără pereche au b.status NULL.", "e": "Pentru a păstra LEFT JOIN, muți condiția în ON: ... ON a.id = b.a_id AND b.status = 'ok'.", "px": ["LEFT JOIN umple cu NULL partea din dreapta când nu există pereche. Dar `WHERE b.status = 'ok'` respinge rândurile cu NULL, deci pierzi exact rândurile păstrate de LEFT JOIN.", "Dacă vrei să păstrezi clienții fără pereche, muți condiția în `ON`."]}, {"id": "zq7", "d": "sql", "nou": 1, "t": "mc", "q": "Care e diferența dintre UNION și UNION ALL?", "o": ["UNION elimină duplicatele, UNION ALL le păstrează (și e mai rapid)", "Sunt identice", "UNION ALL elimină duplicatele"], "a": 0, "h": "Cost de deduplicare.", "e": "UNION face sortare/deduplicare. UNION ALL doar concatenează rezultatele.", "px": ["`UNION` elimină duplicatele (face o muncă în plus). `UNION ALL` doar lipește rezultatele și e mai rapid.", "Încearcă: numără rândurile din fiecare."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT dept FROM emp WHERE salary > 6000\nUNION\nSELECT dept FROM emp WHERE salary < 5000;\n\nSELECT dept FROM emp WHERE salary > 6000\nUNION ALL\nSELECT dept FROM emp WHERE salary < 5000;\n"}}, {"id": "zq8", "d": "sql", "nou": 1, "t": "mc", "q": "Ce face ROW_NUMBER() OVER (PARTITION BY client ORDER BY data DESC)?", "o": ["Numerotează rândurile fiecărui client de la 1, cele mai recente primele", "Șterge duplicatele", "Grupează clienții într-un singur rând"], "a": 0, "h": "Funcție fereastră.", "e": "Pentru cea mai recentă comandă per client filtrezi rn = 1 într-o subinterogare.", "px": ["`PARTITION BY` împarte rândurile în grupuri fără să le unească (spre deosebire de `GROUP BY`). `ROW_NUMBER` numerotează în fiecare grup.", "Filtrezi `rn = 1` ca să iei cel mai recent rând per client.", "Încearcă: rulează cele două interogări."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS orders;\nCREATE TABLE orders(id INT, client TEXT, total INT, dt TEXT);\nINSERT INTO orders VALUES (1,'A',100,'2024-01-01'),(2,'B',50,'2024-01-01'),(3,'A',70,'2024-01-02'),(4,'C',30,'2024-01-03'),(5,'A',20,'2024-01-03');\nDROP TABLE IF EXISTS order_items;\nCREATE TABLE order_items(order_id INT, sku TEXT, qty INT);\nINSERT INTO order_items VALUES (1,'x',1),(1,'y',2),(2,'x',1);\n\nSELECT id, client, total,\n  ROW_NUMBER() OVER (PARTITION BY client ORDER BY dt DESC, id DESC) AS rn\nFROM orders ORDER BY client, rn;\n\n-- cea mai recenta comanda per client:\nSELECT * FROM (\n  SELECT *, ROW_NUMBER() OVER (PARTITION BY client ORDER BY dt DESC, id DESC) AS rn FROM orders\n) WHERE rn = 1;\n"}}, {"id": "zq9", "d": "sql", "nou": 1, "t": "mc", "q": "Cum diferă RANK() de DENSE_RANK() când două rânduri au același scor?", "o": ["RANK sare numere după egalitate (1,1,3), DENSE_RANK nu (1,1,2)", "Sunt identice", "DENSE_RANK sare numere"], "a": 0, "h": "Gol în numerotare.", "e": "DENSE_RANK nu lasă goluri după egalități.", "px": ["Doi elevi au aceeași notă maximă. `RANK` le dă locul 1 și 1, iar următorul primește locul 3 (se „sare” un loc). `DENSE_RANK` dă 1, 1, 2, fără goluri."]}, {"id": "zq10", "d": "sql", "nou": 1, "t": "mc", "q": "Ai un index compus (a, b). Pentru care filtru indexul NU ajută eficient?", "o": ["WHERE b = 5 (fără a)", "WHERE a = 1", "WHERE a = 1 AND b = 5"], "a": 0, "h": "Regula prefixului din stânga.", "e": "Un index compus se folosește începând de la prima coloană. Fără a, optimizatorul de obicei nu-l poate folosi.", "px": ["Indexul (a, b) e ca o agendă sortată întâi după a, apoi după b. Cauți ușor după a, sau după a și b. După b singur nu poți, pentru că b e sortat doar în interiorul fiecărui a."]}, {"id": "zq11", "d": "sql", "nou": 1, "t": "mc", "q": "De ce WHERE YEAR(data) = 2024 poate fi lent pe o coloană indexată?", "o": ["Funcția aplicată pe coloană împiedică folosirea indexului; folosești data >= '2024-01-01' AND data < '2025-01-01'", "YEAR e depreciat", "Indexul se șterge"], "a": 0, "h": "Sargable.", "e": "Condițiile „sargable” compară coloana direct, fără funcții pe ea.", "px": ["Indexul e sortat după valoarea coloanei, nu după `YEAR(coloana)`. Dacă aplici o funcție pe coloană, baza trebuie să calculeze funcția pe fiecare rând.", "Rescrie ca interval: `data >= '2024-01-01' AND data < '2025-01-01'`."]}, {"id": "zq12", "d": "sql", "nou": 1, "t": "mc", "q": "Care LIKE poate folosi un index B-tree obișnuit?", "o": ["LIKE 'abc%'", "LIKE '%abc'", "LIKE '%abc%'"], "a": 0, "h": "Prefix fix.", "e": "Un prefix cunoscut permite căutare în interval. Wildcard la început obligă la scanare completă.", "px": ["Indexul e sortat alfabetic. „Cuvintele care încep cu abc” sunt grupate la un loc, deci `LIKE 'abc%'` merge. `LIKE '%abc'` nu are un punct de pornire, deci scanează tot."]}, {"id": "zq13", "d": "sql", "nou": 1, "t": "mc", "q": "De ce LIMIT 10 OFFSET 100000 devine lent?", "o": ["Baza trebuie să parcurgă și să arunce cele 100000 de rânduri dinainte; paginarea pe cheie (WHERE id > ultimul) e mai rapidă", "LIMIT nu merge cu OFFSET", "OFFSET e limitat la 1000"], "a": 0, "h": "Keyset pagination.", "e": "Offset mare = muncă inutilă. Folosești WHERE id > ? ORDER BY id LIMIT 10.", "px": ["`OFFSET 100000` nu sare direct: baza citește și aruncă cele 100000 de rânduri. Cu cât paginile sunt mai departe, cu atât e mai lent.", "Alternativa: paginare pe cheie, `WHERE id > ultimul_id ORDER BY id LIMIT 10`."]}, {"id": "zq14", "d": "sql", "nou": 1, "t": "mc", "q": "Cum previi SQL injection în aplicație?", "o": ["Interogări parametrizate (prepared statements), nu concatenare de string-uri", "Înlocuiești apostroful cu spațiu", "Folosești LIMIT 1"], "a": 0, "h": "Separi codul de date.", "e": "Cu prepared statements, valoarea nu poate schimba structura interogării.", "px": ["Nu lipi textul utilizatorului în interogare. Trimiți interogarea cu locuri goale (`?`) și valorile separat. Baza le tratează mereu ca date, niciodată ca SQL."]}, {"id": "zq15", "d": "sql", "nou": 1, "t": "mc", "q": "Ce înseamnă ACID la tranzacții?", "o": ["Atomicity, Consistency, Isolation, Durability", "Access, Control, Index, Data", "Append, Commit, Insert, Delete"], "a": 0, "h": "Patru proprietăți.", "e": "Tranzacția se execută complet sau deloc (atomicitate), lasă baza consistentă, e izolată de altele și durabilă după COMMIT.", "px": ["ACID: Atomicity (tot sau nimic), Consistency (regulile bazei rămân respectate), Isolation (tranzacțiile paralele nu se încurcă), Durability (după commit, datele rezistă la oprire)."]}, {"id": "zq16", "d": "sql", "nou": 1, "t": "mc", "q": "Ce face COALESCE(a, b, 'n/a')?", "o": ["Întoarce prima valoare non-NULL din listă", "Concatenează valorile", "Întoarce suma"], "a": 0, "h": "Valoare de rezervă pentru NULL.", "e": "Util pentru afișare: COALESCE(telefon, 'fără telefon').", "px": ["`COALESCE` întoarce prima valoare care nu e NULL din listă.", "Încearcă: înlocuiește NULL-urile cu un text la alegerea ta."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT name, COALESCE(boss_id, 0) AS sef, COALESCE(NULL, NULL, 'implicit') AS prima_nenula FROM emp LIMIT 3;\n"}}, {"id": "zq17", "d": "sql", "nou": 1, "t": "mc", "q": "În MySQL, ce întoarce CONCAT('a', NULL, 'b')?", "o": ["NULL", "'ab'", "'anullb'"], "a": 0, "h": "NULL contaminează.", "e": "CONCAT întoarce NULL dacă un argument e NULL. CONCAT_WS sare peste NULL.", "px": ["Orice operație cu NULL dă NULL. În MySQL `CONCAT('a', NULL, 'b')` e NULL; `CONCAT_WS` sare peste NULL. Aici folosim `||` din SQLite, care se comportă la fel.", "Încearcă: rulează ambele."], "tr": {"l": "sql", "c": "\nSELECT 'a' || NULL || 'b' AS concatenare_cu_null;     -- NULL\nSELECT 'a' || COALESCE(NULL, '') || 'b' AS cu_coalesce;  -- ab\n"}}, {"id": "zq18", "d": "sql", "nou": 1, "t": "mc", "q": "Care e diferența dintre DELETE și TRUNCATE?", "o": ["DELETE poate avea WHERE și e logat rând cu rând; TRUNCATE golește tot tabelul, e DDL și resetează AUTO_INCREMENT", "Sunt identice", "TRUNCATE are WHERE"], "a": 0, "h": "Cât de mult șterg și cum.", "e": "TRUNCATE nu acceptă WHERE. DROP elimină și structura tabelului.", "px": ["`DELETE` șterge rânduri alese cu `WHERE`. `TRUNCATE` golește tot tabelul, rapid, fără `WHERE`. Fiind DDL, în MySQL resetează și `AUTO_INCREMENT`."]}, {"id": "zq19", "d": "sql", "nou": 1, "t": "mc", "q": "Ce întoarce SUM(col) pe un set gol, față de COUNT(col)?", "o": ["SUM dă NULL, COUNT dă 0", "Ambele dau 0", "Ambele dau NULL"], "a": 0, "h": "Agregate pe nimic.", "e": "Folosești COALESCE(SUM(col), 0) dacă vrei 0.", "px": ["Pe zero rânduri, `COUNT` dă 0, dar `SUM` și `AVG` dau NULL.", "De aceea scrii `COALESCE(SUM(...), 0)`.", "Încearcă: rulează."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT SUM(salary), COUNT(salary), AVG(salary) FROM emp WHERE dept = 'Legal';\nSELECT COALESCE(SUM(salary), 0) AS suma_sigura FROM emp WHERE dept = 'Legal';\n"}}, {"id": "zq20", "d": "sql", "nou": 1, "t": "mc", "q": "Ce face INSERT ... ON DUPLICATE KEY UPDATE (MySQL)?", "o": ["Dacă există o cheie unică/primară duplicat, face UPDATE în loc de eroare", "Ignoră rândul", "Șterge rândul vechi și inserează unul nou"], "a": 0, "h": "Upsert.", "e": "Spre deosebire de REPLACE, nu șterge rândul vechi.", "px": ["Dacă cheia unică există deja, în loc de eroare faci `UPDATE`. În SQLite și PostgreSQL sintaxa e `ON CONFLICT`, în MySQL `ON DUPLICATE KEY UPDATE`.", "Încearcă: rulează și vezi un singur rând cu 5."], "tr": {"l": "sql", "c": "\nDROP TABLE IF EXISTS stoc;\nCREATE TABLE stoc(sku TEXT PRIMARY KEY, nr INT);\nINSERT INTO stoc VALUES ('x', 1);\nINSERT INTO stoc VALUES ('x', 5)\n  ON CONFLICT(sku) DO UPDATE SET nr = excluded.nr;   -- in MySQL: ON DUPLICATE KEY UPDATE\nSELECT * FROM stoc;\n"}}, {"id": "zq21", "d": "sql", "nou": 1, "t": "mc", "q": "Care e diferența dintre IN și EXISTS?", "o": ["EXISTS verifică doar dacă există vreun rând în subinterogare (se oprește la primul) și nu are problema NULL din NOT IN", "Sunt interzise împreună", "IN merge doar cu numere"], "a": 0, "h": "Corelare și NULL.", "e": "NOT EXISTS e de obicei varianta sigură față de NOT IN.", "px": ["`EXISTS` întreabă „există măcar un rând?” și se oprește la primul. `IN` compară cu o listă de valori. Cu `NOT IN` apare capcana NULL, iar `NOT EXISTS` nu o are."]}, {"id": "zq22", "d": "sql", "nou": 1, "t": "mc", "q": "Ce garantează o cheie primară?", "o": ["Unicitate și NOT NULL, doar una pe tabel (poate fi compusă)", "Doar unicitate, poate avea NULL", "Doar index, fără unicitate"], "a": 0, "h": "PK versus UNIQUE.", "e": "UNIQUE permite NULL (în MySQL, mai multe) și poate exista de mai multe ori pe tabel.", "px": ["Cheia primară identifică fiecare rând: valorile sunt unice, fără NULL. Un tabel are cel mult una, dar poate fi formată din mai multe coloane."]}, {"id": "zq23", "d": "sql", "nou": 1, "t": "mc", "q": "Ce face ON DELETE CASCADE la o cheie străină?", "o": ["La ștergerea rândului părinte se șterg automat rândurile copil", "Blochează ștergerea", "Setează copiii pe NULL"], "a": 0, "h": "Efect în lanț.", "e": "SET NULL setează cheia străină pe NULL. RESTRICT blochează ștergerea.", "px": ["Dacă ștergi clientul (părintele), comenzile lui (copiii) se șterg automat. Fără `CASCADE`, baza ar refuza ștergerea, sau ai rămâne cu comenzi „orfane”. Folosește-l cu grijă."]}, {"id": "zq24", "d": "sql", "nou": 1, "t": "mc", "q": "BETWEEN 5 AND 10 include limitele?", "o": ["Da, ambele (5 și 10)", "Nu, exclude ambele", "Include doar 5"], "a": 0, "h": "Inclusiv.", "e": "Pentru date cu oră atenție: BETWEEN pe zi poate omite după 00:00 din ultima zi.", "px": ["`BETWEEN 5 AND 10` înseamnă `>= 5 AND <= 10`: ambele capete sunt incluse. La date cu oră, atenție: `BETWEEN '2024-01-01' AND '2024-01-31'` nu prinde 31 ianuarie după ora 00:00."]}, {"id": "zq25", "d": "sql", "nou": 1, "t": "mc", "q": "Ce rezultat dă AVG(col) pe valorile 10, 20, NULL?", "o": ["15, pentru că NULL e ignorat", "10", "Eroare"], "a": 0, "h": "Agregate ignoră NULL.", "e": "Se împarte la numărul de valori non-NULL (2), nu la 3.", "px": ["`AVG` ignoră NULL: împarte la numărul de valori non-NULL, nu la toate rândurile.", "Încearcă: compară cele două rezultate."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT AVG(boss_id) AS media_ignorand_null, SUM(boss_id) * 1.0 / COUNT(*) AS suma_pe_toate FROM emp;\n"}}, {"id": "zq26", "d": "sql", "nou": 1, "t": "mc", "q": "Cum găsești duplicatele pe coloana email?", "o": ["SELECT email, COUNT(*) FROM t GROUP BY email HAVING COUNT(*) > 1", "SELECT DISTINCT email FROM t", "SELECT email FROM t WHERE COUNT(*) > 1"], "a": 0, "h": "GROUP BY + HAVING.", "e": "WHERE nu acceptă agregate, de aceea HAVING.", "px": ["Grupezi după coloana pe care o cauți și păstrezi grupurile cu mai mult de 1 rând.", "`WHERE COUNT(*) > 1` nu merge: `WHERE` rulează înainte de grupare.", "Încearcă: rulează."], "tr": {"l": "sql", "c": "\nDROP TABLE IF EXISTS t;\nCREATE TABLE t(id INT, email TEXT);\nINSERT INTO t VALUES (1,'a@x'),(2,'b@x'),(3,'a@x'),(4,'a@x');\nSELECT email, COUNT(*) AS nr FROM t GROUP BY email HAVING COUNT(*) > 1;\n"}}, {"id": "zq27", "d": "sql", "nou": 1, "t": "mc", "q": "Ce e un self join?", "o": ["Un join al tabelului cu el însuși, cu alias-uri diferite (ex. angajat și manager)", "Un join fără condiție", "Un join între baze diferite"], "a": 0, "h": "Alias obligatoriu.", "e": "Ex: FROM angajati e JOIN angajati m ON e.manager_id = m.id.", "px": ["Self join: același tabel cu două alias-uri (`e` și `b`). `LEFT JOIN` păstrează și angajatul fără șef.", "Încearcă: schimbă în `JOIN` simplu și vezi că Ana dispare."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT e.name AS angajat, b.name AS sef\nFROM emp e LEFT JOIN emp b ON e.boss_id = b.id\nORDER BY e.id;\n"}}, {"id": "zq28", "d": "sql", "nou": 1, "t": "mc", "q": "Ce reprezintă a treia formă normală (3NF), pe scurt?", "o": ["Atributele non-cheie depind doar de cheie, nu de alte atribute non-cheie", "Toate tabelele au maxim 3 coloane", "Fiecare tabel are 3 chei"], "a": 0, "h": "Fără dependențe tranzitive.", "e": "Evită repetarea datelor: de exemplu orașul și codul poștal separate de adresa clientului.", "px": ["3NF: fiecare coloană care nu face parte din cheie depinde de cheie și de nimic altceva. Dacă ai `cod_postal` și `oras` în tabelul clienților, `oras` depinde de `cod_postal`: ar trebui separat într-un alt tabel."]}, {"id": "zq29", "d": "sql", "nou": 1, "t": "mc", "q": "Ce face SELECT DISTINCT a, b FROM t?", "o": ["Elimină rândurile în care perechea (a, b) se repetă", "Elimină duplicatele doar pe a", "Sortează după a și b"], "a": 0, "h": "Se aplică pe combinație.", "e": "DISTINCT acționează pe întregul rând selectat.", "px": ["`DISTINCT` elimină rândurile identice pe ÎNTREAGA combinație de coloane selectate.", "Încearcă: rulează."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT DISTINCT dept, salary FROM emp ORDER BY dept, salary;\nSELECT COUNT(*) AS rand, COUNT(DISTINCT dept || salary) AS perechi_distincte FROM emp;\n"}}, {"id": "zy1", "d": "py", "nou": 1, "t": "mc", "q": "def f(x, lista=[]): lista.append(x); return lista. Ce întoarce f(1) apoi f(2)?", "o": ["[1] apoi [1, 2] — lista implicită e creată o singură dată", "[1] apoi [2]", "Eroare"], "a": 0, "h": "Mutable default argument.", "e": "Valoarea implicită se evaluează la definirea funcției. Soluție: lista=None și creezi lista în corp.", "px": ["Valoarea implicită `lista=[]` se creează O SINGURĂ DATĂ, când Python citește definiția funcției. E ca un caiet lăsat pe masă: fiecare apel scrie în același caiet.", "Soluția: pui `None` și, în funcție, creezi o listă nouă la fiecare apel. E ca și cum ai da fiecărui apel un caiet curat.", "Încearcă: rulează exemplul și compară cele două funcții. Prima ține minte apelurile anterioare, a doua nu."], "tr": {"l": "python", "c": "def adauga(x, lista=[]):\n    lista.append(x)\n    return lista\n\nprint(adauga(1))   # [1]\nprint(adauga(2))   # asteptat [2], dar iese [1, 2]\n\ndef adauga_corect(x, lista=None):\n    if lista is None:\n        lista = []\n    lista.append(x)\n    return lista\n\nprint(adauga_corect(1))\nprint(adauga_corect(2))\n"}}, {"id": "zy2", "d": "py", "nou": 1, "t": "mc", "q": "Care e diferența dintre == și is?", "o": ["== compară valorile, is verifică dacă sunt același obiect", "Sunt identice", "is compară valorile"], "a": 0, "h": "Egalitate versus identitate.", "e": "Folosești is pentru None: if x is None.", "px": ["`==` întreabă „arată la fel?”, `is` întreabă „e chiar același obiect?”. Două foi cu același text sunt egale (`==`), dar nu sunt aceeași foaie (`is`).", "Pentru `None` folosești mereu `is None`, fiindcă există un singur None.", "Încearcă: schimbă `a.append(3)` și vezi că `c` se schimbă și el, dar `b` nu."], "tr": {"l": "python", "c": "a = [1, 2]\nb = [1, 2]\nc = a\n\nprint(a == b)   # True: aceleasi valori\nprint(a is b)   # False: obiecte diferite\nprint(a is c)   # True: acelasi obiect\nprint(id(a) == id(b), id(a) == id(c))\n\nx = None\nprint(x is None)   # asa verifici None\n"}}, {"id": "zy3", "d": "py", "nou": 1, "t": "mc", "q": "Diferența dintre @classmethod și @staticmethod?", "o": ["classmethod primește clasa (cls), staticmethod nu primește nici self, nici cls", "Sunt identice", "staticmethod primește cls"], "a": 0, "h": "Primul argument.", "e": "classmethod e util pentru constructori alternativi; staticmethod e o funcție grupată în clasă.", "px": ["`@classmethod` primește clasa (`cls`) și e bun pentru „fabrici” care creează obiecte în alt mod. `@staticmethod` e o funcție obișnuită, doar ținută în clasă din motive de ordine.", "Dacă nu ai nevoie nici de obiect, nici de clasă, e static.", "Încearcă: apelează `Utilizator.din_text('Bob,Iasi')` și vezi cum crește `nr`."], "tr": {"l": "python", "c": "class Utilizator:\n    nr = 0\n    def __init__(self, nume):\n        self.nume = nume\n        Utilizator.nr += 1\n\n    @classmethod\n    def din_text(cls, text):      # constructor alternativ\n        nume = text.split(',')[0]\n        return cls(nume)\n\n    @staticmethod\n    def e_valid(nume):            # nu foloseste nici self, nici cls\n        return len(nume) > 1\n\nu = Utilizator.din_text('Ana,Cluj')\nprint(u.nume, Utilizator.nr)\nprint(Utilizator.e_valid('A'))\n"}}, {"id": "zy4", "d": "py", "nou": 1, "t": "mc", "q": "Diferența dintre __str__ și __repr__?", "o": ["__str__ e pentru afișare prietenoasă (print), __repr__ pentru reprezentare neambiguă, de debugging", "Sunt identice", "__repr__ e pentru print"], "a": 0, "h": "Cine e publicul?", "e": "Dacă lipsește __str__, print folosește __repr__.", "px": ["`__str__` e pentru oameni (ce vezi cu `print`), `__repr__` e pentru programatori (cât mai exact, de obicei așa ai putea recrea obiectul).", "Dacă lipsește `__str__`, `print` folosește `__repr__`.", "Încearcă: șterge metoda `__str__` și vezi ce afișează `print(p)`."], "tr": {"l": "python", "c": "class Punct:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __repr__(self):\n        return f\"Punct({self.x}, {self.y})\"      # pentru programatori\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"          # pentru afisare\n\np = Punct(1, 2)\nprint(p)         # foloseste __str__\nprint(repr(p))   # foloseste __repr__\nprint([p])       # in liste apare __repr__\n"}}, {"id": "zy5", "d": "py", "nou": 1, "t": "mc", "q": "Ce se întâmplă cu hash-ul dacă o clasă definește __eq__ dar nu și __hash__?", "o": ["Instanțele devin nehashabile (__hash__ = None), deci nu merg în set sau ca chei de dict", "Rămâne hash-ul implicit", "Eroare la definirea clasei"], "a": 0, "h": "Regula de consistență.", "e": "Obiectele egale trebuie să aibă același hash, așa că Python dezactivează hash-ul implicit.", "px": ["Dacă două obiecte sunt egale, trebuie să aibă și același hash. De aceea Python scoate hash-ul automat când tu schimbi `__eq__`, ca să nu strici regula.", "Ca să poți pune obiectele în `set` sau ca chei de dicționar, definești și `__hash__`.", "Încearcă: rulează și vezi eroarea `unhashable type`."], "tr": {"l": "python", "c": "class A:\n    def __init__(self, v): self.v = v\n    def __eq__(self, other): return self.v == other.v\n\na, b = A(1), A(1)\nprint(a == b)          # True\ntry:\n    print({a})         # nehashabil\nexcept TypeError as e:\n    print(\"Eroare:\", e)\n\nclass B(A):\n    def __hash__(self): return hash(self.v)\n\nprint({B(1), B(1)})    # un singur element\n"}}, {"id": "zy6", "d": "py", "nou": 1, "t": "mc", "q": "Ce face un atribut cu două underscore în față (self.__x) într-o clasă?", "o": ["Name mangling: se redenumește în _NumeClasa__x, ca să nu se suprapună în subclase", "Îl face privat strict, imposibil de accesat", "Îl face constant"], "a": 0, "h": "Python nu are private adevărat.", "e": "O singură underscore (_x) e doar convenție de „intern”.", "px": ["Python nu are „private” adevărat. Cu două underscore în față, numele devine `_NumeClasa__nume`, ca să nu se calce cu o variabilă din subclasă.", "O singură underscore (`_x`) e doar un semn: „e intern, nu-l atinge”.", "Încearcă: afișează `vars(c)` și vezi numele schimbat."], "tr": {"l": "python", "c": "class Cont:\n    def __init__(self):\n        self.__sold = 100      # name mangling\n        self._intern = 5       # doar conventie\n\nc = Cont()\nprint(c._intern)\ntry:\n    print(c.__sold)\nexcept AttributeError as e:\n    print(\"Eroare:\", e)\nprint(c._Cont__sold)           # asa e redenumit\nprint(vars(c))\n"}}, {"id": "zy7", "d": "py", "nou": 1, "t": "mc", "q": "class A: ... class B(A): ... class C(A): ... class D(B, C): ... În ce ordine caută Python metodele pentru D?", "o": ["D, B, C, A (MRO, C3 linearization)", "D, A, B, C", "D, B, A, C"], "a": 0, "h": "D.__mro__.", "e": "MRO păstrează ordinea din declarație și părinții după copii.", "px": ["MRO e lista în care Python caută o metodă: întâi clasa ta, apoi părinții în ordinea scrisă, apoi bunicul comun la sfârșit.", "Aici caută `D → B → C → A → object`, deci ia `hi` din B.", "Încearcă: schimbă în `class D(C, B)` și vezi cine câștigă."], "tr": {"l": "python", "c": "class A:\n    def hi(self): return 'A'\nclass B(A):\n    def hi(self): return 'B'\nclass C(A):\n    def hi(self): return 'C'\nclass D(B, C): pass\n\nprint(D().hi())\nprint([k.__name__ for k in D.__mro__])\n"}}, {"id": "zy8", "d": "py", "nou": 1, "t": "mc", "q": "Ce face @property cu setter?", "o": ["Permite citire/scriere ca atribut, dar cu logică (validare) în spate", "Face atributul constant", "Face metoda statică"], "a": 0, "h": "Atribut cu comportament.", "e": "Definești @x.setter ca să validezi valoarea la atribuire.", "px": ["`@property` face dintr-o metodă un „atribut” cu paznic: scrii `c.raza = 3`, dar în spate rulează codul tău de validare.", "Utilă când vrei să verifici valorile sau să calculezi ceva la citire (cum e `aria`).", "Încearcă: setează `c.raza = -5` și vezi eroarea."], "tr": {"l": "python", "c": "class Cerc:\n    def __init__(self, raza):\n        self._raza = raza\n    @property\n    def raza(self):\n        return self._raza\n    @raza.setter\n    def raza(self, v):\n        if v < 0:\n            raise ValueError(\"raza nu poate fi negativa\")\n        self._raza = v\n    @property\n    def aria(self):\n        return 3.14159 * self._raza ** 2\n\nc = Cerc(2)\nc.raza = 3                 # apeleaza setter-ul\nprint(c.raza, round(c.aria, 2))\ntry:\n    c.raza = -1\nexcept ValueError as e:\n    print(\"Eroare:\", e)\n"}}, {"id": "zy9", "d": "py", "nou": 1, "t": "mc", "q": "Ce face open('f.txt', 'w') dacă fișierul există deja?", "o": ["Îl golește (trunchiază) imediat", "Adaugă la sfârșit", "Aruncă eroare"], "a": 0, "h": "Moduri de deschidere.", "e": "'a' adaugă, 'x' dă eroare dacă există, 'r+' citește și scrie fără golire.", "px": ["Modul `'w'` șterge ce era în fișier și scrie de la zero. Modul `'a'` adaugă la sfârșit. `'x'` dă eroare dacă fișierul există.", "E ca diferența dintre a șterge pagina și a scrie pe ea, sau a scrie sub ce era deja.", "Încearcă: rulează și vezi că „prima” a dispărut, dar „a doua” a rămas după `'a'`."], "tr": {"l": "python", "c": "with open('test.txt', 'w') as f:\n    f.write('prima\\n')\nwith open('test.txt', 'w') as f:      # 'w' goleste fisierul!\n    f.write('a doua\\n')\nwith open('test.txt') as f:\n    print(f.read())\n\nwith open('test.txt', 'a') as f:      # 'a' adauga la sfarsit\n    f.write('a treia\\n')\nwith open('test.txt') as f:\n    print(f.read())\n"}}, {"id": "zy10", "d": "py", "nou": 1, "t": "mc", "q": "De ce se recomandă with open(...) as f?", "o": ["Închide fișierul automat, chiar dacă apare excepție", "E mai rapid", "Permite doar citire"], "a": 0, "h": "Context manager.", "e": "with apelează __exit__ la ieșire, ceea ce închide fișierul.", "px": ["`with` e ca un angajat care închide ușa după tine, chiar dacă apare o eroare în drum.", "Fără `with` trebuie să-ți amintești `close()` (și dacă apare eroare înainte de el, rămâne deschis).", "Încearcă: rulează și vezi `closed` pe `False`, apoi `True`."], "tr": {"l": "python", "c": "f = open('t.txt', 'w')\nf.write('salut')\nprint(f.closed)       # False: fisier inca deschis\nf.close()\nprint(f.closed)       # True\n\nwith open('t.txt') as g:\n    print(g.read())\nprint(g.closed)       # True: with l-a inchis singur\n"}}, {"id": "zy11", "d": "py", "nou": 1, "t": "mc", "q": "Ce diferență e între f.read(), f.readline() și f.readlines()?", "o": ["Tot conținutul ca string / o linie / lista tuturor liniilor", "Sunt identice", "readline citește tot"], "a": 0, "h": "Dimensiuni diferite.", "e": "Pentru fișiere mari iterezi direct: for linie in f.", "px": ["`read()` ia tot, `readline()` o singură linie, `readlines()` o listă cu toate liniile.", "La fișiere mari parcurgi direct `for linie in f`, ca să nu ții totul în memorie.", "Încearcă: vezi cum arată `\\n` la sfârșitul fiecărei linii."], "tr": {"l": "python", "c": "with open('t.txt', 'w') as f:\n    f.write('a\\nb\\nc\\n')\n\nwith open('t.txt') as f:\n    print(repr(f.read()))        # tot textul\nwith open('t.txt') as f:\n    print(repr(f.readline()))    # o linie\nwith open('t.txt') as f:\n    print(f.readlines())         # lista de linii\nwith open('t.txt') as f:\n    for linie in f:              # recomandat la fisiere mari\n        print(linie.strip())\n"}}, {"id": "zy12", "d": "py", "nou": 1, "t": "mc", "q": "Cum ștergi un fișier în Python?", "o": ["os.remove('f.txt') sau Path('f.txt').unlink()", "file.delete()", "os.rmdir('f.txt')"], "a": 0, "h": "Modulul os sau pathlib.", "e": "os.rmdir e pentru directoare goale.", "px": ["`os.remove(cale)` șterge un fișier. Pentru un director gol folosești `os.rmdir`.", "Mereu verifici cu `os.path.exists` înainte, ca să nu primești eroare dacă nu există.", "Încearcă: rulează de două ori `os.remove` și vezi eroarea."], "tr": {"l": "python", "c": "import os\nwith open('de_sters.txt', 'w') as f:\n    f.write('x')\nprint(os.path.exists('de_sters.txt'))   # True\nos.remove('de_sters.txt')\nprint(os.path.exists('de_sters.txt'))   # False\n"}}, {"id": "zy13", "d": "py", "nou": 1, "t": "mc", "q": "Diferența dintre list comprehension [x*x for x in r] și generator expression (x*x for x in r)?", "o": ["Generatorul produce valorile pe rând, fără să construiască lista în memorie", "Sunt identice", "Generatorul e o listă mai rapidă"], "a": 0, "h": "Paranteze rotunde.", "e": "Generatorul se consumă o singură dată.", "px": ["Parantezele pătrate construiesc toată lista deodată. Parantezele rotunde creează un „robinet” care dă câte o valoare când i-o ceri.", "Pe 100000 de elemente, generatorul ocupă câțiva zeci de octeți, lista sute de mii.", "Încearcă: rulează și compară cele două `getsizeof`."], "tr": {"l": "python", "c": "lista = [x * x for x in range(5)]\ngen = (x * x for x in range(5))\n\nprint(lista)\nprint(gen)              # un obiect generator, nu valori\nprint(sum(gen))         # il consumi\nprint(sum(gen))         # a doua oara e gol -> 0\n\nimport sys\nprint(sys.getsizeof([x for x in range(100000)]), sys.getsizeof(x for x in range(100000)))\n"}}, {"id": "zy14", "d": "py", "nou": 1, "t": "mc", "q": "Diferența dintre copy.copy și copy.deepcopy?", "o": ["copy e superficială (obiectele interne partajate), deepcopy copiază recursiv", "Sunt identice", "deepcopy doar pentru dict"], "a": 0, "h": "Structuri imbricate.", "e": "Cu copy, modificarea unei liste interne apare în ambele copii.", "px": ["Copia superficială copiază doar „plicul” de sus; obiectele din el rămân aceleași. Copia profundă copiază și conținutul plicurilor.", "Dacă ai liste în liste, `copy.copy` nu e suficient.", "Încearcă: schimbă `a[1]` și vezi cine se modifică."], "tr": {"l": "python", "c": "import copy\na = [1, [2, 3]]\nb = copy.copy(a)        # superficiala\nc = copy.deepcopy(a)    # profunda\n\na[1].append(99)\nprint(a)\nprint(b)   # lista interioara e aceeasi -> are si 99\nprint(c)   # copie independenta\n"}}, {"id": "zy15", "d": "py", "nou": 1, "t": "mc", "q": "Ce primesc *args și **kwargs într-o funcție?", "o": ["args: tuplu cu argumentele poziționale extra; kwargs: dict cu argumentele cu nume extra", "args: dict, kwargs: tuplu", "Ambele: liste"], "a": 0, "h": "Tuplu și dicționar.", "e": "Folosite la decoratori și funcții wrapper.", "px": ["`*args` adună argumentele fără nume într-un tuplu. `**kwargs` adună argumentele cu nume într-un dicționar.", "Cu `*` și `**` la apel faci invers: desfaci lista sau dicționarul în argumente.", "Încearcă: apelează `f('a', 'b', nume='Ana')`."], "tr": {"l": "python", "c": "def f(*args, **kwargs):\n    print(\"args:\", args)\n    print(\"kwargs:\", kwargs)\n\nf(1, 2, x=3, y=4)\n\ndef aduna(a, b, c):\n    return a + b + c\n\nprint(aduna(*[1, 2, 3]))\nprint(aduna(**{'a': 1, 'b': 2, 'c': 3}))\n"}}, {"id": "zy16", "d": "py", "nou": 1, "t": "mc", "q": "fs = [lambda: i for i in range(3)]; [f() for f in fs]. Ce rezultă?", "o": ["[2, 2, 2] — late binding: i e citit la apel", "[0, 1, 2]", "[3, 3, 3]"], "a": 0, "h": "Closure-ul captează variabila, nu valoarea.", "e": "Soluție: lambda i=i: i.", "px": ["Funcția `lambda` nu își ia o copie a lui `i`, ci se uită la `i` în momentul apelului. Până atunci bucla s-a terminat și `i` e 2.", "Cu `i=i` o obligi să rețină valoarea de la crearea ei.", "Încearcă: rulează ambele și compară."], "tr": {"l": "python", "c": "fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])          # [2, 2, 2]\n\nfs2 = [lambda i=i: i for i in range(3)]\nprint([f() for f in fs2])         # [0, 1, 2]\n"}}, {"id": "zy17", "d": "py", "nou": 1, "t": "mc", "q": "Ce face blocul else dintr-un try/except?", "o": ["Rulează doar dacă nu a apărut nicio excepție în try", "Rulează doar dacă apare excepție", "Rulează mereu"], "a": 0, "h": "try / except / else / finally.", "e": "finally rulează în orice caz. else e pentru codul care depinde de succesul lui try.", "px": ["`else` rulează doar când `try` nu a dat erori. `finally` rulează întotdeauna, chiar și când apare o eroare.", "Pune în `try` doar linia care poate eșua, iar restul în `else`.", "Încearcă: apelează cu `imparte(1, 0)` și vezi ce se afișează."], "tr": {"l": "python", "c": "def imparte(a, b):\n    try:\n        rez = a / b\n    except ZeroDivisionError:\n        print(\"nu se imparte la 0\")\n    else:\n        print(\"fara erori:\", rez)     # doar daca try a mers\n    finally:\n        print(\"mereu rulez\")\n\nimparte(6, 3)\nimparte(1, 0)\n"}}, {"id": "zy18", "d": "py", "nou": 1, "t": "mc", "q": "Ce face un decorator?", "o": ["Primește o funcție și întoarce alta (de obicei un wrapper), aplicată cu @nume", "Șterge o funcție", "Face funcția asincronă"], "a": 0, "h": "Funcții care transformă funcții.", "e": "functools.wraps păstrează numele și docstring-ul funcției originale.", "px": ["Un decorator ia o funcție și o înlocuiește cu alta (un „înveliș”) care face ceva înainte și după.", "`@chrono` deasupra funcției e doar scris prescurtat pentru `aduna = chrono(aduna)`.", "Încearcă: scoate `@functools.wraps(f)` și vezi cum se schimbă `aduna.__name__`."], "tr": {"l": "python", "c": "import functools\n\ndef chrono(f):\n    @functools.wraps(f)\n    def wrapper(*args, **kwargs):\n        print(\"apel:\", f.__name__, args)\n        rez = f(*args, **kwargs)\n        print(\"rezultat:\", rez)\n        return rez\n    return wrapper\n\n@chrono\ndef aduna(a, b):\n    \"aduna doua numere\"\n    return a + b\n\naduna(2, 3)\nprint(aduna.__name__, aduna.__doc__)   # pastrate de wraps\n"}}, {"id": "zy19", "d": "py", "nou": 1, "t": "mc", "q": "Ce se întâmplă când un generator a produs toate valorile și apelezi next()?", "o": ["Se ridică StopIteration", "Întoarce None", "Reîncepe de la început"], "a": 0, "h": "Epuizarea iteratorului.", "e": "Bucla for prinde StopIteration automat.", "px": ["Un generator dă câte o valoare la fiecare `next()`. Când nu mai are, ridică `StopIteration`.", "Bucla `for` prinde singură `StopIteration` și se oprește frumos.", "Încearcă: adaugă al patrulea `next(g)` și vezi eroarea."], "tr": {"l": "python", "c": "def numara(n):\n    for i in range(n):\n        yield i\n\ng = numara(2)\nprint(next(g))\nprint(next(g))\ntry:\n    print(next(g))\nexcept StopIteration:\n    print(\"generatorul s-a terminat\")\n"}}, {"id": "zy20", "d": "py", "nou": 1, "t": "mc", "q": "Ce face @dataclass?", "o": ["Generează automat __init__, __repr__ și __eq__ pe baza câmpurilor declarate", "Face clasa imutabilă", "Salvează clasa în fișier"], "a": 0, "h": "Mai puțin cod repetitiv.", "e": "frozen=True o face imutabilă.", "px": ["`@dataclass` scrie în locul tău `__init__`, `__repr__` și `__eq__` din câmpurile declarate.", "Cu `frozen=True` obiectul devine imutabil.", "Încearcă: afișează `p` și vezi reprezentarea făcută automat."], "tr": {"l": "python", "c": "from dataclasses import dataclass\n\n@dataclass\nclass Produs:\n    nume: str\n    pret: float = 0.0\n\np = Produs(\"pix\", 2.5)\nprint(p)                          # __repr__ automat\nprint(p == Produs(\"pix\", 2.5))    # __eq__ automat\n\n@dataclass(frozen=True)\nclass Punct:\n    x: int\n    y: int\nq = Punct(1, 2)\ntry:\n    q.x = 5\nexcept Exception as e:\n    print(\"Eroare:\", type(e).__name__)\n"}}, {"id": "zy21", "d": "py", "nou": 1, "t": "mc", "q": "În NumPy, ce dă arr * 2 pentru un ndarray, față de lista * 2?", "o": ["ndarray: fiecare element dublat; listă: lista repetată de două ori", "Sunt identice", "Ambele repetă"], "a": 0, "h": "Vectorizare.", "e": "NumPy face operații element cu element, rapid, fără bucle Python.", "px": ["Lista înmulțită cu 2 își repetă conținutul: `[1,2]*2` dă `[1,2,1,2]`. Un tablou NumPy lucrează element cu element: `np.array([1,2])*2` dă `[2,4]`."]}, {"id": "zy22", "d": "py", "nou": 1, "t": "mc", "q": "În Pandas, diferența dintre df.loc și df.iloc?", "o": ["loc selectează după etichete, iloc după poziție (index întreg)", "Sunt identice", "iloc după etichete"], "a": 0, "h": "Etichetă versus poziție.", "e": "df.loc[2] caută eticheta 2, df.iloc[2] al treilea rând.", "px": ["`loc` caută după etichete (numele rândului/coloanei), `iloc` după poziție (0, 1, 2...). Cu index implicit numeric arată la fel, de aceea se confundă. La `loc`, capătul din slice e inclus; la `iloc`, nu."]}, {"id": "zy23", "d": "py", "nou": 1, "t": "mc", "q": "Ce face df.groupby('oras')['vanzari'].sum()?", "o": ["Grupează după oraș și adună vânzările pe fiecare grup", "Sortează după oraș", "Șterge duplicatele"], "a": 0, "h": "Ca GROUP BY din SQL.", "e": "Rezultatul e o Series cu orașul ca index.", "px": ["Pașii: 1) împarte rândurile pe orașe, 2) ia coloana `vanzari`, 3) adună valorile din fiecare grup. Rezultatul e o serie cu un total per oraș."]}, {"id": "zy24", "d": "py", "nou": 1, "t": "mc", "q": "În Django, ordinea corectă după modificarea unui model?", "o": ["python manage.py makemigrations, apoi migrate", "migrate, apoi makemigrations", "runserver"], "a": 0, "h": "Generezi, apoi aplici.", "e": "makemigrations creează fișierul de migrare, migrate îl aplică în baza de date.", "px": ["`makemigrations` scrie fișierul cu schimbarea (planul). `migrate` o aplică în baza de date. Fără al doilea pas, baza rămâne neschimbată."]}, {"id": "zy25", "d": "py", "nou": 1, "t": "mc", "q": "Diferența dintre Model.objects.get(...) și .filter(...) în Django ORM?", "o": ["get întoarce un singur obiect (sau DoesNotExist/MultipleObjectsReturned), filter întoarce un QuerySet", "Sunt identice", "filter ridică DoesNotExist"], "a": 0, "h": "Un obiect versus mai multe.", "e": "filter nu ridică excepție dacă nu găsește nimic, doar întoarce un QuerySet gol.", "px": ["`get()` aduce exact UN obiect. Dacă nu există, aruncă `DoesNotExist`; dacă sunt mai multe, `MultipleObjectsReturned`. `filter()` întoarce un QuerySet (0, 1 sau mai multe), niciodată eroare pentru „nimic găsit”."]}, {"id": "zy26", "d": "py", "nou": 1, "t": "mc", "q": "Ce implementează un context manager?", "o": ["Metodele __enter__ și __exit__", "__open__ și __close__", "__start__ și __stop__"], "a": 0, "h": "with.", "e": "Se poate scrie și cu @contextlib.contextmanager.", "px": ["Un context manager are `__enter__` (la intrarea în `with`) și `__exit__` (la ieșire, chiar și după erori).", "Așa funcționează `with open(...)`: la ieșire închide fișierul.", "Încearcă: rulează și urmărește ordinea mesajelor."], "tr": {"l": "python", "c": "class Deschide:\n    def __enter__(self):\n        print(\"intru\")\n        return self\n    def __exit__(self, tip, val, tb):\n        print(\"ies\")\n        return False\n\nwith Deschide() as d:\n    print(\"in interior\")\n\ntry:\n    with Deschide():\n        raise ValueError(\"oops\")\nexcept ValueError:\n    print(\"eroarea a ajuns afara, dar __exit__ a rulat\")\n"}}, {"id": "zy27", "d": "py", "nou": 1, "t": "mc", "q": "Ce face GIL-ul (Global Interpreter Lock) în CPython?", "o": ["Permite unui singur thread să execute bytecode Python la un moment dat, deci threadurile nu accelerează cod CPU-bound", "Blochează fișierele", "Blochează importurile"], "a": 0, "h": "Thread-uri versus procese.", "e": "Pentru CPU-bound folosești multiprocessing; pentru I/O, threads sau asyncio.", "px": ["GIL e un „microfon unic”: în CPython un singur thread execută cod Python la un moment dat. Pentru calcule grele, threadurile nu merg mai repede; folosești `multiprocessing`. Pentru așteptări (rețea, fișiere), threadurile ajută."]}, {"id": "zy28", "d": "py", "nou": 1, "t": "mc", "q": "Ce înseamnă polimorfismul prin duck typing?", "o": ["Contează ce metode are obiectul, nu din ce clasă provine", "Toate clasele trebuie să moștenească din aceeași bază", "Funcțiile au același nume"], "a": 0, "h": "Dacă merge ca rața...", "e": "Funcția care apelează x.speak() funcționează cu orice obiect care are speak().", "px": ["Duck typing: „dacă merge ca o rață și face ca o rață, e rață”. Contează dacă obiectul are metoda, nu din ce clasă vine.", "Nu ai nevoie de o clasă-mamă comună.", "Încearcă: adaugă o clasă nouă cu `vorbeste` și trece-o prin funcție."], "tr": {"l": "python", "c": "class Rata:\n    def vorbeste(self): return \"Mac!\"\nclass Robot:\n    def vorbeste(self): return \"Bip!\"\n\ndef fa_sa_vorbeasca(x):\n    print(x.vorbeste())      # nu ne intereseaza clasa, ci metoda\n\nfor obiect in (Rata(), Robot()):\n    fa_sa_vorbeasca(obiect)\n"}}, {"id": "zy29", "d": "py", "nou": 1, "t": "mc", "q": "Ce fac metodele magice __len__ și __getitem__?", "o": ["Permit len(obj) și obj[i], deci obiectul se comportă ca o colecție", "Sunt doar documentație", "Sunt apelate la import"], "a": 0, "h": "Protocoale de colecție.", "e": "Python apelează aceste metode când folosești funcții și operatori standard.", "px": ["Metodele magice (cu două underscore) sunt „cârligele” prin care funcțiile Python (`len`, `[]`, `for`, `in`) cer obiectului să se comporte ca o colecție.", "Scrii `__len__` și `__getitem__` și obiectul tău poate fi parcurs cu `for`.", "Încearcă: adaugă `__contains__` și vezi diferența."], "tr": {"l": "python", "c": "class Raft:\n    def __init__(self, *carti): self.carti = list(carti)\n    def __len__(self): return len(self.carti)\n    def __getitem__(self, i): return self.carti[i]\n\nr = Raft(\"A\", \"B\", \"C\")\nprint(len(r))\nprint(r[1])\nfor c in r:            # merge cu __getitem__\n    print(c)\nprint(\"B\" in r)\n"}}, {"id": "zy30", "d": "py", "nou": 1, "t": "mc", "q": "Care e rolul unui mediu virtual (venv)?", "o": ["Izolează pachetele proiectului de cele globale și de alte proiecte", "Face codul mai rapid", "Criptează codul"], "a": 0, "h": "Dependențe pe proiect.", "e": "python -m venv .venv, apoi pip install în mediul activat; requirements.txt fixează versiunile.", "px": ["Fiecare proiect își ia pachetele proprii într-un folder izolat. Un proiect poate folosi versiunea 1 dintr-o bibliotecă, altul versiunea 2, fără conflict. Creare: `python -m venv .venv`, apoi îl activezi."]}, {"id": "lv1", "d": "php", "nou": 1, "t": "mc", "q": "Laravel: $books = Book::all(); foreach ($books as $b) { echo $b->author->name; } Cu 25 de cărți, câte interogări rulează și care e remediul?", "o": ["1 + 25 (problema N+1); remediul: Book::with('author')->get() (2 interogări)", "25 de interogări doar pentru autori, remediul e Book::cursor()", "O singură interogare, Eloquent face JOIN automat"], "a": 0, "h": "Gândește-te la câte ori se încarcă relația.", "e": "Relația se încarcă leneș la fiecare acces. Eager loading cu with() face 2 interogări în total.", "px": ["`Book::all()` face 1 interogare. Apoi, la fiecare `$b->author`, Laravel face încă una pentru autor (încărcare leneșă): 1 + 25. Asta e N+1.", "Soluție: `Book::with('author')->get()`, doar 2 interogări."]}, {"id": "lv2", "d": "php", "nou": 1, "t": "mc", "q": "Cum faci ca Laravel să arunce excepție când codul încarcă leneș o relație (util să prinzi N+1 în dezvoltare)?", "o": ["Model::preventLazyLoading(! app()->isProduction()) — aruncă LazyLoadingViolationException", "Model::strictQueries(true)", "DB::forbidLazy()"], "a": 0, "h": "Metodă statică pe Model, de obicei în AppServiceProvider::boot().", "e": "preventLazyLoading() face lazy loading-ul să arunce LazyLoadingViolationException. handleLazyLoadingViolationsUsing() permite doar logare.", "px": ["În dezvoltare vrei să afli unde ai N+1. `Model::preventLazyLoading(! app()->isProduction())` aruncă excepție la încărcarea leneșă. În producție nu vrei să oprești utilizatorii."]}, {"id": "lv3", "d": "php", "nou": 1, "t": "mc", "q": "Ce nume are, implicit, tabela pivot între modelele User și Role la belongsToMany?", "o": ["role_user (ordine alfabetică, cu coloanele role_id și user_id)", "user_role", "users_roles"], "a": 0, "h": "Numele modelelor în ordine alfabetică, la singular.", "e": "Convenția Laravel: modelele în ordine alfabetică, la singular, unite cu underscore. Poți specifica alt nume ca al doilea argument.", "px": ["Convenția: numele celor două modele în ordine alfabetică, singular, cu underscore: `role_user`, cu `role_id` și `user_id`. Poți schimba numele ca al doilea argument la `belongsToMany`."]}, {"id": "lv4", "d": "php", "nou": 1, "t": "mc", "q": "Cum numeri comentariile fiecărei postări fără să le încarci, într-o singură interogare?", "o": ["Post::withCount('comments')->get(), apoi $post->comments_count", "Post::with('comments')->count()", "Post::all()->comments->count()"], "a": 0, "h": "Apare un atribut nou: {relație}_count.", "e": "withCount() adaugă coloana {relation}_count. Există și withSum, withMin, withMax, withAvg, withExists.", "px": ["`withCount('comments')` adaugă un `COUNT` în aceeași interogare și produce atributul `comments_count`, fără să încarce comentariile."]}, {"id": "lv5", "d": "php", "nou": 1, "t": "mc", "q": "Ce face $fillable într-un model Eloquent?", "o": ["Listează atributele permise la mass assignment (listă albă); $guarded e lista neagră", "Listează atributele care se afișează în JSON", "Listează coloanele obligatorii din migrare"], "a": 0, "h": "Protecție la Model::create($request->all()).", "e": "Cu $fillable doar atributele din listă pot fi completate prin create()/fill(); restul sunt ignorate.", "px": ["Mass assignment: `Post::create($request->all())`. Dacă cineva trimite și `is_admin=1`? `$fillable` e lista albă: doar acelea se pot completa în masă. `$guarded` e invers, lista neagră."]}, {"id": "lv6", "d": "php", "nou": 1, "t": "mc", "q": "După $post->delete() pe un model cu trait-ul SoftDeletes, ce se întâmplă?", "o": ["Se setează coloana deleted_at; rândul rămâne în tabel și e exclus din interogările normale", "Rândul se șterge definitiv", "Modelul se mută într-un tabel de arhivă"], "a": 0, "h": "Cum îl vezi și cum îl ștergi pentru totdeauna?", "e": "withTrashed() include înregistrările șterse logic, restore() le readuce, forceDelete() le elimină definitiv.", "px": ["`SoftDeletes` nu șterge rândul, ci setează `deleted_at`. Interogările normale îl ignoră. Îl vezi cu `withTrashed()` și îl readuci cu `restore()`."]}, {"id": "lv7", "d": "php", "nou": 1, "t": "mc", "q": "De ce nu poți folosi eager loading (with) împreună cu cursor() la Eloquent și ce alegi în loc?", "o": ["cursor() ține un singur model în memorie și nu poate încărca relații; folosești lazy()", "cursor() e deprecat", "cursor() nu poate face WHERE"], "a": 0, "h": "Cea mai mică memorie are un cost.", "e": "Documentația: cursor() nu face eager load; lazy() e alternativa când ai nevoie de relații.", "px": ["`cursor()` citește rând cu rând, cu un singur model în memorie, deci nu poate încărca relații (eager loading). `lazy()` face chunk-uri, dar le expune ca un LazyCollection și suportă `with`."]}, {"id": "lv8", "d": "php", "nou": 1, "t": "mc", "q": "Parcurgi cu chunk() o tabelă și, în callback, modifici coloana după care filtrezi. Ce recomandă documentația?", "o": ["Folosești chunkById(), care paginează după cheia primară", "Folosești chunk() cu un callback mai mare", "Folosești get() și apoi foreach"], "a": 0, "h": "Paginarea după offset se strică dacă rândurile se mută din filtru.", "e": "chunkById() e recomandat când actualizezi înregistrările în timpul iterării.", "px": ["Dacă modifici în callback coloana după care filtrezi, `chunk()` poate sări rânduri, pentru că paginarea se bazează pe `OFFSET`. `chunkById()` paginează după cheia primară și rămâne corect."]}, {"id": "lv9", "d": "php", "nou": 1, "t": "mc", "q": "Ce diferență e între firstOrCreate() și updateOrCreate()?", "o": ["firstOrCreate găsește sau creează (nu modifică ce există); updateOrCreate găsește și actualizează sau creează", "Sunt identice", "updateOrCreate nu creează niciodată"], "a": 0, "h": "Al doilea argument are rol diferit.", "e": "updateOrCreate(['departure'=>...], ['price'=>99]) caută după primul array și aplică al doilea la actualizare. $model->wasRecentlyCreated arată dacă a fost creat.", "px": ["`firstOrCreate` caută; dacă nu găsește, creează. Nu modifică ce există. `updateOrCreate` caută și, dacă găsește, actualizează cu valorile date."]}, {"id": "lv10", "d": "php", "nou": 1, "t": "mc", "q": "Ce nume de tabelă folosește implicit modelul AirTrafficController?", "o": ["air_traffic_controllers (snake case, plural)", "airtrafficcontrollers", "AirTrafficController"], "a": 0, "h": "Convenția de nume Eloquent.", "e": "Se suprascrie cu protected $table = 'nume'.", "px": ["Laravel ia numele clasei, îl transformă în snake_case și îl face plural: `AirTrafficController` devine `air_traffic_controllers`. Dacă tabela are alt nume, setezi `$table`."]}, {"id": "lv11", "d": "php", "nou": 1, "t": "mc", "q": "Care e diferența dintre $this->app->bind() și singleton() în containerul Laravel?", "o": ["bind creează o instanță nouă la fiecare rezolvare; singleton întoarce aceeași instanță", "Sunt identice", "singleton se rezolvă doar o dată pe zi"], "a": 0, "h": "Câte instanțe obții la resolve?", "e": "scoped() e între ele: aceeași instanță în ciclul unui request/job. instance() leagă un obiect deja creat.", "px": ["`bind` = fabrică: la fiecare cerere primești obiect nou. `singleton` = o singură instanță, refolosită."]}, {"id": "lv12", "d": "php", "nou": 1, "t": "mc", "q": "Un controller cere în constructor o interfață EventPusher. Ce trebuie făcut ca containerul să o poată injecta?", "o": ["Legi interfața de o implementare: $this->app->bind(EventPusher::class, RedisEventPusher::class)", "Nimic, containerul ghicește implementarea", "Declari interfața final"], "a": 0, "h": "Containerul nu poate instanția o interfață.", "e": "Rezolvarea automată merge doar pentru clase concrete fără dependențe sau cu dependențe concrete.", "px": ["O interfață nu poate fi instanțiată. Containerul trebuie să afle ce clasă concretă o implementează: `$this->app->bind(EventPusher::class, RedisEventPusher::class)`, într-un service provider."]}, {"id": "lv13", "d": "php", "nou": 1, "t": "mc", "q": "La ce folosește contextual binding ($this->app->when(...)->needs(...)->give(...))?", "o": ["Injectează implementări diferite ale aceleiași interfețe, în funcție de clasa care o cere", "Leagă servicii doar în mediul de testare", "Face singleton pe un request"], "a": 0, "h": "Aceeași interfață, clienți diferiți.", "e": "Exemplu din documentație: PhotoController primește disk-ul local, VideoController primește s3.", "px": ["Două clase cer aceeași interfață, dar vrei implementări diferite. `when(PhotoController::class)->needs(Filesystem::class)->give(...)` alege pe cea potrivită după cine o cere."]}, {"id": "lv14", "d": "php", "nou": 1, "t": "mc", "q": "Ce înseamnă un binding scoped() în Laravel?", "o": ["Aceeași instanță în cadrul unui request/job, resetată între ele", "Instanță nouă la fiecare apel", "Instanță partajată pe tot serverul, pe vecie"], "a": 0, "h": "Important la Octane și la cozi.", "e": "scoped e util pentru servicii care nu trebuie să ducă stare între request-uri în procese de lungă durată.", "px": ["`scoped` = singleton cu durată scurtă: aceeași instanță pe durata unui request (sau job), apoi resetată. E util în Octane și cozi, unde procesul rămâne pornit."]}, {"id": "lv15", "d": "php", "nou": 1, "t": "mc", "q": "Cum faci ca un middleware să ruleze DUPĂ ce request-ul a fost procesat de aplicație?", "o": ["Apelezi $next($request) mai întâi, salvezi $response și apoi execuți logica, la final returnezi $response", "Pui logica în constructor", "Folosești metoda boot() a middleware-ului"], "a": 0, "h": "Totul se petrece în jurul lui $next.", "e": "Logica înainte de $next e before middleware; după $next e after middleware.", "px": ["Middleware-ul e ca un tunel. Ce scrii înainte de `$next($request)` rulează la intrare. Pentru logică după procesare, salvezi `$response = $next($request);`, faci ce ai de făcut și întorci `$response`."]}, {"id": "lv16", "d": "php", "nou": 1, "t": "mc", "q": "Ce face metoda terminate() a unui middleware (terminable middleware)?", "o": ["Rulează după ce răspunsul a fost trimis către browser", "Oprește request-ul", "Se apelează înainte de primul middleware"], "a": 0, "h": "Util pentru log-uri lente sau sesiuni.", "e": "Documentația precizează că necesită FastCGI. Pentru a reutiliza aceeași instanță înregistrezi middleware-ul ca singleton.", "px": ["`terminate()` rulează după ce răspunsul a plecat spre browser. Bun pentru lucruri lente (logare, scriere de date) care nu trebuie să întârzie utilizatorul."]}, {"id": "lv17", "d": "php", "nou": 1, "t": "mc", "q": "Care grup de middleware implicit include sesiuni, cookie-uri și protecția CSRF?", "o": ["web", "api", "ambele identic"], "a": 0, "h": "Rutele din routes/api.php nu au sesiuni.", "e": "Grupul web: cookie-uri, sesiune, CSRF, bindings. Grupul api e minimal.", "px": ["Grupul `web` include sesiunea, cookie-urile și CSRF; rutele din `routes/web.php` îl primesc automat. Grupul `api` nu are sesiuni sau CSRF."]}, {"id": "lv18", "d": "php", "nou": 1, "t": "mc", "q": "Cum atașezi unei rute un middleware cu parametri, ex. rolurile editor și publisher?", "o": ["->middleware(EnsureUserHasRole::class.':editor,publisher')", "->middleware(EnsureUserHasRole::class, 'editor', 'publisher')", "->middleware(EnsureUserHasRole::class)->with('editor')"], "a": 0, "h": "Doi puncte, apoi lista cu virgulă.", "e": "Parametrii ajung în handle() după $next.", "px": ["Parametrii se dau după `:` și se separă prin virgulă: `EnsureUserHasRole::class.':editor,publisher'`. Ajung ca argumente suplimentare în `handle()`."]}, {"id": "lv19", "d": "php", "nou": 1, "t": "mc", "q": "Ce face $request->validate([...]) când validarea eșuează la o cerere XHR/AJAX?", "o": ["Întoarce răspuns 422 cu JSON cu erorile", "Redirecționează înapoi cu erorile în sesiune", "Aruncă excepție 500"], "a": 0, "h": "La cereri normale e altceva.", "e": "La o cerere HTTP obișnuită, face redirect înapoi și memorează erorile și inputul în sesiune.", "px": ["La cererile obișnuite, utilizatorul e trimis înapoi la formular cu erori. La XHR sau când clientul cere JSON, `validate()` întoarce 422 cu un JSON al erorilor."]}, {"id": "lv20", "d": "php", "nou": 1, "t": "mc", "q": "Ce întoarce $request->validated() față de $request->all()?", "o": ["Doar datele care au trecut prin regulile de validare", "Toate datele, dar curățate de spații", "Doar câmpurile care au eșuat"], "a": 0, "h": "Siguranță la mass assignment.", "e": "Practic: Model::create($request->validated()) în loc de ->all().", "px": ["`all()` ia tot ce a trimis clientul, inclusiv câmpuri neașteptate. `validated()` ia doar câmpurile care au trecut prin reguli."]}, {"id": "lv21", "d": "php", "nou": 1, "t": "mc", "q": "Într-un FormRequest, ce se întâmplă dacă authorize() întoarce false?", "o": ["Răspuns 403 Forbidden, fără să ruleze regulile", "Se afișează erorile de validare", "Se ignoră și se rulează rules()"], "a": 0, "h": "Nu e o problemă de validare.", "e": "authorize() decide dacă utilizatorul are voie să facă acțiunea; rules() decide dacă datele sunt valide.", "px": ["`authorize()` e verificat primul. Dacă dă false, utilizatorul primește 403 și regulile de validare nici nu rulează."]}, {"id": "lv22", "d": "php", "nou": 1, "t": "mc", "q": "Cum validezi un email unic la UPDATE, fără să pice pe propriul rând?", "o": ["Rule::unique('users')->ignore($user->id)", "'email' => 'unique:users,email,null'", "Dezactivezi regula unique la update"], "a": 0, "h": "Excluzi propriul id din verificare.", "e": "Se poate pasa și întregul model. Rule::unique(...)->withoutTrashed() ignoră rândurile soft-deleted.", "px": ["Regula `unique` pică dacă emailul există deja, inclusiv la tine. `Rule::unique('users')->ignore($user->id)` exclude rândul curent."]}, {"id": "lv23", "d": "php", "nou": 1, "t": "mc", "q": "Ce face regula bail într-o listă de reguli, ex. 'bail|required|unique:posts|max:255'?", "o": ["Oprește validarea câmpului la prima regulă eșuată", "Oprește validarea tuturor câmpurilor", "Face câmpul opțional"], "a": 0, "h": "Evită, de exemplu, interogarea unique pe un câmp gol.", "e": "stopOnFirstFailure() pe validator oprește validarea tuturor câmpurilor.", "px": ["Fără `bail`, Laravel verifică toate regulile și întoarce toate erorile. Cu `bail`, câmpul se oprește la prima eșuată, ca să nu rulezi inutil `unique` (interogare în DB) pe ceva gol."]}, {"id": "lv24", "d": "php", "nou": 1, "t": "mc", "q": "De ce un câmp opțional ca 'publish_at' => 'date' pică la șirul gol, iar cu 'nullable|date' trece?", "o": ["ConvertEmptyStringsToNull transformă '' în null, iar null e permis doar cu nullable", "Laravel ignoră câmpurile goale", "date acceptă mereu șirul gol"], "a": 0, "h": "Middleware-ul care convertește șirurile goale.", "e": "Documentația: TrimStrings și ConvertEmptyStringsToNull fac ca șirurile goale să devină null, deci câmpurile opționale au nevoie de nullable.", "px": ["Un input gol trimite `''`. Laravel îl transformă în `null` (ConvertEmptyStringsToNull). Regula `date` nu acceptă null, dar `nullable` spune că null e permis."]}, {"id": "lv25", "d": "php", "nou": 1, "t": "mc", "q": "Ce diferență e între o conexiune (connection) și o coadă (queue) la cozile Laravel?", "o": ["Conexiunea e backend-ul (Redis, SQS, database); coada e o stivă numită în cadrul unei conexiuni", "Sunt sinonime", "Coada e backend-ul, conexiunea e numele job-ului"], "a": 0, "h": "onConnection('sqs') vs onQueue('emails').", "e": "Se pot prioritiza cozi diferite în același worker: queue:work --queue=high,default.", "px": ["Conexiunea e „unde”: Redis, SQS, baza de date. Coada e un „raft” numit (`default`, `emails`) în acea conexiune. Poți avea workere separate pentru cozi diferite."]}, {"id": "lv26", "d": "php", "nou": 1, "t": "mc", "q": "Ai făcut deploy cu cod nou pentru job-uri. De ce trebuie să rulezi php artisan queue:restart?", "o": ["Workerul queue:work e un proces de lungă durată care ține codul în memorie și nu vede modificările", "Ca să se șteargă tabela failed_jobs", "Ca să crească numărul de încercări"], "a": 0, "h": "Pornit o dată, rulează săptămâni.", "e": "queue:restart oprește workerii elegant; Supervisor îi repornește. queue:listen reîncarcă codul, dar e mai ineficient.", "px": ["`queue:work` pornește un proces care rămâne activ și ține codul încărcat în memorie. După deploy, el rulează în continuare codul vechi, până îl repornești cu `queue:restart` (oprește curat după jobul curent)."]}, {"id": "lv27", "d": "php", "nou": 1, "t": "mc", "q": "Ce garantează interfața ShouldBeUnique la un job?", "o": ["Doar o instanță a aceluiași job (după uniqueId) poate fi în coadă; folosește un lock din cache", "Job-ul rulează o singură dată în viață", "Job-ul rulează doar noaptea"], "a": 0, "h": "Previne duplicatele în coadă.", "e": "Necesită un driver de cache cu lock-uri atomice. uniqueFor setează durata lock-ului.", "px": ["`ShouldBeUnique` împiedică punerea în coadă a unui al doilea job identic cât timp primul e în coadă sau rulează. Cheia vine din `uniqueId()`; are nevoie de un driver de cache cu lock-uri."]}, {"id": "lv28", "d": "php", "nou": 1, "t": "mc", "q": "Ce rezolvă ->afterCommit() la dispatch-ul unui job?", "o": ["Job-ul e trimis în coadă abia după commit-ul tranzacției curente, ca să vadă datele salvate", "Job-ul rulează de două ori", "Job-ul sare peste tranzacții"], "a": 0, "h": "Worker-ul poate fi mai rapid decât COMMIT-ul.", "e": "Se poate seta global: 'after_commit' => true în config/queue.php.", "px": ["Fără `afterCommit`, jobul poate porni înainte ca tranzacția să facă commit și nu găsește datele. Cu el, jobul e trimis abia după commit."]}, {"id": "lv29", "d": "php", "nou": 1, "t": "mc", "q": "Un job a eșuat definitiv. Cum îl retrimiți după ce ai reparat cauza?", "o": ["php artisan queue:retry {id}, din tabela failed_jobs", "Îl rescrii de mână", "php artisan migrate:retry"], "a": 0, "h": "Job-urile eșuate sunt păstrate în tabela failed_jobs.", "e": "queue:retry all reia toate. Numărul de încercări se controlează cu $tries sau --tries.", "px": ["Joburile eșuate rămân în `failed_jobs`. După ce repari cauza: `php artisan queue:retry {id}` (sau `all`) le pune din nou în coadă."]}, {"id": "lv30", "d": "php", "nou": 1, "t": "mc", "q": "Care e diferența între migrate:rollback și migrate:fresh?", "o": ["rollback anulează ultimul batch rulând down(); fresh șterge toate tabelele și rulează migrările de la zero", "Sunt identice", "fresh anulează doar ultima migrare"], "a": 0, "h": "Unul respectă down(), celălalt nu.", "e": "fresh e distructiv (drop all tables) și nu se pune pe producție. migrate:refresh anulează toate migrările, apoi le rulează din nou.", "px": ["`migrate:rollback` rulează `down()` pentru ultimul lot. `migrate:fresh` șterge toate tabelele și rulează toate migrările de la zero. Nu-l folosi în producție: pierzi datele."]}, {"id": "lv31", "d": "php", "nou": 1, "t": "mc", "q": "Ce face $table->foreignId('user_id')->constrained()->cascadeOnDelete()?", "o": ["Creează coloana și cheia străină către users.id; la ștergerea userului se șterg rândurile copil", "Doar adaugă un index", "Setează user_id pe NULL la ștergere"], "a": 0, "h": "constrained() deduce tabela din nume.", "e": "nullOnDelete() setează NULL, restrictOnDelete() blochează ștergerea.", "px": ["`foreignId('user_id')` creează coloana; `constrained()` o leagă de `users.id`; `cascadeOnDelete()` șterge rândurile când userul e șters."]}, {"id": "lv32", "d": "php", "nou": 1, "t": "mc", "q": "Modifici o coloană cu ->change() într-o migrare. Ce e important?", "o": ["Trebuie să repeți toți modificatorii pe care vrei să-i păstrezi (default, unsigned, comment...)", "Nu e nevoie de nimic, se păstrează automat", "change() adaugă coloana"], "a": 0, "h": "Definiția se înlocuiește, nu se îmbină.", "e": "Modificatorii omiși se pierd.", "px": ["`->change()` înlocuiește definiția coloanei. Ce nu repeți (nullable, default, unsigned...) se pierde. Scrii definiția completă."]}, {"id": "lv33", "d": "php", "nou": 1, "t": "mc", "q": "Rută: Route::get('/posts/{post:slug}', fn (Post $post) => ...). Ce face și ce se întâmplă dacă slug-ul nu există?", "o": ["Implicit model binding după coloana slug; întoarce automat 404", "Caută după id și dă eroare 500", "Întoarce null"], "a": 0, "h": "{post:slug} sau getRouteKeyName().", "e": "getRouteKeyName() pe model schimbă coloana implicită pentru toate rutele.", "px": ["În mod normal, `{post}` caută după id. Cu `{post:slug}` caută după coloana `slug`. Dacă nu găsește, Laravel întoarce automat 404."]}, {"id": "lv34", "d": "php", "nou": 1, "t": "mc", "q": "De ce php artisan route:cache poate eșua?", "o": ["Rutele definite cu closure nu pot fi puse în cache; trebuie controllere", "Nu există comanda", "Funcționează doar în local"], "a": 0, "h": "Serializare.", "e": "După adăugarea de rute noi trebuie rulat din nou route:cache; route:clear îl șterge.", "px": ["Route cache serializează rutele. Closure-urile nu se pot serializa, deci `route:cache` dă eroare. Folosești controllere în rutele pe care le ții în cache."]}, {"id": "lv35", "d": "php", "nou": 1, "t": "mc", "q": "Care e diferența dintre {{ $x }} și {!! $x !!} în Blade?", "o": ["{{ }} escapează prin htmlspecialchars; {!! !!} scoate HTML brut (risc XSS)", "Sunt identice", "{!! !!} escapează dublu"], "a": 0, "h": "Folosește {!! !!} doar pentru conținut de încredere.", "e": "@{{ name }} prefixat cu @ lasă acoladele neatinse pentru framework-uri JS.", "px": ["`{{ $x }}` trece prin `htmlspecialchars`, deci `<script>` apare ca text. `{!! $x !!}` afișează brut: doar pentru HTML în care ai încredere, altfel XSS."]}, {"id": "lv36", "d": "php", "nou": 1, "t": "mc", "q": "Ce metode HTTP verifică middleware-ul CSRF și cum trimiți token-ul la AJAX?", "o": ["POST, PUT, PATCH, DELETE; în header X-CSRF-TOKEN (sau X-XSRF-TOKEN din cookie)", "Doar GET; token în URL", "Toate metodele; token în body JSON obligatoriu"], "a": 0, "h": "@csrf generează un input hidden _token.", "e": "Token-ul se ia din meta csrf-token. Axios trimite automat X-XSRF-TOKEN.", "px": ["CSRF se verifică la metodele care schimbă date: POST, PUT, PATCH, DELETE. La AJAX trimiți tokenul în antetul `X-CSRF-TOKEN` (din meta tag) sau `X-XSRF-TOKEN` (din cookie)."]}, {"id": "lv37", "d": "php", "nou": 1, "t": "mc", "q": "Folosești env('API_KEY') direct într-un controller. În producție, după php artisan config:cache, ce se întâmplă?", "o": ["env() nu mai citește fișierul .env și întoarce null (dacă nu e variabilă de sistem)", "Merge la fel", "Laravel aruncă excepție la deploy"], "a": 0, "h": "Doar config/*.php are voie să apeleze env().", "e": "Soluția: env() în config/services.php, apoi config('services.api.key') în cod.", "px": ["După `config:cache`, fișierul `.env` nu se mai încarcă. `env()` din cod întoarce null. Citești `env()` doar în fișierele din `config/`, iar în aplicație folosești `config('...')`."]}, {"id": "lv38", "d": "php", "nou": 1, "t": "mc", "q": "Ce trebuie respectat despre .env și APP_DEBUG în producție?", "o": ["APP_DEBUG=false, iar .env nu se pune în control de versiuni (se commit-ează .env.example)", "APP_DEBUG=true ca să vezi erorile", "Se commit-ează .env ca să existe backup"], "a": 0, "h": "Una dintre ele poate expune configurații sensibile.", "e": "Documentația: APP_DEBUG trebuie să fie false în producție. Pentru .env există env:encrypt dacă vrei să-l versionezi criptat.", "px": ["`APP_DEBUG=true` în producție expune detalii interne (căi, variabile). `.env` conține secrete, deci nu se pune în Git; în repo rămâne `.env.example`."]}, {"id": "lv39", "d": "php", "nou": 1, "t": "mc", "q": "Ce ai voie să faci în metoda register() a unui service provider?", "o": ["Doar să legi lucruri în container; listener-ele, rutele și view composers merg în boot()", "Orice, inclusiv rute și listener-e", "Doar să apelezi alte provider-e"], "a": 0, "h": "Alte servicii pot să nu fie încă încărcate.", "e": "boot() rulează după ce toți provider-ii au fost înregistrați.", "px": ["În `register()` doar legi lucruri în container (bind). Alte servicii pot să nu fie încă înregistrate. Rutele, evenimentele și view composers se pun în `boot()`."]}, {"id": "lv40", "d": "php", "nou": 1, "t": "mc", "q": "Cum ascunzi existența unei resurse la autorizare refuzată, întorcând 404 în loc de 403?", "o": ["Într-o policy: return Response::denyAsNotFound()", "abort(403) cu mesaj", "Gate::hide()"], "a": 0, "h": "Metoda din clasa Response.", "e": "Implicit, un refuz dă 403. denyWithStatus(404) alege alt cod.", "px": ["Un 403 spune „există, dar nu ai voie”. Dacă nu vrei să dai această informație, în policy întorci `Response::denyAsNotFound()` și utilizatorul vede 404."]}, {"id": "lv41", "d": "php", "nou": 1, "t": "mc", "q": "Cum folosești Gate::before() în autorizare?", "o": ["Rulează înaintea tuturor verificărilor; dacă întoarce true (ex. pentru admin), acordă toate drepturile", "Rulează după policy-uri", "Șterge toate gate-urile"], "a": 0, "h": "Super-admin.", "e": "Dacă întoarce null, verificarea continuă normal.", "px": ["`Gate::before()` rulează înaintea tuturor verificărilor. Dacă întoarce `true` (ex. adminul), accesul e acordat; dacă întoarce `null`, verificarea normală continuă."]}, {"id": "lv42", "d": "php", "nou": 1, "t": "mc", "q": "Ce face DB::transaction(function () {...}) dacă în closure apare o excepție?", "o": ["Face rollback automat și relansează excepția; la succes face commit", "Face commit parțial", "Ignoră excepția"], "a": 0, "h": "Nu trebuie să scrii rollBack() manual.", "e": "Al doilea argument (attempts) reîncearcă la deadlock.", "px": ["`DB::transaction` face commit dacă closure-ul se termină fără probleme. La excepție, face rollback automat și relansează excepția."]}, {"id": "lv43", "d": "php", "nou": 1, "t": "mc", "q": "De ce se pune lockForUpdate() într-o tranzacție?", "o": ["Blocarea e ținută până la commit/rollback; fără tranzacție se eliberează imediat după interogare", "lockForUpdate nu merge în tranzacții", "Ca să meargă mai repede"], "a": 0, "h": "Citește soldul, calculează, scrie.", "e": "sharedLock() împiedică modificarea rândurilor, dar permite alte citiri partajate.", "px": ["`lockForUpdate()` blochează rândurile citite până la finalul tranzacției, ca nimeni să nu le modifice între citire și scriere. În afara tranzacției, blocarea ar dispărea imediat."]}, {"id": "lv44", "d": "php", "nou": 1, "t": "mc", "q": "Ce avertizează documentația la selectRaw()/orderByRaw() cu date de la utilizator?", "o": ["Expresiile raw nu sunt protejate de injecție; folosești binding-uri, iar numele coloanelor nu pot fi parametri PDO", "Sunt protejate automat", "Sunt interzise"], "a": 0, "h": "PDO nu leagă nume de coloane.", "e": "Pentru ORDER BY validezi coloana din listă albă, nu din input direct.", "px": ["Expresiile `selectRaw`/`orderByRaw` ajung în SQL exact cum le scrii. Valorile utilizatorului le pui prin binding-uri (`?`), iar numele coloanelor le verifici cu o listă albă."]}, {"id": "lv45", "d": "php", "nou": 1, "t": "mc", "q": "Ce condiție trebuie să îndeplinească coloanele din al doilea argument al upsert()?", "o": ["Să aibă index PRIMARY sau UNIQUE (cu excepția SQL Server)", "Să fie de tip string", "Să fie nullable"], "a": 0, "h": "Altfel nu se poate detecta conflictul.", "e": "upsert(valori, coloaneUnice, coloaneDeActualizat) face INSERT sau UPDATE într-un singur apel.", "px": ["`upsert` folosește `ON DUPLICATE KEY` (sau echivalent). Coloanele din al doilea argument trebuie să aibă index PRIMARY sau UNIQUE, altfel baza nu știe când e „duplicat”."]}, {"id": "lv46", "d": "php", "nou": 1, "t": "mc", "q": "Ce face orWhere într-un lanț, dacă vrei logica a AND (b OR c)?", "o": ["Grupezi condițiile cu closure: ->where('a',1)->where(function ($q) { $q->where('b',1)->orWhere('c',1); })", "Pui orWhere direct, merge corect", "Folosești whereOr()"], "a": 0, "h": "Fără paranteze, AND/OR se amestecă.", "e": "Documentația recomandă gruparea cu closure, mai ales cu global scopes.", "px": ["`where('a',1)->orWhere('b',1)->orWhere('c',1)` înseamnă `a OR b OR c`, nu ce vrei. Grupezi cu closure: `where('a',1)->where(function ($q) { $q->where('b',1)->orWhere('c',1); })` pentru `a AND (b OR c)`."]}, {"id": "lv47", "d": "php", "nou": 1, "t": "mc", "q": "Diferența dintre pluck('title'), value('title') și first() la query builder?", "o": ["pluck: colecție de valori; value: o singură valoare scalară; first: un rând (stdClass)", "Toate întorc un string", "pluck întoarce un rând"], "a": 0, "h": "Forma rezultatului.", "e": "value() ia doar prima valoare a coloanei din primul rând.", "px": ["`pluck('title')` întoarce o colecție cu toate valorile. `value('title')` o singură valoare, din primul rând. `first()` întoarce rândul întreg."]}, {"id": "lv48", "d": "php", "nou": 1, "t": "mc", "q": "Ce face $users->toQuery()->update([...]) pe o Eloquent Collection?", "o": ["Convertește colecția în query builder pe cheile modelelor și face un UPDATE în masă", "Actualizează doar în memorie", "Salvează fiecare model separat"], "a": 0, "h": "Colecția păstrează modelele, query-ul le actualizează.", "e": "Metodele de colecție lucrează în memorie, pe modelele deja aduse; query builder-ul execută interogări.", "px": ["`toQuery()` transformă colecția într-o interogare pe cheile modelelor, iar `update()` aplică un singur UPDATE pentru toate."]}, {"id": "lv49", "d": "php", "nou": 1, "t": "mc", "q": "În ce diferă testele Unit de cele Feature în Laravel?", "o": ["Unit nu pornește aplicația (fără DB și servicii framework); Feature testează interacțiuni mai mari, inclusiv cereri HTTP", "Sunt identice", "Unit pornește aplicația, Feature nu"], "a": 0, "h": "Folder: tests/Unit vs tests/Feature.", "e": "Documentația recomandă majoritatea testelor ca Feature.", "px": ["Teste Unit: verifică o bucată mică de cod, fără a porni aplicația. Teste Feature: pornesc aplicația și verifică un flux (cerere HTTP, JSON, bază de date)."]}, {"id": "lv50", "d": "php", "nou": 1, "t": "mc", "q": "Care e ordinea evenimentelor la crearea unui model nou Eloquent?", "o": ["saving → creating → created → saved", "created → creating → saved → saving", "creating → saving → saved → created"], "a": 0, "h": "Saving înconjoară creating.", "e": "La update: saving → updating → updated → saved. Observer-ele grupează aceste handlere.", "px": ["La crearea unui model nou, Eloquent lansează: `saving` → `creating` → (INSERT) → `created` → `saved`. La actualizare, `creating`/`created` sunt înlocuite de `updating`/`updated`."]}, {"id": "zs1", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Care interogare dă angajații cu cel mai mare salariu din fiecare departament, inclusiv egalitățile (rezultat: Ana, Gabi, Eli, Fane)?", "o": ["SELECT name FROM emp e WHERE salary = (SELECT MAX(salary) FROM emp WHERE dept = e.dept)", "SELECT name, MAX(salary) FROM emp GROUP BY dept", "SELECT name FROM emp ORDER BY salary DESC LIMIT 1"], "a": 0, "h": "Subinterogare corelată pe departament (sau RANK() ... = 1).", "e": "A doua dă câte un rând pe departament (și în MySQL cu ONLY_FULL_GROUP_BY dă eroare, name nu e în GROUP BY). A treia întoarce un singur rând pe toată firma.", "px": ["Subinterogarea corelată se rulează pentru fiecare rând: „care e maximul departamentului ACESTUI angajat?” și păstrăm rândul dacă salariul lui e egal cu el.", "Așa rămân și Ana, și Gabi (ambii 9000 în IT). `ORDER BY ... LIMIT 1` ar fi dat un singur rând pe toată firma.", "Încearcă: rulează, apoi înlocuiește cu `SELECT name, MAX(salary) FROM emp GROUP BY dept` și vezi că pierzi un rând."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\n-- varianta corecta: compari cu maximul DIN DEPARTAMENTUL propriu\nSELECT name, dept, salary FROM emp e\nWHERE salary = (SELECT MAX(salary) FROM emp WHERE dept = e.dept)\nORDER BY dept, name;\n"}}, {"id": "zs2", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Care interogare întoarce al doilea cel mai mare salariu DISTINCT (7000)?", "o": ["SELECT MAX(salary) FROM emp WHERE salary < (SELECT MAX(salary) FROM emp)", "SELECT salary FROM emp ORDER BY salary DESC LIMIT 1 OFFSET 1", "SELECT salary FROM emp ORDER BY salary DESC LIMIT 2"], "a": 0, "h": "Atenție la dubluri: există doi angajați cu 9000.", "e": "OFFSET 1 întoarce 9000 (al doilea RÂND, nu a doua valoare distinctă). LIMIT 2 întoarce două rânduri.", "px": ["„Al doilea cel mai mare DISTINCT” = cel mai mare dintre cei mai mici decât maximul. `OFFSET 1` sare peste un RÂND, nu peste o valoare, iar 9000 apare de două ori.", "Încearcă: rulează întâi interogarea de sus, apoi pe cea din comentariu."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT MAX(salary) AS al_doilea\nFROM emp\nWHERE salary < (SELECT MAX(salary) FROM emp);\n\n-- compara cu: SELECT salary FROM emp ORDER BY salary DESC LIMIT 1 OFFSET 1  (da 9000!)\n"}}, {"id": "zs3", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Care interogare dă angajații care câștigă mai mult decât șeful lor (rezultat: Eli)?", "o": ["SELECT e.name FROM emp e JOIN emp b ON e.boss_id = b.id WHERE e.salary > b.salary", "SELECT e.name FROM emp e JOIN emp b ON e.id = b.boss_id WHERE e.salary > b.salary", "SELECT name FROM emp WHERE salary > (SELECT AVG(salary) FROM emp)"], "a": 0, "h": "Self join: e = angajatul, b = șeful.", "e": "A doua inversează relația (compară șefii cu subordonații lor: dă Ana de 4 ori). A treia compară cu media firmei.", "px": ["Self join: același tabel apare de două ori, o dată ca angajat (`e`) și o dată ca șef (`b`), legate prin `boss_id = id`.", "Încearcă: inversează condiția în `ON e.id = b.boss_id` și vezi că întrebarea devine alta."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT e.name AS angajat, e.salary, b.name AS sef, b.salary AS salariu_sef\nFROM emp e\nJOIN emp b ON e.boss_id = b.id\nWHERE e.salary > b.salary;\n"}}, {"id": "zs4", "d": "sql", "nou": 1, "t": "mc", "q": "Tabela dept(name) are: IT, HR, Ops, Legal. emp are angajați doar în IT, HR și Ops. Care interogare găsește departamentele fără angajați (Legal)?", "o": ["SELECT d.name FROM dept d LEFT JOIN emp e ON e.dept = d.name WHERE e.id IS NULL", "SELECT d.name FROM dept d LEFT JOIN emp e ON e.dept = d.name GROUP BY d.name HAVING COUNT(*) = 0", "SELECT d.name FROM dept d JOIN emp e ON e.dept = d.name WHERE e.id IS NULL"], "a": 0, "h": "Rândul fără pereche are NULL pe partea dreaptă.", "e": "La a doua, COUNT(*) numără și rândul cu NULL (valoarea 1), deci HAVING COUNT(*) = 0 nu prinde nimic; ar trebui COUNT(e.id). A treia: INNER JOIN nu produce niciodată rânduri fără pereche.", "px": ["Departamentul fără angajați primește totuși UN rând în rezultat, cu coloanele din `emp` pe NULL. `COUNT(*)` numără rândul acela (1), `COUNT(e.id)` nu (0).", "Încearcă: uită-te la linia „Legal” din al doilea rezultat."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\nDROP TABLE IF EXISTS dept;\nCREATE TABLE dept(name TEXT);\nINSERT INTO dept VALUES ('IT'),('HR'),('Ops'),('Legal');\n\n-- corect: LEFT JOIN + IS NULL\nSELECT d.name FROM dept d\nLEFT JOIN emp e ON e.dept = d.name\nWHERE e.id IS NULL;\n\n-- greseala frecventa: COUNT(*) numara si randul cu NULL\nSELECT d.name, COUNT(*) AS cu_star, COUNT(e.id) AS cu_coloana\nFROM dept d LEFT JOIN emp e ON e.dept = d.name\nGROUP BY d.name;\n"}}, {"id": "zs5", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Ce întoarce: SELECT name FROM emp WHERE id NOT IN (SELECT boss_id FROM emp) ?", "o": ["Niciun rând, pentru că subinterogarea conține NULL (boss_id-ul Anei)", "Bob, Cris, Eli, Fane, Gabi (cei care nu sunt șefi)", "Eroare de sintaxă"], "a": 0, "h": "Cum se comportă NOT IN cu NULL în listă?", "e": "x NOT IN (1, 4, NULL) nu poate fi TRUE (devine UNKNOWN). NOT EXISTS (sau filtru boss_id IS NOT NULL) întoarce cei 5 angajați care nu sunt șefi.", "px": ["`x NOT IN (1, 4, NULL)` înseamnă „x diferit de 1 ȘI de 4 ȘI de NULL”. Comparația cu NULL nu e nici adevărată, nici falsă (e „necunoscut”), deci rândul nu trece.", "`NOT EXISTS` nu are problema asta.", "Încearcă: rulează ambele; prima întoarce zero rânduri."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\n-- NOT IN cu NULL in lista: niciun rand!\nSELECT name FROM emp WHERE id NOT IN (SELECT boss_id FROM emp);\n\n-- varianta sigura\nSELECT name FROM emp e\nWHERE NOT EXISTS (SELECT 1 FROM emp x WHERE x.boss_id = e.id);\n"}}, {"id": "zs6", "d": "sql", "nou": 1, "t": "mc", "q": "Tabela orders(id,client,total,dt): (1,A,100,01.01), (2,B,50,01.01), (3,A,70,02.01), (4,C,30,03.01), (5,A,20,03.01). Ce întoarce SELECT id, SUM(total) OVER (ORDER BY dt) FROM orders ORDER BY id ?", "o": ["150, 150, 220, 270, 270 (rândurile cu același dt sunt „peers” și se adună împreună)", "100, 150, 220, 250, 270", "100, 50, 70, 30, 20"], "a": 0, "h": "Cadrul implicit cu ORDER BY e RANGE, nu ROWS.", "e": "Documentația MySQL: cadrul implicit e RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, care include toți peers. Pentru total cumulat rând cu rând: ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW (cu ORDER BY dt, id).", "px": ["Cu `ORDER BY dt`, rândurile cu aceeași dată sunt „perechi” (peers) și se adună împreună: comenzile 1 și 2 (ambele pe 01.01) primesc 150.", "Cu `ROWS`, adunarea merge rând cu rând: 100, 150, 220, ...", "Încearcă: compară cele două coloane."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS orders;\nCREATE TABLE orders(id INT, client TEXT, total INT, dt TEXT);\nINSERT INTO orders VALUES (1,'A',100,'2024-01-01'),(2,'B',50,'2024-01-01'),(3,'A',70,'2024-01-02'),(4,'C',30,'2024-01-03'),(5,'A',20,'2024-01-03');\nDROP TABLE IF EXISTS order_items;\nCREATE TABLE order_items(order_id INT, sku TEXT, qty INT);\nINSERT INTO order_items VALUES (1,'x',1),(1,'y',2),(2,'x',1);\n\nSELECT id, dt, total,\n  SUM(total) OVER (ORDER BY dt)                    AS implicit_range,\n  SUM(total) OVER (ORDER BY dt, id\n       ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS rand_cu_rand\nFROM orders ORDER BY id;\n"}}, {"id": "zs7", "d": "sql", "nou": 1, "t": "mc", "q": "orders: (1,A,100), (2,B,50), (3,A,70), (4,C,30), (5,A,20); order_items: (1,x,1), (1,y,2), (2,x,1). Ce întoarce SELECT SUM(o.total) FROM orders o JOIN order_items i ON i.order_id = o.id ?", "o": ["250 (comanda 1 apare de două ori: 100+100+50)", "270", "150"], "a": 0, "h": "Fan-out: câte rânduri produce JOIN-ul pentru comanda 1?", "e": "Comanda 1 are 2 articole, deci totalul ei se adună de două ori; comenzile fără articole dispar (INNER JOIN). Corect: agregi înainte de join sau folosești EXISTS.", "px": ["Un JOIN produce câte un rând pentru fiecare articol. Comanda 1 are 2 articole, deci totalul ei (100) apare de două ori. Comenzile fără articole dispar.", "Soluție: agregi înainte de join sau folosești `EXISTS`.", "Încearcă: rulează și compară 250 cu 150."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS orders;\nCREATE TABLE orders(id INT, client TEXT, total INT, dt TEXT);\nINSERT INTO orders VALUES (1,'A',100,'2024-01-01'),(2,'B',50,'2024-01-01'),(3,'A',70,'2024-01-02'),(4,'C',30,'2024-01-03'),(5,'A',20,'2024-01-03');\nDROP TABLE IF EXISTS order_items;\nCREATE TABLE order_items(order_id INT, sku TEXT, qty INT);\nINSERT INTO order_items VALUES (1,'x',1),(1,'y',2),(2,'x',1);\n\n-- JOIN-ul inmulteste comanda 1 (are 2 articole)\nSELECT SUM(o.total) AS suma_gresita\nFROM orders o JOIN order_items i ON i.order_id = o.id;\n\n-- corect: fiecare comanda o singura data\nSELECT SUM(total) AS suma_corecta FROM orders;\nSELECT SUM(total) AS doar_comenzi_cu_articole\nFROM orders o WHERE EXISTS (SELECT 1 FROM order_items i WHERE i.order_id = o.id);\n"}}, {"id": "zs8", "d": "sql", "nou": 1, "t": "mc", "q": "dept: IT, HR, Ops, Legal; emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Care interogare dă TOATE departamentele cu numărul angajaților cu salariu > 6000 (HR 0, IT 4, Legal 0, Ops 0)?", "o": ["SELECT d.name, COUNT(e.id) FROM dept d LEFT JOIN emp e ON e.dept = d.name AND e.salary > 6000 GROUP BY d.name", "SELECT d.name, COUNT(e.id) FROM dept d LEFT JOIN emp e ON e.dept = d.name WHERE e.salary > 6000 GROUP BY d.name", "SELECT d.name, COUNT(e.id) FROM dept d JOIN emp e ON e.dept = d.name AND e.salary > 6000 GROUP BY d.name"], "a": 0, "h": "Filtrul pe tabela din dreapta stă în ON, nu în WHERE.", "e": "Cu WHERE pe e.salary, rândurile cu NULL dispar și LEFT JOIN devine practic INNER JOIN: rămâne doar IT. La fel cu INNER JOIN.", "px": ["Rândurile fără pereche au `e.salary` NULL. În `WHERE`, `NULL > 6000` nu e adevărat, deci rândul dispare. Condiția în `ON` doar decide cu cine se potrivește.", "Încearcă: rulează și numără rândurile din fiecare rezultat."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\nDROP TABLE IF EXISTS dept;\nCREATE TABLE dept(name TEXT);\nINSERT INTO dept VALUES ('IT'),('HR'),('Ops'),('Legal');\n\n-- filtrul in ON: pastrezi TOATE departamentele\nSELECT d.name, COUNT(e.id) AS nr\nFROM dept d LEFT JOIN emp e ON e.dept = d.name AND e.salary > 6000\nGROUP BY d.name ORDER BY d.name;\n\n-- filtrul in WHERE: LEFT JOIN devine, practic, INNER JOIN\nSELECT d.name, COUNT(e.id) AS nr\nFROM dept d LEFT JOIN emp e ON e.dept = d.name\nWHERE e.salary > 6000\nGROUP BY d.name;\n"}}, {"id": "zs9", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). dept: IT, HR, Ops, Legal. Care interogare întoarce fiecare departament o singură dată dacă are angajați cu salariu > 5000 (HR, IT)?", "o": ["SELECT d.name FROM dept d WHERE EXISTS (SELECT 1 FROM emp e WHERE e.dept = d.name AND e.salary > 5000)", "SELECT d.name FROM dept d JOIN emp e ON e.dept = d.name WHERE e.salary > 5000", "SELECT name FROM dept WHERE name IN (SELECT dept FROM emp WHERE salary < 5000)"], "a": 0, "h": "JOIN înmulțește rândurile.", "e": "Varianta cu JOIN întoarce IT de 4 ori și HR o dată. A treia filtrează după salariu < 5000 (dă Ops).", "px": ["`EXISTS` întreabă doar „există măcar unul?”, deci fiecare departament apare o singură dată. JOIN-ul repetă departamentul pentru fiecare angajat.", "Încearcă: compară numărul de rânduri."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\nDROP TABLE IF EXISTS dept;\nCREATE TABLE dept(name TEXT);\nINSERT INTO dept VALUES ('IT'),('HR'),('Ops'),('Legal');\n\nSELECT d.name FROM dept d\nWHERE EXISTS (SELECT 1 FROM emp e WHERE e.dept = d.name AND e.salary > 5000);\n\n-- cu JOIN apar dubluri:\nSELECT d.name FROM dept d JOIN emp e ON e.dept = d.name WHERE e.salary > 5000;\n"}}, {"id": "zs10", "d": "sql", "nou": 1, "t": "mc", "q": "orders (client A): (1,100,01.01), (3,70,02.01), (5,20,03.01). Ce întoarce SELECT id, total - LAG(total) OVER (PARTITION BY client ORDER BY dt, id) FROM orders WHERE client = 'A' ORDER BY id ?", "o": ["NULL, -30, -50", "100, -30, -50", "0, 70, 20"], "a": 0, "h": "Primul rând din partiție nu are rând anterior.", "e": "LAG întoarce NULL când nu există rând anterior (implicit). Poți da o valoare implicită: LAG(total, 1, 0).", "px": ["`LAG(total)` aduce valoarea de pe rândul anterior din aceeași partiție. Pe primul rând nu există anterior, deci rezultatul e NULL.", "`LAG(total, 1, 0)` ar pune 0 în loc de NULL.", "Încearcă: schimbă în `LEAD` și vezi sensul."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS orders;\nCREATE TABLE orders(id INT, client TEXT, total INT, dt TEXT);\nINSERT INTO orders VALUES (1,'A',100,'2024-01-01'),(2,'B',50,'2024-01-01'),(3,'A',70,'2024-01-02'),(4,'C',30,'2024-01-03'),(5,'A',20,'2024-01-03');\nDROP TABLE IF EXISTS order_items;\nCREATE TABLE order_items(order_id INT, sku TEXT, qty INT);\nINSERT INTO order_items VALUES (1,'x',1),(1,'y',2),(2,'x',1);\n\nSELECT id, total,\n  total - LAG(total) OVER (PARTITION BY client ORDER BY dt, id) AS diferenta\nFROM orders WHERE client = 'A' ORDER BY id;\n"}}, {"id": "zs11", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Ana (id 1) e șefa lui Bob, Cris, Dana, Fane și Gabi; Dana e șefa lui Eli. Ce întoarce WITH RECURSIVE sub AS (SELECT id FROM emp WHERE boss_id = 1 UNION ALL SELECT e.id FROM emp e JOIN sub s ON e.boss_id = s.id) SELECT COUNT(*) FROM sub ?", "o": ["6 (toți subordonații, direcți și indirecți)", "5 (doar cei direcți)", "7 (inclusiv Ana)"], "a": 0, "h": "Partea de ancoră + partea recursivă.", "e": "Ancora ia cei 5 direcți, recursia adaugă pe Eli (subordonatul Danei). Ana nu apare, fiindcă ancora pornește de la cei cu boss_id = 1.", "px": ["Începi cu subordonații direcți ai Anei. Apoi, la fiecare pas, adaugi subordonații celor deja găsiți, până nu mai apare nimeni nou.", "Așa ajungi și la Eli (sub Dana). Ana nu apare, fiindcă ancora pornește de la cei cu `boss_id = 1`.", "Încearcă: înlocuiește `COUNT(*)` cu `id` ca să vezi lista."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nWITH RECURSIVE sub AS (\n  SELECT id FROM emp WHERE boss_id = 1          -- ancora: cei directi\n  UNION ALL\n  SELECT e.id FROM emp e JOIN sub s ON e.boss_id = s.id   -- cei de sub ei\n)\nSELECT COUNT(*) FROM sub;\n"}}, {"id": "zs12", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Ce întoarce SELECT dept, SUM(CASE WHEN salary >= 7000 THEN 1 ELSE 0 END), SUM(CASE WHEN salary < 7000 THEN 1 ELSE 0 END) FROM emp GROUP BY dept ORDER BY dept ?", "o": ["HR 0 2; IT 4 0; Ops 0 1", "HR 1 1; IT 2 2; Ops 0 1", "HR 2 0; IT 0 4; Ops 1 0"], "a": 0, "h": "Pivot manual cu CASE în interiorul agregatului.", "e": "IT are 9000, 9000, 7000, 7000 (4 rânduri >= 7000). HR are 5000 și 6000. Ops are 4000.", "px": ["`CASE` în interiorul unui `SUM` e un „contor pe condiții”: pentru fiecare rând pui 1 dacă e adevărat, 0 altfel, iar `SUM` adună.", "Încearcă: adaugă o a treia coloană pentru salarii sub 5000."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT dept,\n  SUM(CASE WHEN salary >= 7000 THEN 1 ELSE 0 END) AS mari,\n  SUM(CASE WHEN salary <  7000 THEN 1 ELSE 0 END) AS mici\nFROM emp GROUP BY dept ORDER BY dept;\n"}}, {"id": "zs13", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Ce întoarce SELECT COUNT(DISTINCT boss_id), COUNT(boss_id), COUNT(*) FROM emp ?", "o": ["2, 6, 7", "2, 7, 7", "1, 6, 7"], "a": 0, "h": "NULL nu se numără în COUNT(coloană).", "e": "boss_id = NULL (Ana), 1 (de 5 ori), 4. DISTINCT non-NULL: {1, 4} = 2. COUNT(boss_id) = 6. COUNT(*) = 7.", "px": ["`COUNT(*)` numără rândurile. `COUNT(coloana)` numără doar valorile care nu sunt NULL. `DISTINCT` le numără o singură dată.", "Încearcă: rulează și explică de ce 7, 6 și 2."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT COUNT(DISTINCT boss_id) AS distincti,\n       COUNT(boss_id)          AS non_null,\n       COUNT(*)                AS toate\nFROM emp;\n"}}, {"id": "zs14", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Care interogare întoarce a treia valoare DISTINCTĂ de salariu (6000)?", "o": ["SELECT DISTINCT salary FROM (SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r FROM emp) AS t WHERE r = 3", "SELECT DISTINCT salary FROM (SELECT salary, RANK() OVER (ORDER BY salary DESC) AS r FROM emp) AS t WHERE r = 3", "SELECT salary FROM (SELECT salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS r FROM emp) AS t WHERE r = 3"], "a": 0, "h": "Care funcție nu lasă goluri în numerotare?", "e": "Salariile desc: 9000, 9000, 7000, 7000, 6000... RANK dă 1,1,3,3,5 (r = 3 dă 7000). ROW_NUMBER = 3 e al treilea rând (7000). DENSE_RANK dă 1,1,2,2,3 (6000). În MySQL derivata cere alias (AS t).", "px": ["`ROW_NUMBER` numerotează rândurile fără egalități. `RANK` lasă goluri după egalități (1,1,3). `DENSE_RANK` nu lasă goluri (1,1,2).", "Pentru „a treia valoare distinctă” folosești `DENSE_RANK() = 3`.", "Încearcă: uită-te la cele trei coloane."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS dense,\n       RANK() OVER (ORDER BY salary DESC) AS rank,\n       ROW_NUMBER() OVER (ORDER BY salary DESC) AS rn\nFROM emp ORDER BY salary DESC;\n"}}, {"id": "zs15", "d": "sql", "nou": 1, "t": "mc", "q": "De ce day - ROW_NUMBER() OVER (ORDER BY day) identifică serii de zile consecutive (gaps and islands)?", "o": ["Într-o serie consecutivă, ziua crește cu 1 și numărul rândului la fel, deci diferența e constantă; la un salt ea se schimbă", "Pentru că ROW_NUMBER sare peste zilele lipsă", "Pentru că diferența e mereu 0"], "a": 0, "h": "Grupezi după diferență.", "e": "Pentru zilele 1,2,3,7,8: diferențele sunt constante în fiecare serie (ex. 0,0,0 apoi 3,3). GROUP BY diferența, cu MIN/MAX/COUNT, dă începutul, sfârșitul și lungimea seriilor.", "px": ["Într-o serie de zile consecutive, și ziua, și numărul rândului cresc cu 1, deci diferența dintre ele rămâne aceeași. La un „salt” în zile, diferența se schimbă.", "Grupând după acea diferență obții seriile.", "Încearcă: uită-te la coloana `grup`: 3 valori egale, apoi o alta."], "tr": {"l": "sql", "c": "\nDROP TABLE IF EXISTS lg;\nCREATE TABLE lg(day TEXT);\nINSERT INTO lg VALUES ('2024-01-01'),('2024-01-02'),('2024-01-03'),('2024-01-07'),('2024-01-08');\nSELECT day, julianday(day) - ROW_NUMBER() OVER (ORDER BY day) AS grup FROM lg;\n\nSELECT MIN(day) AS de_la, MAX(day) AS pana_la, COUNT(*) AS zile\nFROM (SELECT day, julianday(day) - ROW_NUMBER() OVER (ORDER BY day) AS g FROM lg)\nGROUP BY g;\n"}}, {"id": "zs16", "d": "sql", "nou": 1, "t": "mc", "q": "În MySQL, ce se întâmplă cu: DELETE FROM t WHERE id NOT IN (SELECT MIN(id) FROM t GROUP BY email) ?", "o": ["Eroare: nu poți șterge dintr-un tabel și selecta din același tabel într-o subinterogare; rescrii cu tabel derivat sau JOIN", "Șterge duplicatele corect", "Șterge toate rândurile"], "a": 0, "h": "E o restricție din documentația DELETE.", "e": "Documentația MySQL: «You cannot delete from a table and select from the same table in a subquery.» Soluții: DELETE t FROM t LEFT JOIN (SELECT MIN(id) AS id FROM t GROUP BY email) k ON t.id = k.id WHERE k.id IS NULL.", "px": ["MySQL nu te lasă să modifici un tabel și să-l citești în aceeași subinterogare. Rescrierea obișnuită: pui subinterogarea într-un tabel derivat (`SELECT ... FROM (SELECT ...) t`) sau folosești `JOIN`."]}, {"id": "zs17", "d": "sql", "nou": 1, "t": "mc", "q": "Date: emp(id,name,dept,boss_id,salary): (1,Ana,IT,NULL,9000), (2,Bob,IT,1,7000), (3,Cris,IT,1,7000), (4,Dana,HR,1,5000), (5,Eli,HR,4,6000), (6,Fane,Ops,1,4000), (7,Gabi,IT,1,9000). Ce nume întoarce SELECT name FROM emp ORDER BY boss_id ASC, id LIMIT 1 ?", "o": ["Ana (NULL se sortează primul la ASC în MySQL și SQLite)", "Bob (cea mai mică valoare non-NULL)", "Gabi (ultimul rând)"], "a": 0, "h": "Unde pune NULL ordonarea ascendentă?", "e": "MySQL: NULL apare primul la ASC și ultimul la DESC. PostgreSQL face invers (NULLS LAST implicit la ASC).", "px": ["La `ASC`, NULL apare primul în MySQL și SQLite. Ana (fără șef) e prima.", "Încearcă: schimbă în `DESC` și vezi că NULL ajunge ultimul."], "tr": {"l": "sql", "c": "DROP TABLE IF EXISTS emp;\nCREATE TABLE emp(id INT, name TEXT, dept TEXT, boss_id INT, salary INT);\nINSERT INTO emp VALUES\n (1,'Ana','IT',NULL,9000),(2,'Bob','IT',1,7000),(3,'Cris','IT',1,7000),\n (4,'Dana','HR',1,5000),(5,'Eli','HR',4,6000),(6,'Fane','Ops',1,4000),(7,'Gabi','IT',1,9000);\n\nSELECT id, name, boss_id FROM emp ORDER BY boss_id ASC, id;\n"}}, {"id": "zs18", "d": "sql", "nou": 1, "t": "mc", "q": "Ai un index (nume, a, b). Pentru care filtru MySQL poate folosi indexul la căutare?", "o": ["WHERE nume = 'x' AND a = 1", "WHERE a = 1 AND b = 2", "WHERE nume = 'x' OR a = 1"], "a": 0, "h": "Cel mai din stânga prefix.", "e": "Documentația: orice prefix din stânga al indexului se poate folosi. Fără prima coloană sau cu OR între coloane diferite, indexul nu se folosește pentru căutare.", "px": ["Indexul (nume, a, b) funcționează de la stânga la dreapta, ca o agendă: întâi nume, apoi a, apoi b. Poți folosi un prefix: `nume`, `nume + a`, `nume + a + b`. Dacă sari peste `nume`, nu merge."]}, {"id": "zs19", "d": "sql", "nou": 1, "t": "mc", "q": "Ce înseamnă type = ALL în rezultatul unui EXPLAIN MySQL?", "o": ["Scanare completă a tabelei (cel mai slab tip de acces)", "Folosește toate indexurile", "Citește un singur rând"], "a": 0, "h": "Tipuri bune: const, eq_ref, ref, range.", "e": "Documentația ordonează tipurile de la system/const (cele mai bune) la ALL (cel mai slab). index = scanare completă de index.", "px": ["`EXPLAIN` arată planul. `type = ALL` înseamnă că baza citește tot tabelul rând cu rând. De obicei vrei `ref`, `range` sau `const` (folosesc un index)."]}, {"id": "zs20", "d": "sql", "nou": 1, "t": "mc", "q": "Care e nivelul implicit de izolare în InnoDB și ce garantează?", "o": ["REPEATABLE READ: citirile obișnuite din aceeași tranzacție văd același snapshot, stabilit la prima citire", "READ COMMITTED: fiecare citire vede date noi", "SERIALIZABLE: toate tranzacțiile rulează pe rând"], "a": 0, "h": "Snapshot la prima citire.", "e": "READ COMMITTED are snapshot nou la fiecare citire consistentă și dezactivează gap locks. Documentația nu recomandă amestecul de citiri cu și fără blocare în aceeași tranzacție REPEATABLE READ.", "px": ["InnoDB folosește implicit REPEATABLE READ. La prima citire din tranzacție primești un „instantaneu”, iar citirile următoare văd același lucru, chiar dacă alții fac commit între timp."]}, {"id": "zs21", "d": "sql", "nou": 1, "t": "mc", "q": "Cum se comportă MySQL 8 cu SELECT name, address, MAX(age) FROM t GROUP BY name (name nu e cheie primară)?", "o": ["Eroare ONLY_FULL_GROUP_BY: address nu e în GROUP BY și nu depinde funcțional de name; ANY_VALUE(address) acceptă explicit valoarea oarecare", "Merge, alege prima adresă", "Merge, alege ultima adresă"], "a": 0, "h": "Modul SQL activat implicit.", "e": "Dacă name ar fi cheie primară, address ar depinde funcțional de el și interogarea ar fi validă.", "px": ["Cu `ONLY_FULL_GROUP_BY` (activ implicit în MySQL 8), orice coloană din SELECT trebuie să fie în GROUP BY sau în agregare. `address` nu e, deci eroare. Dacă ți-e indiferent care adresă, scrii `ANY_VALUE(address)`."]}, {"id": "zy31", "d": "py", "nou": 1, "t": "mc", "q": "Ce conține x după: x = [[0]*2]*2; x[0][0] = 1 ?", "o": ["[[1, 0], [1, 0]]", "[[1, 0], [0, 0]]", "[[0, 0], [0, 0]]"], "a": 0, "h": "Înmulțirea listei copiază referințe.", "e": "[[0]*2]*2 creează două referințe către aceeași listă interioară. Corect: [[0]*2 for _ in range(2)].", "px": ["`[[0]*2]*2` nu face două liste, ci o listă folosită de două ori (două „etichete” pe același obiect).", "Cu un comprehension creezi liste distincte.", "Încearcă: afișează `x[0] is x[1]` (e True)."], "tr": {"l": "python", "c": "x = [[0] * 2] * 2\nx[0][0] = 1\nprint(x)           # [[1, 0], [1, 0]]\n\ny = [[0] * 2 for _ in range(2)]\ny[0][0] = 1\nprint(y)           # [[1, 0], [0, 0]]\n"}}, {"id": "zy32", "d": "py", "nou": 1, "t": "mc", "q": "t = (1, [2, 3]); t[1].append(4). Ce se întâmplă?", "o": ["Merge: t devine (1, [2, 3, 4]); tuplul e imutabil, dar lista din el nu", "TypeError, tuplul nu se poate modifica", "t devine (1, [2, 3])"], "a": 0, "h": "Imutabilitatea se referă la referințe.", "e": "t[0] = 5 ar da TypeError. Tuplul ține referința la listă, iar lista se poate modifica.", "px": ["Tuplul își ține „legăturile” fixe: nu poți pune alt obiect în locul unuia. Dar dacă un obiect din el e modificabil (lista), îl poți modifica.", "Imutabilitatea e la nivelul legăturilor, nu al obiectelor.", "Încearcă: rulează și vezi ambele rezultate."], "tr": {"l": "python", "c": "t = (1, [2, 3])\nt[1].append(4)\nprint(t)           # (1, [2, 3, 4])\ntry:\n    t[0] = 5\nexcept TypeError as e:\n    print(\"Eroare:\", e)\n"}}, {"id": "zy33", "d": "py", "nou": 1, "t": "mc", "q": "k = dict.fromkeys(['a', 'b'], []); k['a'].append(1). Cât e k?", "o": ["{'a': [1], 'b': [1]} — aceeași listă pentru ambele chei", "{'a': [1], 'b': []}", "Eroare"], "a": 0, "h": "O singură valoare, partajată.", "e": "fromkeys folosește același obiect pentru toate cheile. Pentru liste separate: {c: [] for c in chei}.", "px": ["`fromkeys` pune ACEEAȘI listă pentru toate cheile (e o singură listă, cu mai multe etichete).", "Ca să ai liste separate, folosești un comprehension de dicționar.", "Încearcă: rulează și compară cele două rezultate."], "tr": {"l": "python", "c": "k = dict.fromkeys(['a', 'b'], [])\nk['a'].append(1)\nprint(k)           # {'a': [1], 'b': [1]}\n\ncorect = {c: [] for c in ['a', 'b']}\ncorect['a'].append(1)\nprint(corect)      # {'a': [1], 'b': []}\n"}}, {"id": "zy34", "d": "py", "nou": 1, "t": "mc", "q": "d = {'a': 1}; d.setdefault('a', 9) întoarce...", "o": ["1 și nu schimbă d (cheia există deja)", "9 și actualizează cheia", "None"], "a": 0, "h": "setdefault inserează doar dacă lipsește.", "e": "d.setdefault('b', 2) ar insera b: 2 și ar întoarce 2.", "px": ["`setdefault(cheie, val)`: dacă cheia există, o lasă și dă valoarea ei; dacă nu există, o creează cu `val`.", "E util la numărări sau grupări: `d.setdefault(c, []).append(x)`.", "Încearcă: apelează `d.setdefault('a', 0)` și observă că nu schimbă nimic."], "tr": {"l": "python", "c": "d = {'a': 1}\nprint(d.setdefault('a', 9))   # 1, cheia exista\nprint(d.setdefault('b', 2))   # 2, o adauga\nprint(d)\n"}}, {"id": "zy35", "d": "py", "nou": 1, "t": "mc", "q": "Ce întoarce {'a': 1, 'b': 2}.popitem() în Python 3.7+?", "o": ["('b', 2) — ultimul element inserat (LIFO)", "('a', 1)", "Un element oarecare, fără garanții"], "a": 0, "h": "Dicționarele păstrează ordinea inserării.", "e": "Documentația W3Schools: popitem() elimină ultima pereche inserată.", "px": ["De la Python 3.7 dicționarele păstrează ordinea inserării, iar `popitem()` scoate ultima pereche (ca stiva: ultimul intrat, primul ieșit).", "Dacă ai nevoie de primul: `next(iter(d))` și `del`.", "Încearcă: adaugă o a treia cheie și vezi care iese."], "tr": {"l": "python", "c": "d = {'a': 1, 'b': 2}\nprint(d.popitem())     # ('b', 2): ultimul inserat\nprint(d)\n"}}, {"id": "zy36", "d": "py", "nou": 1, "t": "mc", "q": "s = {1, 2, 3}. Ce dă s ^ {3, 4}?", "o": ["{1, 2, 4} (diferența simetrică)", "{3}", "{1, 2, 3, 4}"], "a": 0, "h": "Elementele care sunt în exact una dintre mulțimi.", "e": "& e intersecție, | reuniune, - diferență, ^ diferență simetrică.", "px": ["`^` păstrează elementele care apar în EXACT una dintre mulțimi, nu în ambele.", "Ține minte: `&` = și, `|` = sau, `-` = fără, `^` = unul singur.", "Încearcă: schimbă mulțimile și prezice rezultatul înainte să rulezi."], "tr": {"l": "python", "c": "s = {1, 2, 3}\nprint(s & {2, 3, 4})   # intersectie\nprint(s | {4})         # reuniune\nprint(s - {1})         # diferenta\nprint(s ^ {3, 4})      # in exact una dintre ele\n"}}, {"id": "zy37", "d": "py", "nou": 1, "t": "mc", "q": "Ce dau -7 // 2 și -7 % 3?", "o": ["-4 și 2 (împărțirea întreagă rotunjește în jos)", "-3 și -1", "-3 și 2"], "a": 0, "h": "Floor division, nu trunchiere.", "e": "Python respectă identitatea a == (a // b) * b + a % b, iar restul are semnul împărțitorului.", "px": ["`//` rotunjește în jos (spre minus infinit), nu spre zero. De aceea `-7 // 2` e `-4`.", "Restul `%` are semnul împărțitorului, ca regula `a == (a//b)*b + a%b` să rămână adevărată.", "Încearcă: calculează `-7 // 2` și `int(-7 / 2)` și vezi diferența."], "tr": {"l": "python", "c": "print(7 // 2, -7 // 2)     # 3 -4  (rotunjeste in jos)\nprint(7 % 3, -7 % 3)       # 1 2\na, b = -7, 2\nprint(a == (a // b) * b + a % b)\n"}}, {"id": "zy38", "d": "py", "nou": 1, "t": "mc", "q": "Ce dau round(2.5) și round(3.5) în Python 3?", "o": ["2 și 4 (rotunjire la cel mai apropiat par)", "3 și 4", "2 și 3"], "a": 0, "h": "Banker's rounding.", "e": "La egalitate (.5) rotunjește spre numărul par.", "px": ["La `.5` Python rotunjește spre numărul PAR (rotunjire „bancară”): `2.5 → 2`, `3.5 → 4`. E menită să nu favorizeze mereu în sus.", "Pentru bani folosește `decimal.Decimal`.", "Încearcă: rulează și vezi șirul 0, 2, 2, 4."], "tr": {"l": "python", "c": "print(round(0.5), round(1.5), round(2.5), round(3.5))\nprint(round(2.675, 2))     # 2.67 (nu 2.68!), din cauza floatului\n"}}, {"id": "zy39", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă 0.1 + 0.2 == 0.3 și cum compari corect?", "o": ["False; compari cu math.isclose() sau cu round()", "True", "Eroare de tip"], "a": 0, "h": "Reprezentare binară în virgulă mobilă.", "e": "0.1 + 0.2 = 0.30000000000000004.", "px": ["Calculatorul scrie numerele în binar și `0.1` nu se poate scrie exact (ca `1/3` în zecimal). Rămâne o mică eroare.", "Compari cu `math.isclose` sau rotunjești.", "Încearcă: rulează și vezi `0.30000000000000004`."], "tr": {"l": "python", "c": "import math\nprint(0.1 + 0.2)\nprint(0.1 + 0.2 == 0.3)\nprint(math.isclose(0.1 + 0.2, 0.3))\nprint(round(0.1 + 0.2, 2) == 0.3)\n"}}, {"id": "zy40", "d": "py", "nou": 1, "t": "mc", "q": "Ce întorc (0 or 'a'), (1 and 'b') și ('' and 1)?", "o": ["'a', 'b' și '' (operatorii întorc operandul, nu bool)", "True, True, False", "'a', 'b', 0"], "a": 0, "h": "Scurtcircuit cu valori.", "e": "or întoarce primul operand adevărat sau ultimul; and primul operand fals sau ultimul.", "px": ["`or` întoarce primul operand adevărat (sau ultimul), `and` primul fals (sau ultimul). Nu întorc neapărat True/False.", "Truc folosit des: `nume or 'anonim'`.", "Încearcă: prezice rezultatul înainte să rulezi."], "tr": {"l": "python", "c": "print(0 or 'a')       # 'a'\nprint(1 and 'b')      # 'b'\nprint('' and 1)       # ''\nprint(None or 0)      # 0\nnume = ''\nprint(nume or 'anonim')   # valoare implicita\n"}}, {"id": "zy41", "d": "py", "nou": 1, "t": "mc", "q": "li = [1, 2, 3, 4]; for v in li: if v % 2 == 0: li.remove(v). Ce e li la final?", "o": ["[1, 3]", "[1, 3, 4]", "[1, 2, 3, 4]"], "a": 0, "h": "Modifici lista în timp ce o parcurgi.", "e": "Aici merge din întâmplare (sar peste elemente). Regula sigură: iterezi pe copie (li[:]) sau construiești o listă nouă cu comprehension.", "px": ["Când ștergi dintr-o listă în timp ce o parcurgi, indecșii se mută și Python sare peste elemente.", "Soluția: construiești o listă nouă cu comprehension sau iterezi pe o copie `li[:]`.", "Încearcă: rulează al doilea exemplu: aici rezultatul e greșit."], "tr": {"l": "python", "c": "li = [1, 2, 3, 4]\nfor v in li:\n    if v % 2 == 0:\n        li.remove(v)\nprint(li)             # [1, 3] -- din intamplare\n\nli2 = [2, 4, 6, 1]\nfor v in li2:\n    if v % 2 == 0:\n        li2.remove(v)\nprint(li2)            # [4, 1] !!! sare peste elemente\n\nprint([v for v in [2, 4, 6, 1] if v % 2])   # varianta corecta\n"}}, {"id": "zy42", "d": "py", "nou": 1, "t": "mc", "q": "def g(): n = 0; def inner(): nonlocal n; n += 1; return n; return inner. c = g(); c(); print(c()). Ce afișează?", "o": ["2 (nonlocal modifică variabila din funcția exterioară)", "1", "UnboundLocalError"], "a": 0, "h": "Scope: Local → Enclosing → Global → Built-in.", "e": "Fără nonlocal, n += 1 ar da UnboundLocalError. global lucrează la nivel de modul.", "px": ["`nonlocal` îi spune funcției interioare: „`n` nu e al meu, e din funcția de deasupra”. Fără el, `n += 1` ar încerca să creeze un `n` local.", "Cheia e regula LEGB: Local, Enclosing, Global, Built-in.", "Încearcă: scoate `nonlocal n` și vezi `UnboundLocalError`."], "tr": {"l": "python", "c": "def g():\n    n = 0\n    def inner():\n        nonlocal n\n        n += 1\n        return n\n    return inner\n\nc = g()\nc()\nprint(c())    # 2\n"}}, {"id": "zy43", "d": "py", "nou": 1, "t": "mc", "q": "def bad(): print(zz); zz = 1. Ce se întâmplă la bad()?", "o": ["UnboundLocalError: zz e variabilă locală (atribuită în funcție) folosită înainte de atribuire", "NameError", "Afișează None"], "a": 0, "h": "Atribuirea face variabila locală pe toată funcția.", "e": "Dacă zz exista la nivel global, tot UnboundLocalError ar apărea.", "px": ["Dacă într-o funcție ATRIBUI o variabilă (oriunde), Python o consideră locală în TOATĂ funcția. Citirea ei înainte de atribuire dă eroare.", "Dacă doar citești, merge: caută în global.", "Încearcă: comentează linia `zz = 1` din `bad` și vezi că dispare eroarea."], "tr": {"l": "python", "c": "def bad():\n    try:\n        print(zz)\n    except UnboundLocalError as e:\n        print(\"UnboundLocalError:\", e)\n    zz = 1\n\nbad()\n\nzz = 'global'\ndef ok():\n    print(zz)       # citeste globalul\nok()\n"}}, {"id": "zy44", "d": "py", "nou": 1, "t": "mc", "q": "class P: x = []. p1 = P(); p2 = P(); p1.x.append(1). Ce e p2.x?", "o": ["[1] — lista e atribut de clasă, partajată de toate instanțele", "[]", "Eroare"], "a": 0, "h": "Atribut de clasă mutabil.", "e": "Pentru stare per instanță, creezi lista în __init__: self.x = [].", "px": ["Atributul de clasă e un singur obiect, comun tuturor instanțelor (ca un afiș pe perete). `self.x` în `__init__` creează unul separat pentru fiecare.", "Listele și dicționarele nu se pun ca atribute de clasă dacă vrei date separate.", "Încearcă: rulează și compară `p2.x` cu `q2.x`."], "tr": {"l": "python", "c": "class P:\n    x = []            # atribut de clasa: partajat\n\np1, p2 = P(), P()\np1.x.append(1)\nprint(p2.x)           # [1]\n\nclass Q:\n    def __init__(self):\n        self.x = []   # atribut de instanta\nq1, q2 = Q(), Q()\nq1.x.append(1)\nprint(q2.x)           # []\n"}}, {"id": "zy45", "d": "py", "nou": 1, "t": "mc", "q": "class Q: n = 0; def __init__(self): self.n = 5. q = Q(). Ce dau (q.n, Q.n)?", "o": ["(5, 0) — atributul de instanță umbrește pe cel de clasă", "(5, 5)", "(0, 0)"], "a": 0, "h": "Ordinea de căutare a atributelor.", "e": "self.n = 5 creează atribut pe instanță; Q.n rămâne 0.", "px": ["Python caută întâi pe instanță, apoi pe clasă. `self.n = 5` creează un atribut NOU pe instanță, care ascunde pe cel din clasă.", "Dacă ștergi atributul instanței, se vede din nou cel al clasei.", "Încearcă: rulează și urmărește cele trei valori."], "tr": {"l": "python", "c": "class Q:\n    n = 0\n    def __init__(self):\n        self.n = 5\n\nq = Q()\nprint(q.n, Q.n)     # 5 0\ndel q.n\nprint(q.n)          # 0: acum vede atributul clasei\n"}}, {"id": "zy46", "d": "py", "nou": 1, "t": "mc", "q": "class V1: def hi(self): return 'V1'. class V2(V1): def hi(self): return 'V2+' + super().hi(). Ce dă V2().hi()?", "o": ["'V2+V1'", "'V2+'", "'V1'"], "a": 0, "h": "super() delegă la clasa următoare din MRO.", "e": "Metoda copilului poate extinde comportamentul părintelui.", "px": ["`super()` înseamnă „clasa următoare din lanț”. Copilul poate adăuga ceva peste comportamentul părintelui.", "Fără `super().hi()` metoda părintelui nu rulează.", "Încearcă: scoate `+ super().hi()` și vezi diferența."], "tr": {"l": "python", "c": "class V1:\n    def hi(self): return 'V1'\nclass V2(V1):\n    def hi(self): return 'V2+' + super().hi()\n\nprint(V2().hi())     # V2+V1\n"}}, {"id": "zy47", "d": "py", "nou": 1, "t": "mc", "q": "M2 și M3 moștenesc din M1 și toate au hi(); M4(M2, M3) nu definește hi(). Ce dă M4().hi()?", "o": ["Cel din M2 (MRO: M4, M2, M3, M1, object)", "Cel din M3", "Cel din M1"], "a": 0, "h": "Ordinea claselor părinte contează.", "e": "M4.__mro__ afișează ordinea de căutare (C3 linearization).", "px": ["MRO: M4 caută în M2, apoi M3, apoi M1 (părintele comun vine ultimul). M2 are `hi`, deci se oprește acolo.", "Ordinea în care scrii părinții contează: `class M4(M3, M2)` ar da `M3`.", "Încearcă: inversează părinții."], "tr": {"l": "python", "c": "class M1:\n    def hi(self): return 'M1'\nclass M2(M1):\n    def hi(self): return 'M2'\nclass M3(M1):\n    def hi(self): return 'M3'\nclass M4(M2, M3): pass\n\nprint(M4().hi())\nprint([c.__name__ for c in M4.__mro__])\n"}}, {"id": "zy48", "d": "py", "nou": 1, "t": "mc", "q": "gg = (x for x in range(2)); (list(gg), list(gg)). Ce dă?", "o": ["([0, 1], []) — generatorul se consumă o singură dată", "([0, 1], [0, 1])", "Eroare"], "a": 0, "h": "Iterator epuizat.", "e": "Pentru reutilizare folosești o listă sau reconstruiești generatorul.", "px": ["Generatorul e ca un pachet de cărți pe care îl împarți o singură dată: după ce ai dat toate cărțile, rămâne gol.", "Dacă ai nevoie din nou, creezi alt generator sau folosești o listă.", "Încearcă: apelează `list(gg)` a treia oară."], "tr": {"l": "python", "c": "gg = (x for x in range(2))\nprint(list(gg))    # [0, 1]\nprint(list(gg))    # []  (epuizat)\n\ndef gen():\n    yield from range(2)\ng = gen()\nprint(list(g), list(g))\n"}}, {"id": "zy49", "d": "py", "nou": 1, "t": "mc", "q": "Ce dau '10' < '9' și 10 < 9?", "o": ["True și False (șirurile se compară caracter cu caracter)", "False și False", "True și True"], "a": 0, "h": "'1' vine înaintea lui '9'.", "e": "Pentru sortare numerică convertești în int sau folosești key=int.", "px": ["Șirurile se compară literă cu literă: `'1'` vine înaintea lui `'9'`. Numerele se compară ca valori.", "Pentru sortare numerică de șiruri folosești `key=int`.", "Încearcă: sortează liste de șiruri cu și fără `key=int`."], "tr": {"l": "python", "c": "print('10' < '9')            # True: compara caracter cu caracter\nprint(10 < 9)                # False\nprint(sorted(['10', '9', '2']))\nprint(sorted(['10', '9', '2'], key=int))\n"}}, {"id": "zy50", "d": "py", "nou": 1, "t": "mc", "q": "print(f\"{3.14159:.2f}|{42:05d}|{1234567:,}\") afișează...", "o": ["3.14|00042|1,234,567", "3.14|42|1234567", "3.1|00042|1.234.567"], "a": 0, "h": "Specificatori de format.", "e": ".2f = două zecimale, 05d = 5 cifre cu zerouri în față, , = separator de mii.", "px": ["După `:` scrii formatul: `.2f` = două zecimale, `05d` = 5 cifre cu zerouri în față, `,` = separator de mii.", "`>` aliniază la dreapta, `<` la stânga, `^` la centru.", "Încearcă: schimbă numerele și formatele."], "tr": {"l": "python", "c": "print(f\"{3.14159:.2f}|{42:05d}|{1234567:,}\")\nprint(f\"{'a':>5}|{'b':<5}|{'c':^5}|\")\nprint(f\"{0.256:.1%}\")\n"}}, {"id": "zy51", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă isinstance(True, int)?", "o": ["True — bool e subclasă a lui int", "False", "Eroare"], "a": 0, "h": "True == 1.", "e": "De aceea sum([True, True, False]) dă 2.", "px": ["În Python `True` este `1` și `False` este `0`, pentru că `bool` moștenește din `int`.", "De aceea poți număra condițiile adevărate cu `sum`.", "Încearcă: `sum(x > 2 for x in [1, 3, 5])`."], "tr": {"l": "python", "c": "print(isinstance(True, int))   # True: bool e subclasa a lui int\nprint(True + True)            # 2\nprint(sum([True, True, False]))\nprint(type(True).__name__)\n"}}, {"id": "zy52", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă json.dumps({'a': (1, 2), 'b': None})?", "o": ["'{\"a\": [1, 2], \"b\": null}' — tuplul devine listă, None devine null", "'{\"a\": (1, 2), \"b\": None}'", "Eroare, tuplul nu e serializabil"], "a": 0, "h": "JSON are doar liste, nu tupluri.", "e": "json.loads('[1,\"2\",true]') redă [1, '2', True].", "px": ["JSON nu cunoaște tupluri, `None` sau `True`. La scriere devin liste, `null`, `true`; la citire revin ca liste, `None`, `True`.", "Deci un tuplu trimis prin JSON se întoarce ca listă.", "Încearcă: rulează și compară ce intră cu ce iese."], "tr": {"l": "python", "c": "import json\ns = json.dumps({'a': (1, 2), 'b': None, 'c': True})\nprint(s)                  # tuplul devine lista, None -> null, True -> true\nprint(json.loads(s))\nprint(json.loads('[1, \"2\", true]'))\n"}}, {"id": "zy53", "d": "py", "nou": 1, "t": "mc", "q": "re.findall(r'<.+>', '<a><b>') versus re.findall(r'<.+?>', '<a><b>')", "o": ["['<a><b>'] și ['<a>', '<b>'] (greedy vs lazy)", "['<a>', '<b>'] în ambele", "['<a><b>'] în ambele"], "a": 0, "h": "? după cuantificator.", "e": "Cuantificatorul greedy ia cât mai mult, cel lazy (+?) cât mai puțin.", "px": ["Un cuantificator „lacom” (`+`) ia cât mai mult posibil. Cu `?` după el devine „leneș” și se oprește la prima potrivire.", "Pentru taguri HTML, de obicei vrei varianta leneșă.", "Încearcă: schimbă textul și vezi diferența."], "tr": {"l": "python", "c": "import re\ntext = '<a><b>'\nprint(re.findall(r'<.+>', text))     # greedy: ia cat mai mult\nprint(re.findall(r'<.+?>', text))    # lazy: ia cat mai putin\n"}}, {"id": "zy54", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă re.match(r'b', 'abc') față de re.search(r'b', 'abc')?", "o": ["match: None (potrivire doar la început); search: obiect Match", "Ambele găsesc 'b'", "Ambele dau None"], "a": 0, "h": "Ancorarea la începutul șirului.", "e": "re.fullmatch cere potrivirea întregului șir.", "px": ["`match` verifică doar începutul șirului, `search` caută oriunde, `fullmatch` cere să se potrivească tot șirul.", "Greșeala frecventă: folosești `match` și te miri că nu găsește.", "Încearcă: rulează cele trei apeluri."], "tr": {"l": "python", "c": "import re\nprint(re.match(r'b', 'abc'))      # None: match cauta doar la inceput\nprint(re.search(r'b', 'abc'))     # gaseste b oriunde\nprint(re.fullmatch(r'abc', 'abc'))\n"}}, {"id": "zy55", "d": "py", "nou": 1, "t": "mc", "q": "def tf(): try: return 'try' finally: print('fin'). Ce se afișează și ce întoarce tf()?", "o": ["Afișează fin, apoi întoarce 'try' (finally rulează înainte de return)", "Doar 'try'", "Afișează fin și întoarce None"], "a": 0, "h": "finally rulează mereu.", "e": "Dacă finally ar avea propriul return, acela ar înlocui valoarea.", "px": ["`finally` rulează MEREU înainte ca funcția să iasă, chiar dacă ai deja `return`.", "Dacă și `finally` are `return`, acela câștigă (de obicei e o greșeală).", "Încearcă: rulează și urmărește ordinea."], "tr": {"l": "python", "c": "def tf():\n    try:\n        return 'try'\n    finally:\n        print('fin')\n\nprint(tf())\n\ndef tf2():\n    try:\n        return 'try'\n    finally:\n        return 'finally'     # finally poate suprascrie return-ul!\n\nprint(tf2())\n"}}, {"id": "zy56", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă 3 > 2 > 2?", "o": ["False — se evaluează ca (3 > 2) and (2 > 2)", "True", "Eroare"], "a": 0, "h": "Comparațiile înlănțuite.", "e": "1 < 2 < 3 e True. Nu e (3 > 2) > 2, adică True > 2.", "px": ["Python înțelege `a < b < c` ca `(a < b) and (b < c)`, ca la matematică.", "De aceea `3 > 2 > 2` e `True and False`.", "Încearcă: scrie `0 < x < 10` cu mai multe valori."], "tr": {"l": "python", "c": "print(1 < 2 < 3)       # True\nprint(3 > 2 > 2)       # False: (3 > 2) and (2 > 2)\nx = 5\nprint(1 < x < 10)      # interval\n"}}, {"id": "zy57", "d": "py", "nou": 1, "t": "mc", "q": "a = [0, [1]]; copy.copy(a)[1] is a[1] și copy.deepcopy(a)[1] is a[1]. Ce dau?", "o": ["True și False", "False și False", "True și True"], "a": 0, "h": "Superficial vs profund.", "e": "copy.copy păstrează aceleași obiecte interne; deepcopy le duplică.", "px": ["Copia superficială păstrează aceleași obiecte interioare. Cea profundă le duplică.", "`is` verifică dacă e exact același obiect.", "Încearcă: modifică `a[1]` și vezi ce copie se schimbă."], "tr": {"l": "python", "c": "import copy\na = [0, [1]]\nprint(copy.copy(a)[1] is a[1])       # True\nprint(copy.deepcopy(a)[1] is a[1])   # False\n"}}, {"id": "zy58", "d": "py", "nou": 1, "t": "mc", "q": "sorted(['b', 'C', 'a']) versus sorted(['b', 'C', 'a'], key=str.lower)", "o": ["['C', 'a', 'b'] și ['a', 'b', 'C']", "['a', 'b', 'C'] în ambele", "['C', 'a', 'b'] în ambele"], "a": 0, "h": "Majusculele sunt înaintea minusculelor în ordinea Unicode.", "e": "key=str.lower sortează fără să țină cont de majuscule.", "px": ["Python compară codurile caracterelor: majusculele (`'C'`) vin înaintea minusculelor (`'a'`).", "Cu `key=str.lower` sortezi fără să ții cont de majuscule.", "Încearcă: sortează după lungime cu `key=len`."], "tr": {"l": "python", "c": "print(sorted(['b', 'C', 'a']))\nprint(sorted(['b', 'C', 'a'], key=str.lower))\nprint(sorted(['bb', 'a', 'ccc'], key=len, reverse=True))\n"}}, {"id": "zy59", "d": "py", "nou": 1, "t": "mc", "q": "type(1/2).__name__ și type(4/2).__name__ în Python 3?", "o": ["float și float (/ întoarce mereu float; // întoarce int pentru operanzi int)", "float și int", "int și int"], "a": 0, "h": "4/2 e 2.0.", "e": "Pentru împărțire întreagă folosești //.", "px": ["În Python 3, `/` dă mereu float (chiar `4/2 = 2.0`). Pentru împărțire întreagă folosești `//`.", "Atenție la `//` cu float: `7.0 // 2 = 3.0`.", "Încearcă: rulează și vezi tipurile."], "tr": {"l": "python", "c": "print(1 / 2, type(1 / 2).__name__)\nprint(4 / 2, type(4 / 2).__name__)    # 2.0 float\nprint(4 // 2, type(4 // 2).__name__)  # 2 int\n"}}, {"id": "zy60", "d": "py", "nou": 1, "t": "mc", "q": "a = (1); b = (1,). Ce tipuri au?", "o": ["a e int, b e tuplu (virgula face tuplul)", "Ambele sunt tupluri", "a e tuplu, b e int"], "a": 0, "h": "Parantezele singure nu creează tupluri.", "e": "La fel, () e tuplul gol.", "px": ["Parantezele singure nu fac tuplu: `(1)` e doar numărul 1 între paranteze. Virgula face tuplul: `(1,)`.", "Tuplul gol e `()`.", "Încearcă: `type((1, 2))`."], "tr": {"l": "python", "c": "a = (1)\nb = (1,)\nprint(type(a).__name__, type(b).__name__)\nprint(type(()).__name__)\n"}}, {"id": "zy61", "d": "py", "nou": 1, "t": "mc", "q": "Ce afișează list(range(10, 0, -3)) și len(range(2, 10, 3))?", "o": ["[10, 7, 4, 1] și 3", "[10, 7, 4] și 2", "[10, 7, 4, 1] și 4"], "a": 0, "h": "Stop-ul e exclus.", "e": "range(2, 10, 3) dă 2, 5, 8 (3 elemente).", "px": ["`range(start, stop, pas)`: stop nu se include. Cu pas negativ numeri în jos.", "Eroarea clasică: `range(5)` dă 0..4, nu 1..5.", "Încearcă: `list(range(1, 6))`."], "tr": {"l": "python", "c": "print(list(range(10, 0, -3)))\nprint(len(range(2, 10, 3)), list(range(2, 10, 3)))\nprint(list(range(0)))\n"}}, {"id": "zy62", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă list(filter(None, [0, 1, '', 2]))?", "o": ["[1, 2] (elementele fals sunt eliminate)", "[0, '']", "[0, 1, '', 2]"], "a": 0, "h": "None ca funcție = verificarea valorii de adevăr.", "e": "Valori fals: 0, '', [], {}, None, 0.0.", "px": ["`filter(None, ...)` păstrează doar elementele care sunt „adevărate”. Sunt „false”: `0`, `''`, `[]`, `{}`, `None`, `0.0`.", "Atenție: și `0` e eliminat, chiar dacă e un număr valid.", "Încearcă: adaugă `'0'` (șir) și vezi că rămâne."], "tr": {"l": "python", "c": "print(list(filter(None, [0, 1, '', 2, [], 'a'])))\nprint(bool(0), bool(''), bool([]), bool(None), bool(0.0))\n"}}, {"id": "zy63", "d": "py", "nou": 1, "t": "mc", "q": "Care e diferența dintre str.find și str.index la un substring absent?", "o": ["find întoarce -1; index aruncă ValueError", "Ambele întorc -1", "Ambele aruncă ValueError"], "a": 0, "h": "Un tratează lipsa prin valoare, altul prin excepție.", "e": "'abc'.find('z') → -1; 'abc'.index('z') → ValueError.", "px": ["`find` raportează lipsa printr-o valoare (`-1`), `index` printr-o eroare.", "Atenție: `if s.find('x'):` e greșit pentru că `-1` e adevărat și `0` e fals.", "Încearcă: rulează și vezi ambele."], "tr": {"l": "python", "c": "print('abc'.find('z'))       # -1\ntry:\n    print('abc'.index('z'))\nexcept ValueError as e:\n    print(\"ValueError:\", e)\nprint('ab'.index('b'))\n"}}, {"id": "zy64", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă 'a-b-c'.replace('-', '', 1)?", "o": ["'ab-c' (înlocuiește doar prima apariție)", "'abc'", "'a-b-c'"], "a": 0, "h": "Al treilea argument = numărul maxim de înlocuiri.", "e": "Fără al treilea argument înlocuiește toate aparițiile.", "px": ["Al treilea argument al lui `replace` limitează numărul de înlocuiri.", "`replace` nu modifică șirul original (șirurile sunt imutabile), ci întoarce unul nou.", "Încearcă: `s.replace('-', '+', 2)`."], "tr": {"l": "python", "c": "s = 'a-b-c'\nprint(s.replace('-', ''))       # toate\nprint(s.replace('-', '', 1))    # doar prima\n"}}, {"id": "zy65", "d": "py", "nou": 1, "t": "mc", "q": "Ce dă {'a': None}.get('a', 5)?", "o": ["None — cheia există; valoarea implicită se folosește doar când lipsește cheia", "5", "KeyError"], "a": 0, "h": "get verifică cheia, nu valoarea.", "e": "Pentru a trata și None: d.get('a') or 5, cu atenție la 0 și ''.", "px": ["`get(cheie, implicit)` folosește valoarea implicită DOAR când cheia lipsește. Dacă e acolo cu valoarea `None`, primești `None`.", "Dacă vrei să tratezi și `None`, folosești `or`, dar atenție la `0` și `''`.", "Încearcă: rulează și compară cele trei apeluri."], "tr": {"l": "python", "c": "d = {'a': None}\nprint(d.get('a', 5))     # None: cheia exista\nprint(d.get('x', 5))     # 5: cheia lipseste\nprint(d.get('a') or 5)   # 5: trateaza si None\n"}}, {"id": "xr1", "d": "react", "nou": 1, "t": "mc", "q": "useEffect(() => { ... }) fără array de dependențe. Când rulează efectul?", "o": ["După fiecare randare (commit)", "Doar la montare", "Doar la demontare"], "a": 0, "h": "Lipsa array-ului înseamnă „mereu”.", "e": "Fără array rulează după fiecare randare. Cu [] rulează o dată după montare, iar cu [a, b] când a sau b se schimbă (comparație cu Object.is).", "px": ["Efectul e o „temă de după randare”. Fără array o faci după FIECARE randare, cu `[]` doar prima dată, cu `[a]` când se schimbă `a`.", "Încearcă: apasă butonul `b`. Apar doar liniile fără array, nu și cele cu `[a]`. Apoi apasă `a` și vezi că rulează și cea cu `[a]`."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [a, setA] = useState(0);\n  const [b, setB] = useState(0);\n  const [log, setLog] = useState([]);\n  const nota = (t) => setLog((l) => [...l, t]);\n\n  useEffect(() => { nota(\"fara array: rulez dupa fiecare randare\"); });\n  useEffect(() => { nota(\"[]: rulez doar la montare\"); }, []);\n  useEffect(() => { nota(\"[a]: rulez cand se schimba a\"); }, [a]);\n\n  return (\n    <div>\n      <button onClick={() => setA(a + 1)}>a = {a}</button>{\" \"}\n      <button onClick={() => setB(b + 1)}>b = {b}</button>\n      <ul>{log.map((t, i) => <li key={i}>{t}</li>)}</ul>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr2", "d": "react", "nou": 1, "t": "mc", "q": "Când rulează funcția de cleanup returnată de un useEffect?", "o": ["Înainte ca efectul să ruleze din nou (dacă dependențele s-au schimbat) și la demontare", "Doar la prima randare", "Niciodată automat, o apelezi tu"], "a": 0, "h": "Anulează ce a făcut setup-ul.", "e": "Cleanup-ul oglindește setup-ul: oprește abonamente, intervale, conexiuni.", "px": ["Cleanup-ul e „strânsul după tine”: oprești intervalul, abonamentul sau conexiunea pe care efectul le-a pornit.", "Încearcă: apasă „Ascunde” și deschide consola: apare mesajul de cleanup. Fără cleanup, intervalul ar rula mai departe, ascuns."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction Ceas() {\n  const [n, setN] = useState(0);\n  useEffect(() => {\n    const id = setInterval(() => setN((x) => x + 1), 1000);\n    return () => { clearInterval(id); console.log(\"cleanup: opresc intervalul\"); };\n  }, []);\n  return <p>Secunde: {n}</p>;\n}\n\nfunction App() {\n  const [arata, setArata] = useState(true);\n  return (\n    <div>\n      <button onClick={() => setArata(!arata)}>{arata ? \"Ascunde\" : \"Arata\"} ceasul</button>\n      {arata && <Ceas />}\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr3", "d": "react", "nou": 1, "t": "mc", "q": "De ce în dezvoltare (Strict Mode) vezi efectul rulând de două ori (setup → cleanup → setup)?", "o": ["React testează dacă cleanup-ul tău e complet; apare doar în dezvoltare", "E un bug al React", "Se întâmplă și în producție"], "a": 0, "h": "Un test intenționat.", "e": "Dacă dublarea cauzează probleme, cleanup-ul e incomplet (de exemplu o conexiune care nu se închide).", "px": ["În dezvoltare, `StrictMode` rulează efectul de două ori (setup, cleanup, setup) ca să verifice că ai scris corect cleanup-ul. În producție nu se întâmplă.", "Încearcă: rulează, deschide consola și numără mesajele. Apoi scoate `StrictMode` și compară."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nimport { StrictMode } from \"react\";\n\nfunction App() {\n  useEffect(() => {\n    console.log(\"setup\");\n    return () => console.log(\"cleanup\");\n  }, []);\n  return <p>Deschide consola: vezi setup, cleanup, setup</p>;\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<StrictMode><App /></StrictMode>);\n"}}, {"id": "xr4", "d": "react", "nou": 1, "t": "mc", "q": "Cum eviți ca un răspuns întârziat dintr-un fetch dintr-un useEffect să suprascrie date mai noi (race condition)?", "o": ["Un flag ignore pus pe true în cleanup, verificat înainte de setData", "Pui fetch într-un setTimeout", "Elimini array-ul de dependențe"], "a": 0, "h": "Cleanup marchează cererea veche ca ignorată.", "e": "Documentația: let ignore = false; ... if (!ignore) setData(result); return () => { ignore = true; }.", "px": ["Cererea A pleacă, apoi utilizatorul schimbă filtrul și pleacă cererea B. Dacă A se termină ultima, vechiul răspuns îl suprascrie pe cel nou.", "Soluție din documentație: în efect `let ignore = false;`, în `.then` verifici `if (!ignore)`, iar în cleanup pui `ignore = true`. Când se reia efectul, răspunsul vechi e ignorat."]}, {"id": "xr5", "d": "react", "nou": 1, "t": "mc", "q": "Ai const [n, setN] = useState(0) și un handler cu setN(n + 1); setN(n + 1); setN(n + 1). Cât e n după randare?", "o": ["1", "3", "0"], "a": 0, "h": "State-ul e un snapshot al randării curente.", "e": "n rămâne 0 în tot handlerul, deci toate cele trei apeluri pun 1. Cu setN(x => x + 1) de trei ori ar fi 3.", "px": ["În tot handlerul, `n` e o poză făcută la începutul randării: rămâne 0. Cele trei `setN(n + 1)` spun toate „pune 1”, deci rezultatul e 1.", "Cu `x => x + 1` îi dai o rețetă („ia valoarea curentă și adaugă 1”), iar React o aplică pe rând: 3.", "Încearcă: apasă fiecare buton de la 0 și compară rezultatele."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [n, setN] = useState(0);\n  return (\n    <div>\n      <p>n = {n}</p>\n      <button onClick={() => { setN(n + 1); setN(n + 1); setN(n + 1); }}>+1 de 3 ori (n + 1)</button>{\" \"}\n      <button onClick={() => { setN((x) => x + 1); setN((x) => x + 1); setN((x) => x + 1); }}>+1 de 3 ori (x =&gt; x + 1)</button>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr6", "d": "react", "nou": 1, "t": "mc", "q": "Când folosești forma setN(n => n + 1) în loc de setN(n + 1)?", "o": ["Când noua valoare depinde de cea anterioară și faci mai multe actualizări în același eveniment", "Doar la obiecte", "Niciodată, e depreciată"], "a": 0, "h": "Coada de actualizări.", "e": "Funcția updater primește valoarea cea mai recentă din coadă.", "px": ["În tot handlerul, `n` e o poză făcută la începutul randării: rămâne 0. Cele trei `setN(n + 1)` spun toate „pune 1”, deci rezultatul e 1.", "Cu `x => x + 1` îi dai o rețetă („ia valoarea curentă și adaugă 1”), iar React o aplică pe rând: 3.", "Încearcă: apasă fiecare buton de la 0 și compară rezultatele."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [n, setN] = useState(0);\n  return (\n    <div>\n      <p>n = {n}</p>\n      <button onClick={() => { setN(n + 1); setN(n + 1); setN(n + 1); }}>+1 de 3 ori (n + 1)</button>{\" \"}\n      <button onClick={() => { setN((x) => x + 1); setN((x) => x + 1); setN((x) => x + 1); }}>+1 de 3 ori (x =&gt; x + 1)</button>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr7", "d": "react", "nou": 1, "t": "mc", "q": "Ce probleme apar când folosești indexul ca key într-o listă care se reordonează sau în care ștergi elemente?", "o": ["Componentele își pierd identitatea și starea (ex. un input) se asociază elementului greșit", "Niciuna, indexul e cea mai bună cheie", "React aruncă eroare"], "a": 0, "h": "Cheia trebuie să identifice datele, nu poziția.", "e": "Folosești id-uri stabile din date. Nu genera chei cu Math.random() în randare: se recreează toate elementele la fiecare randare.", "px": ["Cheia (`key`) e „buletinul” fiecărui element. Dacă pui indexul, când ștergi primul rând, al doilea preia indexul 0 și React crede că e același element, deci păstrează textul scris în el.", "Încearcă: scrie ceva în dreptul lui „Ana” în ambele liste, apoi apasă „Șterge primul”. În lista cu index, textul scris rămâne la persoana greșită; în cea cu `key=nume`, dispare odată cu Ana."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [liste, setListe] = useState([\"Ana\", \"Bob\", \"Cris\"]);\n  return (\n    <div>\n      <button onClick={() => setListe(liste.slice(1))}>Sterge primul</button>\n      <h4>key = index (gresit)</h4>\n      {liste.map((nume, i) => <div key={i}>{nume}: <input defaultValue=\"\" placeholder=\"scrie aici\" /></div>)}\n      <h4>key = nume (corect)</h4>\n      {liste.map((nume) => <div key={nume}>{nume}: <input defaultValue=\"\" placeholder=\"scrie aici\" /></div>)}\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr8", "d": "react", "nou": 1, "t": "mc", "q": "Care sunt regulile cheilor (key) la liste?", "o": ["Unice între frați și stabile între randări", "Unice în toată aplicația și generate la fiecare randare", "Trebuie să fie numere"], "a": 0, "h": "Unicitate locală + stabilitate.", "e": "Același key poate apărea în liste diferite, dar nu între elementele aceleiași liste.", "px": ["`key` îi spune lui React „cine e cine” într-o listă. Trebuie să fie unic între frați și stabil între randări (id din date, nu `Math.random()`).", "Cu indexul din array ca key, la inserare sau reordonare React poate lipi starea unui element pe altul."]}, {"id": "xr9", "d": "react", "nou": 1, "t": "mc", "q": "Ce garantează useMemo?", "o": ["Nimic semantic: e o optimizare care poate fi aruncată de React; recalculează când se schimbă dependențele (Object.is)", "Că funcția nu rulează niciodată de două ori", "Că valoarea rămâne pentru totdeauna"], "a": 0, "h": "Optimizare, nu garanție.", "e": "În Strict Mode în dezvoltare, funcția de calcul e apelată de două ori ca să detecteze impuritatea.", "px": ["`useMemo` reține rezultatul unui calcul între randări și îl recalculează doar când se schimbă dependențele. E o optimizare: codul trebuie să fie corect și fără ea, iar React poate arunca valoarea memorată."]}, {"id": "xr10", "d": "react", "nou": 1, "t": "mc", "q": "Ce face ref.current = valoare (useRef) față de setState?", "o": ["Nu declanșează re-randare; ref e mutabil și păstrat între randări", "Declanșează re-randare", "Resetează componenta"], "a": 0, "h": "Ref = valoare care nu contează la afișare.", "e": "Nu citi și nu scrie ref.current în timpul randării: o faci în event handlere sau în efecte.", "px": ["`ref` e o cutie în care păstrezi ceva între randări, fără să cheme React să redeseneze. `state` redesenează.", "Încearcă: apasă de câteva ori butonul „ref + 1”: pe ecran nu se schimbă nimic, dar consola arată valoarea. Apoi apasă „stare + 1” și vezi că ecranul „recuperează” valoarea ref."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [stare, setStare] = useState(0);\n  const ref = useRef(0);\n  return (\n    <div>\n      <p>stare = {stare}</p>\n      <p>ref.current = {ref.current} (se actualizeaza la urmatoarea randare)</p>\n      <button onClick={() => { ref.current += 1; console.log(\"ref:\", ref.current); }}>ref + 1 (fara re-randare)</button>{\" \"}\n      <button onClick={() => setStare(stare + 1)}>stare + 1 (cu re-randare)</button>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr11", "d": "react", "nou": 1, "t": "mc", "q": "Cum actualizezi corect un obiect din state: person = { name: 'Ana', city: 'Cluj' } ca să schimbi doar city?", "o": ["setPerson({ ...person, city: 'Iași' })", "person.city = 'Iași'", "setPerson(person.city = 'Iași')"], "a": 0, "h": "Nu muta starea; înlocuiește obiectul.", "e": "Spread e superficial: pentru obiecte imbricate copiezi fiecare nivel. Mutația locală a unui obiect proaspăt creat e permisă.", "px": ["`setPerson` primește obiectul nou și React îl compară cu cel vechi după referință. Dacă îi dai același obiect modificat pe loc, crede că nu s-a schimbat nimic.", "`{ ...person, city: 'Iași' }` face o copie cu orașul schimbat.", "Încearcă: apasă butonul „greșit” (nu se schimbă pe ecran), apoi pe cel „corect” (se schimbă)."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [person, setPerson] = useState({ name: \"Ana\", city: \"Cluj\" });\n  return (\n    <div>\n      <pre>{JSON.stringify(person)}</pre>\n      <button onClick={() => setPerson({ ...person, city: \"Iasi\" })}>Schimba orasul (corect)</button>{\" \"}\n      <button onClick={() => { person.city = \"Brasov\"; setPerson(person); }}>Muta direct (gresit)</button>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr12", "d": "react", "nou": 1, "t": "mc", "q": "Cum adaugi un element la un array din state fără să muți array-ul?", "o": ["setItems([...items, nou]) (sau concat)", "items.push(nou) apoi setItems(items)", "items[items.length] = nou"], "a": 0, "h": "Array nou, nu același.", "e": "Cu același array, React vede aceeași referință și poate sări peste re-randare.", "px": ["Gândește-te la un dosar. `push` bagă o foaie nouă în ACELAȘI dosar: React se uită doar la copertă și crede că nu s-a schimbat nimic.", "`[...items, x]` face un dosar NOU, cu foile copiate și una adăugată; React vede dosarul nou și redesenează.", "Încearcă: apasă întâi „push” de câteva ori (nu apare nimic), apoi apasă butonul corect: apar dintr-odată și cele de dinainte."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [items, setItems] = useState([\"mere\"]);\n  return (\n    <div>\n      <button onClick={() => { items.push(\"pere\"); setItems(items); }}>push (gresit)</button>{\" \"}\n      <button onClick={() => setItems([...items, \"gutui\"])}>[...items, nou] (corect)</button>\n      <ul>{items.map((x, i) => <li key={i}>{x}</li>)}</ul>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr13", "d": "react", "nou": 1, "t": "mc", "q": "De ce nu poți apela un Hook (useState) într-un if sau într-o buclă?", "o": ["React se bazează pe ordinea identică a apelurilor Hook la fiecare randare", "Pentru că e mai lent", "Pentru că JavaScript nu permite"], "a": 0, "h": "Ordinea apelurilor identifică starea.", "e": "Hook-urile se apelează doar la nivelul superior al componentelor sau al hook-urilor custom.", "px": ["React nu știe numele variabilelor tale de stare, ci doar ordinea: „primul Hook, al doilea Hook...”. Dacă un `if` face ca ordinea să se schimbe între randări, valorile se amestecă. Hook-urile se apelează mereu la nivelul de sus al componentei."]}, {"id": "xr14", "d": "react", "nou": 1, "t": "mc", "q": "Ce problemă rezolvă Context?", "o": ["Prop drilling: transmiți date adânc în arbore fără să le pasezi prin fiecare nivel", "Rutarea", "Memorarea calculelor"], "a": 0, "h": "Temă, utilizator curent.", "e": "Înainte de context, ia în calcul transmiterea prin props sau JSX ca children.", "px": ["Contextul e ca un panou de afișaj în clădire: oricine, la orice etaj, poate citi ce scrie pe el, fără să i-l pasezi din mână în mână prin toate camerele.", "`Mijloc` nu primește nicio proprietate, dar `Buton` din interiorul lui tot citește tema.", "Încearcă: apasă „Schimbă tema” și vezi că ambele butoane se schimbă."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nconst Tema = createContext(\"light\");\n\nfunction Buton() {\n  const tema = useContext(Tema);\n  return <button style={{ background: tema === \"dark\" ? \"#222\" : \"#eee\", color: tema === \"dark\" ? \"#fff\" : \"#000\" }}>Tema: {tema}</button>;\n}\nfunction Mijloc() { return <div><Buton /></div>; }   // nu stie de tema\n\nfunction App() {\n  const [tema, setTema] = useState(\"light\");\n  return (\n    <Tema.Provider value={tema}>\n      <button onClick={() => setTema(tema === \"light\" ? \"dark\" : \"light\")}>Schimba tema</button>\n      <Mijloc />\n      <Buton />\n    </Tema.Provider>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr15", "d": "react", "nou": 1, "t": "mc", "q": "Ce primește useContext(Ctx) când componenta nu e într-un Provider?", "o": ["Valoarea implicită dată la createContext(defaultValue)", "undefined obligatoriu", "Eroare mereu"], "a": 0, "h": "createContext primește un argument.", "e": "Se folosește cel mai apropiat Provider din arbore; la schimbarea valorii, consumatorii se re-randează.", "px": ["Fără un `Provider` deasupra, componenta primește valoarea implicită din `createContext(...)`.", "Încearcă: rulează și vezi cele două rânduri."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nconst Tema = createContext(\"valoare implicita\");\n\nfunction Citeste() { return <p>Valoare: {useContext(Tema)}</p>; }\n\nfunction App() {\n  return (\n    <div>\n      <Citeste />\n      <Tema.Provider value=\"din Provider\"><Citeste /></Tema.Provider>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr16", "d": "react", "nou": 1, "t": "mc", "q": "Ce schimbă React.memo(Componenta)?", "o": ["Sare peste re-randare dacă props-urile sunt egale (comparație superficială) cu cele anterioare", "Face componenta să ruleze o singură dată", "Elimină state-ul"], "a": 0, "h": "Doar props, comparate superficial.", "e": "Un obiect sau o funcție creată la fiecare randare e prop nou de fiecare dată; de aceea se folosesc useMemo/useCallback.", "px": ["`memo` spune: „dacă proprietățile sunt la fel ca data trecută, sar peste această componentă”.", "Încearcă: apasă butonul și deschide consola. „randare Copil” apare doar o dată. Scoate `memo` și vezi că apare la fiecare apăsare."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nconst Copil = memo(function Copil({ nume }) {\n  console.log(\"randare Copil:\", nume);\n  return <p>{nume}</p>;\n});\n\nfunction App() {\n  const [n, setN] = useState(0);\n  return (\n    <div>\n      <button onClick={() => setN(n + 1)}>Re-randeaza parintele ({n})</button>\n      <Copil nume=\"Ana\" />\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr17", "d": "react", "nou": 1, "t": "mc", "q": "Când e un efect (useEffect) alegerea greșită?", "o": ["Pentru a calcula date derivate pentru afișare sau pentru a răspunde la un click; acelea merg în randare sau în event handlere", "Pentru sincronizare cu un sistem extern", "Pentru abonamente"], "a": 0, "h": "Efectele sunt pentru sincronizarea cu exteriorul.", "e": "Documentația: nu folosi efecte pentru transformarea datelor la randare și nici pentru evenimente de utilizator.", "px": ["Efectul e pentru sincronizare cu lumea din afară (rețea, timer, DOM extern). Pentru ce poți calcula din props/state, calculezi direct în randare. Pentru un click, folosești handler-ul de eveniment."]}, {"id": "xr18", "d": "react", "nou": 1, "t": "mc", "q": "Un efect face setCount(count + 1) și are [count] în dependențe. Ce se întâmplă?", "o": ["Buclă infinită: efectul schimbă dependența de care depinde", "Rulează o singură dată", "Eroare de sintaxă"], "a": 0, "h": "Modifică ceea ce îl declanșează.", "e": "Spargi bucla schimbând logica sau dependențele (ex. updater funcțional sau mutarea logicii în handler).", "px": ["Efectul schimbă `count`, schimbarea îl declanșează din nou, iar el schimbă iar `count`... și tot așa, la infinit. Fix: `setCount(c => c + 1)` fără `count` în dependențe, sau regândești de ce ai nevoie de efect."]}, {"id": "xr19", "d": "react", "nou": 1, "t": "mc", "q": "Ce e o componentă controlată (controlled) la un <input>?", "o": ["Valoarea vine din state (value + onChange), React e sursa adevărului", "Input fără value", "Input cu defaultValue"], "a": 0, "h": "value și onChange.", "e": "La componenta necontrolată, DOM-ul ține valoarea și o citești cu un ref.", "px": ["Controlat înseamnă că React ține valoarea (în state) și câmpul doar o arată. La necontrolat, valoarea stă în câmpul din pagină.", "Încearcă: scrie în ambele câmpuri. Doar primul e reflectat în paragraful de dedesubt."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction App() {\n  const [text, setText] = useState(\"\");\n  return (\n    <div>\n      <input value={text} onChange={(e) => setText(e.target.value)} placeholder=\"controlat\" />\n      <p>React stie: \"{text}\"</p>\n      <input defaultValue=\"\" placeholder=\"necontrolat\" />\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr20", "d": "react", "nou": 1, "t": "mc", "q": "Cum se comportă useState(calculScump()) față de useState(() => calculScump())?", "o": ["Prima apelează calculScump la fiecare randare (rezultatul e ignorat după prima); a doua îl apelează doar la inițializare", "Sunt identice", "A doua dă eroare"], "a": 0, "h": "Inițializare leneșă.", "e": "Funcția de inițializare se rulează doar la prima randare.", "px": ["`useState(calculScump())` apelează funcția la fiecare randare (rezultatul se ignoră după prima). `useState(() => calculScump())` o apelează doar la început.", "Încearcă: apasă butonul de câteva ori și numără mesajele din consolă."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\nfunction calculScump() { console.log(\"calculScump apelat\"); return 42; }\n\nfunction App() {\n  const [a] = useState(calculScump());          // se apeleaza la fiecare randare\n  const [b] = useState(() => calculScump());    // doar la prima\n  const [n, setN] = useState(0);\n  return <button onClick={() => setN(n + 1)}>Randare nr. {n} (vezi consola)</button>;\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xr21", "d": "react", "nou": 1, "t": "mc", "q": "Care e diferența dintre props și state?", "o": ["Props vin de la părinte și sunt doar-citire; state e al componentei și îl modifică prin setter", "Sunt același lucru", "State vine de la părinte"], "a": 0, "h": "Cine le deține?", "e": "Modificarea unui state declanșează re-randarea componentei.", "px": ["Props sunt „argumentele” primite de la părinte; nu le modifici. State e memoria proprie a componentei; o schimbi doar prin setter, iar React o randează din nou."]}, {"id": "xr22", "d": "react", "nou": 1, "t": "mc", "q": "De ce JSX nu acceptă class ci className?", "o": ["class e cuvânt rezervat în JavaScript; JSX se compilează în JavaScript", "Pentru că React nu suportă CSS", "E o preferință de stil"], "a": 0, "h": "JSX e JavaScript.", "e": "La fel: htmlFor în loc de for.", "px": ["JSX arată ca HTML, dar se compilează în JavaScript, unde `class` e cuvânt rezervat (declară clase). De aceea atributul se numește `className`."]}, {"id": "xr23", "d": "react", "nou": 1, "t": "mc", "q": "Ce se întâmplă dacă pui {array.map(...)} fără key?", "o": ["React avertizează în consolă și poate asocia greșit elementele la modificări", "Eroare fatală", "Nu se afișează lista"], "a": 0, "h": "Avertisment, nu eroare.", "e": "Fiecare element returnat din map are nevoie de key pe elementul rădăcină.", "px": ["Fără `key`, React avertizează în consolă și se bazează pe poziție. La inserare sau reordonare poate asocia greșit elementele cu starea lor (ex. textul dintr-un input)."]}, {"id": "xr24", "d": "react", "nou": 1, "t": "mc", "q": "Ce e useCallback(fn, deps)?", "o": ["Memorează funcția între randări, ca să aibă aceeași referință cât timp dependențele nu se schimbă", "Apelează funcția asincron", "Ca useEffect, dar sincron"], "a": 0, "h": "Pentru funcții, nu valori.", "e": "Util când funcția e dependență de efect sau prop pentru o componentă cu memo.", "px": ["La fiecare randare, o funcție definită în componentă e una nouă. `useCallback` o păstrează aceeași cât timp dependențele nu se schimbă. Contează când o dai unei componente `memo` sau o folosești în dependențele unui efect."]}, {"id": "xr25", "d": "react", "nou": 1, "t": "mc", "q": "Ce înseamnă „lifting state up”?", "o": ["Muți state-ul în cel mai apropiat părinte comun, ca mai mulți copii să-l partajeze", "Muți state-ul în Redux", "Muți state-ul în localStorage"], "a": 0, "h": "Părinte comun.", "e": "Părintele ține state-ul și îl dă copiilor prin props, plus handlere pentru modificare.", "px": ["Ca la școală: Andrei și Maria sunt doi colegi de bancă (componentele copil), iar învățătoarea e părintele. Dacă fiecare ține creionul în ghiozdanul lui, nu se văd între ei. Învățătoarea pune creionul într-o cutie pe catedră, iar ei îl folosesc de acolo.", "Pasul 1, înainte: fiecare buton din secțiunea de sus are propriul `useState`. Apasă pe „Andrei”: se schimbă doar butonul lui, iar Maria rămâne pe „stins”. Nu partajează nimic.", "Pasul 2, după: `useState` a fost șters din copii și scris o singură dată în `Camera`, adică în părintele comun. Starea e acum într-un singur loc.", "Pasul 3, legătura: părintele trimite în jos valoarea (`aprins={aprins}`) și funcția de schimbare (`onApasa={setAprins}`). Copilul citește valoarea și cheamă funcția când apeși.", "Încearcă: apasă „Andrei” în secțiunea „După”. Se schimbă și „Maria” și titlul, pentru că toți citesc aceeași stare. Apoi apasă „Andrei” în secțiunea „Înainte” și compară."], "tr": {"l": "react", "c": "import { useState, useEffect, useRef, useMemo, useCallback, memo, createContext, useContext } from \"react\";\nimport { createRoot } from \"react-dom/client\";\n\n// PASUL 1 (ÎNAINTE, greșit): fiecare copil are state-ul lui, deci nu se văd între ei\nfunction ButonGresit({ nume }) {\n  const [aprins, setAprins] = useState(false);\n  return <button onClick={() => setAprins(!aprins)}>{nume} vede becul: {aprins ? \"aprins\" : \"stins\"}</button>;\n}\n\n// PASUL 2 (DUPĂ, corect): copiii nu mai au state, primesc totul de la părinte\nfunction ButonCorect({ nume, aprins, onApasa }) {\n  return <button onClick={() => onApasa(!aprins)}>{nume} vede becul: {aprins ? \"aprins\" : \"stins\"}</button>;\n}\n\nfunction Camera() {\n  const [aprins, setAprins] = useState(false);   // state-ul a fost „ridicat” aici\n  return (\n    <div>\n      <h3>Becul e {aprins ? \"aprins 💡\" : \"stins 🌑\"}</h3>\n      <ButonCorect nume=\"Andrei\" aprins={aprins} onApasa={setAprins} />{\" \"}\n      <ButonCorect nume=\"Maria\" aprins={aprins} onApasa={setAprins} />\n    </div>\n  );\n}\n\nfunction App() {\n  return (\n    <div>\n      <h2>Înainte (fără lifting state up)</h2>\n      <ButonGresit nume=\"Andrei\" /> <ButonGresit nume=\"Maria\" />\n      <h2>După (state ridicat în părinte)</h2>\n      <Camera />\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}, {"id": "xe1", "d": "en", "nou": 1, "t": "mc", "q": "Choose the correct sentence.", "o": ["I have worked here since 2022.", "I have worked here for 2022.", "I work here since 2022."], "a": 0, "h": "since + moment, for + durată.", "e": "Present perfect cu since (punct de început: since 2022) sau for (durată: for three years).", "px": ["Cu `since` spui punctul de start (2022, Monday), cu `for` durata (three years). Cu aceste două se folosește present perfect, nu prezentul: „I have worked here since 2022.”"]}, {"id": "xe2", "d": "en", "nou": 1, "t": "mc", "q": "“I ___ the bug yesterday.” Which form is correct?", "o": ["fixed", "have fixed", "fix"], "a": 0, "h": "Yesterday cere trecutul simplu.", "e": "Past simple pentru un moment încheiat în trecut. Present perfect nu se combină cu yesterday, last week, in 2020.", "px": ["`yesterday` cere trecutul simplu: „I fixed the bug yesterday.” Present perfect nu se combină cu un moment trecut precis (yesterday, last week)."]}, {"id": "xe3", "d": "en", "nou": 1, "t": "mc", "q": "“If I ___ more time, I would write more tests.”", "o": ["had", "have", "would have"], "a": 0, "h": "Conditional tip 2 (ireal în prezent).", "e": "If + past simple, would + infinitiv. În limbajul formal se poate spune și „If I were...” la persoana I/III singular.", "px": ["Conditionalul 2 (ipotetic, puțin probabil acum): `If + past simple, would + verb`. „If I had more time, I would write more tests.” Nu spui „If I would have”."]}, {"id": "xe4", "d": "en", "nou": 1, "t": "mc", "q": "Which sentence is correct?", "o": ["I am looking forward to working with you.", "I am looking forward to work with you.", "I look forward working with you."], "a": 0, "h": "to + verb cu -ing.", "e": "În looking forward to, „to” e preposiție, deci urmează -ing.", "px": ["După „look forward to” vine forma cu -ing, pentru că „to” e prepoziție, nu parte din infinitiv: „I am looking forward to working with you.”"]}, {"id": "xe5", "d": "en", "nou": 1, "t": "mc", "q": "“Actually” means:", "o": ["De fapt", "În prezent", "Actual"], "a": 0, "h": "False friend.", "e": "Actually = de fapt. Pentru „actual” spui current sau present; „în prezent” = currently.", "px": ["„Actually” = „de fapt”, nu „actual”. „Actual” în engleză = „real, efectiv”."]}, {"id": "xe6", "d": "en", "nou": 1, "t": "mc", "q": "“I’m not eventually sure.” What’s wrong?", "o": ["„Eventually” înseamnă „până la urmă”, nu „eventual”; corect: possibly / maybe", "Nimic", "Trebuie scris eventualy"], "a": 0, "h": "False friend.", "e": "Eventually = în cele din urmă. Eventual (în română) = possible, any.", "px": ["Falsul prieten: „eventually” = „până la urmă, în cele din urmă”. Pentru „eventual” în sensul românesc spui „possibly” sau „maybe”."]}, {"id": "xe7", "d": "en", "nou": 1, "t": "mc", "q": "“We need to ___ the meeting to Friday.”", "o": ["postpone", "delay from", "cancel again"], "a": 0, "h": "A muta mai târziu.", "e": "Postpone = a amâna (to + dată). Cancel = a anula; delay = a întârzia.", "px": ["„Postpone” = a amâna. „Postpone the meeting to Friday” = muți ședința pe vineri. Pentru a o muta mai devreme: „bring forward”."]}, {"id": "xe8", "d": "en", "nou": 1, "t": "mc", "q": "What does “ASAP” mean in a work email?", "o": ["As soon as possible — cât mai repede", "Always send a proposal", "At some agreed point"], "a": 0, "h": "Abreviere frecventă.", "e": "Alte abrevieri: FYI (for your information), EOD (end of day), ETA (estimated time of arrival), OOO (out of office).", "px": ["ASAP = „as soon as possible”. Se pronunță fie literă cu literă, fie „ei-sap”. Pare urgent: nu-l folosi la orice."]}, {"id": "xe9", "d": "en", "nou": 1, "t": "mc", "q": "“Could you please ___ me your report?”", "o": ["send", "say", "tell"], "a": 0, "h": "A trimite un document.", "e": "tell se folosește cu informații (tell me the time); send cu obiecte, documente, mesaje.", "px": ["„Send me” = „trimite-mi”. După „could you please” vine verbul la infinitiv fără „to”: „Could you please send me your report?”"]}, {"id": "xe10", "d": "en", "nou": 1, "t": "mc", "q": "Which is the polite way to ask someone to repeat?", "o": ["Sorry, could you say that again, please?", "What? Repeat!", "You didn’t say clear."], "a": 0, "h": "Politețea contează la interviu.", "e": "Variante: „Sorry, I didn’t catch that”, „Could you rephrase the question?”.", "px": ["Vrei să fii politicos: „Sorry, could you say that again, please?” Alte variante: „Pardon?”, „Could you repeat that?”"]}, {"id": "xe11", "d": "en", "nou": 1, "t": "mc", "q": "“I’m responsible ___ testing the new feature.”", "o": ["for", "of", "at"], "a": 0, "h": "Prepoziția după responsible.", "e": "responsible for + -ing sau substantiv; responsible to = răspunde în fața cuiva.", "px": ["„Responsible” se construiește cu prepoziția `for`: „responsible for testing”. Prepoziția face parte din expresie și se învață împreună cu adjectivul."]}, {"id": "xe12", "d": "en", "nou": 1, "t": "mc", "q": "“I’m good ___ finding bugs.”", "o": ["at", "in", "on"], "a": 0, "h": "Prepoziție după good.", "e": "good at + -ing; interested in; afraid of; depend on; proud of.", "px": ["„Good at” = priceput la ceva. „I’m good at finding bugs.” Alte expresii: „interested in”, „afraid of”, „proud of”."]}, {"id": "xe13", "d": "en", "nou": 1, "t": "mc", "q": "Which sentence is correct?", "o": ["The software is down; we are working on a fix.", "The software is under; we working on a fix.", "The software are down; we work on a fix."], "a": 0, "h": "Acord și timp verbal.", "e": "Software e nenumărabil: the software is. „We are working on” descrie ceva în desfășurare.", "px": ["„Software” e nenumărabil, deci „is”, nu „are”. „Down” = nefuncțional. Presupunem un incident: „The software is down; we are working on a fix.”"]}, {"id": "xe14", "d": "en", "nou": 1, "t": "mc", "q": "“There is a lot of ___ in this document.” Which word is correct?", "o": ["information", "informations", "an information"], "a": 0, "h": "Nenumărabil.", "e": "information, advice, feedback, equipment, software sunt nenumărabile: fără -s și fără a/an. Spui a piece of information.", "px": ["„Information” e nenumărabil: fără -s și fără „an”. Folosești „a piece of information” sau „some information”. La fel: advice, feedback, software, equipment."]}, {"id": "xe15", "d": "en", "nou": 1, "t": "mc", "q": "What is the best answer to “Tell me about yourself” in an interview?", "o": ["A short summary: current role, relevant experience, and why I’m interested in this job", "My whole life story from childhood", "I don’t know what to say."], "a": 0, "h": "Prezent, trecut relevant, viitor.", "e": "Un răspuns de 1-2 minute, structurat. Nu intra în detalii personale irelevante.", "px": ["Răspuns scurt, în 3 părți: rolul actual, experiența relevantă, de ce te interesează postul. Nu povestești toată viața."]}, {"id": "xe16", "d": "en", "nou": 1, "t": "mc", "q": "“What is your biggest weakness?” Which answer is the most professional?", "o": ["I sometimes spend too long on details, so I now set time limits for each task.", "I have no weaknesses.", "I hate working with people."], "a": 0, "h": "Recunoaște și arată ce faci pentru îmbunătățire.", "e": "Alege o slăbiciune reală, dar nu critică pentru rol, și arată ce ai făcut ca să o gestionezi.", "px": ["Un răspuns bun recunoaște o slăbiciune reală, dar arată ce faci ca s-o gestionezi. „Nu am slăbiciuni” sună nesincer."]}, {"id": "xe17", "d": "en", "nou": 1, "t": "mc", "q": "“Why should we hire you?” Choose the strongest answer.", "o": ["I have the skills you need and examples of results: for instance, I reduced failed tests by 30%.", "Because I need a job.", "Because I’m better than everyone."], "a": 0, "h": "Dovezi, nu afirmații.", "e": "Folosește un rezultat măsurabil din experiența ta (ai grijă să fie real).", "px": ["Răspunsul puternic leagă ce știi de nevoia firmei, cu un exemplu concret, de preferință cu cifre. Nu compari cu ceilalți și nu spui că ai nevoie de job."]}, {"id": "xe18", "d": "en", "nou": 1, "t": "mc", "q": "What does the STAR method stand for?", "o": ["Situation, Task, Action, Result", "Skills, Time, Attitude, Responsibility", "Start, Test, Approve, Release"], "a": 0, "h": "Structură pentru răspunsuri comportamentale.", "e": "La „Tell me about a time when...” povestești: situația, sarcina ta, ce ai făcut și rezultatul.", "px": ["STAR: Situation (contextul), Task (ce aveai de făcut), Action (ce ai făcut tu), Result (ce s-a întâmplat, cu cifre). Se folosește la întrebări de tip „Tell me about a time when...”."]}, {"id": "xe19", "d": "en", "nou": 1, "t": "mc", "q": "“A bug” in a bug report: which description is the clearest?", "o": ["Steps to reproduce, expected result, actual result", "It doesn’t work.", "The developer made a mistake."], "a": 0, "h": "Un raport bun e reproductibil.", "e": "Adaugă mediu (browser, versiune), capturi de ecran, severitate.", "px": ["Un bug report bun poate fi reprodus de altcineva: pașii, ce te așteptai (expected) și ce s-a întâmplat (actual). „Nu merge” nu ajută pe nimeni."]}, {"id": "xe20", "d": "en", "nou": 1, "t": "mc", "q": "“Deploy” means:", "o": ["A pune aplicația în funcțiune pe un server/mediu", "A șterge codul", "A scrie documentația"], "a": 0, "h": "Release process.", "e": "deploy = livrare în mediu (staging, production). rollback = revenirea la versiunea anterioară.", "px": ["„Deploy” = a pune o versiune a aplicației în funcțiune pe un server sau într-un mediu (staging, production). Substantiv: „a deployment”."]}, {"id": "xe21", "d": "en", "nou": 1, "t": "mc", "q": "“Rollback” in a release process means:", "o": ["Revenirea la versiunea anterioară după o problemă", "Un test automat", "O ședință de planificare"], "a": 0, "h": "Marșul înapoi.", "e": "Planul de rollback face parte dintr-un deployment responsabil.", "px": ["„Rollback” = întoarcerea la versiunea anterioară, bună, după ce o lansare produce probleme."]}, {"id": "xe22", "d": "en", "nou": 1, "t": "mc", "q": "What is “staging”?", "o": ["Un mediu asemănător producției, în care testezi înainte de lansare", "Un mediu de producție", "Un tip de bază de date"], "a": 0, "h": "Între dev și production.", "e": "Mediile uzuale: development, test/QA, staging, production.", "px": ["„Staging” e mediul de probă, cât mai asemănător cu producția. Testezi acolo înainte de lansare ca utilizatorii reali să nu vadă erorile."]}, {"id": "xe23", "d": "en", "nou": 1, "t": "mc", "q": "“Regression testing” checks that...", "o": ["modificările noi nu au stricat funcționalități existente", "aplicația funcționează pe viteză mică", "codul e scris frumos"], "a": 0, "h": "Re-testare după schimbări.", "e": "Testele de regresie se automatizează frecvent.", "px": ["Regresie = ce mergea înainte nu mai merge după o modificare. Regression testing reia teste vechi ca să verifice asta."]}, {"id": "xe24", "d": "en", "nou": 1, "t": "mc", "q": "Which sentence is correct?", "o": ["I didn’t understand the question.", "I don’t understood the question.", "I didn’t understood the question."], "a": 0, "h": "Auxiliar la trecut: did + infinitiv.", "e": "Cu didn’t verbul rămâne la infinitiv (understand), nu la trecut.", "px": ["În propoziții negative, verbul auxiliar `did` poartă trecutul, iar verbul principal rămâne la infinitiv: „didn’t understand”, nu „didn’t understood”."]}, {"id": "xe25", "d": "en", "nou": 1, "t": "mc", "q": "“I’d like to ___ for the delay.”", "o": ["apologize", "apology", "excuse me"], "a": 0, "h": "Verb formal.", "e": "I apologize for the delay / I’m sorry for the delay. Apology e substantiv.", "px": ["„Apologize for” = a-ți cere scuze pentru. „I’d like to apologize for the delay.” Verbul se scrie și „apologise” în engleza britanică."]}, {"id": "xe26", "d": "en", "nou": 1, "t": "mc", "q": "What does “to follow up” mean in a business email?", "o": ["A reveni cu un mesaj ulterior, pentru a continua o discuție anterioară", "A urma pe cineva pe stradă", "A termina o discuție"], "a": 0, "h": "Reminder politicos.", "e": "Exemplu: „I’m following up on my email from Monday.”", "px": ["„Follow up” = a reveni la o discuție anterioară: „I’m following up on my email from Monday.” Ton politicos și obișnuit în email-uri de business."]}, {"id": "xe27", "d": "en", "nou": 1, "t": "mc", "q": "What does “to escalate an issue” mean?", "o": ["A transmite problema unui nivel superior (manager, echipă specializată)", "A rezolva problema singur", "A ignora problema"], "a": 0, "h": "Ierarhie de suport.", "e": "În suport, „tier 1 → tier 2 → engineering” sunt niveluri de escaladare.", "px": ["„Escalate” = a transmite problema mai sus (manager sau echipă specializată) când nu poți s-o rezolvi la nivelul tău."]}, {"id": "xe28", "d": "en", "nou": 1, "t": "mc", "q": "What does “workaround” mean?", "o": ["Soluție temporară care ocolește o problemă, fără să o rezolve de fapt", "Programul de lucru", "O funcție nouă"], "a": 0, "h": "Nu e fix definitiv.", "e": "Exemplu: „As a workaround, clear the cache until the fix is released.”", "px": ["„Workaround” = soluție temporară care ocolește problema, fără să o rezolve de fapt. Spui: „There’s a workaround until we ship the fix.”"]}, {"id": "xe29", "d": "en", "nou": 1, "t": "mc", "q": "Which sentence is more natural at an interview?", "o": ["I’m interested in this role because it combines testing and customer support.", "I want this job because I need money.", "This job is very easy for me."], "a": 0, "h": "Motivație legată de rol.", "e": "Pregătește o propoziție despre ce te atrage la companie și la rol.", "px": ["Un răspuns bun arată interes real și face legătura cu postul. „Am nevoie de bani” sau „e ușor” sună rău."]}, {"id": "xe30", "d": "en", "nou": 1, "t": "mc", "q": "“I have been testing since 9 o’clock.” Which tense is used?", "o": ["Present perfect continuous (acțiune începută în trecut, continuă în prezent)", "Past simple", "Future perfect"], "a": 0, "h": "have been + -ing.", "e": "Se folosește pentru acțiuni în desfășurare, cu accent pe durată.", "px": ["„Have been testing since 9” e present perfect continuous: a început la 9 și continuă acum. `Since` + punct de start, `for` + durată."]}, {"id": "xe31", "d": "en", "nou": 1, "t": "mc", "q": "“Sensible” and “sensitive” are not the same. Which sentence is correct?", "o": ["She made a sensible decision.", "She made a sensitive decision (= rezonabilă).", "He is a very sensible person (= emotiv)."], "a": 0, "h": "False friends clasice.", "e": "sensible = rezonabil; sensitive = sensibil, emotiv.", "px": ["Falsii prieteni: „sensible” = rezonabil, cu bun-simț; „sensitive” = sensibil. „A sensible decision” e o decizie înțeleaptă."]}, {"id": "xe32", "d": "en", "nou": 1, "t": "mc", "q": "Choose the correct sentence.", "o": ["He has fewer bugs than before.", "He has less bugs than before.", "He has few bug than before."], "a": 0, "h": "Numărabil → fewer.", "e": "fewer + substantiv numărabil plural (bugs); less + nenumărabil (less time). În uz informal se aude „less bugs”, dar fewer e forma corectă.", "px": ["Pentru numărabile (bugs, errors) folosești `fewer`; pentru nenumărabile (time, water) `less`. „Fewer bugs”, dar „less time”."]}, {"id": "xh1", "d": "web", "nou": 1, "t": "mc", "q": "Cum declari corect favicon-ul unei pagini?", "o": ["<link rel=\"icon\" href=\"favicon.ico\"> în <head>", "<img rel=\"icon\" src=\"favicon.ico\"> în <body>", "<meta favicon=\"favicon.ico\">"], "a": 0, "h": "Un element din head, cu rel.", "e": "Elementul <link> descrie relația cu o resursă externă: rel=\"icon\" (favicon), rel=\"stylesheet\", rel=\"preload\", rel=\"canonical\".", "px": ["Favicon-ul e iconița din tab. Îl declari în `<head>` cu `<link rel=\"icon\" href=\"...\">`."]}, {"id": "xh2", "d": "web", "nou": 1, "t": "mc", "q": "Ce face <link rel=\"canonical\" href=\"...\"> în <head>?", "o": ["Indică URL-ul preferat al paginii, ca motoarele să nu trateze duplicatele ca pagini separate", "Încarcă un font", "Blochează indexarea"], "a": 0, "h": "Util la conținut duplicat.", "e": "Canonical e un semnal pentru Google; în Search Console apare, de exemplu, „Duplicate without user-selected canonical”.", "px": ["Aceeași pagină poate avea mai multe URL-uri (cu parametri, cu/fără www). `canonical` spune motoarelor de căutare care e URL-ul „oficial”, ca să nu fie tratate drept duplicate."]}, {"id": "xh3", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre elemente block și inline?", "o": ["Block ocupă toată lățimea și începe pe rând nou (div, p); inline curge în text și ocupă doar cât conținutul (span, a)", "Block e mai mic decât inline", "Inline poate avea mereu width și height"], "a": 0, "h": "Comportament la așezare.", "e": "Pe elemente inline, width și height nu au efect; inline-block le permite.", "px": ["Block începe pe rând nou și ocupă toată lățimea. Inline curge în text și ocupă doar cât conținutul. `inline-block` e un mix: stă în rând, dar acceptă `width` și `height`.", "Încearcă: schimbă `display` pe fiecare."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .b, .i { background: #ffe0b2; margin: 4px; }\n  .i { display: inline; background: #c8e6c9; width: 300px; height: 80px; padding: 10px; }\n  .ib { display: inline-block; background: #bbdefb; width: 100px; height: 40px; }\n</style>\n</head>\n<body>\n<div class=\"b\">div (block): ocupă tot rândul</div>\n<span class=\"i\">span (inline): width și height ignorate</span>\n<span class=\"ib\">inline-block: le respectă</span>\n</body>\n</html>\n"}}, {"id": "xh4", "d": "web", "nou": 1, "t": "mc", "q": "Ce regulă are atributul id față de class?", "o": ["id trebuie să fie unic în pagină; class poate fi folosit pe mai multe elemente", "Sunt identice", "class trebuie să fie unic"], "a": 0, "h": "Unic versus reutilizabil.", "e": "În CSS, #id are specificitate mai mare decât .class.", "px": ["`id` e ca un CNP: unic în pagină. `class` e ca o categorie: o folosești pe câte elemente vrei, iar un element poate avea mai multe clase."]}, {"id": "xh5", "d": "web", "nou": 1, "t": "mc", "q": "Ce face <picture> cu mai multe <source>?", "o": ["Alege prima sursă potrivită (media/type), iar <img> e fallback-ul obligatoriu", "Afișează toate imaginile", "Merge fără <img>"], "a": 0, "h": "Art direction și formate moderne.", "e": "Exemplu: AVIF → WebP → JPG. media poate schimba imaginea după ecran sau tema (prefers-color-scheme).", "px": ["`<picture>` alege prima `<source>` care se potrivește (după media sau type), ex. AVIF dacă browserul îl știe. `<img>` e obligatoriu, cu rol de rezervă."]}, {"id": "xh6", "d": "web", "nou": 1, "t": "mc", "q": "De ce are nevoie un <iframe> de atributul title?", "o": ["Pentru accesibilitate: cititoarele de ecran descriu conținutul încorporat", "Pentru SEO obligatoriu", "Pentru a încărca mai repede"], "a": 0, "h": "Screen readers.", "e": "Alte atribute utile: sandbox (restricții), loading=\"lazy\", referrerpolicy.", "px": ["Cititorul de ecran anunță un iframe după titlu. Fără `title`, utilizatorul aude doar „frame”, fără să știe ce conține."]}, {"id": "xh7", "d": "web", "nou": 1, "t": "mc", "q": "De ce o pagină refuză să se încarce într-un <iframe> pe alt site?", "o": ["Serverul trimite X-Frame-Options sau CSP frame-ancestors, care interzic încorporarea", "Browserul nu suportă iframe", "Lipsește atributul sandbox"], "a": 0, "h": "Headere de securitate.", "e": "E o protecție împotriva clickjacking.", "px": ["Un site poate interzice încorporarea lui în altele (protecție contra clickjacking) prin `X-Frame-Options` sau `Content-Security-Policy: frame-ancestors`. Browserul respectă și blochează iframe-ul."]}, {"id": "xh8", "d": "web", "nou": 1, "t": "mc", "q": "Ce face atributul sandbox pe un <iframe>?", "o": ["Aplică restricții conținutului încorporat, ridicate selectiv cu tokeni (allow-scripts, allow-forms...)", "Face iframe-ul mai rapid", "Ascunde iframe-ul"], "a": 0, "h": "Tokenii dau înapoi permisiuni.", "e": "Documentația avertizează: nu combina allow-scripts cu allow-same-origin pentru conținut necontrolat.", "px": ["`sandbox` pune conținutul încorporat într-un „țarc”: fără scripturi, formulare etc. Ridici restricțiile pe care le vrei prin tokeni: `allow-scripts`, `allow-forms`."]}, {"id": "xh9", "d": "web", "nou": 1, "t": "mc", "q": "Cum deschizi corect un <dialog> modal?", "o": ["dialog.showModal() — blochează restul paginii (inert) și se închide cu Esc", "dialog.show() — e modal", "Doar cu atributul open, e recomandat"], "a": 0, "h": "show() nu e modal.", "e": "show() deschide non-modal. Backdrop-ul se stilizează cu ::backdrop. Un formular cu method=\"dialog\" închide dialogul.", "px": ["`showModal()` deschide dialogul peste pagină, blochează restul și se închide cu Esc. `show()` îl deschide fără să blocheze nimic.", "Încearcă: apasă fiecare buton și apoi încearcă să apeși pe altă parte a paginii."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>dialog::backdrop { background: rgba(0,0,0,.4); }</style>\n</head>\n<body>\n<button id=\"m\">showModal()</button> <button id=\"n\">show()</button>\n<dialog id=\"d\"><p>Salut din dialog</p><form method=\"dialog\"><button>Închide</button></form></dialog>\n<script>\n  const d = document.getElementById(\"d\");\n  m.onclick = () => d.showModal();   // modal: restul paginii e blocat, Esc închide\n  n.onclick = () => d.show();        // non-modal\n</script>\n</body>\n</html>\n"}}, {"id": "xh10", "d": "web", "nou": 1, "t": "mc", "q": "Ce e o cale relativă (file path) față de una absolută într-un src?", "o": ["Relativă pornește de la fișierul curent (ex. img/logo.png); absolută include protocolul/domeniul sau începe cu / din rădăcină", "Sunt identice", "Relativă merge doar local"], "a": 0, "h": "Unde începe calea?", "e": "../ urcă un director, / pornește din rădăcina site-ului.", "px": ["Cale relativă: pornește de la fișierul curent (`img/logo.png`). Cale absolută: adresă completă (`https://site.ro/img/logo.png`) sau care pornește de la rădăcină (`/img/logo.png`)."]}, {"id": "xh11", "d": "web", "nou": 1, "t": "mc", "q": "Care tag este semantic pentru navigarea principală?", "o": ["<nav>", "<div class=\"nav\"> (nesemantic)", "<menu-list>"], "a": 0, "h": "Elemente semantice: header, nav, main, article, section, footer.", "e": "Semantica ajută accesibilitatea (screen readers) și SEO.", "px": ["Pentru navigarea principală folosești `<nav>`, nu `<div class=\"nav\">`. Spune browserului și tehnologiilor de asistență ce rol are blocul."]}, {"id": "xh12", "d": "web", "nou": 1, "t": "mc", "q": "Ce face loading=\"lazy\" pe un <img>?", "o": ["Amână încărcarea imaginii până se apropie de viewport", "Încarcă imaginea înaintea paginii", "Comprimă imaginea"], "a": 0, "h": "Imagini sub fold.", "e": "Nu îl pune pe imaginea LCP (de sus): ai încărca-o mai târziu.", "px": ["`loading=\"lazy\"` amână încărcarea imaginii până se apropie de ecran, deci pagina pornește mai repede. Nu-l pune pe imaginea principală, de sus.", "Încearcă: deschide F12 → Network și derulează."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n</head>\n<body>\n<p>Derulează în jos: imaginile din partea de jos se încarcă abia când te apropii.</p>\n<div style=\"height:900px\"></div>\n<img src=\"https://placehold.co/300x120/png?text=lazy\" loading=\"lazy\" width=\"300\" height=\"120\" alt=\"\">\n</body>\n</html>\n"}}, {"id": "xh13", "d": "web", "nou": 1, "t": "mc", "q": "Cum faci o pagină responsive la nivel de HTML?", "o": ["<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"> în head", "<meta name=\"responsive\">", "Doar cu JavaScript"], "a": 0, "h": "Fără meta viewport, mobilul randează pagina ca desktop.", "e": "Peste meta se adaugă media queries sau container queries.", "px": ["Fără `meta viewport`, telefoanele randează pagina ca pe una de desktop, apoi o micșorează. `width=device-width, initial-scale=1` îi spune să folosească lățimea reală a ecranului. Fără el, nici media queries nu funcționează cum te aștepți."]}, {"id": "xc1", "d": "web", "nou": 1, "t": "mc", "q": "Care selector are specificitate mai mare: #meniu, .meniu.activ sau a.link?", "o": ["#meniu (id)", "a.link", "Toate la fel"], "a": 0, "h": "Id > clasă > element.", "e": "Specificitatea se compară ca (id, clase/atribute/pseudo-clase, elemente). Inline style bate selectorii.", "px": ["Ordinea specificității: id > clasă/atribut/pseudo-clasă > etichetă. `#meniu` bate `.meniu.activ`, care bate `a.link`. La egalitate câștigă regula scrisă mai târziu."]}, {"id": "xc2", "d": "web", "nou": 1, "t": "mc", "q": "Ce face display: flex pe un container față de display: grid?", "o": ["flex aranjează pe o singură axă (rând sau coloană); grid pe două axe (rânduri și coloane)", "Sunt identice", "grid e doar pentru tabele"], "a": 0, "h": "Unidimensional versus bidimensional.", "e": "Flex: navbar, centrare. Grid: layout de pagină și galerii.", "px": ["Flex aranjează elementele pe O linie (sau coloană). Grid le aranjează pe două dimensiuni, rânduri și coloane.", "Încearcă: adaugă încă 3 elemente în fiecare și vezi cum se comportă."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .flex { display:flex; gap:8px; } .grid { display:grid; grid-template-columns: repeat(3, 1fr); gap:8px; margin-top:16px; }\n  .flex div, .grid div { background:#c5cae9; padding:12px; }\n</style>\n</head>\n<body>\n<div class=\"flex\"><div>flex 1</div><div>flex 2</div><div>flex 3</div></div>\n<div class=\"grid\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div></div>\n</body>\n</html>\n"}}, {"id": "xc3", "d": "web", "nou": 1, "t": "mc", "q": "Cum centrezi un element pe ambele axe cu flexbox?", "o": ["display:flex; justify-content:center; align-items:center pe container", "margin:auto pe un inline", "text-align:center pe container"], "a": 0, "h": "justify = axa principală, align = axa transversală.", "e": "Cu grid: display:grid; place-items:center.", "px": ["Flex: `justify-content` centrează pe axa principală, `align-items` pe cea transversală. Grid: `place-items: center` face ambele.", "Încearcă: schimbă `flex-direction: column` și vezi că rolurile axelor se inversează."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .centru { display:flex; justify-content:center; align-items:center; height:180px; background:#e3f2fd; }\n  .g { display:grid; place-items:center; height:120px; background:#fff3e0; margin-top:12px; }\n</style>\n</head>\n<body>\n<div class=\"centru\"><b>Centrat cu flex</b></div>\n<div class=\"g\"><b>Centrat cu grid</b></div>\n</body>\n</html>\n"}}, {"id": "xc4", "d": "web", "nou": 1, "t": "mc", "q": "Ce face box-sizing: border-box?", "o": ["width include conținutul, padding-ul și bordura", "width include și marginea", "Elimină padding-ul"], "a": 0, "h": "Calculul lățimii.", "e": "Marginea rămâne în afara lățimii.", "px": ["Cu `content-box`, `width` e doar lățimea conținutului, iar padding și bordura se adaugă. Cu `border-box`, `width` include și padding și bordura.", "Încearcă: rulează și compară cele două cutii (a doua e mai îngustă). Apasă F12 pe pagină, dacă vrei să le măsori."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  div { width: 200px; padding: 20px; border: 5px solid #333; margin: 10px; background: #e3f2fd; }\n  .bb { box-sizing: border-box; }\n</style>\n</head>\n<body>\n<div>content-box: lățime totală = 200 + 40 + 10 = 250px</div>\n<div class=\"bb\">border-box: lățime totală = 200px</div>\n</body>\n</html>\n"}}, {"id": "xc5", "d": "web", "nou": 1, "t": "mc", "q": "Când se aplică margin collapse?", "o": ["Marginile verticale adiacente ale blocurilor se contopesc în cea mai mare; nu se aplică în flex/grid", "Marginile orizontale se adună", "Niciodată"], "a": 0, "h": "Doar pe verticală.", "e": "Padding sau bordură între elemente oprește colapsul.", "px": ["Două margini verticale care se ating se contopesc: rămâne cea mai mare (40px), nu suma (60px). În flex și grid nu se întâmplă.", "Încearcă: măsoară vizual spațiul dintre A și B în cele două cazuri."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .a { margin-bottom: 40px; background: #ffe0b2; }\n  .b { margin-top: 20px; background: #c8e6c9; }\n  .flex { display: flex; flex-direction: column; }\n</style>\n</head>\n<body>\n<h4>Bloc normal: spațiu = 40px (nu 60)</h4>\n<div class=\"a\">A</div><div class=\"b\">B</div>\n<h4>Flex: marginile se adună = 60px</h4>\n<div class=\"flex\"><div class=\"a\">A</div><div class=\"b\">B</div></div>\n</body>\n</html>\n"}}, {"id": "xc6", "d": "web", "nou": 1, "t": "mc", "q": "position: absolute se raportează la...", "o": ["Cel mai apropiat strămoș poziționat (nu static); altfel la viewport/initial containing block", "Părintele direct, mereu", "Elementul frate anterior"], "a": 0, "h": "Pune position:relative pe părinte.", "e": "fixed se raportează la viewport, sticky comută între relative și fixed la scroll.", "px": ["Elementul absolut se măsoară față de cel mai apropiat strămoș care NU e `static`. De aceea pui `position: relative` pe părinte.", "Încearcă: șterge `position: relative` și vezi cum „zboară” spre colțul paginii."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .parinte { position: relative; width: 250px; height: 120px; background: #e3f2fd; margin: 30px; }\n  .copil { position: absolute; top: 10px; right: 10px; background: #ef9a9a; padding: 6px; }\n</style>\n</head>\n<body>\n<div class=\"parinte\">părinte (relative)<div class=\"copil\">absolut</div></div>\n</body>\n</html>\n"}}, {"id": "xc7", "d": "web", "nou": 1, "t": "mc", "q": "Ce unitate e relativă la fontul elementului rădăcină?", "o": ["rem", "em", "px"], "a": 0, "h": "Root em.", "e": "em e relativ la font-size-ul părintelui (se compune la imbricare).", "px": ["`rem` = „root em”: relativ la `font-size` de pe `<html>`. `em` e relativ la fontul elementului curent (sau al părintelui), deci se poate „compune”."]}, {"id": "xc8", "d": "web", "nou": 1, "t": "mc", "q": "Ce face z-index?", "o": ["Controlează ordinea de suprapunere, dar doar pe elemente poziționate (și în același stacking context)", "Mărește elementul", "Ascunde elementul"], "a": 0, "h": "Stacking context.", "e": "Un z-index mare nu iese din stacking context-ul părintelui.", "px": ["`z-index` decide cine e deasupra, dar doar pe elemente poziționate (relative, absolute...), flex sau grid. Funcționează în interiorul unui stacking context, deci 9999 nu bate un părinte aflat în alt context."]}, {"id": "xc9", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre display:none și visibility:hidden?", "o": ["none scoate elementul din layout; hidden îl ascunde dar păstrează spațiul", "Sunt identice", "hidden scoate elementul din layout"], "a": 0, "h": "Spațiul rămâne sau nu.", "e": "opacity:0 îl face transparent, dar rămâne interactiv.", "px": ["`display:none` scoate elementul complet din pagină (nu mai ocupă loc). `visibility:hidden` îl face invizibil, dar spațiul rămâne.", "Încearcă: observă golul lăsat de rândul 3."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .x { background: #ffcdd2; padding: 6px; margin: 6px 0; }\n</style>\n</head>\n<body>\n<div class=\"x\">Rând 1</div>\n<div class=\"x\" style=\"display:none\">Rând 2 (display:none)</div>\n<div class=\"x\" style=\"visibility:hidden\">Rând 3 (visibility:hidden)</div>\n<div class=\"x\">Rând 4</div>\n</body>\n</html>\n"}}, {"id": "xc10", "d": "web", "nou": 1, "t": "mc", "q": "Ce face un media query @media (max-width: 600px) { ... }?", "o": ["Aplică regulile doar când lățimea viewport-ului e ≤ 600px", "Aplică regulile peste 600px", "Aplică doar la print"], "a": 0, "h": "Max-width = până la.", "e": "Abordarea mobile-first folosește min-width.", "px": ["Regulile din `@media (max-width: 600px)` se aplică doar când fereastra e de cel mult 600px lățime.", "Încearcă: trage de marginea ferestrei sau folosește F12 → mod mobil."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  body { background: #e3f2fd; }\n  @media (max-width: 600px) { body { background: #ffcdd2; } }\n</style>\n</head>\n<body>\n<p>Micșorează fereastra sub 600px: fundalul devine roșu.</p>\n</body>\n</html>\n"}}, {"id": "xc11", "d": "web", "nou": 1, "t": "mc", "q": "Cum folosești o variabilă CSS?", "o": ["Definești --culoare: #333 și o citești cu var(--culoare)", "$culoare: #333", "let culoare = #333"], "a": 0, "h": "Custom properties.", "e": "Se moștenesc și se pot schimba la runtime (inclusiv din JS), spre deosebire de variabilele Sass.", "px": ["O variabilă CSS se declară cu `--nume` și se citește cu `var(--nume)`. Se moștenește: o poți suprascrie pe un element și copiii lui o vor vedea.", "Încearcă: schimbă `--culoare` din `:root` și vezi cum se schimbă tot."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  :root { --culoare: #1565c0; --spatiu: 12px; }\n  .card { color: var(--culoare); padding: var(--spatiu); border: 2px solid var(--culoare); }\n  .alt { --culoare: #c62828; }\n</style>\n</head>\n<body>\n<div class=\"card\">Variabilă CSS</div>\n<div class=\"card alt\">Aceeași clasă, altă valoare</div>\n</body>\n</html>\n"}}, {"id": "xc12", "d": "web", "nou": 1, "t": "mc", "q": "Ce face selectorul :has() (de ex. section:has(.featured))?", "o": ["Selectează elementul pe baza descendenților sau a vecinilor; practic un „selector părinte”", "Selectează doar copiii direcți", "Adaugă conținut"], "a": 0, "h": "Relațional.", "e": "Baseline din decembrie 2023. Nu poate fi imbricat într-un alt :has(); evită ancore largi (body, *).", "px": ["`:has()` e un „selector părinte”: `.card:has(img)` înseamnă „cardul care CONȚINE o imagine”.", "Încearcă: șterge imaginea din al doilea card și vezi că stilul dispare."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .card { padding: 12px; margin: 8px; border: 2px solid #ccc; border-radius: 8px; }\n  .card:has(img) { border-color: green; background: #e8f5e9; }\n</style>\n</head>\n<body>\n<div class=\"card\">Card fără imagine</div>\n<div class=\"card\">Card cu imagine <img src=\"https://placehold.co/30\" alt=\"\"></div>\n<div class=\"card\">Alt card fără imagine</div>\n</body>\n</html>\n"}}, {"id": "xc13", "d": "web", "nou": 1, "t": "mc", "q": "Cum faci ca un card să-și schimbe layout-ul după lățimea containerului său, nu a ecranului?", "o": ["container-type: inline-size pe părinte și @container (width > 700px) { ... }", "@media (min-width: 700px)", "Cu JavaScript obligatoriu"], "a": 0, "h": "Container queries.", "e": "Componenta devine reutilizabilă în orice loc din pagină. Unități speciale: cqw, cqi, cqh.", "px": ["Container query: stilul depinde de lățimea CONTAINERULUI, nu a ferestrei. Aceeași componentă arată diferit în locuri de lățimi diferite.", "Încearcă: schimbă lățimile 250px și 550px."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .wrap { container-type: inline-size; border: 2px dashed #888; padding: 8px; margin-bottom: 14px; }\n  .card { display:grid; gap:8px; background:#e3f2fd; padding:8px; }\n  @container (width > 400px) { .card { grid-template-columns: 1fr 1fr; background:#c8e6c9; } }\n</style>\n</head>\n<body>\n<div class=\"wrap\" style=\"width: 250px\"><div class=\"card\"><b>A</b><b>B</b></div></div>\n<div class=\"wrap\" style=\"width: 550px\"><div class=\"card\"><b>A</b><b>B</b></div></div>\n</body>\n</html>\n"}}, {"id": "xc14", "d": "web", "nou": 1, "t": "mc", "q": "Cum funcționează @layer la cascadă?", "o": ["Ordinea straturilor decide înaintea specificității; stratul declarat ultimul câștigă; stilurile fără strat bat cele din straturi (la declarații normale)", "Specificitatea decide mereu", "Straturile se aplică în ordine alfabetică"], "a": 0, "h": "@layer reset, base, utilities;", "e": "La !important ordinea se inversează: straturile timpurii bat pe cele târzii.", "px": ["Straturile (`@layer`) decid înaintea specificității: stratul declarat ultimul câștigă. Aici `tema` bate `baza`, chiar dacă `#app .btn` are specificitate mai mare.", "Încearcă: inversează ordinea în `@layer baza, tema;`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  @layer baza, tema;\n  @layer tema { .btn { color: green; } }\n  @layer baza { #app .btn { color: red; } }   /* specificitate mai mare, dar strat mai devreme */\n</style>\n</head>\n<body>\n<div id=\"app\"><span class=\"btn\">Ce culoare am?</span></div>\n</body>\n</html>\n"}}, {"id": "xc15", "d": "web", "nou": 1, "t": "mc", "q": "Ce permite CSS nesting nativ?", "o": ["Scrii reguli în interiorul altora (.card { .titlu { ... } &:hover { ... } }) fără preprocesor", "Doar variabile", "Doar animații"], "a": 0, "h": "& referă selectorul părinte.", "e": "Diferență față de Sass: nu poți concatena (&__element nu funcționează). & ia specificitatea ca în :is().", "px": ["Nesting nativ: scrii regulile copil în interiorul părintelui, fără Sass. `&` înseamnă „selectorul părinte”.", "Încearcă: adaugă încă un selector imbricat."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  .card { padding: 12px; border: 1px solid #999; width: 260px;\n    .titlu { font-weight: bold; color: #1565c0; }\n    &:hover { background: #fffde7; }\n    & p { margin: 4px 0; }\n  }\n</style>\n</head>\n<body>\n<div class=\"card\"><div class=\"titlu\">Titlu</div><p>Text în card (treci cu mouse-ul)</p></div>\n</body>\n</html>\n"}}, {"id": "xc16", "d": "web", "nou": 1, "t": "mc", "q": "Ce face font-size: clamp(1rem, 2.5vw, 2rem)?", "o": ["Dimensiune fluidă: nu coboară sub 1rem, nu urcă peste 2rem, între ele se scalează cu viewport-ul", "Fixează 2.5vw", "Folosește mereu 1rem"], "a": 0, "h": "clamp(min, preferat, max).", "e": "Echivalent cu max(min, min(preferat, max)). Pentru accesibilitate maximul să fie cel puțin dublul minimului.", "px": ["`clamp(min, preferat, max)` ține valoarea între limite, iar între ele o lasă să crească cu fereastra.", "Încearcă: lărgește fereastra și urmărește titlul."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  h1 { font-size: clamp(1rem, 2.5vw + 0.5rem, 3rem); }\n</style>\n</head>\n<body>\n<h1>Titlu fluid</h1>\n<p>Lărgește și îngustează fereastra: titlul crește, dar nu sub 1rem și nu peste 3rem.</p>\n</body>\n</html>\n"}}, {"id": "xc17", "d": "web", "nou": 1, "t": "mc", "q": "Care e diferența dintre :is() și :where() la specificitate?", "o": ["is() ia specificitatea celui mai specific argument; where() are specificitate zero", "Sunt identice", "where() are specificitate maximă"], "a": 0, "h": "Zero versus cel mai mare.", "e": "where() e bun pentru stiluri de bază ușor de suprascris.", "px": ["`:is()` ia specificitatea celui mai specific selector din listă, `:where()` are specificitate ZERO, deci e ușor de suprascris.", "Încearcă: înlocuiește `:where` cu `:is` și vezi ce culoare are `x`."], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n  :where(.a) .x { color: red; }     /* specificitate 0 pentru :where */\n  .x { color: blue; }               /* bate, chiar daca e scrisa DUPA */\n  :is(h1, h2) .y { color: green; }\n</style>\n</head>\n<body>\n<div class=\"a\"><span class=\"x\">x</span></div>\n<section><h2><span class=\"y\">y</span></h2></section>\n</body>\n</html>\n"}}, {"id": "xc18", "d": "web", "nou": 1, "t": "mc", "q": "Ce înseamnă proprietățile logice (margin-inline, padding-block)?", "o": ["Se raportează la direcția textului (inline/block), nu la stânga/dreapta/sus/jos, deci merg și la RTL", "Sunt pentru print", "Sunt pentru animații"], "a": 0, "h": "Independente de direcție.", "e": "inline-start/end înlocuiesc left/right în limbi cu scriere RTL.", "px": ["`margin-inline` înseamnă „pe direcția textului”: stânga/dreapta în română, dar invers într-o limbă scrisă de la dreapta la stânga. Proprietățile logice fac layoutul corect pentru ambele, fără reguli separate."]}, {"id": "xt1", "d": "web", "nou": 1, "t": "mc", "q": "Ce înseamnă „utility-first” la Tailwind?", "o": ["Stilizezi direct în HTML cu clase mici, cu un singur scop (flex, p-4, text-center)", "Scrii CSS separat pentru fiecare componentă", "Folosești doar stiluri inline"], "a": 0, "h": "Combinezi clase în markup.", "e": "Față de stilurile inline poți folosi variante (hover:, md:, dark:) și valori dintr-o temă.", "px": ["În loc să scrii o clasă `.card` în CSS, pui clase mici direct în HTML: `p-4`, `flex`, `text-center`. Fiecare face un singur lucru."]}, {"id": "xt2", "d": "web", "nou": 1, "t": "mc", "q": "În Tailwind, ce face clasa md:flex?", "o": ["Aplică display:flex de la breakpoint-ul md (min-width 48rem, 768px) în sus", "Aplică flex doar sub md", "Aplică flex doar pe md exact"], "a": 0, "h": "Mobile-first.", "e": "Clasele fără prefix se aplică pe toate ecranele; prefixele se aplică de la breakpoint în sus.", "px": ["Tailwind e mobile-first: clasele fără prefix se aplică peste tot, iar prefixele (`md:`) de la acel breakpoint în sus. `md` = 768px.", "Încearcă: lărgește sau îngustează fereastra. (Exemplul folosește Tailwind v4 prin CDN și are nevoie de internet.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n</head>\n<body>\n<div class=\"p-4\">\n  <div class=\"rounded bg-sky-200 p-4 text-center md:bg-emerald-200 md:text-left\">\n    Sub 768px: albastru, centrat. De la 768px în sus (md): verde, aliniat la stânga.\n  </div>\n</div>\n</body>\n</html>\n"}}, {"id": "xt3", "d": "web", "nou": 1, "t": "mc", "q": "De ce <div class=\"sm:text-center\"> nu centrează textul pe telefon?", "o": ["Prefixul sm: se aplică de la 640px în sus; pentru mobil folosești clasa fără prefix, ex. text-center sm:text-left", "Tailwind nu suportă text-center", "sm: înseamnă sub 640px"], "a": 0, "h": "Mobile-first, nu desktop-first.", "e": "Pentru intervale folosești max-*: md:max-lg:flex.", "px": ["Tailwind e mobile-first: clasele fără prefix se aplică peste tot, iar prefixele (`md:`) de la acel breakpoint în sus. `md` = 768px.", "Încearcă: lărgește sau îngustează fereastra. (Exemplul folosește Tailwind v4 prin CDN și are nevoie de internet.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n</head>\n<body>\n<div class=\"p-4\">\n  <div class=\"rounded bg-sky-200 p-4 text-center md:bg-emerald-200 md:text-left\">\n    Sub 768px: albastru, centrat. De la 768px în sus (md): verde, aliniat la stânga.\n  </div>\n</div>\n</body>\n</html>\n"}}, {"id": "xt4", "d": "web", "nou": 1, "t": "mc", "q": "Cum instalezi stilurile în Tailwind v4 în fișierul CSS?", "o": ["@import \"tailwindcss\";", "@tailwind base; @tailwind components; @tailwind utilities;", "import 'tailwind'"], "a": 0, "h": "Directivele @tailwind au dispărut din v4.", "e": "În v4 configurarea e „CSS-first”, cu @theme, iar tailwind.config.js nu mai e detectat automat (există @config).", "px": ["În Tailwind v4 configurezi în CSS cu `@theme`. Aici definești culoarea `brand` și imediat poți scrie `bg-brand`.", "Încearcă: schimbă valoarea lui `--color-brand`. (Necesită internet pentru CDN.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n<style type=\"text/tailwindcss\">\n  @theme { --color-brand: #7c3aed; --breakpoint-3xl: 120rem; }\n</style>\n</head>\n<body>\n<div class=\"p-6\"><button class=\"rounded bg-brand px-4 py-2 text-white hover:bg-brand/80\">Culoare din @theme</button></div>\n</body>\n</html>\n"}}, {"id": "xt5", "d": "web", "nou": 1, "t": "mc", "q": "Cum definești culori sau breakpoint-uri proprii în Tailwind v4?", "o": ["În CSS, într-un bloc @theme (ex. --breakpoint-3xl: 120rem)", "Obligatoriu în tailwind.config.js", "Doar prin plugin npm"], "a": 0, "h": "CSS-first configuration.", "e": "Valorile din @theme devin și variabile CSS.", "px": ["În v4, personalizarea se face în CSS, nu într-un `tailwind.config.js`: într-un bloc `@theme { --color-brand: #0a7; --breakpoint-3xl: 120rem; }`. Tailwind generează automat clasele (`bg-brand`, `3xl:...`)."]}, {"id": "xt6", "d": "web", "nou": 1, "t": "mc", "q": "Ce se întâmplă la <div class=\"grid flex\"> în Tailwind?", "o": ["Câștigă clasa care apare mai târziu în fișierul CSS generat, nu cea scrisă ultima în HTML; adaugă doar clasa dorită", "Câștigă mereu ultima din HTML", "Eroare"], "a": 0, "h": "Ordinea din stylesheet.", "e": "Soluție: condiționează clasele în cod (gridLayout ? 'grid' : 'flex'). Modificatorul ! forțează (bg-red-500!).", "px": ["Ambele clase setează `display`. Contează ordinea din fișierul CSS generat de Tailwind, nu ordinea din atributul `class`. Nu pune două clase care se bat pe aceeași proprietate."]}, {"id": "xt7", "d": "web", "nou": 1, "t": "mc", "q": "Cum scrii o valoare arbitrară în Tailwind?", "o": ["Între paranteze pătrate, ex. bg-[#316ff6] sau w-[137px]", "bg(#316ff6)", "bg=#316ff6"], "a": 0, "h": "Ieșirea din tema predefinită.", "e": "Merge și la variante: min-[320px]:text-center.", "px": ["Valorile arbitrare între `[ ]` te lasă să ieși din tema predefinită: `bg-[#316ff6]`, `w-[137px]`.", "Încearcă: schimbă culoarea. (Necesită internet pentru CDN.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n</head>\n<body>\n<div class=\"p-6\"><button class=\"bg-[#316ff6] w-[137px] rounded py-2 text-white\">arbitrar</button></div>\n</body>\n</html>\n"}}, {"id": "xt8", "d": "web", "nou": 1, "t": "mc", "q": "Cum aplici stiluri pe baza lățimii containerului în Tailwind v4?", "o": ["Părintele are clasa @container, iar copiii @md:flex-row", "container-md:", "Doar cu media queries"], "a": 0, "h": "Container queries sunt încorporate.", "e": "Exemplu: <div class=\"@container\"><div class=\"flex flex-col @md:flex-row\">.", "px": ["Container queries: stilul depinde de lățimea părintelui, nu a ecranului. Părintele primește `@container`, iar copiii `@md:flex-row`. Componenta se adaptează oriunde o pui."]}, {"id": "xt9", "d": "web", "nou": 1, "t": "mc", "q": "Ce înlocuiește bg-opacity-50 din Tailwind v3?", "o": ["Modificatorul de opacitate: bg-black/50", "opacity-bg-50", "bg-50"], "a": 0, "h": "Slash.", "e": "În v4 au dispărut utilitarele *-opacity-*. Tot din v4: shrink-* și grow-* în loc de flex-shrink/flex-grow.", "px": ["În v4 opacitatea se scrie cu slash în numele culorii: `bg-black/50`. Vechiul `bg-opacity-50` a dispărut.", "Încearcă: schimbă 50 în 20. (Necesită internet pentru CDN.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n</head>\n<body>\n<div class=\"p-6 bg-sky-200\"><div class=\"bg-black/50 p-4 text-white\">bg-black/50: negru cu 50% opacitate</div></div>\n</body>\n</html>\n"}}, {"id": "xt10", "d": "web", "nou": 1, "t": "mc", "q": "Ce s-a schimbat în v4 la culoarea implicită a bordurii?", "o": ["Implicit e currentColor (în v3 era gray-200)", "Rămâne gray-200", "E transparentă"], "a": 0, "h": "Specifică culoarea explicit.", "e": "Și outline-none devine outline-hidden; important se scrie la sfârșit: flex!.", "px": ["În v3 bordura implicită era `gray-200`. În v4 e `currentColor`. Pentru culoare, o specifici explicit: `border border-gray-200`."]}, {"id": "xt11", "d": "web", "nou": 1, "t": "mc", "q": "Cum previi duplicarea la Tailwind când același set de clase apare des?", "o": ["Creezi o componentă (React/Vue/partial) sau iterezi într-un loop", "Copiezi clasele manual peste tot", "Folosești mereu !important"], "a": 0, "h": "Reutilizare prin componente.", "e": "Pentru CSS simplu în limbaje de template se poate folosi @layer components cu .btn-primary.", "px": ["Dacă același grup de clase apare în 10 locuri, nu copiezi: faci o componentă (React/Vue/partial) sau generezi elementele într-un loop. Astfel modifici într-un singur loc."]}, {"id": "xt12", "d": "web", "nou": 1, "t": "mc", "q": "Cum aplici un stil pentru dark mode în Tailwind?", "o": ["dark:bg-gray-800 (variantă dark:)", "@dark(bg-gray-800)", "bg-gray-800-dark"], "a": 0, "h": "Variante: hover:, focus:, dark:, sm:...", "e": "Variantele se pot combina: dark:hover:bg-gray-700.", "px": ["Varianta `dark:` aplică stilul în modul întunecat. Implicit urmează setarea sistemului; aici am legat-o de clasa `dark`, ca să o poți comuta.", "Încearcă: apasă linkul. (Necesită internet pentru CDN.)"], "tr": {"l": "html", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4\"></script>\n<style type=\"text/tailwindcss\">@custom-variant dark (&:where(.dark, .dark *));</style>\n</head>\n<body>\n<div class=\"p-6\"><button onclick=\"document.documentElement.classList.toggle('dark')\" class=\"underline\">comută .dark pe html</button>\n<div class=\"mt-4 bg-white p-4 text-black dark:bg-gray-800 dark:text-white\">Tema se schimbă cu dark:</div></div>\n</body>\n</html>\n"}}, {"id": "xg1", "d": "seo", "nou": 1, "t": "mc", "q": "Care e unitatea de bază a datelor în GA4?", "o": ["Evenimentul (event) cu parametri", "Vizualizarea de pagină", "Sesiunea"], "a": 0, "h": "Diferența față de Universal Analytics.", "e": "GA4 măsoară interacțiuni ca evenimente; page_view e doar un eveniment.", "px": ["În GA4 totul e eveniment: o vizualizare de pagină, un click, o achiziție. Fiecare are parametri (de ex. numele paginii, valoarea). În Universal Analytics, unitatea era sesiunea/pageview."]}, {"id": "xg2", "d": "seo", "nou": 1, "t": "mc", "q": "Ce sunt „key events” în GA4?", "o": ["Evenimentele marcate ca importante (fostele „conversions”)", "Evenimentele automate", "Evenimentele de eroare"], "a": 0, "h": "Redenumire a conversiilor.", "e": "Servesc la rapoarte și audiențe sugerate.", "px": ["Key events = evenimentele pe care le marchezi ca importante pentru afacere (achiziție, lead). Se numeau „conversions”; Google a păstrat numele „conversion” pentru Google Ads."]}, {"id": "xg3", "d": "seo", "nou": 1, "t": "mc", "q": "Când e o sesiune „engaged” în GA4?", "o": ["Durează peste 10 secunde, SAU are un key event, SAU are cel puțin 2 vizualizări de pagină/ecran", "Doar dacă are peste 1 minut", "Doar dacă utilizatorul face scroll"], "a": 0, "h": "Trei criterii alternative.", "e": "Engagement rate = sesiuni engaged / sesiuni.", "px": ["O sesiune e „engaged” dacă îndeplinește măcar una: durează peste 10 secunde, are un key event sau are cel puțin 2 vizualizări de pagină/ecran."]}, {"id": "xg4", "d": "seo", "nou": 1, "t": "mc", "q": "Cum se definește bounce rate în GA4?", "o": ["Procentul de sesiuni care NU au fost engaged", "Procentul utilizatorilor care părăsesc ultima pagină", "La fel ca în Universal Analytics"], "a": 0, "h": "Inversul engagement rate.", "e": "Sub 10 secunde, fără eveniment cheie și cu o singură pagină = sesiune cu bounce.", "px": ["Bounce rate în GA4 = procentul de sesiuni care NU au fost engaged. E complementul lui engagement rate (suma lor = 100%). Nu e același lucru cu bounce rate din Universal Analytics."]}, {"id": "xg5", "d": "seo", "nou": 1, "t": "mc", "q": "Ce afectează setarea de păstrare a datelor la nivel de eveniment (2 sau 14 luni) în GA4?", "o": ["Doar explorările și rapoartele de pâlnie; rapoartele standard agregate nu sunt afectate", "Toate rapoartele", "Doar datele demografice"], "a": 0, "h": "Dacă vrei rapoarte pe 26 de luni?", "e": "2 luni sau 14 luni la proprietățile standard; 26/38/50 doar la GA4 360. Datele de vârstă/gen/interese se șterg după 2 luni.", "px": ["Setarea (2 sau 14 luni) afectează doar rapoartele pe date la nivel de eveniment: explorările. Rapoartele standard, agregate, nu sunt afectate."]}, {"id": "xg6", "d": "seo", "nou": 1, "t": "mc", "q": "Ce metrici bazează raportul Performance din Search Console?", "o": ["Clicks, Impressions, CTR (clicks/impressions) și Average position", "Sesiuni, utilizatori, conversii", "Cost, CPC, ROAS"], "a": 0, "h": "Date despre afișarea în Google Search.", "e": "Implicit afișează ultimele 3 luni și se poate grupa după query, pagină, țară, dispozitiv.", "px": ["Raportul Performance din Search Console arată: Clicks, Impressions, CTR (clicks/impressions) și Average position."]}, {"id": "xg7", "d": "seo", "nou": 1, "t": "mc", "q": "Care e diferența dintre „Discovered – currently not indexed” și „Crawled – currently not indexed” în Search Console?", "o": ["Discovered: Google știe de URL dar nu l-a accesat încă; Crawled: l-a accesat, dar nu l-a indexat (încă)", "Sunt sinonime", "Discovered înseamnă indexat"], "a": 0, "h": "Accesat sau nu.", "e": "Excluded by noindex tag = Google a găsit directiva noindex și respectă. Duplicate without user-selected canonical = Google a ales altă versiune.", "px": ["„Discovered” = Google știe de URL, dar nu l-a vizitat încă. „Crawled” = l-a vizitat, dar nu l-a pus în index (de multe ori din cauza calității sau a duplicării)."]}, {"id": "xg8", "d": "seo", "nou": 1, "t": "mc", "q": "Care sunt Core Web Vitals actuale și pragurile „bune”?", "o": ["LCP ≤ 2,5 s, INP ≤ 200 ms, CLS ≤ 0,1", "LCP ≤ 4 s, FID ≤ 100 ms, CLS ≤ 0,5", "TTFB ≤ 1 s, FCP ≤ 1 s, TBT ≤ 0"], "a": 0, "h": "INP a înlocuit FID.", "e": "Evaluarea se face la percentila 75 a încărcărilor de pagină, pe mobil și desktop. INP a devenit metrică stabilă în 2024.", "px": ["Core Web Vitals: LCP (cât de repede apare conținutul principal) ≤ 2,5 s; INP (răspunsul la interacțiuni) ≤ 200 ms; CLS (mutări neașteptate ale paginii) ≤ 0,1."]}, {"id": "xg9", "d": "seo", "nou": 1, "t": "mc", "q": "Ce măsoară INP (Interaction to Next Paint)?", "o": ["Cât de rapid răspunde pagina vizual la interacțiunile utilizatorului", "Cât durează încărcarea imaginii principale", "Cât se mută elementele în pagină"], "a": 0, "h": "Interactivitate.", "e": "LCP = încărcare, CLS = stabilitate vizuală.", "px": ["INP măsoară cât timp trece între o acțiune (click, tastă) și momentul în care pagina se actualizează vizual. A înlocuit FID ca Core Web Vital în martie 2024."]}, {"id": "xg10", "d": "seo", "nou": 1, "t": "mc", "q": "Ce e un parametru UTM și la ce folosește?", "o": ["Parametri în URL (utm_source, utm_medium, utm_campaign) care spun din ce campanie vine traficul", "Un tip de cookie", "Un cod de eroare"], "a": 0, "h": "Atribuirea campaniilor.", "e": "Se completează și utm_term/utm_content. Apar în GA4 la sursă/mediu/campanie.", "px": ["UTM sunt etichete adăugate la URL (`utm_source`, `utm_medium`, `utm_campaign`) ca să știi din ce campanie a venit vizitatorul. Nu pune în ele date personale."]}, {"id": "xg11", "d": "seo", "nou": 1, "t": "mc", "q": "La ce folosește Google Tag Manager (GTM)?", "o": ["Gestionezi tag-urile (GA4, Meta Pixel...) printr-o interfață, cu trigger-e și variabile, fără să modifici codul la fiecare tag", "Înlocuiește Google Analytics", "Face backup la site"], "a": 0, "h": "Container, tag, trigger, variabilă.", "e": "Datele personalizate se transmit prin dataLayer.", "px": ["GTM e un „panou de control” pentru tag-uri: adaugi GA4, Meta Pixel etc. din interfață, cu trigger-e (când rulează) și variabile, fără să modifici codul site-ului."]}, {"id": "xg12", "d": "seo", "nou": 1, "t": "mc", "q": "Cum verifici un domeniu întreg (inclusiv subdomenii și http/https) în Search Console?", "o": ["Proprietate de tip „Domeniu”, verificată prin înregistrare DNS TXT", "Proprietate cu prefix URL, verificată doar prin fișier HTML", "Nu se poate"], "a": 0, "h": "Domain property vs URL-prefix.", "e": "Proprietatea cu prefix URL acoperă doar acel prefix exact.", "px": ["Proprietatea „Domeniu” acoperă toate subdomeniile și toate protocoalele (http/https), dar se verifică prin înregistrare DNS TXT. Proprietatea „Prefix URL” acoperă doar adresa exactă."]}, {"id": "xg13", "d": "seo", "nou": 1, "t": "mc", "q": "Ce arată instrumentul URL Inspection?", "o": ["Starea unei pagini în indexul Google și rezultatul unui test live; poți cere indexarea", "Doar viteza paginii", "Doar backlink-urile"], "a": 0, "h": "O singură pagină.", "e": "Utile după corectarea unei erori sau publicarea unei pagini noi.", "px": ["URL Inspection arată cum vede Google pagina: dacă e în index, ce probleme are, și permite un test live și solicitarea indexării."]}, {"id": "xg14", "d": "seo", "nou": 1, "t": "mc", "q": "Ce face fișierul sitemap.xml trimis în Search Console?", "o": ["Listează URL-urile pe care vrei să le descopere Google; nu garantează indexarea", "Garantează indexarea", "Blochează paginile"], "a": 0, "h": "Ajutor de descoperire.", "e": "robots.txt controlează crawling-ul; noindex controlează indexarea.", "px": ["Sitemap-ul e o listă de URL-uri pe care vrei să le descopere Google. Ajută la descoperire, dar nu garantează indexarea."]}, {"id": "xg15", "d": "seo", "nou": 1, "t": "mc", "q": "Care e diferența dintre robots.txt și meta noindex?", "o": ["robots.txt oprește crawling-ul; noindex cere eliminarea din index (pagina trebuie să fie accesibilă ca să fie citit)", "Sunt identice", "noindex blochează crawling-ul"], "a": 0, "h": "Un URL blocat în robots.txt poate rămâne în index.", "e": "Dacă blochezi în robots.txt, Google nu mai vede noindex-ul.", "px": ["`robots.txt` spune crawlerului unde să nu intre. `noindex` cere ca pagina să nu fie în index, dar pagina trebuie să fie accesibilă ca Google să vadă eticheta. Un URL blocat în robots.txt poate rămâne în index fără conținut."]}, {"id": "xm1", "d": "mkt", "nou": 1, "t": "mc", "q": "Cum se calculează CTR?", "o": ["Clickuri împărțite la afișări (impressions)", "Afișări împărțite la clickuri", "Conversii împărțite la clickuri"], "a": 0, "h": "Click-through rate.", "e": "CPC = cost per click, CPM = cost la o mie de afișări, conversion rate = conversii / vizite (sau clickuri).", "px": ["CTR = click-through rate = clickuri / afișări × 100. Exemplu: 50 de clickuri la 2000 de afișări = 2,5%."]}, {"id": "xm2", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce măsoară ROAS?", "o": ["Venitul generat pentru fiecare unitate cheltuită pe reclame (venit / cost reclame)", "Profitul net", "Costul pe lead"], "a": 0, "h": "Return on ad spend.", "e": "ROI ia în calcul profitul față de investiție; ROAS doar venitul față de cheltuiala pe reclame.", "px": ["ROAS = venit din reclame / cost reclame. Dacă cheltui 100 lei și vinzi 400 lei, ROAS = 4 (sau 400%). Nu ține cont de costul produselor, deci nu e profit."]}, {"id": "xm3", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce înseamnă CAC și LTV și cum se raportează?", "o": ["CAC = costul de achiziție al unui client; LTV = valoarea pe viață a unui client; LTV ar trebui să fie mult peste CAC", "CAC = costul pe click; LTV = timpul pe site", "Sunt același indicator"], "a": 0, "h": "Unit economics.", "e": "O regulă folosită des este LTV:CAC de cel puțin 3:1, dar depinde de afacere.", "px": ["CAC = cât te costă să aduci un client. LTV = cât aduce un client în toată relația. Regulă folosită des: LTV:CAC de cel puțin 3:1. Reper orientativ, nu lege."]}, {"id": "xm4", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e AOV (average order value)?", "o": ["Valoarea medie a unei comenzi: venit total / număr de comenzi", "Numărul mediu de produse pe vizită", "Rata de abandon a coșului"], "a": 0, "h": "Magazine online.", "e": "Poți crește AOV prin bundle-uri, prag de transport gratuit, cross-sell.", "px": ["AOV = venit total / număr de comenzi. Dacă ai 5000 lei din 50 de comenzi, AOV = 100 lei. Îl crești prin pachete, praguri pentru transport gratuit etc."]}, {"id": "xm5", "d": "mkt", "nou": 1, "t": "mc", "q": "Cum diferă un MQL de un SQL?", "o": ["MQL: lead calificat de marketing (interes arătat); SQL: lead acceptat de vânzări ca potențial real", "Sunt sinonime", "MQL e client, SQL e prospect"], "a": 0, "h": "Cine îl califică?", "e": "Pâlnia: vizitator → lead → MQL → SQL → oportunitate → client.", "px": ["MQL (Marketing Qualified Lead) = a arătat interes (a descărcat un ghid). SQL (Sales Qualified Lead) = vânzările l-au verificat și vor să-l contacteze."]}, {"id": "xm6", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce face Meta Pixel?", "o": ["Cod JavaScript pe site care măsoară acțiuni ale vizitatorilor și alimentează audiențe și optimizarea reclamelor", "Face backup la reclame", "Înlocuiește Google Analytics"], "a": 0, "h": "Evenimente standard: Purchase, Lead, AddToCart, ViewContent.", "e": "Colectează și date tehnice (headere, cookie Facebook, ID pixel).", "px": ["Meta Pixel e o bucată de JavaScript pe site. Trimite către Meta ce fac vizitatorii (vizualizare, adaugă în coș, cumpără), pentru măsurare, optimizare și audiențe."]}, {"id": "xm7", "d": "mkt", "nou": 1, "t": "mc", "q": "Cum deduplici evenimentele trimise atât de Pixel, cât și de Conversions API?", "o": ["Trimiți același event_name și același event_id (eventID la Pixel) pe ambele canale", "Dezactivezi Pixel-ul", "Trimiți doar server"], "a": 0, "h": "Potrivire de câmpuri.", "e": "Documentația Meta: deduplicare în 48 de ore; se preferă evenimentul primit primul. eventID e al 4-lea argument din fbq('track', ...).", "px": ["Dacă trimiți același eveniment și din browser (Pixel), și de pe server (Conversions API), Meta îl poate număra de două ori. Trimiți același `event_name` și același `event_id` pe ambele canale, iar Meta păstrează un singur eveniment."]}, {"id": "xm8", "d": "mkt", "nou": 1, "t": "mc", "q": "Care e diferența dintre match type-urile Google Ads broad, phrase și exact?", "o": ["Broad: variante largi ale intenției; phrase: înțelesul frazei cu ordinea relevantă; exact: același înțeles/intenție strâns", "Sunt sinonime", "Exact e cel mai larg"], "a": 0, "h": "Control versus acoperire.", "e": "Negative keywords exclud căutările irelevante.", "px": ["Broad = variante largi ale intenției. Phrase = înțelesul frazei, ordinea contează unde schimbă sensul. Exact = înțelesul exact sau foarte apropiat. Cu cât e mai larg, cu atât ai mai mult trafic, dar mai puțin relevant."]}, {"id": "xm9", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e Quality Score în Google Ads și ce NU este?", "o": ["Instrument de diagnostic 1-10 pe cuvânt cheie (CTR așteptat, relevanța reclamei, experiența paginii); nu e KPI de optimizat și nu intră direct în licitație", "Un KPI principal de optimizat", "Prețul plătit pe click"], "a": 0, "h": "Trei componente: Above average / Average / Below average.", "e": "Indică unde poți îmbunătăți reclama sau pagina de destinație.", "px": ["Quality Score (1-10) e un instrument de diagnostic pe cuvânt cheie: CTR așteptat, relevanța reclamei, experiența pe pagina de destinație. Nu e un factor direct în licitație."]}, {"id": "xm10", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e remarketing?", "o": ["Reclame către oameni care au vizitat deja site-ul sau au interacționat cu brandul", "Reclame către oameni care n-au auzit de brand", "Trimiterea unui al doilea email"], "a": 0, "h": "Audiențe pe baza comportamentului.", "e": "În Meta: custom audiences; în Google: audience lists.", "px": ["Remarketing = arăți reclame oamenilor care ți-au vizitat deja site-ul sau au interacționat cu brandul. Au deja interes, deci conversia e de obicei mai ieftină."]}, {"id": "xm11", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e un lookalike audience la Meta?", "o": ["Audiență nouă cu profil similar cu o sursă existentă (ex. clienți actuali)", "Audiență copiată din concurență", "Audiență a prietenilor"], "a": 0, "h": "Pornești de la un seed.", "e": "Calitatea sursei (clienți valoroși) influențează rezultatul.", "px": ["Lookalike = Meta caută oameni cu profil similar cu o sursă a ta (ex. clienții actuali). Calitatea sursei contează: sursă bună, audiență bună."]}, {"id": "xm12", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e un A/B test corect?", "o": ["Compari două variante (A și B) pe public comparabil, schimbând o singură variabilă, cu volum suficient pentru semnificație", "Compari două campanii cu bugete diferite", "Schimbi totul odată"], "a": 0, "h": "O variabilă pe test.", "e": "Decizi după metrica stabilită dinainte (ex. conversion rate), nu după prima diferență.", "px": ["A/B test = două variante, public comparabil, schimbi o singură variabilă, rulezi suficient timp, apoi compari. Dacă schimbi mai multe lucruri deodată, nu știi ce a făcut diferența."]}, {"id": "xm13", "d": "mkt", "nou": 1, "t": "mc", "q": "Cum ar trebui structurat un email de vânzări rece (cold email)?", "o": ["Scurt, personalizat, cu o singură cerere clară și un beneficiu pentru destinatar", "Lung, cu toate produsele", "Fără subiect, ca să fie curios"], "a": 0, "h": "Valoare + CTA unic.", "e": "Respectă GDPR: bază legală, opțiune de dezabonare.", "px": ["Un cold email bun e scurt, personalizat (arată că știi cine e destinatarul), spune ce câștigă el și are o singură cerere clară (de ex. 15 minute de discuție)."]}, {"id": "xm14", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce diferență e între SEO și SEM?", "o": ["SEO = rezultate organice (nu plătești per click); SEM = vizibilitate plătită în motoare de căutare (Google Ads)", "Sunt același lucru", "SEM e doar social media"], "a": 0, "h": "Organic versus plătit.", "e": "SEA e un alt nume pentru reclamele plătite pe căutare.", "px": ["SEO = rezultate organice, nu plătești per click, dar efectul vine în timp. SEM = vizibilitate plătită în motoare de căutare (Google Ads), rezultatele vin repede."]}, {"id": "xd1", "d": "mkt", "nou": 1, "t": "mc", "q": "Care e diferența dintre grafica raster și cea vectorială?", "o": ["Raster: pixeli, se degradează la mărire (Photoshop); vector: forme matematice, se scalează fără pierdere (Illustrator, CorelDRAW)", "Sunt identice", "Vectorul e doar pentru fotografii"], "a": 0, "h": "Logo = vector.", "e": "Formate: raster (JPG, PNG, GIF, WebP), vector (SVG, AI, EPS, PDF).", "px": ["Raster = grilă de pixeli (fotografie, Photoshop): la mărire se pixelează. Vectorial = formule matematice (Illustrator, SVG): rămâne clar la orice mărime. Logo-urile se fac vectorial."]}, {"id": "xd2", "d": "mkt", "nou": 1, "t": "mc", "q": "Pentru ce folosești Photoshop, Illustrator și InDesign?", "o": ["Photoshop: editare foto/raster; Illustrator: logo-uri și ilustrații vectoriale; InDesign: pagini multiple (broșuri, reviste, PDF-uri)", "Toate fac același lucru", "Photoshop pentru logo-uri, Illustrator pentru fotografii"], "a": 0, "h": "Raster / vector / layout.", "e": "CorelDRAW e echivalentul de grafică vectorială, Corel PHOTO-PAINT pentru raster.", "px": ["Photoshop: fotografii și imagini raster. Illustrator: logo-uri și ilustrații vectoriale. InDesign: aranjare în pagină (broșuri, reviste, cărți)."]}, {"id": "xd3", "d": "mkt", "nou": 1, "t": "mc", "q": "RGB sau CMYK pentru un banner web și pentru un flyer tipărit?", "o": ["RGB pentru web; CMYK pentru tipar", "CMYK pentru web; RGB pentru tipar", "RGB pentru ambele"], "a": 0, "h": "Ecran versus cerneală.", "e": "Documentația Adobe: lucrezi în RGB și convertești în CMYK la sfârșit. Culorile din afara gamutului CMYK sunt aproximate.", "px": ["Ecranele emit lumină: RGB (roșu, verde, albastru). Tiparul folosește cerneluri: CMYK (cyan, magenta, galben, negru). Imprimantele nu pot reproduce toate culorile RGB, deci verifici culorile pentru tipar."]}, {"id": "xd4", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce rezoluție se recomandă pentru tipar și pentru web?", "o": ["Tipar: aproximativ 300 PPI; web: contează dimensiunea în pixeli, 72 PPI e convenția", "Tipar: 72 PPI; web: 300 PPI", "Nu contează"], "a": 0, "h": "PPI = pixeli pe inch.", "e": "Mărirea (upsampling) interpolează pixeli noi și scade claritatea; pornește de la imagini mari.", "px": ["Tipar: aproximativ 300 PPI la mărimea finală. Web: contează dimensiunea în pixeli (de ex. 1200 px lățime). Valoarea 72 PPI din fișier nu schimbă calitatea pe ecran."]}, {"id": "xd5", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce face o mască de strat (layer mask) în Photoshop?", "o": ["Ascunde sau arată părți dintr-un strat nedistructiv: negru ascunde, alb arată", "Șterge definitiv pixelii", "Schimbă modul de culoare"], "a": 0, "h": "Nedistructiv, spre deosebire de radieră.", "e": "Poți picta pe mască oricând pentru a repara.", "px": ["Masca de strat: ascunzi părți fără să ștergi. Pe mască, negru ascunde, alb arată, griul dă transparență parțială. Poți corecta oricând."]}, {"id": "xd6", "d": "mkt", "nou": 1, "t": "mc", "q": "Pentru ce e potrivit fiecare format: PSD, JPEG, PNG, SVG?", "o": ["PSD: lucru cu straturi; JPEG: fotografii pe web (cu pierderi); PNG: grafică cu transparență (fără pierderi); SVG: vectori scalabili", "Toate sunt identice", "PNG are pierderi, JPEG are transparență"], "a": 0, "h": "Format de lucru versus de livrare.", "e": "TIFF e fără pierderi, pentru arhivare/tipar. GIF are paletă limitată și animație.", "px": ["PSD = fișier de lucru cu straturi. JPEG = fotografii, cu pierderi. PNG = grafică cu transparență, fără pierderi. SVG = grafică vectorială pe web."]}, {"id": "xd7", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e un Smart Object în Photoshop?", "o": ["Strat care păstrează conținutul original, permițând scalare și filtre nedistructive", "Un strat de text", "Un șablon"], "a": 0, "h": "Păstrează sursa.", "e": "Poți redimensiona de mai multe ori fără să pierzi calitatea.", "px": ["Smart Object păstrează imaginea originală. Poți micșora și mări fără pierdere de calitate și aplica filtre editabile (Smart Filters)."]}, {"id": "xd8", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e un „bleed” (margine de tăiere) la tipar?", "o": ["Zona suplimentară (de obicei 3 mm) pe care o extinzi dincolo de marginea paginii, ca să nu rămână margini albe la tăiere", "Un tip de font", "Un format de imagine"], "a": 0, "h": "Fundalul trebuie să ajungă dincolo de linia de tăiere.", "e": "Se livrează PDF cu bleed și semne de tăiere, de obicei în CMYK.", "px": ["Bleed = marginea suplimentară (de obicei 3 mm) pe care o extinzi dincolo de marginea paginii. Tăierea la tipar nu e perfectă; fără bleed pot apărea dungi albe."]}, {"id": "xd9", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce face Canva spre deosebire de Adobe Photoshop?", "o": ["Canva e un instrument online cu șabloane pentru design rapid (postări, prezentări); Photoshop oferă control profesional la nivel de pixel", "Sunt identice", "Canva e doar pentru video"], "a": 0, "h": "Viteză versus control.", "e": "Figma e folosit mai ales pentru UI/UX și lucru colaborativ.", "px": ["Canva: online, cu șabloane, pentru design rapid (postări, prezentări). Photoshop: control profesional pe pixeli, straturi, retușare."]}, {"id": "xd10", "d": "mkt", "nou": 1, "t": "mc", "q": "Ce e un font „outlined” (convertit în contururi) la un logo trimis la tipar?", "o": ["Textul transformat în forme vectoriale, ca să nu depindă de fontul instalat", "Un font subțire", "Un font cu bordură"], "a": 0, "h": "Fără fonturi lipsă.", "e": "În Illustrator: Type > Create Outlines.", "px": ["Fonturile trebuie instalate pe calculatorul care deschide fișierul. Convertite în contururi (outline), literele devin forme vectoriale și arată la fel oriunde, deci tipografia nu schimbă fontul."]}, {"id": "xe33", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“We are looking for a team player.” What does “team player” mean?", "o": ["Cineva care colaborează bine cu ceilalți", "Un sportiv", "Un șef"], "a": 0, "h": "Expresie frecventă în anunțuri.", "e": "Alte expresii: detail-oriented (atent la detalii), self-starter (proactiv), fast learner (învață repede).", "px": ["„Team player” = cineva care colaborează bine și își ajută colegii. E un termen frecvent în anunțuri de angajare."]}, {"id": "xe34", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "Choose the correct sentence.", "o": ["I have been working here for three years.", "I am working here since three years.", "I work here from three years."], "a": 0, "h": "for + durată, cu present perfect.", "e": "În engleză nu spui „since three years”. Since = punct de start, for = durată.", "px": ["Present perfect continuous + `for` + durată: „I have been working here for three years.” Prezentul simplu nu merge cu „for three years”."]}, {"id": "xe35", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“Could you give me some feedback?” Which is correct about “feedback”?", "o": ["Feedback e nenumărabil: some feedback, a piece of feedback", "Se spune feedbacks", "Se spune a feedback"], "a": 0, "h": "Nenumărabil.", "e": "La fel: advice, information, equipment, software, knowledge.", "px": ["„Feedback” e nenumărabil: nu are plural. Spui „some feedback” sau „a piece of feedback”, nu „feedbacks”."]}, {"id": "xe36", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“I’m writing to ___ about the open position.” Which is correct?", "o": ["inquire", "ask for to", "request me"], "a": 0, "h": "Email formal.", "e": "Alte formule: „I’m writing to apply for...”, „Please find attached my CV”.", "px": ["„Inquire about” = a întreba despre ceva. „I’m writing to inquire about the open position.” Se scrie și „enquire” în engleza britanică."]}, {"id": "xe37", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "Which closing is appropriate for a formal email?", "o": ["Kind regards,", "See ya!", "Bye bye"], "a": 0, "h": "Politețe.", "e": "Mai formal: Yours sincerely / Best regards. Printre variantele curente: Best, Regards.", "px": ["Pentru emailuri formale: „Kind regards”, „Best regards”, „Sincerely”. „Cheers” și „Bye” sunt prea informale."]}, {"id": "xe38", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“I’m used to working under pressure.” What does “be used to + -ing” mean?", "o": ["A fi obișnuit cu ceva", "A folosi ceva", "Obișnuiam să fac ceva"], "a": 0, "h": "Nu confunda cu used to + infinitiv.", "e": "I used to work night shifts = obișnuiam să lucrez în ture de noapte.", "px": ["„Be used to + -ing” = a fi obișnuit cu. „I’m used to working under pressure.” Nu-l confunda cu „used to + infinitiv” (obișnuiam să)."]}, {"id": "xe39", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“How do you handle tight deadlines?” Which answer is best?", "o": ["I prioritize tasks, communicate early about risks, and break the work into small steps.", "I don’t get deadlines.", "I just work faster."], "a": 0, "h": "Metodă + comunicare.", "e": "Combină acțiuni concrete cu un exemplu scurt (STAR).", "px": ["Un răspuns bun arată metodă: prioritizezi, anunți devreme riscurile, împarți munca în pași mici."]}, {"id": "xe40", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“Please find attached the report.” What does it mean?", "o": ["Atașat găsiți raportul.", "Vă rog, găsiți raportul pierdut.", "Raportul este atașat de colegi."], "a": 0, "h": "Formulă standard de email.", "e": "Variante: „I’ve attached...”, „Attached is...”.", "px": ["„Please find attached the report” = „Atașat găsiți raportul”. Formulă standard în email-uri. Varianta mai simplă: „I’ve attached the report.”"]}, {"id": "xe41", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "What is the difference between “affect” and “effect”?", "o": ["affect = verb (a influența); effect = substantiv (efect)", "affect = substantiv; effect = verb mereu", "Sunt sinonime perfecte"], "a": 0, "h": "Regula uzuală.", "e": "The bug affects users. The bug has an effect on users. (Excepție: to effect change = a produce o schimbare.)", "px": ["`affect` e de obicei verb („a influența”): „This bug affects users.” `effect` e de obicei substantiv („efect”): „The effect was immediate.” Trucul: A = Action, E = End result."]}, {"id": "xe42", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“I’m in charge of the support team.” What does it mean?", "o": ["Eu conduc/răspund de echipa de suport", "Mi se cere plata de la echipă", "Sunt încărcat de echipă"], "a": 0, "h": "In charge of = responsabil de.", "e": "Atenție la false friends: to charge = a taxa, a încărca.", "px": ["„In charge of” = responsabil de, conduce. „The person in charge” = șeful, responsabilul."]}, {"id": "xe43", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "“Remind me” vs. “remember”: which is correct?", "o": ["Please remind me to send the email.", "Please remember me to send the email.", "Please remind to me send the email."], "a": 0, "h": "Remind = a aminti cuiva.", "e": "I remember = îmi amintesc. Remind someone to do something.", "px": ["„Remind me to...” = „amintește-mi să...”. „Remember” = a-ți aminti singur. Corect: „Please remind me to send the email.”"]}, {"id": "xe44", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "What does “I’ll get back to you” mean?", "o": ["Revin la tine cu un răspuns mai târziu", "Mă întorc acasă", "Te aduc înapoi"], "a": 0, "h": "Politicos la interviu.", "e": "Variante: „I’ll circle back”, „Let me check and come back to you”.", "px": ["„I’ll get back to you” = „revin cu un răspuns”. O promisiune politicoasă că vei răspunde după ce te informezi."]}, {"id": "xe45", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "Choose the correct form: “I ___ never used that tool before.”", "o": ["have", "has", "am"], "a": 0, "h": "Present perfect cu I.", "e": "I/you/we/they have; he/she/it has.", "px": ["„Never” se folosește cu present perfect: „I have never used that tool.” „Have” e auxiliar, apoi participiul (used)."]}, {"id": "xe46", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "Which question is grammatically correct?", "o": ["What do you do in your free time?", "What you do in your free time?", "What does you do in your free time?"], "a": 0, "h": "Auxiliar do/does.", "e": "La persoana a III-a: What does he do?", "px": ["În întrebări cu „do”, ordinea e: cuvânt interogativ + auxiliar + subiect + verb. „What do you do...?” Cu „you” auxiliarul e `do`, nu `does`."]}, {"id": "xe47", "d": "en", "nou": 1, "lng": "en", "t": "mc", "q": "What does “KPI” stand for?", "o": ["Key Performance Indicator", "Key Project Idea", "Known Process Item"], "a": 0, "h": "Indicator de performanță.", "e": "Exemple: conversion rate, CTR, ROAS, timp de răspuns la tichete.", "px": ["KPI = Key Performance Indicator: indicator-cheie de performanță (de ex. rata de conversie). Cifra cu care măsori dacă ți-ai atins obiectivul."]}, {"id": "np1", "d": "node", "nou": 1, "t": "mc", "q": "Ce face comanda npm install (fără alt argument) într-un proiect care are package.json?", "o": ["Citește dependențele din package.json și le instalează în node_modules", "Pornește aplicația", "Șterge folderul node_modules și package.json"], "a": 0, "h": "Gândește-te: «instalează ce scrie în listă».", "e": "npm install citește dependencies și devDependencies din package.json, descarcă pachetele în node_modules și scrie/actualizează package-lock.json.", "px": ["Gândește-te la o rețetă (package.json) cu lista de ingrediente. `npm install` merge la magazin și aduce toate ingredientele în bucătărie (folderul `node_modules`).", "Pasul 1: clonezi proiectul (`git clone ...`). Pasul 2: `npm install` aduce pachetele. Pasul 3: `npm start` pornește aplicația.", "`package-lock.json` reține versiunile exacte instalate, ca toți colegii să aibă aceleași."]}, {"id": "np2", "d": "node", "nou": 1, "t": "mc", "q": "Ce face npm start și de unde știe ce să ruleze?", "o": ["Rulează scriptul „start” din secțiunea scripts a lui package.json", "Instalează toate pachetele", "Publică pachetul pe npm"], "a": 0, "h": "Caută cheia „scripts” în package.json.", "e": "npm start rulează scripts.start. Dacă nu există și ai un server.js, rulează implicit node server.js. Pentru alte scripturi folosești npm run <nume>.", "px": ["În `package.json` ai o secțiune `\"scripts\"`, ca o listă de butoane: `\"start\": \"node server.js\"`, `\"test\": \"jest\"`.", "`npm start` apasă butonul „start”. Pentru orice alt script scrii `npm run nume` (de ex. `npm run build`).", "Ordinea la un proiect nou luat de pe GitHub: `npm install`, apoi `npm start`."]}, {"id": "np3", "d": "node", "nou": 1, "t": "mc", "q": "Cum folosești un pachet npm (ex. dayjs) într-o pagină HTML simplă, fără npm install și fără build?", "o": ["Cu <script type=\"module\"> și import de la un CDN ESM (ex. https://esm.sh/dayjs)", "Nu se poate: pachetele npm merg doar pe server", "Copiezi folderul node_modules în pagină"], "a": 0, "h": "Browserele moderne știu să facă import din URL-uri.", "e": "Browserele acceptă module ES. Un CDN ca esm.sh servește pachete npm ca module, deci le imporți direct dintr-un URL. Pentru aplicații mari folosești totuși npm și un bundler.", "px": ["Pasul 1: într-un proiect real scrii `npm install dayjs`, apoi `import dayjs from \"dayjs\"`. Calculatorul tău descarcă pachetul.", "Pasul 2: într-o pagină simplă, browserul ia același pachet direct de la un CDN: `import dayjs from \"https://esm.sh/dayjs\"`, în `script.js` (care rulează ca modul).", "Încearcă: deschide fila `script.js`, apasă butonul din pagină și urmărește consola din Preview.", "Atenție: depinzi de CDN și de internet, iar versiunea e în URL (`@1.11.13`). Pentru proiecte serioase folosești `npm` și un bundler."], "tr": {"l": "webpage", "c": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n</head>\n<body>\n<h3>Pachet npm într-o pagină (dayjs + canvas-confetti)</h3>\n<button id=\"b\">Arată data</button>\n<p id=\"out\">Apasă butonul.</p>\n</body>\n</html>\n", "f": {"html": "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n</head>\n<body>\n<h3>Pachet npm într-o pagină (dayjs + canvas-confetti)</h3>\n<button id=\"b\">Arată data</button>\n<p id=\"out\">Apasă butonul.</p>\n</body>\n</html>\n", "css": "body { font-family: Arial, sans-serif; padding: 20px; }\nbutton { padding: 8px 14px; cursor: pointer; }\n#out { font-size: 20px; color: #047857; }\n", "js": "// În proiect: npm install dayjs, apoi import dayjs from \"dayjs\";\n// În browser, fără instalare, același pachet vine de la esm.sh:\nimport dayjs from \"https://esm.sh/dayjs@1.11.13\";\nimport confetti from \"https://esm.sh/canvas-confetti@1.9.3\";\n\ndocument.getElementById(\"b\").addEventListener(\"click\", () => {\n  document.getElementById(\"out\").textContent = \"Azi: \" + dayjs().format(\"DD.MM.YYYY HH:mm\");\n  confetti();\n  console.log(\"click pe buton\");\n});\n"}}}, {"id": "np4", "d": "react", "nou": 1, "t": "mc", "q": "Într-un proiect React ai scris import dayjs from \"dayjs\". Ce trebuie să existe ca să meargă?", "o": ["Pachetul instalat cu npm install dayjs (apare în package.json și node_modules)", "Nimic: React aduce singur orice pachet", "Un fișier dayjs.css lângă componentă"], "a": 0, "h": "De unde ia importul codul?", "e": "import \"dayjs\" caută pachetul în node_modules. Fără npm install dayjs (sau fără el în package.json) apare eroarea „Module not found”.", "px": ["Pasul 1: scrii în cod `import dayjs from \"dayjs\"`.", "Pasul 2: pachetul trebuie adus în proiect cu `npm install dayjs`. Se trece în `package.json` și se descarcă în `node_modules`.", "Pasul 3: bundler-ul (Vite, Webpack) îl găsește acolo și îl pune în aplicație.", "Încearcă: în MiniCode (React) importul merge fără instalare, pentru că pachetul se ia de la esm.sh. Ștergi linia de import și vezi cum dispare data."], "tr": {"l": "react", "c": "import { useState } from \"react\";\nimport { createRoot } from \"react-dom/client\";\nimport dayjs from \"dayjs\";            // în MiniCode vine de la esm.sh; în proiect: npm install dayjs\nimport { nanoid } from \"nanoid\";      // npm install nanoid\n\nfunction App() {\n  const [id, setId] = useState(() => nanoid(8));\n  return (\n    <div>\n      <p>Azi: {dayjs().format(\"DD.MM.YYYY\")}</p>\n      <p>ID generat: <b>{id}</b></p>\n      <button onClick={() => setId(nanoid(8))}>ID nou</button>\n    </div>\n  );\n}\n\ncreateRoot(document.getElementById(\"root\")).render(<App />);\n"}}]; const s0 = html.indexOf('const IV_BANK'); const e0 = s0 >= 0 ? html.indexOf('\n];', s0) : -1; if (e0 > s0) { html = html.slice(0, e0) + "\n/* ---------- Loturi noi 2026-10-04 ---------- */\n" + NEWQ.map(x => JSON.stringify(x).replace(/</g, "\\u003c")).join(",\n") + "," + html.slice(e0); } } catch (e) {}
